function fldHtml(p,[k,l,t]){const v=p[k];const id="pf_"+k;
  if(t==="contra"){const s=new Set(String(v||"").split(",").filter(Boolean));return'<fieldset class="f wide" style="border:1px solid var(--line);border-radius:6px;padding:6px 10px"><legend style="font-size:13px;color:var(--muted)">'+l+'</legend><div class="cols2">'+CAC_CONTRA.map(([c,n])=>'<label class="chk" style="font-size:13px"><input type="checkbox" data-contra="'+c+'"'+(s.has(c)?" checked":"")+'> '+esc(n)+'</label>').join("")+'</div></fieldset>';}
  if(t==="eps")return'<label class="f">'+l+'<select id="'+id+'">'+opt(epsList(),v,"—")+'</select></label>';
  if(t==="ro")return'<label class="f">'+l+'<input type="text" id="'+id+'" value="'+esc(v)+'" readonly></label>';
  if(Array.isArray(t))return'<label class="f">'+l+'<select id="'+id+'">'+opt(t,v,"—")+'</select></label>';
  if(t==="date")return'<label class="f">'+l+'<input type="date" id="'+id+'" value="'+(v?iso(v):"")+'"></label>';
  return'<label class="f">'+l+'<input type="text" id="'+id+'" '+(t==="num"?'inputmode="decimal" ':"")+'value="'+esc(v??"")+'"></label>';}
function readPF(){const o={};pfDef().forEach(([,fs])=>fs.forEach(([k,,t])=>{if(t==="ro")return;if(t==="contra"){o[k]=[...document.querySelectorAll("[data-contra]:checked")].map(e=>e.dataset.contra).join(",")||null;return;}const el=$("pf_"+k);if(!el)return;let v=el.value.trim();o[k]=t==="eps"?(v||null):t==="date"?pdate(v):t==="num"?num(v):(v||null);}));o.Obs=($("pf_Obs")||{}).value||null;
  if(o.Municipio&&!o.MunicipioDANE){const c=MUN_DANE[norm(o.Municipio)];if(c)o.MunicipioDANE=c;}return o;}
function vPac(){
  ensureIdx();const q=norm(ST.ui.pq||"");const fe=ST.ui.pfe||"act";const c=ST.corte;
  const L=ST.book.pac.filter(p=>epsOk(p)&&(fe==="all"||(fe==="act"?activeAt(p,c):!activeAt(p,c)))&&(!q||norm(p.ID+" "+nombre(p)+" "+(p.Documento||"")).includes(q))).sort((a,b)=>String(a.ID).localeCompare(String(b.ID)));
  let h=head("Pacientes","El ID es de la persona, no del cupo: no se reasigna nunca. Los egresos se registran como movimiento con fecha; el registro no se borra. La solicitud de laboratorio del mes siguiente está en Paraclínicos.",'<button type="button" class="btn primary" data-a="pnew">Nuevo paciente</button>');
  h+='<div class="pacgrid"><div class="panel" style="display:grid;gap:10px"><div class="copyrow"><input type="text" id="pq" placeholder="Buscar ID, nombre o documento" value="'+esc(ST.ui.pq||"")+'" style="flex:1;min-width:160px"><div class="seg" role="group">'+[["act","Activos"],["ina","Inactivos"],["all","Todos"]].map(([k,l])=>'<button type="button" data-a="pfe|'+k+'" aria-pressed="'+(fe===k)+'">'+l+'</button>').join("")+'</div></div>'+
  '<div class="tablebox" style="max-height:70vh;overflow:auto"><table><thead><tr><th>ID</th><th>Paciente</th><th>Turno</th><th>Acceso</th></tr></thead><tbody>'+
  (L.map(p=>{const a=accessAt(p,c);return'<tr class="click'+(ST.sel.pac===p.ID?" sel":"")+'" data-a="psel|'+p.ID+'"><td class="mono">'+esc(p.ID)+'</td><td>'+esc(nombre(p))+'<span class="sub">'+esc(p.EPS||"")+(activeAt(p,c)?"":" · "+esc(p.Estado||"inactivo"))+'</span></td><td>'+esc(p.Turno||"—")+'<span class="sub">Puesto '+esc(p.Puesto||"—")+'</span></td><td>'+(a?'<span class="tag '+(isCVC(a)?"cvc":"fav")+'">'+esc(a)+'</span>':"—")+'</td></tr>';}).join("")||'<tr><td colspan="4" class="empty">Sin pacientes con ese filtro.</td></tr>')+'</tbody></table></div><p class="note">'+L.length+' pacientes</p></div>';
  h+='<div class="panel" style="display:grid;gap:14px;min-width:0">'+pacDetail()+'</div></div>';return h;}
function pacDetail(){
  const isNew=ST.sel.pac==="__new";const p=isNew?(ST.ui.pnew=ST.ui.pnew||{ID:nextPid(),Estado:"Activo",SesSemana:3,DuracionMin:ST.book.cfgv.durDefault,IngresoUnidad:TODAY(),RutaAcceso:"Sin valorar",TxEstado:"Sin evaluar"}):IDX.pac.get(ST.sel.pac);
  if(!p)return'<div class="empty">Seleccione un paciente de la lista o cree uno nuevo.</div>';
  let h='<div class="mhead"><div><h3 style="margin:0">'+(isNew?"Nuevo paciente":esc(p.ID)+" · "+esc(nombre(p)))+'</h3>'+(isNew?'<p class="note" style="margin:2px 0 0">Se le asignará el '+esc(p.ID)+'. Obligatorio: documento, apellidos, nombres, EPS, ingreso a la unidad, turno y puesto.</p>':'<p class="note" style="margin:2px 0 0">Estado: <strong>'+esc(p.Estado||"Activo")+'</strong>'+(p.FechaEstado?" desde "+fd(p.FechaEstado):"")+(p.Actualizado?" · última edición "+esc(p.Actualizado)+" por "+esc(p.Usuario||""):"")+'</p>')+'</div><button type="button" class="btn primary" data-a="psave">'+(isNew?"Crear paciente":"Guardar cambios")+'</button></div>';
  if(!isNew)h+=tpHtml(p,ST.corte,true);
  pfDef().forEach(([g,fs],i)=>{const inner='<div class="form">'+fs.map(f=>fldHtml(p,f)).join("")+'</div>';h+=i===5?'<details class="hist"><summary>'+g+'</summary><p class="note">Alimentan la matriz de la Cuenta de Alto Costo (Reportes). Los códigos siguen el instructivo de cada variable.</p>'+inner+'</details>':'<div><h3>'+g+'</h3>'+inner+'</div>';});
  h+='<label class="f">Observaciones<textarea id="pf_Obs">'+esc(p.Obs||"")+'</textarea></label>';
  if(isNew)return h;
  h+='<div><h3>Registrar</h3><div class="seg" role="group">'+[["mov","Movimiento"],["nov","Novedad"],["ate","Atención por disciplina"],["est","Estudio o procedimiento"],["vac","Vacuna VHB"],["acn","Novedad de acceso"],["ctc","Contacto"],["lab","Paraclínico"]].map(([k,l])=>'<button type="button" data-a="preg|'+k+'" aria-pressed="'+(ST.ui.preg===k)+'">'+l+'</button>').join("")+'</div><div style="margin-top:10px">'+pacReg(p)+'</div></div>';
  const tb=(k,cols,rows,an)=>rows.length?'<div class="tablebox"><table><thead><tr>'+cols.map(c=>'<th>'+c[0]+'</th>').join("")+(an?'<th></th>':"")+'</tr></thead><tbody>'+rows.map(r=>'<tr class="'+(r.Anulado==="SI"?"anul":"")+'">'+cols.map(c=>'<td>'+c[1](r)+'</td>').join("")+(an?'<td>'+(r.Anulado==="SI"?'<span class="sub">Anulado: '+esc(r.MotivoAnulacion||"")+'</span>':'<button type="button" class="lnk" data-a="anul|'+k+'|'+r.ID+'">Anular</button>')+'</td>':"")+'</tr>').join("")+'</tbody></table></div>':'<p class="note">Sin registros.</p>';
  const all=k=>ST.book[k].filter(o=>o.Paciente===p.ID);
  const S=all("ses").sort((a,b)=>b.Fecha-a.Fecha);
  h+='<details class="hist" open><summary>Sesiones ('+S.length+')</summary>'+tb("ses",[["Fecha",r=>fd(r.Fecha)],["Estado",r=>esc(r.Estado)+(r.Responsable?'<span class="sub">'+esc(r.Responsable)+(r.Motivo?" · "+esc(r.Motivo):"")+'</span>':"")],["Min",r=>esc(r.DuracionMin??"")],["Acceso",r=>esc(r.Acceso||"")],["Peso",r=>(r.PesoPre??"")+(r.PesoPost!=null?" → "+r.PesoPost:"")],["TAS",r=>esc(r.TASPre??"")],["Registró",r=>'<span class="sub">'+esc(r.Usuario||"")+'</span>']],S.slice(0,40),true)+(S.length>40?'<p class="note">Se muestran las 40 más recientes.</p>':"")+'</details>';
  h+='<details class="hist"><summary>Eventos ('+all("evt").length+')</summary>'+tb("evt",[["Fecha",r=>fd(r.Fecha)],["Evento",r=>esc(r.Tipo)],["Severidad",r=>esc(r.Severidad||"")],["Conducta",r=>esc(r.Conducta||"")],["Resuelto",r=>esc(r.Resuelto||"")+(r.Resuelto!=="Sí"&&live(r)?' <button type="button" class="lnk" data-a="evclose|'+r.ID+'">cerrar</button>':"")],["Hemocultivo",r=>esc(r.Hemocultivo||"")]],all("evt").sort((a,b)=>b.Fecha-a.Fecha),true)+'</details>';
  const Lb=all("lab").sort((a,b)=>b.FechaToma-a.FechaToma);
  h+='<details class="hist"><summary>Paraclínicos ('+Lb.length+')</summary>'+tb("lab",[["Fecha",r=>fd(r.FechaToma)],["Examen",r=>esc((EX[r.Examen]||{}).l||r.Examen)],["Valor",r=>esc(r.Valor)+" "+esc((EX[r.Examen]||{}).u||"")],["Método",r=>'<span class="sub">'+esc(r.Metodo||"")+'</span>']],Lb.slice(0,80),true)+'</details>';
  h+='<details class="hist"><summary>Novedades ('+all("nov").length+')</summary>'+tb("nov",[["Tipo",r=>esc(r.Tipo)+(r.Causa?'<span class="sub">'+esc(r.Causa)+(r.Atribuible?" · atribuible: "+esc(r.Atribuible):"")+'</span>':"")],["Inicio",r=>fd(r.Inicio)],["Fin",r=>r.Fin?fd(r.Fin):(live(r)?'<button type="button" class="lnk" data-a="novclose|'+r.ID+'">registrar egreso</button>':"")],["Descripción",r=>esc(r.Descripcion||"")]],all("nov").sort((a,b)=>b.Inicio-a.Inicio),true)+'</details>';
  h+='<details class="hist"><summary>Movimientos ('+all("mov").length+')</summary>'+tb("mov",[["Fecha",r=>fd(r.Fecha)],["Tipo",r=>esc(r.Tipo)],["Detalle",r=>esc(r.Detalle||"")],["Registró",r=>'<span class="sub">'+esc(r.Usuario||"")+'</span>']],all("mov").sort((a,b)=>b.Fecha-a.Fecha),true)+'</details>';
  h+='<details class="hist"><summary>Novedades de acceso ('+all("acn").length+')</summary>'+tb("acn",[["Fecha",r=>fd(r.Fecha)],["Novedad",r=>esc(r.Tipo)],["Acceso resultante",r=>esc(r.AccesoResultante||"")],["Detalle",r=>esc(r.Detalle||"")]],all("acn").sort((a,b)=>b.Fecha-a.Fecha),true)+'</details>';
  h+='<details class="hist"><summary>Atenciones por disciplina ('+all("ate").length+')</summary>'+tb("ate",[["Fecha",r=>fd(r.Fecha)],["Disciplina",r=>esc(r.Disciplina)],["Nota",r=>esc(r.Nota||"")],["Registró",r=>'<span class="sub">'+esc(r.Usuario||"")+'</span>']],all("ate").sort((a,b)=>b.Fecha-a.Fecha),true)+'</details>';
  h+='<details class="hist"><summary>Valoraciones mensuales ('+all("val").length+')</summary>'+tb("val",[["Fecha",r=>fd(r.Fecha)],["Profesional",r=>esc(r.Profesional||"")],["Calidad",r=>esc(r.CalidadCategoria||"")],["Plan",r=>'<span style="font-size:13px">'+esc(String(r.Plan||"").slice(0,160))+'</span>']],all("val").sort((a,b)=>b.Fecha-a.Fecha),true)+'</details>';
  h+='<details class="hist"'+(all("est").length?" open":"")+'><summary>Estudios, imágenes y procedimientos ('+all("est").length+')</summary>'+tb("est",[["Fecha",r=>fd(r.Fecha)],["Estudio",r=>esc(r.Nombre)+'<span class="sub">'+esc(r.Tipo||"")+(r.Relevante==="Sí"?" · tener presente":"")+'</span>'],["Qué dice",r=>'<span style="font-size:13px">'+esc(r.Resultado||"")+'</span>'+(r.Seguimiento?'<span class="sub">Seguimiento: '+esc(r.Seguimiento)+'</span>':"")],["Próximo control",r=>r.ProximoControl?fd(r.ProximoControl):""],["Soporte",r=>'<span class="sub">'+esc(r.Soporte||"")+'</span>']],all("est").sort((a,b)=>b.Fecha-a.Fecha),true)+'</details>';
  const vs=vacStatus(p,ST.corte);h+='<details class="hist"><summary>Vacunación VHB ('+all("vac").length+' dosis) · '+esc(vacEtiqueta(vs.code))+'</summary><p class="note">'+esc(vs.txt)+'</p>'+tb("vac",[["Fecha",r=>fd(r.Fecha)],["Serie",r=>esc(r.Serie||"1")],["Dosis",r=>esc(r.NumDosis??"")],["Esquema",r=>'<span style="font-size:13px">'+esc(r.Esquema||"")+'</span>'],["Lote",r=>esc(r.Lote||"")],["Registró",r=>'<span class="sub">'+esc(r.Usuario||"")+'</span>']],all("vac").sort((a,b)=>b.Fecha-a.Fecha),true)+'</details>';
  const ts=txState(p);h+='<details class="hist"><summary>Trasplante · '+esc(p.TxEstado||"Sin evaluar")+' · '+ts.hecho+'/'+ts.apl+' estudios</summary>'+(ts.falta.length?'<p class="note">Faltan: '+esc(ts.falta.map(x=>x.it.split(" · ").pop()).join("; "))+'</p>':'<p class="note">Lista de estudios completa.</p>')+'<button type="button" class="btn sm" data-a="go2tx|'+p.ID+'">Gestionar en Trasplante</button></details>';
  h+='<details class="hist"><summary>Contactos ('+all("ctc").length+')</summary>'+tb("ctc",[["Fecha",r=>fd(r.Fecha)],["Medio",r=>esc(r.Medio)],["Resultado",r=>esc(r.Resultado||"")],["Nota",r=>esc(r.Nota||"")],["Registró",r=>'<span class="sub">'+esc(r.Usuario||"")+'</span>']],all("ctc").sort((a,b)=>b.Fecha-a.Fecha),false)+'</details>';
  return h;}
function pacReg(p){const t=ST.ui.preg||"mov";const T=iso(TODAY());
  if(t==="est")return estForm();
  if(t==="vac"){const s=vacStatus(p,ST.corte);return'<p class="note">'+esc(s.txt)+'</p><button type="button" class="btn" data-a="vacnew|'+p.ID+'">Registrar dosis de vacuna VHB</button> <button type="button" class="lnk" data-a="go|vac">Ver toda la cohorte</button>';}
  if(t==="mov")return'<div class="form"><label class="f">Tipo<select id="r_t">'+opt(MOV_TIPOS,"","Seleccione…")+'</select></label><label class="f">Fecha<input type="date" id="r_f" value="'+T+'"></label><label class="f wide">Detalle y soporte (desistimiento, epicrisis, acta)<input type="text" id="r_d"></label></div><button type="button" class="btn" data-a="pregsave|mov" style="margin-top:8px">Registrar movimiento</button><p class="note">Abandono exige desistimiento firmado o búsqueda activa documentada (ficha CAC dia_23).</p>';
  if(t==="nov")return'<div class="form"><label class="f">Tipo<select id="r_t">'+opt(NOV_TIPOS,"Hospitalización")+'</select></label><label class="f">Inicio<input type="date" id="r_i" value="'+T+'"></label><label class="f">Fin (egreso)<input type="date" id="r_e"></label><label class="f">Causa (hospitalización)<select id="r_c">'+opt(CAUSA_HOSP,"","—")+'</select></label><label class="f">¿Atribuible a ERC o diálisis?<select id="r_at">'+opt(ATRIB,"","—")+'</select></label><label class="f">¿Evitable?<select id="r_ev">'+opt(["Sí","No","En estudio"],"","—")+'</select></label><label class="f wide">Descripción<input type="text" id="r_d"></label></div><button type="button" class="btn" data-a="pregsave|nov" style="margin-top:8px">Registrar novedad</button><p class="note">Mientras la novedad esté abierta, el turno del día propone «Suspendida» y no cuenta inasistencia.</p>';
  if(t==="ate")return'<div class="form"><label class="f">Disciplina<select id="r_x">'+opt(DISCIPLINAS,"Nutrición")+'</select></label><label class="f">Fecha<input type="date" id="r_f" value="'+T+'"></label><label class="f wide">Nota<input type="text" id="r_d"></label></div><button type="button" class="btn" data-a="pregsave|ate" style="margin-top:8px">Registrar atención</button><p class="note">Las fechas de atención por disciplina alimentan la matriz CAC (fechas de valoración por nutrición, psicología, trabajo social, etc.). La valoración mensual registra sola la de nefrología.</p>';
  if(t==="acn")return'<div class="form"><label class="f">Novedad<select id="r_x">'+opt(ACC_NOV,"","Seleccione…")+'</select></label><label class="f">Fecha<input type="date" id="r_f" value="'+T+'"></label><label class="f">Acceso resultante<select id="r_a">'+opt(ACCESOS,"","Sin cambio")+'</select></label><label class="f wide">Detalle<input type="text" id="r_d"></label></div><button type="button" class="btn" data-a="pregsave|acn" style="margin-top:8px">Registrar novedad de acceso</button><p class="note">Si la novedad cambia el acceso (inserción de catéter, primera punción de FAV), se actualiza el acceso actual y la fecha desde la cual lo tiene.</p>';
  if(t==="ctc")return'<div class="form"><label class="f">Fecha<input type="date" id="r_f" value="'+T+'"></label><label class="f">Medio<select id="r_m">'+opt(MEDIOS,"Llamada")+'</select></label><label class="f">Resultado<select id="r_r">'+opt(RESULT_CTC,"")+'</select></label><label class="f wide">Nota<input type="text" id="r_d"></label></div><button type="button" class="btn" data-a="pregsave|ctc" style="margin-top:8px">Registrar contacto</button>';
  return'<div class="form"><label class="f">Examen<select id="r_x">'+opt(EXAMS.map(e=>[e.k,e.l]),"Hb")+'</select></label><label class="f">Valor<input type="text" id="r_v"></label><label class="f">Fecha de toma<input type="date" id="r_f" value="'+T+'"></label><label class="f">Método o escala<input type="text" id="r_m" placeholder="Kt/V: fórmula · escala: nombre"></label></div><button type="button" class="btn" data-a="pregsave|lab" style="margin-top:8px">Registrar paraclínico</button>';}
function pacSave(){if(needUser())return;const isNew=ST.sel.pac==="__new";const o=readPF();
  if(isNew){const miss=["Documento","Apellidos","Nombres","EPS","IngresoUnidad","Turno","Puesto"].filter(k=>!o[k]);if(miss.length){toast("Falta: "+miss.join(", "));return;}
    if(ST.book.pac.some(p=>String(p.Documento)===String(o.Documento))){toast("Ese documento ya existe en el maestro. Búsquelo en «Todos».");return;}
    const p=Object.assign({},ST.ui.pnew,o,{ID:nextPid(),Estado:"Activo",Usuario:ST.user,Actualizado:nowTs()});if(!p.AccesoActual&&p.AccesoInicial){p.AccesoActual=p.AccesoInicial;p.AccesoDesde=p.InicioTRR||p.IngresoUnidad;}
    ST.book.pac.push(p);logW("CREA","pac",p.ID,"");changed();ST.ui.pnew=null;ST.sel.pac=p.ID;reindex();toast("Paciente "+p.ID+" creado.");render();return;}
  const p=IDX.pac.get(ST.sel.pac);const n=updRec("pac",p,o);if(n){p.Usuario=ST.user;p.Actualizado=nowTs();}reindex();toast(n?"Cambios guardados ("+n+" campos).":"Sin cambios.");render();}
function pacRegSave(t){if(needUser())return;const p=IDX.pac.get(ST.sel.pac);const v=id=>($(id)||{}).value||"";
  if(t==="mov"){const tipo=v("r_t"),f=pdate(v("r_f"));if(!tipo||!f){toast("Elija tipo y fecha.");return;}if(tipo==="Abandono"&&v("r_d").trim().length<5){toast("Abandono: describa el soporte (desistimiento o búsqueda activa).");return;}
    addRec("mov","M-",{Paciente:p.ID,Fecha:f,Tipo:tipo,Detalle:v("r_d").trim()});updRec("pac",p,{Estado:tipo==="Reingreso"?"Activo":EGRESO_ESTADO[tipo],FechaEstado:f});if(tipo==="Trasplante")updRec("pac",p,{TxEstado:"Trasplantado",TxFecha:f});}
  else if(t==="nov"){const i=pdate(v("r_i")),e=pdate(v("r_e"));if(!i){toast("Falta la fecha de inicio.");return;}if(e&&e<i){toast("El egreso no puede ser antes del ingreso.");return;}if(v("r_t")==="Hospitalización"&&!v("r_c")){toast("Indique la causa de la hospitalización.");return;}addRec("nov","N-",{Paciente:p.ID,Tipo:v("r_t"),Inicio:i,Fin:e,Descripcion:v("r_d").trim(),Causa:v("r_c"),Atribuible:v("r_at"),Evitable:v("r_ev")});}
  else if(t==="ate"){const f=pdate(v("r_f"));if(!f){toast("Fecha inválida.");return;}addRec("ate","A-",{Paciente:p.ID,Fecha:f,Disciplina:v("r_x"),Nota:v("r_d").trim()});}
  else if(t==="acn"){const f=pdate(v("r_f")),x=v("r_x");if(!f||!x){toast("Elija la novedad y la fecha.");return;}const res=v("r_a")||ACC_NOV_RES[x]||"";addRec("acn","AC-",{Paciente:p.ID,Fecha:f,Tipo:x,Detalle:v("r_d").trim(),AccesoResultante:res});if(res)updRec("pac",p,{AccesoActual:res,AccesoDesde:f});if(x==="Creación de FAV"&&isCVC(p.AccesoActual))updRec("pac",p,{RutaAcceso:"FAV creada, en maduración",FechaRuta:f});if(x==="Remisión a cirugía vascular")updRec("pac",p,{RutaAcceso:"Remitido a cirugía vascular",FechaRuta:f});}
  else if(t==="est"){if(!estSave(p))return;}
  else if(t==="ctc"){const f=pdate(v("r_f"));if(!f){toast("Fecha inválida.");return;}addRec("ctc","K-",{Paciente:p.ID,Fecha:f,Medio:v("r_m"),Resultado:v("r_r"),Nota:v("r_d").trim()});}
  else{const x=v("r_x"),val=v("r_v").trim(),f=pdate(v("r_f"));const e=EX[x];if(!val||!f){toast("Falta valor o fecha.");return;}if(!e.txt){const n=num(val);if(n==null||n<e.lo||n>e.hi){toast(e.l+": valor fuera de rango plausible ("+e.lo+"–"+e.hi+").");return;}}
    addRec("lab","L-",{Paciente:p.ID,FechaToma:f,Examen:x,Valor:e.txt?val:num(val),Metodo:v("r_m").trim()||(x==="KtV"?ST.book.cfgv.ktvMetodo:"")});if(["AntiHBs","HBsAg","AntiHBc"].includes(x)){reindex();vacSync(IDX.pac.get(p.ID));}}
  reindex();toast("Registrado.");render();}


/* ================= turno del día ================= */
function turnoOpts(d){const w=d.getDay();return turnosCfg().filter(t=>t.d.includes(w)).map(t=>t.n);}
function tKey(){return ST.ui.tdate+"|"+ST.ui.tturno;}
function tDefRow(p,d){const ab=absentOn(p,d);const n=ab?p._nov.find(x=>(x.Tipo==="Hospitalización"||x.Tipo==="Viaje / traslado temporal")&&x.Inicio<=d&&(!x.Fin||d<=x.Fin)):null;
  return{sid:"",estado:ab?"Suspendida":"",motivo:ab?(n.Tipo==="Hospitalización"?"Hospitalización":"Viaje o diálisis en otra unidad"):"",causa:n&&n.Causa||"",atrib:n&&n.Atribuible||"",nota:"",min:num(p.DuracionMin)||ST.book.cfgv.durDefault,acc:accessAt(p,d)||"",pp:"",pq:"",ufm:"",tapre:"",tapost:"",fc:"",fr:"",sat:"",glu:"",ktv:"",puesto:num(p.Puesto)||"",tipo:"Programada",motExtra:"",contrato:"",repro:"",ev:[],saved:false,pre:ab,lim:""};}
function tInit(){
  if(!ST.ui.tdate)ST.ui.tdate=iso(TODAY());const d=pdate(ST.ui.tdate);const ops=turnoOpts(d);
  if(!ops.includes(ST.ui.tturno))ST.ui.tturno=ops[0]||"";
  if(ST.ui.tdraft&&ST.ui.tdraft.key===tKey())return;
  ensureIdx();const rows={};const list=[];
  ST.book.pac.forEach(p=>{const ses=p._ses.find(s=>iso(s.Fecha)===ST.ui.tdate&&(s.Turno===ST.ui.tturno||!s.Turno&&p.Turno===ST.ui.tturno));const inT=p.Turno===ST.ui.tturno&&activeAt(p,d);if(!inT&&!ses)return;list.push(p.ID);
    if(ses)rows[p.ID]={sid:ses.ID,estado:ses.Estado,motivo:ses.Motivo||"",causa:"",atrib:"",nota:ses.Nota||"",min:ses.DuracionMin,acc:ses.Acceso||"",pp:ses.PesoPre??"",pq:ses.PesoPost??"",ufm:ses.UFMaquina??"",tapre:ses.TASPre?ses.TASPre+"/"+(ses.TADPre??""):"",tapost:ses.TASPost?ses.TASPost+"/"+(ses.TADPost??""):"",fc:ses.FC??"",fr:ses.FR??"",sat:ses.SatO2??"",glu:ses.Gluco??"",ktv:ses.KtVOCM??"",puesto:ses.Puesto??(num(p.Puesto)||""),tipo:ses.Tipo||"Programada",motExtra:ses.MotivoExtra||"",contrato:ses.PorContrato||"",repro:ses.Reprograma?iso(ses.Reprograma):"",ev:[],saved:true,lim:ses.LimpiezaPuesto||""};
    else rows[p.ID]=tDefRow(p,d);});
  ST.ui.tdraft={key:tKey(),rows,list};
}
function chipsSala(p,d){const g=gidStats(p,d,8),t=taStats(p,d,8),gl=p.DM==="SI"?glucoStats(p,addDays(d,-28),d):null,k=lastLab(p,"KtV",addMonths(d,-3),d),ko=ktvOnline(p,d,8);
  const c=[];if(g.n)c.push('<span class="ch'+(g.pct>4?" bad":"")+'" title="Ganancia interdialítica: peso pre de la sesión menos peso post de la anterior, promedio de '+g.n+' intervalos">GID '+f1(g.kg)+' kg · '+f1(g.pct)+' %</span>');
  if(t.n)c.push('<span class="ch'+(t.sPre>=160?" bad":"")+'" title="Promedio de TA pre-diálisis de las últimas '+t.n+' sesiones">TA '+fmtTA(t.sPre,t.dPre)+'</span>');
  if(gl&&gl.n)c.push('<span class="ch'+(gl.hipo?" bad":"")+'" title="Glucometrías de las últimas 4 semanas">Glu '+f1(gl.avg,0)+(gl.hipo?" · "+gl.hipo+" < 70":"")+'</span>');
  if(k||ko)c.push('<span class="ch'+(((k&&num(k.Valor))||ko.avg)<1.2?" bad":"")+'" title="'+(k?"Kt/V de laboratorio "+fd(k.FechaToma):"")+(ko?" · en línea promedio "+ko.n+" sesiones":"")+'">Kt/V '+(k?f1(num(k.Valor),2):"—")+(ko?" · línea "+f1(ko.avg,2):"")+'</span>');
  return c.length?'<span class="chs">'+c.join("")+'</span>':"";}
function vTurno(){
  tInit();const T=ST.ui.tdraft;const d=pdate(ST.ui.tdate);const ops=turnoOpts(d);
  const L=T.list.map(id=>IDX.pac.get(id)).sort((a,b)=>(num(T.rows[a.ID].puesto)||99)-(num(T.rows[b.ID].puesto)||99));
  const done=L.filter(p=>T.rows[p.ID].saved).length;const pend=L.filter(p=>!T.rows[p.ID].estado).length;
  let h=head("Turno del día","Un clic por paciente: lo que no se toca queda con la prescripción. Cualquier aviso antes de la hora del turno es «Canceló», no inasistencia. Los promedios de GID, TA, glucometría y Kt/V se calculan con las últimas 8 sesiones.",'<button type="button" class="btn" data-a="textra">Agregar paciente (extra o reprogramada)</button><button type="button" class="btn" data-a="texpextra">Exportar sesiones extra por contrato</button><button type="button" class="btn" data-a="tall">Marcar pendientes como realizada</button><button type="button" class="btn primary" data-a="tsave">Guardar turno</button>');
  h+='<div class="copyrow"><label class="f" style="max-width:190px">Fecha del turno<input type="date" id="tdate" value="'+ST.ui.tdate+'"></label>'+(ops.length?'<div class="seg" role="group" aria-label="Turno">'+ops.map(o=>'<button type="button" data-a="tturno|'+o+'" aria-pressed="'+(o===ST.ui.tturno)+'">'+o+'</button>').join("")+'</div>':'<span class="alert warn"><p>'+DIAS_L[d.getDay()]+': no hay turnos configurados ese día (Referencia → Turnos).</p></span>')+
    '<span class="note" id="tcount">'+L.length+' pacientes · '+done+' guardados · '+pend+' sin estado</span></div>';
  if(!L.length)return h+'<div class="panel empty">No hay pacientes asignados a este turno. Asigne turno y puesto en Pacientes, o agregue un paciente extra.</div>'+vMapa(d);
  h+='<div class="panel tablebox" style="padding:0"><table class="turno"><thead><tr><th>Silla</th><th>Paciente</th><th>Estado</th><th>Min</th><th>Acceso</th><th>Peso pre</th><th>Peso post</th><th>UF</th><th>TA pre</th><th>TA post</th><th>FC · FR · SatO2</th><th>Glucometría</th><th>Kt/V línea</th><th>Motivo si no se realizó</th><th title="Desinfección del puesto después del uso">Desinf. puesto</th><th>Eventos</th></tr></thead><tbody>'+L.map(p=>tRow(p)).join("")+'</tbody></table></div>';
  return h+'<p class="note">UF neta = peso pre − peso post (1 kg ≈ 1 L); tasa de UF = UF en mL / peso post / horas de la sesión, en rojo si supera 13 mL/kg/h. «máq. mL» es el volumen ultrafiltrado que muestra la máquina al final; la diferencia con la UF por peso corresponde a líquidos administrados o ingeridos durante la sesión. TA como 130/80. Peso en kg. La silla se puede cambiar solo para esta sesión (máquina dañada); el puesto habitual se cambia en Pacientes. Glucometría solo para pacientes con diabetes. Kt/V en línea: el que reporta la máquina (dialisancia iónica), si lo tiene. «Desinf. puesto»: marque cuando el puesto quedó desinfectado después de ese uso (fuente de la cobertura documental de limpieza que lee IAAS).</p>'+vMapa(d);
}
function tRow(p){const T=ST.ui.tdraft;const r=T.rows[p.ID];const re=r.estado==="Realizada",no=r.estado&&!re;const dis=re?"":" disabled";const P=ST.book.cfgv.puestos||13;const d=pdate(ST.ui.tdate);
  const nevH=p._evt.length;
  let h='<tr data-pid="'+p.ID+'" class="'+(r.saved?"row-saved":r.estado?"row-dirty":"")+'"><td><select data-t="'+p.ID+'|puesto" aria-label="Silla" style="min-width:58px">'+opt(Array.from({length:P},(_,i)=>i+1),r.puesto,"—")+'</select>'+(num(r.puesto)&&num(p.Puesto)&&num(r.puesto)!==num(p.Puesto)?'<span class="sub" style="color:var(--warn)">habitual '+p.Puesto+'</span>':"")+'</td>'+
   '<td style="min-width:230px"><strong>'+esc(nombre(p))+'</strong>'+(r.tipo!=="Programada"?' <span class="tag inst">'+esc(r.tipo)+(r.contrato==="SI"?" · contrato":"")+'</span>':"")+'<span class="sub">'+esc(p.ID)+' · '+esc(p.EPS||"sin EPS")+(r.pre?' · <span style="color:var(--warn)">novedad abierta</span>':"")+'</span>'+chipsSala(p,d)+'</td>'+
   '<td><div class="est">'+ESTADOS_SES.map(([v,l,c])=>'<button type="button" class="'+c+'" data-a="test|'+p.ID+'|'+v+'" aria-pressed="'+(r.estado===v)+'">'+l+'</button>').join("")+'</div></td>'+
   '<td><input class="w-min" type="number" inputmode="numeric" data-t="'+p.ID+'|min" value="'+(r.min??"")+'"'+dis+' aria-label="Minutos"></td>'+
   '<td><select data-t="'+p.ID+'|acc"'+dis+' aria-label="Acceso">'+opt(ACCESOS,r.acc,"—")+'</select></td>'+
   '<td><input class="w-kg" type="text" inputmode="decimal" data-t="'+p.ID+'|pp" value="'+esc(r.pp)+'"'+dis+' aria-label="Peso pre"></td>'+
   '<td><input class="w-kg" type="text" inputmode="decimal" data-t="'+p.ID+'|pq" value="'+esc(r.pq)+'"'+dis+' aria-label="Peso post"></td>'+
   '<td style="min-width:104px"><span data-ufv="'+p.ID+'">'+ufView(p,r)+'</span><input class="w-kg" type="text" inputmode="numeric" data-t="'+p.ID+'|ufm" value="'+esc(r.ufm)+'"'+dis+' aria-label="UF de la máquina en mL" placeholder="máq. mL" style="margin-top:3px;width:84px"></td>'+
   '<td><input class="w-ta" type="text" inputmode="numeric" data-t="'+p.ID+'|tapre" value="'+esc(r.tapre)+'" placeholder="130/80"'+dis+' aria-label="TA pre"></td>'+
   '<td><input class="w-ta" type="text" inputmode="numeric" data-t="'+p.ID+'|tapost" value="'+esc(r.tapost)+'" placeholder="120/75"'+dis+' aria-label="TA post"></td>'+
   '<td style="min-width:130px"><div style="display:flex;gap:3px"><input class="w-min" style="width:42px" type="number" data-t="'+p.ID+'|fc" value="'+esc(r.fc??"")+'"'+dis+' title="FC (lpm)" placeholder="FC"><input class="w-min" style="width:38px" type="number" data-t="'+p.ID+'|fr" value="'+esc(r.fr??"")+'"'+dis+' title="FR (rpm)" placeholder="FR"><input class="w-min" style="width:42px" type="number" data-t="'+p.ID+'|sat" value="'+esc(r.sat??"")+'"'+dis+' title="SatO2 (%)" placeholder="Sat%"></div></td>'+
   '<td><input class="w-tas" type="number" inputmode="numeric" data-t="'+p.ID+'|glu" value="'+esc(r.glu)+'"'+dis+' aria-label="Glucometría" placeholder="mg/dL"></td>'+
   '<td><input class="w-tas" type="text" inputmode="decimal" data-t="'+p.ID+'|ktv" value="'+esc(r.ktv)+'"'+dis+' aria-label="Kt/V en línea"></td>'+
   '<td style="min-width:200px">'+(no?'<select data-t="'+p.ID+'|motivo" data-re="1" aria-label="Motivo">'+opt(MOTIVOS.map(m=>m[0]),r.motivo,"Motivo…")+'</select>'+
     (r.motivo==="Hospitalización"?'<select data-t="'+p.ID+'|causa" aria-label="Causa de la hospitalización" style="margin-top:3px">'+opt(CAUSA_HOSP,r.causa,"Causa de la hospitalización…")+'</select><select data-t="'+p.ID+'|atrib" aria-label="Atribuible" style="margin-top:3px">'+opt(ATRIB,r.atrib,"¿Atribuible a ERC o diálisis?")+'</select>':"")+
     '<input type="text" data-t="'+p.ID+'|nota" value="'+esc(r.nota)+'" placeholder="Detalle (opcional)" style="margin-top:3px">':'<span class="sub">—</span>')+'</td>'+
   '<td>'+limCell(p,r,re)+'</td>'+'<td>'+(()=>{const sv=r.sid?p._evt.filter(e=>e.Sesion===r.sid).length:0;const n=sv+r.ev.length;return'<button type="button" class="btn sm" data-a="tev|'+p.ID+'">'+(n?n+" evento"+(n>1?"s":""):"+ Evento")+'</button>'+(nevH?'<span class="sub">'+nevH+' en historial</span>':"");})()+'</td></tr>';
  if(ST.ui.evOpen===p.ID){const sv=r.sid?p._evt.filter(e=>e.Sesion===r.sid):[];const hist=p._evt.slice(-10).reverse();
    h+='<tr class="evrow" data-pid="'+p.ID+'"><td></td><td colspan="14"><div class="grid2"><div>'+(re?'<h3>Registrar evento de esta sesión</h3><div class="form" style="grid-template-columns:repeat(auto-fill,minmax(150px,1fr))"><label class="f" style="grid-column:span 2">Evento<select id="ev_t">'+opt(EVENTOS,"","Seleccione…")+'</select></label><label class="f">Severidad<select id="ev_s">'+opt(SEV,"Leve")+'</select></label><label class="f" style="grid-column:span 2">Conducta<input type="text" id="ev_c"></label><label class="f">Resuelto<select id="ev_r">'+opt(RESUELTO,"Sí")+'</select></label><label class="f">Hemocultivo (ITS-CVC)<select id="ev_h">'+opt([["Pendiente","Tomado (resultado en Laboratorio)"],["No tomado","No tomado"]],"","—")+'</select></label><label class="chk" style="font-size:13px;align-self:end"><input type="checkbox" id="ev_sp"> Reportar a seguridad del paciente</label></div>'+
    '<div class="copyrow" style="margin-top:6px"><button type="button" class="btn primary sm" data-a="tevadd|'+p.ID+'">Agregar evento</button><span class="note">Se guarda con el turno. El resultado del hemocultivo lo registra Laboratorio → Microbiología; IAAS clasifica el episodio.</span></div>'+
    (sv.length||r.ev.length?'<ul class="note" style="margin:6px 0 0">'+sv.map(e=>'<li>'+esc(e.Tipo)+' · '+esc(e.Severidad)+' · '+esc(e.Resuelto)+' (guardado)</li>').join("")+r.ev.map((e,i)=>'<li>'+esc(e.Tipo)+' · '+esc(e.Severidad)+' · '+esc(e.Resuelto)+' <button type="button" class="lnk" data-a="tevdel|'+p.ID+'|'+i+'">quitar</button></li>').join("")+'</ul>':""):'<p class="note">Marque la sesión como realizada para registrar eventos de esta sesión.</p>')+'</div>'+
    '<div><h3>Historial de eventos del paciente ('+p._evt.length+')</h3>'+(hist.length?'<div class="tablebox"><table class="mini"><tbody>'+hist.map(e=>'<tr><td class="mono">'+fd(e.Fecha)+'</td><td>'+esc(e.Tipo)+'<span class="sub">'+esc(e.Severidad||"")+(e.Conducta?" · "+esc(e.Conducta):"")+'</span></td><td>'+esc(e.Resuelto||"")+'</td></tr>').join("")+'</tbody></table></div>'+(p._evt.length>10?'<p class="note">Últimos 10 de '+p._evt.length+'.</p>':""):'<p class="note">Sin eventos previos.</p>')+'</div></div>'+
    '<div class="copyrow" style="margin-top:6px"><button type="button" class="btn sm" data-a="tev|'+p.ID+'">Cerrar</button></div></td></tr>';}
  return h;}
function tSave(){
  if(needUser())return;const T=ST.ui.tdraft;const d=pdate(ST.ui.tdate);const errs=[];let nNew=0,nUpd=0,nEv=0,nHosp=0;
  T.list.forEach(id=>{const r=T.rows[id];if(!r.estado)return;const p=IDX.pac.get(id);
    if(r.estado==="Realizada"){if(num(r.min)==null||num(r.min)<30||num(r.min)>480)errs.push(id+": minutos fuera de 30-480");if(!r.acc)errs.push(id+": falta el acceso");
      [["tapre","TA pre"],["tapost","TA post"]].forEach(([f,l])=>{if(r[f]&&!parseTA(r[f]))errs.push(id+": "+l+" debe escribirse como 130/80");});
      const pp=num(r.pp),pq=num(r.pq);if(pp!=null&&(pp<20||pp>250))errs.push(id+": peso pre fuera de rango");if(pq!=null&&(pq<20||pq>250))errs.push(id+": peso post fuera de rango");if(pp!=null&&pq!=null&&pp-pq>8)errs.push(id+": UF de más de 8 kg, revise los pesos");if(pp!=null&&pq!=null&&pq-pp>1)errs.push(id+": peso post mayor que el pre en más de 1 kg, revise los pesos");const um=num(r.ufm);if(r.ufm!==""&&r.ufm!=null&&(um==null||um<0||um>8000))errs.push(id+": UF de la máquina en mL (0-8.000)");
      const g=num(r.glu);if(r.glu!==""&&r.glu!=null&&(g==null||g<20||g>700))errs.push(id+": glucometría fuera de rango");const k=num(r.ktv);if(r.ktv!==""&&r.ktv!=null&&(k==null||k<0.3||k>3.5))errs.push(id+": Kt/V en línea fuera de rango");}
    else{if(!r.motivo)errs.push(id+": falta el motivo de la sesión no realizada");if(r.motivo==="Hospitalización"&&!r.causa)errs.push(id+": falta la causa de la hospitalización");}});
  if(errs.length){toast("No se guardó. "+errs.slice(0,3).join(" · ")+(errs.length>3?" …":""));return;}
  T.list.forEach(id=>{const r=T.rows[id];if(!r.estado)return;const p=IDX.pac.get(id);const re=r.estado==="Realizada";const a=parseTA(r.tapre),b=parseTA(r.tapost);
    const o={Fecha:d,Paciente:id,Turno:ST.ui.tturno,Puesto:num(r.puesto),Tipo:r.tipo||"Programada",MotivoExtra:r.motExtra||"",PorContrato:r.contrato||"",Reprograma:pdate(r.repro),Estado:r.estado,Motivo:re?"":r.motivo,Responsable:re?"":(MOT_RESP[r.motivo]||"Otro"),Nota:re?"":r.nota,DuracionMin:re?num(r.min):null,Acceso:re?r.acc:"",PesoPre:re?num(r.pp):null,PesoPost:re?num(r.pq):null,TASPre:re&&a?a[0]:null,TADPre:re&&a?a[1]:null,TASPost:re&&b?b[0]:null,TADPost:re&&b?b[1]:null,FC:re?num(r.fc):null,FR:re?num(r.fr):null,SatO2:re?num(r.sat):null,Gluco:re?num(r.glu):null,KtVOCM:re?num(r.ktv):null};const uf=re?ufCalc(num(r.pp),num(r.pq),num(r.min)):null;o.UFNeta=uf&&uf.kg!=null?Math.round(uf.kg*100)/100:null;o.UFR=uf&&uf.ufr!=null?Math.round(uf.ufr*10)/10:null;o.UFMaquina=re?num(r.ufm):null;o.LimpiezaPuesto=re&&r.lim==="SI"?"SI":"";
    let s;if(r.sid){s=ST.book.ses.find(x=>x.ID===r.sid);if(updRec("ses",s,o))nUpd++;}else{s=addRec("ses","S-",o);r.sid=s.ID;nNew++;}
    r.ev.forEach(e=>{const sp=e._sp;delete e._sp;const ev=addRec("evt","E-",Object.assign({Fecha:d,Paciente:id,Sesion:s.ID},e,{FechaCierre:e.Resuelto==="Sí"?d:null}));nEv++;
      if(sp)addRec("seg","SP-",{Fecha:d,Paciente:id,Clasificacion:"Por clasificar",Categoria:e.Tipo,Severidad:e.Severidad,Descripcion:e.Tipo+(e.Conducta?" · "+e.Conducta:""),AccionInmediata:e.Conducta,Estado:"Abierto",Evento:ev.ID});});r.ev=[];r.saved=true;
    if(!re&&r.motivo==="Hospitalización"){const open=p._nov.find(n=>n.Tipo==="Hospitalización"&&n.Inicio<=d&&(!n.Fin||n.Fin>=d));if(!open){addRec("nov","N-",{Paciente:id,Tipo:"Hospitalización",Inicio:d,Fin:null,Descripcion:r.nota||r.causa,Causa:r.causa,Atribuible:r.atrib||"En estudio"});nHosp++;}else if(r.causa&&!open.Causa)updRec("nov",open,{Causa:r.causa,Atribuible:r.atrib||open.Atribuible});}
    if(re&&r.acc&&r.acc!==p.AccesoActual){updRec("pac",p,{AccesoActual:r.acc,AccesoDesde:d});}});
  reindex();toast("Turno guardado: "+nNew+" nuevas, "+nUpd+" corregidas, "+nEv+" eventos"+(nHosp?", "+nHosp+" hospitalización abierta (registre el egreso cuando salga)":"")+".");render();
}
function dlgExtra(){const d=pdate(ST.ui.tdate);const T=ST.ui.tdraft;const cand=ST.book.pac.filter(p=>activeAt(p,d)&&!T.list.includes(p.ID)).sort((a,b)=>String(a.ID).localeCompare(b.ID));const P=ST.book.cfgv.puestos||13;
  openDlg("Agregar paciente al turno "+ST.ui.tturno+" del "+fd(d),'<div class="form"><label class="f wide">Paciente<select id="x_p">'+opt(cand.map(p=>[p.ID,p.ID+" · "+nombre(p)+" · "+(p.EPS||"")+" · "+(p.Turno||"sin turno")]),"","Seleccione…")+'</select></label><label class="f">Tipo<select id="x_t">'+opt(["Extra","Reprogramada"],"Extra")+'</select></label><label class="f">Silla<select id="x_s">'+opt(Array.from({length:P},(_,i)=>i+1),"","—")+'</select></label><label class="f">Motivo de la sesión extra<select id="x_m">'+opt(MOT_EXTRA,"","—")+'</select></label><label class="f">Fecha original (si es reprogramada)<input type="date" id="x_r"></label><label class="chk wide" style="font-size:14px"><input type="checkbox" id="x_c"> Requiere solicitud a la EPS (sesión por encima del contrato)</label></div><p class="note">La sesión extra no cambia el turno habitual del paciente. Las marcadas «por contrato» salen en la exportación para la solicitud a la EPS.</p>',"Agregar",()=>{
    const id=$("x_p").value;if(!id)return"Elija el paciente.";const t=$("x_t").value;if(t==="Reprogramada"&&!$("x_r").value)return"Indique la fecha de la sesión que se reprograma.";
    const p=IDX.pac.get(id);const r=tDefRow(p,d);r.tipo=t;r.motExtra=$("x_m").value;r.contrato=$("x_c").checked?"SI":"";r.repro=$("x_r").value;r.puesto=num($("x_s").value)||"";T.rows[id]=r;T.list.push(id);render();toast(id+" agregado como "+t.toLowerCase()+". Guarde el turno al terminar.");});}
function dlgExpExtra(){const m=ym(pdate(ST.ui.tdate)||ST.corte);openDlg("Sesiones extra por contrato",'<label class="f">Mes<input type="month" id="xe_m" value="'+m+'"></label><p class="note">Incluye las sesiones extra marcadas «por contrato» y los pacientes cuya prescripción del mes supera el máximo contractual de su EPS (Referencia).</p>',"Exportar",()=>{expExtra($("xe_m").value);});}
function expExtra(mes){ensureIdx();const ms=pdate(mes+"-01"),me=monthEnd(ms);const rows=[];const C=ST.book.cfgv;
  ST.book.pac.forEach(p=>{if(!overlaps(p,ms,me))return;const S=sesIn(p,ms,me);const prog=progDays(p,ms,me).length;const extra=S.filter(s=>s.Tipo==="Extra"&&s.PorContrato==="SI");const mx=C.maxSes[p.EPS]??C.maxSes.OTRA;
    extra.forEach(s=>rows.push({p,f:s.Fecha,t:s.Turno,mot:s.MotivoExtra||"",est:s.Estado,prog,mx,obs:"Sesión extra registrada"}));
    if(mx!=null&&prog>mx)rows.push({p,f:null,t:p.Turno,mot:"Prescripción del mes ("+prog+") supera el máximo contractual ("+mx+")",est:"Proyectada",prog,mx,obs:(prog-mx)+" sesiones por encima del contrato"});});
  exportSheets("Sesiones_extra_contrato_"+mes+".xlsx",[["Solicitud EPS",rows.sort((a,b)=>String(a.p.EPS).localeCompare(b.p.EPS)),[["EPS",r=>r.p.EPS],["ID",r=>r.p.ID],["Tipo doc.",r=>r.p.TipoDoc],["Documento",r=>r.p.Documento],["Paciente",r=>nombre(r.p)],["Fecha",r=>r.f],["Turno",r=>r.t],["Motivo",r=>r.mot],["Estado",r=>r.est],["Prescritas en el mes",r=>r.prog],["Máximo contractual",r=>r.mx],["Observación",r=>r.obs]]]]);}
function vMapa(d){const P=ST.book.cfgv.puestos||13;const w=d.getDay();const T=turnosCfg().filter(t=>t.d.includes(w));const act=ST.book.pac.filter(p=>activeAt(p,d));
  const jor=[...new Set(T.map(t=>t.j))];const by={};const draft=ST.ui.tdraft&&ST.ui.tdraft.key===tKey()?ST.ui.tdraft:null;
  act.forEach(p=>{const t=T.find(x=>x.n===p.Turno);if(!t)return;let pu=num(p.Puesto);const s=p._ses.find(x=>iso(x.Fecha)===iso(d)&&num(x.Puesto));if(s)pu=num(s.Puesto);if(draft&&p.Turno===ST.ui.tturno&&draft.rows[p.ID])pu=num(draft.rows[p.ID].puesto)||pu;if(!pu)return;const k=t.j+"|"+pu;(by[k]=by[k]||[]).push(p.ID);});
  const asig=Object.values(by).reduce((a,b)=>a+b.length,0);const cap=jor.length*P;const sin=act.filter(p=>T.some(t=>t.n===p.Turno)&&!num(p.Puesto));const dup=Object.values(by).filter(a=>a.length>1).length;
  let h='<div class="panel"><div class="mhead"><h3 style="margin:0">Sillas del '+DIAS_L[w]+' '+fd(d)+'</h3><span class="note">'+asig+' de '+cap+' cupos de este día ocupados'+(cap?' ('+pct(asig/cap)+')':"")+(dup?' · <strong style="color:var(--bad)">'+dup+' sillas con dos pacientes</strong>':"")+'</span></div><div class="tablebox" style="margin-top:10px"><div class="pmap" style="grid-template-columns:90px repeat('+P+',minmax(44px,1fr))"><div class="h"></div>';
  for(let i=1;i<=P;i++)h+='<div class="h" style="text-align:center">'+i+'</div>';
  jor.forEach(j=>{h+='<div class="h">'+j+'</div>';for(let i=1;i<=P;i++){const a=by[j+"|"+i];h+='<div class="'+(a?(a.length>1?"dup":"oc"):"free")+'" title="'+(a?a.join(", "):"Libre")+'">'+(a?a.join("/"):"·")+'</div>';}});
  h+='</div></div>'+(sin.length?'<p class="note">Activos de este día sin silla: '+sin.map(p=>esc(p.ID)).join(", ")+'</p>':"")+'<p class="note">Turnos de este día: '+T.map(t=>esc(t.n)).join(" · ")+'. Dos turnos de la misma jornada que comparten día (por ejemplo M-J-S y M-J-V el martes) compiten por las mismas sillas.</p></div>';return h;}

