  for(let i=5;i<L.length;i++){const r=L[i];if(!r||!r[1])continue;const f=pdate(r[0]);const p=getP(r[1],r[2]);if(!p||!f){skip++;continue;}
    LM.forEach(([k,c])=>{const v=r[c];if(v==null||v==="")return;const n=num(v);if(n==null)return;add("lab","L-",{Paciente:p.ID,FechaToma:f,Examen:k,Valor:typeof v==="string"&&/[<>]/.test(v)?v.trim():n,Metodo:k==="KtV"?"Método no registrado en el Dashboard":"Importado (fecha = mes del bloque)"});nL++;});}
  if(skip)W.push("Laboratorios: "+skip+" filas con ID que no está en el maestro (números jubilados u otra modalidad); no se importaron.");
  /* vacunación */
  const V=aoa(wb,"8.VACUNACION_HEPB")||[];for(let i=5;i<V.length;i++){const r=V[i];if(!r||!r[0])continue;const p=getP(r[0],r[1]);if(!p)continue;const v=num(r[8]),f=pdate(r[7]);if(v!=null&&f){add("lab","L-",{Paciente:p.ID,FechaToma:f,Examen:"AntiHBs",Valor:v,Metodo:"Importado de vacunación"});nL++;}if(/NO RESPONDEDOR/.test(norm(r[13]))&&!/REFUERZO/.test(norm(r[13])))p.VHBNoRespondedor="SI";}
