const pxNoAnul=r=>!String(r.Nota||"").startsWith("[ANULADO]");

/* ---------- utilidades de cálculo ---------- */
function pxPer(per){const ms=pdate(per+"-01");return{ms,me:monthEnd(ms)};}
function pxHDM(per){const H=pxHD();if(!H)return null;ensureIdx();const{ms,me}=pxPer(per);const L=x=>x.filter(live);const inM=(d)=>d&&d>=ms&&d<=me;
  return{ms,me,pac:pacs().filter(p=>overlaps(p,ms,me)),evt:L(H.evt).filter(e=>inM(e.Fecha)),aud:L(H.aud).filter(a=>inM(a.Fecha)),atb:L(H.atb),ses:L(H.ses).filter(s=>inM(s.Fecha)&&s.Estado==="Realizada"),seg:L(H.seg)};}
function pxManSum(per,mat,id){return PX.book.man.filter(m=>m.Periodo===per&&m.Matriz===mat&&m.Indicador===id&&pxNoAnul(m)).map(m=>({p:PROG[m.Programa]?PROG[m.Programa].n:m.Programa||"Manual",num:num(m.Numerador)||0,den:num(m.Denominador)||0}));}
function pxLstM(per,keys){const R=PX.book.lst.filter(x=>String(x.Fecha).startsWith(per)&&keys.includes(x.Lista));return{n:R.length,cum:R.reduce((a,x)=>a+(num(x.Cumplidos)||0),0),apl:R.reduce((a,x)=>a+(num(x.Aplicables)||0),0),conf:R.filter(x=>num(x.Aplicables)>0&&num(x.Cumplidos)===num(x.Aplicables)).length};}
function pxRes(def,parts){const n=parts.reduce((a,p)=>a+(p.num||0),0),d=parts.reduce((a,p)=>a+(p.den||0),0);const val=d?n/d*def.f:null;let est="Sin dato";
  if(val!=null){if(def.s==="seg"||def.meta==null)est="Seguimiento";else est=(def.s==="down"?val<=def.meta:val>=def.meta)?"Cumple":"No cumple";}return Object.assign({},def,{num:n,den:d,val,est,parts:parts.filter(p=>p.num||p.den||p.sd)});}
function pxFmt(r){if(!r||r.val==null)return"—";return f1(r.val,r.f===1?0:(r.id==="IAAS-02"||r.id==="IAAS-09"?2:1))+(r.u==="%"?" %":"");}
const pxEstCls=e=>e==="Cumple"?"ok":e==="No cumple"?"bad":e==="Seguimiento"?"info":"base";

