/* Módulo nativo del portal (no iframe): comparte usuarios, mensajes, Laboratorio, Producción, SP, IAAS y PROA.
   Libro propio «Libro del programa VIH» (objeto VXS), prefijo de funciones vx, acciones data-x. */
/* ===================== RIESGO CARDIOVASCULAR Y FUNCIÓN RENAL (compartido portal / Nefroprotección) =====================
   Fórmulas transcritas de las publicaciones; ninguna está validada por la IPS. La decisión clínica es del profesional.
   - CKD-EPI 2021 sin raza: Inker LA et al. N Engl J Med 2021;385:1737-49.
   - Cockcroft-Gault: Cockcroft DW, Gault MH. Nephron 1976;16:31-41 (depuración estimada en mL/min, no normalizada).
     La piden los nominales de prediálisis/TMND de la EPS; la CAC usa CKD-EPI 2021 para estadificar.
   - SCORE2 (SCORE2 working group, Eur Heart J 2021;42:2439-54): coeficientes, supervivencia basal y calibración de la
     región de riesgo alto (la que aplicó PURE-Colombia). Recalibración para Colombia: López-López JP et al., PURE-Colombia,
     Eur J Prev Cardiol 2025;32(7):564-72 (multiplicar por 0,75 en mujeres y 0,61 en hombres). Válido de 40 a 69 años,
     sin diabetes ni enfermedad cardiovascular establecida.
   - Framingham general (D'Agostino RB et al. Circulation 2008;117:743-53). Ajuste para Colombia de la GPC de dislipidemias
     MinSalud-Colciencias (multiplicar por 0,75); la GPC no precisa la versión de Framingham. PURE-Colombia propone otros
     factores (0,67 mujeres; 0,27 hombres) y se muestran aparte.
   - Categoría automática por ERC: ESC 2021 (Visseren FLJ et al. Eur Heart J 2021;42:3227-337). La herramienta técnica de
     la CAC también reconoce alto riesgo automático con TFGe < 45 o albuminuria persistente.
*/
const RCV=(function(){
"use strict";
function ckdepi(scr,age,female){if(!(scr>0)||age==null)return null;const k=female?0.7:0.9,a=female?-0.241:-0.302;return 142*Math.pow(Math.min(scr/k,1),a)*Math.pow(Math.max(scr/k,1),-1.2)*Math.pow(0.9938,age)*(female?1.012:1);}
function cockcroft(scr,age,kg,female){if(!(scr>0)||age==null||!(kg>0))return null;return(140-age)*kg/(72*scr)*(female?0.85:1);}
const MMOL=38.67; /* mg/dL de colesterol → mmol/L */
const S2={M:{age:0.3742,smk:0.6012,sbp:0.2777,tc:0.1458,hdl:-0.2698,xsmk:-0.0755,xsbp:-0.0255,xtc:-0.0281,xhdl:0.0426,s0:0.9605,sc1:0.3207,sc2:0.9360,col:0.61},
          F:{age:0.4648,smk:0.7744,sbp:0.3131,tc:0.1002,hdl:-0.2606,xsmk:-0.1088,xsbp:-0.0277,xtc:-0.0226,xhdl:0.0613,s0:0.9776,sc1:0.5710,sc2:0.9369,col:0.75}};
function score2(o){const s=o.sexo==="F"?"F":o.sexo==="M"?"M":null;const miss=[];if(!s)miss.push("sexo");if(o.edad==null)miss.push("edad");if(o.pas==null)miss.push("PA sistólica");if(o.ct==null)miss.push("colesterol total");if(o.hdl==null)miss.push("HDL");if(o.tab==null)miss.push("tabaquismo");
  if(miss.length)return{ok:false,why:"Falta: "+miss.join(", ")+"."};
  if(o.edad<40||o.edad>69)return{ok:false,why:"SCORE2 aplica de 40 a 69 años (para 70 o más existe SCORE2-OP, no recalibrado para Colombia)."};
  if(o.dm)return{ok:false,why:"SCORE2 no aplica con diabetes (existe SCORE2-Diabetes, no recalibrado para Colombia)."};
  if(o.ecv)return{ok:false,why:"No se calcula con enfermedad cardiovascular establecida: es riesgo muy alto."};
  const b=S2[s],cage=(o.edad-60)/5,csbp=(o.pas-120)/20,ctc=o.ct/MMOL-6,chdl=(o.hdl/MMOL-1.3)/0.5,smk=o.tab?1:0;
  const lp=b.age*cage+b.smk*smk+b.sbp*csbp+b.tc*ctc+b.hdl*chdl+b.xsmk*smk*cage+b.xsbp*csbp*cage+b.xtc*ctc*cage+b.xhdl*chdl*cage;
  const unc=1-Math.pow(b.s0,Math.exp(lp));const reg=1-Math.exp(-Math.exp(b.sc1+b.sc2*Math.log(-Math.log(1-unc))));const col=reg*b.col;
  const lim=o.edad<50?[2.5,7.5]:[5,10];const cat=col*100<lim[0]?"Bajo a moderado":col*100<lim[1]?"Alto":"Muy alto";
  return{ok:true,r:col,rEU:reg,f:b.col,cat,lim,why:"Región de riesgo alto × "+String(b.col).replace(".",",")+" (PURE-Colombia). Categoría con umbrales ESC 2021 para "+(o.edad<50?"< 50":"50–69")+" años ("+String(lim[0]).replace(".",",")+" y "+String(lim[1]).replace(".",",")+" %); esos umbrales no se validaron para la recalibración colombiana."};}
const FR={M:{age:3.06117,tc:1.12370,hdl:-0.93263,sbpU:1.93303,sbpT:1.99881,smk:0.65451,dm:0.57367,mean:23.9802,s0:0.88936,pure:0.27},
          F:{age:2.32888,tc:1.20904,hdl:-0.70833,sbpU:2.76157,sbpT:2.82263,smk:0.52873,dm:0.69154,mean:26.1931,s0:0.95012,pure:0.67}};
function framingham(o){const s=o.sexo==="F"?"F":o.sexo==="M"?"M":null;const miss=[];if(!s)miss.push("sexo");if(o.edad==null)miss.push("edad");if(o.pas==null)miss.push("PA sistólica");if(o.ct==null)miss.push("colesterol total");if(o.hdl==null)miss.push("HDL");if(o.tab==null)miss.push("tabaquismo");if(o.antiHTA==null)miss.push("tratamiento antihipertensivo");
  if(miss.length)return{ok:false,why:"Falta: "+miss.join(", ")+"."};
  if(o.edad<30||o.edad>74)return{ok:false,why:"Framingham general se derivó en personas de 30 a 74 años."};
  const b=FR[s];const lp=b.age*Math.log(o.edad)+b.tc*Math.log(o.ct)+b.hdl*Math.log(o.hdl)+(o.antiHTA?b.sbpT:b.sbpU)*Math.log(o.pas)+(o.tab?b.smk:0)+(o.dm?b.dm:0);
  const r=1-Math.pow(b.s0,Math.exp(lp-b.mean));
  return{ok:true,r0:r,r:r*0.75,rPure:r*b.pure,why:"Framingham general 2008 × 0,75 (ajuste de la GPC colombiana de dislipidemias). Con el factor de PURE-Colombia ("+String(b.pure).replace(".",",")+") sería "+(Math.round(r*b.pure*1000)/10).toString().replace(".",",")+" %."+(o.ecv?" Con enfermedad cardiovascular establecida la escala no aplica: riesgo muy alto.":"")};}
/* Categoría automática (sin escala) */
function auto(o){const W=[];let cat=null;const up=c=>{const r={"Alto":1,"Muy alto":2};if(!cat||r[c]>r[cat])cat=c;};
  if(o.ecv){up("Muy alto");W.push("enfermedad cardiovascular aterosclerótica establecida");}
  const t=o.tfg,a=o.rac;
  if(t!=null){if(t<30||(t<45&&a!=null&&a>30)){up("Muy alto");W.push("ERC grave (TFGe < 30, o 30–44 con RAC > 30)");}
    else if((t<45&&(a==null||a<=30))||(t<60&&a!=null&&a>=30&&a<=300)||(a!=null&&a>300)){up("Alto");W.push("ERC moderada (TFGe 30–44 con RAC < 30; 45–59 con RAC 30–300; o RAC > 300)");}}
  if(o.tfgG5)up("Muy alto");
  return cat?{cat,why:W.join("; ")+" (ESC 2021)."}:null;}
function evalAll(o){const A=auto(o),S=score2(o),F=framingham(o);
  let main=null;if(A)main={src:"auto",cat:A.cat,txt:A.cat+" por "+A.why};
  else if(S.ok)main={src:"score2",cat:S.cat,r:S.r,txt:"SCORE2-Colombia "+pct(S.r)+" · "+S.cat};
  else if(F.ok)main={src:"fram",r:F.r,txt:"Framingham ajustado "+pct(F.r)};
  return{auto:A,score2:S,fram:F,main};}
const pct=r=>r==null?"—":(Math.round(r*1000)/10).toLocaleString("es-CO",{minimumFractionDigits:1,maximumFractionDigits:1})+" %";
const REFS=["SCORE2 working group and ESC Cardiovascular risk collaboration. SCORE2 risk prediction algorithms. Eur Heart J. 2021;42:2439-54.",
 "López-López JP, et al. External validation and comparison of six cardiovascular risk prediction models in the PURE-Colombia study. Eur J Prev Cardiol. 2025;32(7):564-72.",
 "D'Agostino RB Sr, et al. General cardiovascular risk profile for use in primary care: the Framingham Heart Study. Circulation. 2008;117:743-53.",
 "Ministerio de Salud y Protección Social – Colciencias. Guía de práctica clínica de dislipidemias (Framingham recalibrado para Colombia: riesgo × 0,75).",
 "Visseren FLJ, et al. 2021 ESC Guidelines on cardiovascular disease prevention in clinical practice. Eur Heart J. 2021;42:3227-337.",
 "Inker LA, et al. New creatinine- and cystatin C-based equations to estimate GFR without race. N Engl J Med. 2021;385:1737-49.",
 "Cockcroft DW, Gault MH. Prediction of creatinine clearance from serum creatinine. Nephron. 1976;16:31-41."];
return{ckdepi,cockcroft,score2,framingham,auto,evalAll,pct,REFS};
})();

/* ================= v0.5 · barra fija de reporte, novedades, tablero gerencial, oportunidad CE, RCV en VIH ================= */
/* Acciones propias con data-g (no tocan los despachadores data-p, data-x ni data-ce). */
const SIGC_VER="0.5";

/* ---------- barra fija: evento adverso y novedad del servicio ---------- */
function pxFabProg(){const v=PX.view;return PROG[v]&&(PROG[v].g==="mis"||PROG[v].g==="apo")?v:"";}
function pxFab(){let f=document.getElementById("pxfab");if(!f){f=document.createElement("div");f.id="pxfab";f.className="pxfab";f.setAttribute("role","region");f.setAttribute("aria-label","Reportes rápidos");document.body.appendChild(f);}
  const on=!!(PX.user&&PX.book);f.hidden=!on;document.body.classList.toggle("hasfab",on);if(!on){f.innerHTML="";return;}
  const p=pxFabProg();const ab=(PX.book.msg||[]).filter(m=>m.Hilo===m.ID&&pxNovEs(m)&&!["Cerrado","Respondido"].includes(m.Estado)).length;
  f.innerHTML='<button type="button" class="pxfab-b bad" data-g="fabsp" title="Registrar un incidente o evento adverso en Seguridad del paciente'+(p?" (programa "+esc(PROG[p].n)+")":"")+'"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3l9 16H3z"/><path d="M12 10v4M12 17v.5"/></svg><span class="fl">Reportar evento adverso</span><span class="fs">Evento adverso</span></button>'+
   '<button type="button" class="pxfab-b" data-g="fabnov" title="Enviar una novedad del servicio a Coordinación asistencial"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 5h16v11H8l-4 4z"/><path d="M12 8v4M12 14v.5"/></svg><span class="fl">Novedad a Coordinación</span><span class="fs">Novedad a Coordinación</span>'+(ab&&pxAdmin()?'<b class="cnt">'+ab+'</b>':'')+'</button>';}
const NOV_TIPO=["Talento humano (ausencia, incapacidad, turno sin cubrir)","Equipo biomédico o tecnología","Insumos o medicamentos","Infraestructura o servicios públicos (agua, energía)","Sistema de información o conectividad","Agenda, citas o transporte del paciente","Barrera de la EPS (autorización, red, contrato)","Paciente o familia (queja, situación social)","Otra"];
const pxNovEs=m=>String(m.Asunto||"").startsWith("Novedad del servicio");
function pxNovDest(){const a=PX.book.usr.find(u=>u.Activo!=="NO"&&u.Area==="Coordinación asistencial");if(a)return"a:Coordinación asistencial";const ad=PX.book.usr.find(u=>u.Activo!=="NO"&&u.Rol==="Administrador");return ad?"u:"+ad.ID:"";}
function pxDlgNov(){const p=pxFabProg();const to=pxNovDest();
  openDlg("Novedad del servicio para Coordinación asistencial",'<p class="note">Queda como notificación formal en Mensajes, con fecha, hora, acuse de lectura y respuesta. Para un incidente o evento adverso use «Reportar evento adverso».</p><div class="form">'+
   '<label class="f wide">Tipo de novedad<select id="nv_t">'+opt(NOV_TIPO,NOV_TIPO[0])+'</select></label>'+
   '<label class="f">Programa o servicio<select id="nv_p">'+opt(PROGS.filter(x=>x.k!=="ger").map(x=>[x.k,x.n]),p,"—")+'</select></label>'+
   '<label class="f">Prioridad<select id="nv_pr">'+opt(MSG_PRI,"Rutina")+'</select></label>'+
   '<label class="f">¿Afecta la atención de hoy?<select id="nv_af">'+opt(["No","Sí"],"No")+'</select></label>'+
   '<label class="f">Paciente (ID, si aplica)<input type="text" id="nv_pa"></label>'+
   '<label class="f">Plazo de respuesta (opcional)<input type="date" id="nv_pz"></label>'+
   '<label class="f wide">Descripción de la novedad<textarea id="nv_d" rows="4" placeholder="Qué pasó, desde cuándo, a quién afecta y qué se hizo de inmediato"></textarea></label></div>'+
   (to?'<p class="note">Destino: '+esc(pxParaTxt(to))+'.</p>':'<p class="note" style="color:var(--bad)">No hay usuario activo del área Coordinación asistencial ni administrador en el libro.</p>'),"Enviar novedad",()=>{
   if(!to)return"No hay destinatario en el libro institucional.";const d=$("nv_d").value.trim();if(d.length<10)return"Describa la novedad (al menos 10 caracteres).";
   const t=$("nv_t").value,pg=$("nv_p").value,af=$("nv_af").value==="Sí";const pr=$("nv_pr").value;
   const r=pxAdd("msg","M-",{Hilo:"",FechaHora:pxNow(),De:PX.user.ID,Para:to,Tipo:af?"Alerta":"Información",Prioridad:pr,Asunto:"Novedad del servicio · "+t.split(" (")[0]+(pg&&PROG[pg]?" · "+PROG[pg].n:""),Cuerpo:(af?"[AFECTA LA ATENCIÓN DE HOY]\n":"")+"Tipo: "+t+"\n"+d,Paciente:$("nv_pa").value.trim(),Programa:pg,Plazo:$("nv_pz").value,Estado:"Enviado"});r.Hilo=r.ID;
   pxBar();if(!document.getElementById("pxmain").hidden)pxRender();toast("Novedad enviada a "+pxParaTxt(to)+".");});}

/* ---------- Nefroprotección en segundo plano (para el tablero) ---------- */
function pxNefroEnsure(){const box=document.getElementById("nefroapp");const url=pxNefroURL();
  if(!pxNefroFrame()||box.dataset.src!==(url||"embebido")){box.dataset.src=url||"embebido";
    box.innerHTML='<div class="wrap" style="padding-block:10px 0"><div class="copyrow" style="justify-content:space-between"><p class="note" style="margin:0">Ruta de Nefroprotección v8 · '+(url?'cargada desde el servidor ('+esc(url)+'): usa la base de datos del programa.':'embebida en el sistema: trabaja con el libro Excel'+(PX.demo?' y datos ficticios':'')+'; la base de datos solo funciona cuando la Ruta se abre desde el servidor.')+' Sus cambios sin descargar se pierden al salir del sistema.</p>'+(pxAdmin()?'<button type="button" class="btn sm" data-p="nefrocfg">Configurar servidor</button>':'')+'</div></div><iframe id="nefroframe" title="Ruta de Nefroprotección" style="display:block;width:100%;height:calc(100vh - 150px);min-height:620px;border:0;border-top:1px solid var(--line);background:#121820"></iframe>';
    const f=pxNefroFrame();if(url)f.src=url;else f.srcdoc=pxNefroSrcdoc();}}
function pxNefroK(){const w=pxNefroWin();try{if(w&&w.MG&&typeof w.MG.kpi==="function"&&w.MG.book)return w.MG.kpi();}catch(e){}return null;}
let GER_WAIT=null;
function pxGerNefroWait(){if(GER_WAIT)return;let n=0;GER_WAIT=setInterval(()=>{n++;const k=pxNefroK();if(k||n>60){clearInterval(GER_WAIT);GER_WAIT=null;if(PX.view==="ger"&&PX.user)pxRender();}},500);}

/* ---------- tablero gerencial ---------- */
const GER_BANDS=[90,70]; /* bandas de color del tablero (convención de visualización, no norma) */
function gerLogro(i){const v=i.val,m=i.meta;if(v==null||m==null||isNaN(v))return null;if(i.dir==="down"){if(m===0)return v===0?1:0;return v<=m?1:Math.min(m/v,1);}return m<=0?1:Math.min(v/m,1);}
function gerEn(i){const v=i.val,m=i.meta;if(v==null||m==null)return null;if(i.dir==="down")return i.strict?v<m:v<=m;return i.strict?v>m:v>=m;}
function gerProg(k,n,g){return{k,n:n||(PROG[k]?PROG[k].n:k),g:g||(PROG[k]?PROG[k].g:""),st:"ok",why:"",ind:[],kpi:[],risk:[]};}
function gerFin(P){P.ind.forEach(i=>{i.logro=gerLogro(i);i.en=gerEn(i);});const M=P.ind.filter(i=>i.logro!=null);P.nMeta=M.length;P.nOk=M.filter(i=>i.en).length;P.score=M.length?M.reduce((a,i)=>a+i.logro,0)/M.length*100:null;return P;}
const gerFmt=(v,u)=>v==null||isNaN(v)?"—":f1(v,u==="%"||u==="días"?1:2)+(u==="%"?" %":u?" "+u:"");
function gerAtProg(L,isAt,isOut){const prog=L.length,at=L.filter(isAt).length,out=L.filter(isOut).length;return{prog,at,out,pc:prog?at/prog*100:null};}

function gerNefro(m){const P=gerProg("nefro");const K=pxNefroK();
  if(!K){P.st="sd";const w=pxNefroWin();if(pxNefroURL()){P.why="La Ruta se carga desde el servidor; su tablero se consulta dentro del módulo.";}
    else if(PX.demo){P.why="Calculando la cohorte ficticia de Nefroprotección…";pxNefroEnsure();pxGerNefroWait();}
    else P.why=w?"Abra Nefroprotección y cargue el libro del programa; el tablero lo toma de allí mientras la sesión esté abierta.":"Abra Nefroprotección y cargue el libro del programa.";return gerFin(P);}
  K.ind.forEach(i=>P.ind.push({id:i.code,n:i.n,sec:i.sec,val:i.pc,u:"%",meta:i.meta,dir:"up",strict:true,src:i.src==="CAC"?"CAC (alto)":i.src==="INST"?"Institucional":"Línea de base",nd:i.num+" / "+i.den}));
  const pv=K.atProg.prev,mc=K.atProg.mes;
  P.ind.push({id:"AT-PROG",n:"Atenciones atendidas sobre programadas · mes anterior",val:pv.pc,u:"%",meta:95,dir:"up",src:"Institucional",nd:pv.T.at+" / "+pv.T.prog});
  P.kpi.push([K.activos,"activos al corte"],[mc.pc==null?"—":f1(mc.pc,1)+" %","atendidas / programadas en el mes en curso",mc.pc!=null&&mc.pc<95?"warn":""],[K.alertas,"con alerta clínica",K.alertas?"bad":""],[K.venc,"actividades del plan vencidas o sin fecha de realización",K.venc?"warn":""],[K.g3,"en grupo 3 (ERC avanzada)"]);
  if(K.alertas)P.risk.push({l:"bad",t:K.alertas+" pacientes de Nefroprotección con alerta clínica",go:"nefro"});
  if(K.venc)P.risk.push({l:"warn",t:K.venc+" actividades del plan de Nefroprotección vencidas o sin realizar",go:"nefro"});
  P.nota="Corte de la Ruta: "+K.corte+(K.demo?" · datos ficticios":"")+". "+K.porEps.map(([e,n])=>e+" "+n).join(" · ");return gerFin(P);}
function gerHD(){const P=gerProg("hd");if(!pxHD()){P.st="sd";P.why="Sin libro de hemodiálisis cargado.";return gerFin(P);}
  ensureIdx();const x=ctxFor(ST.corte,ST.ps,"");
  IND.forEach(d=>{let r;try{r=evalInd(d,x);}catch(e){console.error(e);return;}const val=r.val==null?null:d.t==="pct"?r.val*100:r.val;let meta=null,strict=false,src="Línea de base";
    if(d.meta!=null){meta=d.meta;src="Institucional";}else if(d.cuts){meta=d.cuts[0];strict=true;src="CAC (alto)";}
    P.ind.push({id:d.c,n:d.n,val,u:d.t==="pct"?"%":d.unit||"",meta,dir:d.dir==="down"?"down":"up",strict,src,nd:(r.n==null?"—":f1(r.n,0))+" / "+(r.d==null?"—":f1(r.d,d.t==="rate"?1:0))});});
  const act=pacs().filter(p=>activeAt(p,ST.corte)).length;let al=0;try{al=alertas().total;}catch(e){}
  P.kpi.push([act,"activos al corte"],[al,"alertas",al?"bad":""]);if(al)P.risk.push({l:"bad",t:al+" alertas abiertas en Hemodiálisis",go:"hd"});
  const lp=pxLabPend().length;if(lp)P.risk.push({l:"warn",t:lp+" solicitudes de laboratorio de hemodiálisis sin resultado",go:"lab"});
  P.nota="Corte "+fd(ST.corte)+" · periodo desde "+fd(ST.ps)+". Sesiones realizadas sobre prescritas = atenciones atendidas sobre programadas (meta 95 %).";return gerFin(P);}
function gerVIH(m){const P=gerProg("vih");if(typeof VX==="undefined"||!VX.book){P.st="sd";P.why="Sin libro del programa VIH cargado.";return gerFin(P);}
  const c=vxCorte();VX_IND.forEach(d=>{let r;try{r=vxCalc(d,c,{});}catch(e){console.error(e);return;}const g=vxRng(d,c);let meta=null,dir="up",strict=false;
    if(g.t!=="lb"){meta=g.a;if(g.t==="down"){dir="down";strict=true;}else strict=!!g.strict;}
    P.ind.push({id:d.id,n:d.n,val:r.pct,u:"%",meta,dir,strict,src:g.t==="lb"?"Línea de base":(d.set==="neps"?"Nueva EPS":"CAC (alto)"),nd:r.num+" / "+r.den});});
  const L=VX.book.cit.filter(x=>x.Anulado!=="SI"&&String(x.Fecha).startsWith(m)&&x.Estado!=="Reprogramada");const A=gerAtProg(L,x=>x.Estado==="Asistió",x=>x.Estado==="No asistió");
  P.ind.push({id:"AT-PROG",n:"Citas atendidas sobre programadas · "+pxMesTxt(m),val:A.pc,u:"%",meta:95,dir:"up",src:"Institucional",nd:A.at+" / "+A.prog});
  const Ac=vxPacs().filter(p=>vxSt(p,c).activo);const roja=Ac.filter(p=>vxAlertas(p,c).nivel==="roja").length;
  P.kpi.push([Ac.length,"activos al corte"],[roja,"en alerta roja",roja?"bad":""],[A.out,"inasistencias en el mes",A.out?"warn":""]);
  if(roja)P.risk.push({l:"bad",t:roja+" personas del programa VIH en alerta roja",go:"vih"});
  P.nota="Corte "+fd(c)+". Programadas: citas del mes en cualquier estado, sin anuladas ni las marcadas «Reprogramada» (su reemplazo ya cuenta).";return gerFin(P);}
function ceOportCalc(m){const I=ceIdx();const R=[];CE.book.cit.forEach(c=>{const a=String(c.AsignadaEn||"").slice(0,7);if(a!==m)return;const s=I.sol.get(c.Solicitud);if(!s||!s.FechaSolicitud||!c.Fecha)return;
    const d=ceDias(s.FechaSolicitud,c.Fecha);const dd=s.FechaDeseada?ceDias(s.FechaDeseada,c.Fecha):null;const e=ceEsp(s.Especialidad);R.push({c,s,d,dd,esp:ceEspN(s.Especialidad),r256:e&&e.ReportaRes256==="SI",tipo:s.TipoConsulta||"",mod:s.Modalidad||""});});
  const st=L=>{const D=L.map(x=>x.d).sort((a,b)=>a-b);const DD=L.map(x=>x.dd).filter(x=>x!=null);return{n:L.length,prom:D.length?D.reduce((a,b)=>a+b,0)/D.length:null,med:D.length?(D.length%2?D[(D.length-1)/2]:(D[D.length/2-1]+D[D.length/2])/2):null,max:D.length?D[D.length-1]:null,nd:DD.length,promD:DD.length?DD.reduce((a,b)=>a+b,0)/DD.length:null};};
  const g={};R.forEach(x=>{const k=x.esp+"|"+x.tipo+"|"+x.mod;(g[k]=g[k]||[]).push(x);});
  return{all:st(R),rows:Object.entries(g).map(([k,L])=>{const[esp,tipo,mod]=k.split("|");return Object.assign({esp,tipo,mod,r256:L[0].r256},st(L));}).sort((a,b)=>a.esp.localeCompare(b.esp)||a.tipo.localeCompare(b.tipo))};}
function gerCE(m){const P=gerProg("ce");if(typeof CE==="undefined"||!CE.book){P.st="sd";P.why="Sin libro de Consulta Externa cargado.";return gerFin(P);}
  const O=ceOportCalc(m);const mo=ceCfg("meta_oportunidad_dias");
  P.ind.push({id:"CE-OPO",n:"Oportunidad: días promedio de la solicitud a la cita asignada",val:O.all.prom,u:"días",meta:mo==null?null:num(mo),dir:"down",src:mo==null?"Sin meta (CE-11)":"Institucional",nd:O.all.n+" citas asignadas"});
  const hoy=ceHoy();const L=CE.book.cit.filter(c=>String(c.Fecha).startsWith(m)&&c.Fecha<hoy);const con=L.some(c=>["ATENDIDA","INASISTENCIA"].includes(c.Estado));
  const A=gerAtProg(L,c=>c.Estado==="ATENDIDA",c=>c.Estado==="INASISTENCIA");
  P.ind.push({id:"AT-PROG",n:"Citas atendidas sobre programadas · "+pxMesTxt(m),val:con?A.pc:null,u:"%",meta:95,dir:"up",src:con?"Institucional":"Sin desenlace registrado (Fase 2)",nd:con?A.at+" / "+A.prog:"—"});
  const S=ceSolsAbiertas();const sin=S.filter(s=>!ceCitaAct(s.ID));const pri=sin.filter(s=>s.Prioridad==="PRIORITARIA_CLINICA").length;
  const av=S.filter(s=>ceBanderas(s).some(b=>b[1]==="Autorización vencida"||b[1]==="Autorización vence antes de la cita")).length;
  P.kpi.push([sin.length,"solicitudes sin cita"],[pri,"prioritarias clínicas sin cita",pri?"bad":""],[av,"autorizaciones vencidas o que vencen antes de la cita",av?"bad":""]);
  if(pri)P.risk.push({l:"bad",t:pri+" solicitudes prioritarias clínicas sin cita en Consulta Externa",go:"ce"});if(av)P.risk.push({l:"bad",t:av+" solicitudes de Consulta Externa con autorización vencida o que vence antes de la cita",go:"ce"});
  P.nota="Oportunidad de "+pxMesTxt(m)+" por fecha de asignación de la cita. Sin meta mientras no se decida CE-11.";return gerFin(P);}
function gerTrans(m){const out=[];
  try{const P=gerMat("iaas",pxIAASCalc(m));P.nota="Matriz GDC-MT-IAAS-001 · "+pxMesTxt(m)+".";out.push(gerFin(P));}catch(e){console.error(e);}
  try{const P=gerMat("proa",pxPROACalc(m));const pe=pxProaPend(m).length;P.kpi.push([pe,"antimicrobianos sin auditar",pe?"warn":""]);if(pe)P.risk.push({l:"warn",t:pe+" tratamientos antimicrobianos sin auditoría PROA en "+pxMesTxt(m),go:"proa"});P.nota="Matriz GDC-MT-PROA-001 · "+pxMesTxt(m)+".";out.push(gerFin(P));}catch(e){console.error(e);}
  try{const P=gerProg("sp");const R=pxSPCalc(m);R.forEach(r=>P.ind.push({id:r.id,n:r.n,val:r.val,u:r.u==="%"?"%":r.u,meta:null,dir:r.s==="down"?"down":"up",src:"Sin meta",nd:r.den?f1(r.num,0)+" / "+f1(r.den,0):"—"}));
    const A=pxSPAll();const ab=A.filter(r=>r.Estado!=="Cerrado");const ea=ab.filter(r=>/adverso/i.test(r.Clasificacion||"")&&!String(r.Analisis||"").trim());
    P.kpi.push([ab.length,"reportes abiertos",ab.length?"warn":""],[ea.length,"eventos adversos sin análisis",ea.length?"bad":""]);if(ea.length)P.risk.push({l:"bad",t:ea.length+" eventos adversos abiertos sin análisis documentado",go:"sp"});
    P.nota="El programa de seguridad del paciente no tiene metas cargadas para SP-01 a SP-05: se muestran como seguimiento y no entran al radar.";out.push(gerFin(P));}catch(e){console.error(e);}
  return out;}
function gerGes(){const out=[];const t=pxToday();
  const P1=gerProg("sogcs");const c=pxComCump(t.slice(0,4),ym(TODAY()));const cv=PX.book.cmp.filter(x=>pxCmpEst(x)==="Vencido").length;
  P1.ind.push({id:"SOG-01",n:"Comités realizados sobre programados en el año (hasta el mes anterior)",val:c.p?c.r/c.p*100:null,u:"%",meta:100,dir:"up",src:"Propuesta (validar)",nd:c.r+" / "+c.p});
  const cm=PX.book.cmp.filter(x=>x.FechaLimite&&x.FechaLimite<t);const cmc=cm.filter(x=>x.Estado==="Cerrado").length;
  P1.ind.push({id:"SOG-02",n:"Compromisos de comité con plazo cumplido que están cerrados",val:cm.length?cmc/cm.length*100:null,u:"%",meta:100,dir:"up",src:"Propuesta (validar)",nd:cmc+" / "+cm.length});
  P1.kpi.push([cv,"compromisos vencidos",cv?"bad":""]);if(cv)P1.risk.push({l:"bad",t:cv+" compromisos de comité vencidos",go:"sogcs"});out.push(gerFin(P1));
  const P2=gerProg("docs");const V=PX.book.doc.filter(d=>d.Estado==="Vigente");const al=V.filter(d=>!d.ProximaRevision||d.ProximaRevision>=t).length;
  P2.ind.push({id:"DOC-01",n:"Documentos vigentes con revisión al día",val:V.length?al/V.length*100:null,u:"%",meta:100,dir:"up",src:"Propuesta (validar)",nd:al+" / "+V.length});
  if(V.length-al)P2.risk.push({l:"warn",t:(V.length-al)+" documentos vigentes con revisión vencida",go:"docs"});out.push(gerFin(P2));
  const P3=gerProg("msg");const nv=PX.book.msg.filter(x=>x.Hilo===x.ID&&pxNovEs(x));const nva=nv.filter(x=>!["Cerrado","Respondido"].includes(x.Estado));const vz=pxVencidos().length;
  P3.kpi.push([nva.length,"novedades del servicio abiertas",nva.length?"warn":""],[nv.length,"novedades registradas"],[vz,"notificaciones con plazo vencido",vz?"bad":""]);
  nva.filter(x=>x.Prioridad==="Urgente"||x.Tipo==="Alerta").forEach(x=>P3.risk.push({l:"bad",t:x.Asunto+" ("+x.FechaHora.slice(0,10)+")",go:"msg"}));
  if(vz)P3.risk.push({l:"bad",t:vz+" notificaciones con plazo vencido sin respuesta",go:"msg"});out.push(gerFin(P3));
  const P4=gerProg("prod");try{const n=pxProdResumen(pxMes()).reduce((a,r)=>a+r.cant,0);P4.kpi.push([n.toLocaleString("es-CO"),"atenciones en "+pxMesTxt(pxMes())]);}catch(e){}out.push(gerFin(P4));
  return out;}
function gerApo(){const P=gerProg("lab");if(!pxHD()){P.st="sd";P.why="El módulo de laboratorio trabaja hoy con la solicitud mensual de hemodiálisis; sin ese libro no hay dato.";return[gerFin(P)];}
  const lp=pxLabPend().length;P.kpi.push([lp,"solicitudes sin resultado",lp?"warn":""]);P.nota="Sin indicador con meta todavía (oportunidad de resultados por definir).";return[gerFin(P)];}
function gerCalc(){const m=pxMes();const G={m,at:pxNow(),P:[]};
  const add=(f)=>{try{const r=f();(Array.isArray(r)?r:[r]).forEach(x=>G.P.push(x));}catch(e){console.error(e);}};
  add(()=>gerNefro(m));add(()=>gerHD());add(()=>gerVIH(m));add(()=>gerCE(m));
  add(()=>gerDP(m));["qt"].forEach(k=>{const P=gerProg(k);P.st="nomod";P.why=PROG[k].nx||"Módulo en desarrollo: sin indicadores medidos.";G.P.push(gerFin(P));});
  add(()=>gerApo());{const P=gerProg("far");P.st="nomod";P.why="Sin módulo por ahora.";G.P.push(gerFin(P));}
  add(()=>gerTrans(m));add(()=>gerGes());
  const S=G.P.filter(p=>p.score!=null);G.score=S.length?S.reduce((a,p)=>a+p.score,0)/S.length:null;G.nMeta=G.P.reduce((a,p)=>a+(p.nMeta||0),0);G.nOk=G.P.reduce((a,p)=>a+(p.nOk||0),0);
  PX.gerCache={m,score:G.score,n:S.length};return G;}
const gerCls=s=>s==null?"base":s>=GER_BANDS[0]?"ok":s>=GER_BANDS[1]?"warn":"bad";
function gerRadar(P){const A=P.filter(p=>p.score!=null||p.st==="sd"||(p.nMeta===0&&p.ind.length));const n=A.length;if(n<3)return'<p class="note">Se necesitan al menos tres programas medidos para dibujar el radar.</p>';
  const cx=230,cy=200,R=140;const pt=(i,v)=>{const a=-Math.PI/2+i*2*Math.PI/n;return[cx+Math.cos(a)*R*v,cy+Math.sin(a)*R*v];};
  let s='<svg class="gerradar" viewBox="0 0 460 410" role="img" aria-label="Radar del rendimiento promedio por programa: '+esc(A.map(p=>p.n+" "+(p.score==null?(p.st==="sd"?"sin dato":"sin meta"):Math.round(p.score)+" %")).join("; "))+'">';
  [0.25,0.5,0.75,1].forEach(r=>{s+='<polygon points="'+A.map((p,i)=>pt(i,r).join(",")).join(" ")+'" fill="none" stroke="var(--line)" stroke-width="1"/>';});
  s+='<polygon points="'+A.map((p,i)=>pt(i,GER_BANDS[1]/100).join(",")).join(" ")+'" fill="none" stroke="var(--warn)" stroke-width="1" stroke-dasharray="4 4" opacity=".7"/>';
  A.forEach((p,i)=>{const[x,y]=pt(i,1);s+='<line x1="'+cx+'" y1="'+cy+'" x2="'+x+'" y2="'+y+'" stroke="var(--line)"/>';});
  s+='<polygon points="'+A.map((p,i)=>pt(i,(p.score||0)/100).join(",")).join(" ")+'" fill="var(--accent)" fill-opacity=".22" stroke="var(--accent)" stroke-width="2"/>';
  A.forEach((p,i)=>{const[x,y]=pt(i,(p.score||0)/100);s+='<circle cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="4" fill="'+(p.score==null?"var(--bg)":"var(--accent)")+'" stroke="var(--accent)" stroke-width="1.5"><title>'+esc(p.n+": "+(p.score==null?"sin dato":f1(p.score,1)+" %"))+'</title></circle>';
    const a=-Math.PI/2+i*2*Math.PI/n;const lx=cx+Math.cos(a)*(R+16),ly=cy+Math.sin(a)*(R+16);const anc=Math.abs(Math.cos(a))<0.2?"middle":Math.cos(a)>0?"start":"end";
    const w=p.n.split(" ");let l1=p.n,l2="";if(p.n.length>13&&w.length>1){const h=Math.ceil(w.length/2);l1=w.slice(0,h).join(" ");l2=w.slice(h).join(" ");}
    const dy=Math.sin(a)>0.3?12:Math.sin(a)<-0.3?-14-(l2?12:0):-4;
    s+='<text x="'+lx.toFixed(1)+'" y="'+(ly+dy).toFixed(1)+'" text-anchor="'+anc+'" class="gl">'+esc(l1)+(l2?'<tspan x="'+lx.toFixed(1)+'" dy="12">'+esc(l2)+'</tspan>':'')+'<tspan x="'+lx.toFixed(1)+'" dy="13" class="gv '+gerCls(p.score)+'">'+(p.score==null?(p.st==="sd"?"sin dato":"sin meta"):Math.round(p.score)+" %")+'</tspan></text>';});
  [25,50,75,100].forEach(v=>{s+='<text x="'+(cx+3)+'" y="'+(cy-R*v/100+11)+'" class="gt">'+v+'</text>';});
  return s+'</svg>';}
function pxGer(){const G=gerCalc();const Pm=G.P.filter(p=>p.g==="mis"),Pa=G.P.filter(p=>p.g==="apo"),Pt=G.P.filter(p=>p.g==="tra"),Pg=G.P.filter(p=>p.g==="ges");
  const risks=[];G.P.forEach(p=>p.risk.forEach(r=>risks.push(Object.assign({p:p.n},r))));risks.sort((a,b)=>(a.l==="bad"?0:1)-(b.l==="bad"?0:1));
  const gaps=[];G.P.forEach(p=>p.ind.forEach(i=>{if(i.logro!=null&&!i.en)gaps.push({p,i});}));gaps.sort((a,b)=>a.i.logro-b.i.logro);
  const radarP=G.P.filter(p=>p.st!=="nomod"&&(p.score!=null||p.ind.length||p.st==="sd")&&p.k!=="prod"&&p.k!=="msg"&&p.k!=="lab");
  const atp=G.P.map(p=>({p,i:p.ind.find(i=>i.id==="AT-PROG"||i.id==="ins_adh")})).filter(x=>x.i&&x.i.val!=null);
  let h='<div class="mhead"><div><p class="eyebrow">Coordinación asistencial · Dirección médica</p><h2 class="mt">Tablero gerencial</h2><p class="note" style="margin:3px 0 0">Estado de los programas frente a sus metas, riesgos abiertos y datos para decidir. Fuentes mensuales: '+esc(pxMesTxt(G.m))+'. Fuentes de cohorte: corte de cada módulo. Calculado '+esc(G.at)+'.</p></div><div class="copyrow"><label class="f" style="max-width:180px">Mes de seguimiento<input type="month" id="pxmes" value="'+pxMes()+'"></label><button type="button" class="btn" data-g="gerexp">Descargar tablero</button><button type="button" class="btn" data-g="print">Imprimir</button></div></div>';
  h+='<div class="tiles">'+
   '<div class="tile '+gerCls(G.score)+'"><span class="tv">'+(G.score==null?"—":f1(G.score,1)+" %")+'</span><span class="tl">rendimiento promedio de los programas medidos</span></div>'+
   '<div class="tile"><span class="tv">'+G.nOk+' / '+G.nMeta+'</span><span class="tl">indicadores en meta (con meta definida)</span></div>'+
   '<div class="tile '+(risks.some(r=>r.l==="bad")?"bad":risks.length?"warn":"ok")+'"><span class="tv">'+risks.length+'</span><span class="tl">riesgos abiertos para decisión</span></div>'+
   '<div class="tile"><span class="tv">'+radarP.filter(p=>p.score!=null).length+' / '+G.P.length+'</span><span class="tl">programas y servicios con medición frente a meta</span></div></div>';
  h+='<div class="gergrid"><div class="panel"><h3>Rendimiento promedio por programa</h3>'+gerRadar(radarP)+'<p class="note">Cada eje es el promedio del logro de los indicadores del programa que tienen meta (0 a 100 %). Línea punteada: '+GER_BANDS[1]+' %. «Sin meta»: el programa mide, pero sus indicadores no tienen meta definida. «Sin dato»: el libro del módulo no está cargado.</p></div>'+
   '<div class="panel"><h3>Riesgos y decisiones pendientes</h3>'+(risks.length?'<ul class="gerrisk">'+risks.slice(0,14).map(r=>'<li><span class="st '+r.l+'">'+(r.l==="bad"?"Alto":"Atención")+'</span> '+esc(r.t)+(r.go&&pxCan(r.go)?' · <button type="button" class="lnk" data-p="go|'+r.go+'">ver</button>':'')+'</li>').join("")+'</ul>':'<p class="note">Sin riesgos abiertos en las fuentes cargadas.</p>')+
   '<h3 style="margin-top:14px">Indicadores con mayor brecha frente a meta</h3>'+(gaps.length?'<div class="tablebox"><table><thead><tr><th>Programa</th><th>Indicador</th><th>Resultado</th><th>Meta</th><th>Logro</th></tr></thead><tbody>'+gaps.slice(0,10).map(({p,i})=>'<tr><td>'+esc(p.n)+'</td><td style="font-size:13px">'+esc(i.n)+'</td><td class="mono" style="white-space:nowrap">'+gerFmt(i.val,i.u)+'</td><td class="mono" style="white-space:nowrap">'+(i.dir==="down"?(i.strict?"< ":"≤ "):(i.strict?"> ":"≥ "))+gerFmt(i.meta,i.u)+'</td><td><span class="st '+gerCls(i.logro*100)+'">'+f1(i.logro*100,0)+' %</span></td></tr>').join("")+'</tbody></table></div>':'<p class="note">Todos los indicadores con meta están en meta.</p>')+'</div></div>';
  h+='<div class="panel"><h3>Atenciones atendidas sobre programadas · meta 95 %</h3>'+(atp.length?'<div class="hbars gerat">'+atp.map(({p,i})=>'<div class="hb"><span class="hbl">'+esc(p.n)+'<span class="sub">'+esc(i.nd)+'</span></span><span class="hbt"><span style="width:'+Math.min(i.val,100).toFixed(1)+'%;background:var(--'+(i.val>=95?"ok":i.val>=GER_BANDS[1]?"warn":"bad")+')"></span><i class="hbm" style="left:95%"></i></span><span class="hbv mono">'+f1(i.val,1)+' %</span></div>').join("")+'</div>':'<p class="note">Sin datos de agenda en los módulos cargados.</p>')+'<p class="note">Hemodiálisis: sesiones realizadas sobre prescritas hasta el corte. Nefroprotección: mes anterior al corte de la Ruta. VIH y Consulta Externa: '+esc(pxMesTxt(G.m))+'. Consulta Externa entra cuando la Fase 2 registre la asistencia.</p></div>';
  const card=p=>{const cls=p.st==="nomod"?"base":p.st==="sd"?"base":gerCls(p.score);
   return'<article class="gercard '+cls+'"><header><span class="pxci">'+pxIcon(p.k)+'</span><b>'+esc(p.n)+'</b><span class="gersc '+cls+'">'+(p.st==="nomod"?"sin módulo":p.st==="sd"?"sin dato":p.score==null?"sin meta":f1(p.score,0)+" %")+'</span></header>'+
    (p.why?'<p class="note">'+esc(p.why)+'</p>':'')+(p.nMeta?'<p class="germ">'+p.nOk+' de '+p.nMeta+' indicadores en meta'+(p.ind.length>p.nMeta?' · '+(p.ind.length-p.nMeta)+' en línea de base o sin meta':'')+'</p>':'')+
    (p.kpi.length?'<div class="gerk">'+p.kpi.map(([v,l,c])=>'<span class="'+(c||"")+'"><b>'+v+'</b> '+esc(l)+'</span>').join("")+'</div>':'')+
    (p.ind.length?'<details><summary>'+p.ind.length+' indicadores</summary><div class="tablebox"><table><thead><tr><th>Indicador</th><th>Resultado</th><th>Meta</th><th>Estado</th></tr></thead><tbody>'+p.ind.map(i=>'<tr><td style="font-size:12.5px">'+esc(i.n)+'<span class="sub">'+esc((i.id||"")+" · "+i.src+(i.nd?" · "+i.nd:""))+'</span></td><td class="mono">'+gerFmt(i.val,i.u)+'</td><td class="mono" style="white-space:nowrap">'+(i.meta==null?"—":(i.dir==="down"?(i.strict?"< ":"≤ "):(i.strict?"> ":"≥ "))+gerFmt(i.meta,i.u))+'</td><td>'+(i.en==null?'<span class="st base">'+(i.val==null?"Sin dato":"Seguimiento")+'</span>':'<span class="st '+(i.en?"ok":"bad")+'">'+(i.en?"En meta":"Fuera")+'</span>')+'</td></tr>').join("")+'</tbody></table></div></details>':'')+
    (p.nota?'<p class="note" style="margin:6px 0 0">'+esc(p.nota)+'</p>':'')+
    (pxCan(p.k)&&PROG[p.k]&&p.st!=="nomod"?'<button type="button" class="btn sm" data-p="go|'+p.k+'">Abrir '+esc(p.n)+'</button>':'')+'</article>';};
  [["Programas misionales",Pm],["Servicios de apoyo",Pa],["Programas transversales",Pt],["Gestión",Pg]].forEach(([t,L])=>{if(L.length)h+='<section class="pxgroup"><h3>'+t+'</h3><div class="gercards">'+L.map(card).join("")+'</div></section>';});
  h+='<details class="panel"><summary><b>Ficha técnica del tablero</b></summary><dl class="cedl" style="margin-top:10px">'+
   '<dt>Logro de un indicador</dt><dd>Mayor es mejor: resultado ÷ meta, con tope de 100 %. Menor es mejor: meta ÷ resultado, con tope de 100 % (si la meta es 0, logro 100 % solo con resultado 0).</dd>'+
   '<dt>Rendimiento del programa</dt><dd>Promedio simple del logro de sus indicadores con meta. Los de línea de base o seguimiento se muestran, pero no entran al promedio. Todos los indicadores pesan igual: es una construcción de gestión, no una medida validada.</dd>'+
   '<dt>Metas usadas</dt><dd>CAC: el punto de corte de cumplimiento alto de cada indicador (consenso CAC de ERC 2025, hemodiálisis y VIH según cada módulo). Nefroprotección «Definir» de la CAC: meta institucional &gt; 70 %. IAAS y PROA: metas de sus matrices institucionales. Atenciones atendidas sobre programadas: 95 % (meta institucional). SOGCS y documentos: 100 % como propuesta por validar.</dd>'+
   '<dt>Rendimiento institucional</dt><dd>Promedio simple de los programas con medición. Programas sin módulo (diálisis peritoneal, quimioterapia, farmacia) no entran.</dd>'+
   '<dt>Bandas de color</dt><dd>≥ '+GER_BANDS[0]+' % verde, '+GER_BANDS[1]+' a '+(GER_BANDS[0]-1)+' % ámbar, &lt; '+GER_BANDS[1]+' % rojo. Convención de visualización de este tablero, no una norma.</dd>'+
   '<dt>Fuentes</dt><dd>Lo que esté cargado en esta sesión del navegador: libro institucional, libros de Hemodiálisis, VIH y Consulta Externa, y la Ruta de Nefroprotección. El tablero no guarda cálculos: se rehace al abrirlo.</dd></dl></details>';
  return h;}
function gerExp(){const G=gerCalc();
  pxExport("Tablero_gerencial_"+G.m+".xlsx",[["Programas",G.P,[["Programa",p=>p.n],["Grupo",p=>PG[p.g]||p.g],["Estado",p=>p.st==="nomod"?"Sin módulo":p.st==="sd"?"Sin dato":"Medido"],["Rendimiento %",p=>p.score==null?"":Math.round(p.score*10)/10],["Indicadores con meta",p=>p.nMeta],["En meta",p=>p.nOk],["Nota",p=>p.why||p.nota||""]]],
   ["Indicadores",G.P.flatMap(p=>p.ind.map(i=>Object.assign({prog:p.n},i))),[["Programa",i=>i.prog],["Código",i=>i.id],["Indicador",i=>i.n],["Resultado",i=>i.val==null?"":Math.round(i.val*100)/100],["Unidad",i=>i.u],["Meta",i=>i.meta==null?"":i.meta],["Sentido",i=>i.dir==="down"?"Menor es mejor":"Mayor es mejor"],["Fuente de la meta",i=>i.src],["Numerador / denominador",i=>i.nd||""],["Logro %",i=>i.logro==null?"":Math.round(i.logro*1000)/10],["Estado",i=>i.en==null?(i.val==null?"Sin dato":"Seguimiento"):i.en?"En meta":"Fuera de meta"]]],
   ["Riesgos",G.P.flatMap(p=>p.risk.map(r=>({p:p.n,l:r.l,t:r.t}))),[["Programa",r=>r.p],["Nivel",r=>r.l==="bad"?"Alto":"Atención"],["Riesgo",r=>r.t]]]]);}

/* ---------- Consulta Externa: oportunidad ---------- */
function ceOportPanel(){const hoy=ceHoy();const mesH=hoy.slice(0,7);const m=CE.ui.opm||mesH;const ms=[];for(let i=0;i<4;i++)ms.push(ym(addMonths(pdate(mesH+"-01"),-i)));
  const O=ceOportCalc(m);const A=O.all;
  let h='<div class="panel" style="margin-top:14px"><div class="mhead"><div><h3 style="margin:0">Oportunidad en la asignación de citas</h3><p class="note" style="margin:3px 0 0">Días calendario de la fecha de solicitud a la fecha de la cita asignada, para las citas asignadas en el mes (lógica del indicador de tiempo de espera para la asignación de cita de la Resolución 256 de 2016; verifique la ficha técnica vigente antes de reportar). Se muestra también la espera frente a la fecha deseada por el paciente.</p></div><div class="seg" role="group" aria-label="Mes">'+ms.map(x=>'<button type="button" data-g="ceopm|'+x+'" aria-pressed="'+(x===m)+'">'+esc(pxMesTxt(x))+'</button>').join("")+'</div></div>';
  h+='<div class="tiles" style="margin-top:10px"><div class="tile"><span class="tv">'+A.n+'</span><span class="tl">citas asignadas en el mes</span></div><div class="tile"><span class="tv">'+(A.prom==null?"—":f1(A.prom,1))+'</span><span class="tl">días promedio solicitud → cita</span></div><div class="tile"><span class="tv">'+(A.med==null?"—":f1(A.med,1))+'</span><span class="tl">mediana de días</span></div><div class="tile"><span class="tv">'+(A.promD==null?"—":f1(A.promD,1))+'</span><span class="tl">días promedio fecha deseada → cita'+(A.nd<A.n?' ('+A.nd+' con fecha deseada)':'')+'</span></div></div>';
  h+=O.rows.length?'<div class="tablebox" style="margin-top:10px"><table><thead><tr><th>Especialidad</th><th>Tipo</th><th>Modalidad</th><th>Citas</th><th>Promedio</th><th>Mediana</th><th>Máximo</th><th>Deseada → cita</th></tr></thead><tbody>'+O.rows.map(r=>'<tr><td>'+esc(r.esp)+(r.r256?' <span class="tag" title="La especialidad está marcada para reporte de la Resolución 256">Res. 256</span>':'')+'</td><td>'+esc(r.tipo)+'</td><td>'+esc(r.mod)+'</td><td class="mono">'+r.n+'</td><td class="mono">'+f1(r.prom,1)+'</td><td class="mono">'+f1(r.med,1)+'</td><td class="mono">'+r.max+'</td><td class="mono">'+(r.promD==null?"—":f1(r.promD,1))+'</td></tr>').join("")+'</tbody></table></div>':'<p class="note">Sin citas asignadas en '+esc(pxMesTxt(m))+'.</p>';
  h+='<p class="note" style="margin-top:8px">Cada cita asignada cuenta una vez, aunque luego se cancele; si una solicitud recibe una segunda cita, la segunda también cuenta desde la fecha de solicitud original. Sin meta institucional hasta decidir CE-11.</p></div>';return h;}

/* ---------- VIH: calculadora de riesgo cardiovascular y TFG ---------- */
function vxRcvDlg(pid){const p=vxP(pid);if(!p)return;const s=vxSt(p,TODAY());const L=k=>vxVal(vxLast(pid,k,TODAY()));const g=id=>{const e=$(id);return e?e.value:"";};
  const fem=String(p.Sexo).startsWith("F");const fu=g("vf_fu");const o={edad:s.edad,sexo:fem?"F":"M",pas:num(g("vf_pas")),ct:L("CT"),hdl:L("HDL"),cr:L("Cr"),tab:fu?fu==="Sí":null};
  const F=(id,l,v,t)=>'<label class="f">'+l+'<input type="'+(t||"number")+'" id="'+id+'" value="'+(v==null?"":esc(v))+'" step="any"></label>';
  const C=(id,l,v)=>'<label class="f">'+l+'<select id="'+id+'">'+opt([["","—"],["1","Sí"],["0","No"]].map(x=>x),v==null?"":v?"1":"0")+'</select></label>';
  openDlg("Riesgo cardiovascular y TFG · "+pid,'<p class="note">Valores tomados del último laboratorio y de la valoración abierta; corríjalos si hace falta. El cálculo no se guarda solo: con «Usar resultado» pasa al campo de la valoración.</p><div class="form">'+
   F("rc_ed","Edad (años)",o.edad)+'<label class="f">Sexo<select id="rc_sx">'+opt([["F","Mujer"],["M","Hombre"]],o.sexo)+'</select></label>'+F("rc_pas","PA sistólica (mmHg)",o.pas)+F("rc_ct","Colesterol total (mg/dL)",o.ct)+F("rc_hdl","HDL (mg/dL)",o.hdl)+F("rc_cr","Creatinina (mg/dL)",o.cr)+
   C("rc_tab","Fuma actualmente",o.tab)+C("rc_aht","Tratamiento antihipertensivo",null)+C("rc_dm","Diabetes",null)+C("rc_ecv","Enfermedad cardiovascular establecida",null)+'</div><div id="rc_out" class="rcvout"></div>',"Usar resultado",()=>{
   const R=vxRcvRun();if(!R||!R.F.ok)return"No hay un resultado de Framingham para usar: "+(R&&R.F.why||"faltan datos.");const e=$("vf_rc");if(!e)return"La valoración ya no está abierta.";e.value=String(Math.round(R.F.r*1000)/10);toast("Framingham ajustado para Colombia copiado a la valoración. Revise la categoría.");});
  document.querySelectorAll("#dlg input,#dlg select").forEach(x=>x.addEventListener("input",vxRcvRun));vxRcvRun();}
function vxRcvRun(){const g=id=>{const e=$(id);return e?e.value:"";};const b=id=>g(id)===""?null:g(id)==="1";
  const o={edad:num(g("rc_ed")),sexo:g("rc_sx"),pas:num(g("rc_pas")),ct:num(g("rc_ct")),hdl:num(g("rc_hdl")),tab:b("rc_tab"),antiHTA:b("rc_aht"),dm:!!b("rc_dm"),ecv:!!b("rc_ecv")};
  const cr=num(g("rc_cr"));o.tfg=cr&&o.edad!=null?RCV.ckdepi(cr,o.edad,o.sexo==="F"):null;
  const F=RCV.framingham(o),S=RCV.score2(o),A=RCV.auto(o);const P=RCV.pct;const out=$("rc_out");if(!out)return null;
  out.innerHTML='<div class="rcvrow"><b>Framingham ajustado para Colombia</b><span class="mono">'+(F.ok?P(F.r):"—")+'</span><small>'+esc(F.ok?F.why:F.why)+'</small></div>'+
   '<div class="rcvrow"><b>SCORE2 recalibrado (PURE-Colombia)</b><span class="mono">'+(S.ok?P(S.r)+" · "+esc(S.cat):"—")+'</span><small>'+esc(S.why)+'</small></div>'+
   '<div class="rcvrow"><b>TFGe CKD-EPI 2021</b><span class="mono">'+(o.tfg==null?"—":f1(o.tfg,0)+" mL/min/1,73 m²")+'</span><small>Ecuación sin raza (Inker 2021). Para estadificar ERC confirme con albuminuria y una segunda medición a los 3 meses (KDIGO 2024).</small></div>'+
   (A?'<div class="rcvrow"><b>Categoría sin escala</b><span>'+esc(A.cat)+'</span><small>'+esc(A.why)+'</small></div>':'')+
   '<p class="note" style="margin:6px 0 0">En personas con VIH, Framingham tiende a subestimar el riesgo (Triant VA et al. Circulation 2018;137:2203-14) y SCORE2 no fue validado en esta población; la ecuación D:A:D, desarrollada en personas con VIH, no está implementada. La categoría de la valoración la asigna el profesional según la GPC del programa.</p>';
  return{F,S,A};}

