function pxPlatView(compact){const P=pxPlat();const bor=P.estado!=="Aprobada";const gr=P.mision===PLAT_DEF.mision&&P.vision===PLAT_DEF.vision;const ed=PX.user&&pxDocEdit();
 const attrs='<div class="platx-attrs">'+PLAT_ATR.map(([n,ic])=>'<div class="platx-attr">'+platSvg(ic)+'<b>'+n+'</b></div>').join("")+'</div>';
 const vis=(c)=>'<div class="platx-v"><div class="platx-yr"><span>Visión</span><b>2030</b></div><div>'+(gr?'<h3>IPS líder y referente en el sur de Colombia</h3>'+(c?'':'<p>en la atención integral de enfermedades de alto costo y manejo especial</p>')+'<div class="platx-pil"><span>Excelencia</span><span>Innovación</span><span>Humanización</span></div>'+(c?'':'<ul class="platx-out"><li>Sostenibilidad operativa</li><li>Alta adherencia a estándares de calidad</li><li>Transformación positiva de la salud en la región</li></ul>'):'<p class="platx-txt">'+esc(P.vision)+'</p>')+'</div></div>';
 const tag=bor?'<span class="tag inst">'+esc(P.estado)+'</span>':'';
 if(compact)return'<section class="panel platx"><div class="platx-top"><h3 style="margin:0">Plataforma estratégica</h3>'+tag+(ed?'<button type="button" class="lnk" data-x="platedit">Editar</button>':'')+'</div><div class="platx-c"><div class="platx-m"><span class="platx-k">Misión</span>'+(gr?'<div class="platx-h"><h2 style="font-size:16px">Servicios de salud para personas con patologías complejas y de alto costo</h2></div>'+attrs:'<p class="platx-txt">'+esc(P.mision)+'</p>')+'</div>'+vis(true)+'</div></section>';
 const valDef=P.valores.length===PLAT_VAL_DEF.length&&P.valores.every((v,i)=>v[0]===PLAT_VAL_DEF[i]);
 return'<section class="platx"><p class="eyebrow platx-top" style="margin:0">Plataforma estratégica '+tag+'</p>'+
  '<div class="platx-m"><div class="platx-h"><span class="platx-k">Misión</span></div>'+(gr?'<div class="platx-h"><h2>Servicios de salud</h2></div>'+attrs+
   '<div class="platx-flow"><div><small>Para quién</small><b>Personas con patologías complejas y de alto costo</b><span>Atención especializada e interdisciplinaria, en especial en Nefrología y Oncología</span></div><div><small>Cómo</small><ul><li>Gestión proactiva del riesgo clínico</li><li>Cumplimiento normativo</li><li>Innovación tecnológica</li></ul></div><div><small>Para qué</small><b>Dignidad, bienestar y calidad de vida</b><span>de los pacientes y sus familias</span></div></div>'
   :'<p class="platx-txt">'+esc(P.mision)+'</p>')+'</div>'+vis(false)+
  '<details id="platfull"><summary>Texto completo de la misión y la visión, valores y objetivos</summary><div class="plat-g"><div><b class="plat-k">Misión</b><p>'+esc(P.mision)+'</p></div><div><b class="plat-k">Visión</b><p>'+esc(P.vision)+'</p></div></div>'+
   '<b class="plat-k">Valores'+(valDef?' · propuesta sin aprobar':'')+'</b><div class="plat-vals">'+P.valores.map(([n,d])=>'<div class="plat-val2"><b>'+esc(n)+'</b><span>'+esc(d)+'</span></div>').join("")+'</div><b class="plat-k">Objetivos estratégicos'+(valDef?' · propuesta sin aprobar':'')+'</b><ol class="plat-obj">'+P.objetivos.map(o=>'<li>'+esc(o)+'</li>').join("")+'</ol></details></section>';}
function pxDlgPlat(){const P=pxPlat();openDlg("Plataforma estratégica",'<p class="note">Texto que ven todos en la portada y en el panel. Use el texto aprobado por la Gerencia; mientras no lo esté, deje el estado en revisión. Mientras la misión y la visión sean las entregadas el 11-oct-2026, la portada las muestra en forma gráfica; si cambia el texto, la portada muestra el texto tal cual.</p><div class="alert warn"><p><strong>Observaciones para la validación.</strong> (1) La misión nombra Nefrología y Oncología, pero no el programa VIH, que hoy es uno de los de mayor volumen y exigencia de reporte. (2) «Líder y referente» en la visión necesita una forma de medirse antes de 2030 (por ejemplo, resultados CAC frente al promedio nacional, acreditación o cobertura regional). (3) «Manejo especial» no está definido. (4) Los valores y los objetivos que aparecen son una propuesta de trabajo; no vienen del texto entregado.</p></div><div class="form">'+vxFld("pl_e","Estado","sel",P.estado,["Borrador por validar","En revisión","Aprobada"])+vxFld("pl_m","Misión","area",P.mision,3,"wide")+vxFld("pl_v","Visión","area",P.vision,3,"wide")+vxFld("pl_va","Valores (uno por línea: Nombre | descripción corta)","area",P.valores.map(x=>x.join(" | ")).join("\n"),5,"wide")+vxFld("pl_o","Objetivos estratégicos (uno por línea)","area",P.objetivos.join("\n"),5,"wide")+'</div>',"Guardar",()=>{
 const N={estado:vxGv("pl_e"),mision:vxGv("pl_m"),vision:vxGv("pl_v"),valores:vxGv("pl_va").split("\n").map(l=>l.split("|").map(x=>x.trim())).filter(x=>x[0]).map(x=>[x[0],x[1]||""]),objetivos:vxGv("pl_o").split("\n").map(x=>x.trim()).filter(Boolean)};if(N.mision.length<10||!N.valores.length)return"Escriba la misión y al menos un valor.";pxSetCfg("plataforma",N);pxLog("MODIFICA","cfg","plataforma","Estado: "+N.estado);PX.dirty=true;pxRender();toast("Plataforma estratégica guardada en el libro institucional.");});}

/* ---------- marco del módulo ---------- */
function vxStart(){return'<div class="mhead"><div><p class="eyebrow">Programa misional</p><h2 class="mt">VIH</h2><p class="note" style="margin:3px 0 0">Cohorte, agenda, laboratorios, TAR, enfermería, vacunación, indicadores CAC y de EPS, reportes y ruta del paciente.</p></div></div>'+
 '<div class="start"><div class="panel"><h3>Abrir el libro del programa</h3><p>El libro del programa VIH es un Excel que se lee y se descarga solo en este navegador.</p><div class="copyrow"><label class="btn primary" for="vxbook">Cargar libro VIH (.xlsx)</label><input type="file" id="vxbook" accept=".xlsx" hidden><button type="button" class="btn" data-x="demo">Ver con datos ficticios</button><button type="button" class="btn" data-x="new">Empezar libro nuevo</button></div></div>'+
 '<div class="panel"><h3>Importar su base actual</h3><p>Cree el libro a partir de la cohorte nominal mensual de Nueva EPS o del archivo CAC de 193 variables. Los datos no salen de este equipo.</p><div class="copyrow"><label class="btn" for="vximp">Importar cohorte o archivo CAC</label><input type="file" id="vximp" accept=".xlsx,.xls" hidden multiple></div></div></div>'+
 '<p class="privacy">Información de VIH: reserva reforzada (Ley 1581 de 2012). No publique ni comparta el libro con datos reales fuera de la institución.</p>';}
/* ---------- tablero ---------- */
function vxTablero(){const c=vxCorte();const A=vxPacs().filter(p=>vxFiltro(p));const act=A.filter(p=>vxSt(p,c).activo);const S=act.map(p=>vxSt(p,c));
 const tar=S.filter(s=>s.recibeTAR).length,ind=S.filter(s=>s.recibeTAR&&s.cv6&&vxCVind(s.cv6)).length,vig=S.filter(s=>s.cv6&&s.cd46).length,inc=S.filter(s=>s.incidente).length;
 const AL=act.map(p=>vxAlertas(p,c));const r=AL.filter(a=>a.nivel==="roja").length,y=AL.filter(a=>a.nivel==="amarilla").length;
 const mes=ym(c);const C=VX.book.cit.filter(vxLive).filter(x=>String(x.Fecha).startsWith(mes)&&vxP(x.Paciente)&&vxFiltro(vxP(x.Paciente)));const asi=C.filter(x=>x.Estado==="Asistió").length,ina=C.filter(x=>x.Estado==="No asistió").length;
 let h=vxTiles([[act.length,"PVV activas al corte "+iso(c)],[vxPctTxt(tar,act.length),"cobertura de TAR ("+tar+")",tar/act.length>=0.95?"ok":""],[vxPctTxt(ind,tar),"en TAR con CV menor de 50 en 6 meses ("+ind+")"],[vxPctTxt(vig,act.length),"con CD4 y CV en 6 meses ("+vig+")"],[inc,"incidentes en el periodo"],[r,"pacientes en alerta roja",r?"bad":"ok"],[y,"en alerta amarilla",y?"warn":""],[vxPctTxt(ina,asi+ina),"inasistencia del mes "+mes+" ("+ina+")"]]);
 const sv=S.filter(s=>s.tar&&!s.tar.Validacion).length;const ag=act.filter(p=>!vxSt(p,c).expuesto&&vxAgEstado(p,"Medicina experta VIH").cls==="bad").length;const au=act.filter(p=>!vxSt(p,c).expuesto).map(p=>vxAudit(p).pct);const aup=au.length?Math.round(au.reduce((a,b)=>a+b,0)/au.length):null;const lf=act.filter(p=>!vxSt(p,c).expuesto&&vxLabPlan(p).some(x=>["Faltante","Vencido"].includes(x.est))).length;const pp=act.filter(p=>vxPrcPend(p).some(x=>!/Caracterizar/.test(x.est))).length;
 h+='<h3 style="margin:14px 0 6px">Qué hacer hoy</h3><div class="tiles vxtodo">'+[[ag,"médico experto vencidos sin agendar","age","pend",ag?"bad":"ok"],[lf,"pacientes con laboratorios faltantes","lab","fal",lf?"warn":"ok"],[pp,"pacientes con PPD o citologías pendientes","prc","ruta",pp?"warn":"ok"],[sv,"esquemas TAR sin validación de seguridad","tar","esq",sv?"warn":"ok"],[aup==null?"—":aup+" %","historias auditables en promedio (lista CAC)","aud","",aup>=90?"ok":aup>=70?"warn":"bad"]].map(([v,l,t,sb,cl])=>'<button type="button" class="tile '+cl+'" data-x="goto|'+t+'|'+sb+'"><span class="tv">'+v+'</span><span class="tl">'+l+' →</span></button>').join("")+'</div>';
 const K=["CAC-09","CAC-12","CAC-28","CAC-16","CAC-10","CAC-33","NEPS-12","NEPS-06"].map(id=>vxCalc(VXI[id],c));
 h+='<div class="pxcols"><div class="panel tablebox" style="padding:0"><table class="pxind"><thead><tr><th>Indicador clave</th><th class="num">Resultado</th><th>Nivel</th></tr></thead><tbody>'+K.map(k=>'<tr class="click" data-x="ind|'+k.d.id+'"><td><span class="mono" style="font-size:11.5px">'+k.d.id+'</span> '+esc(k.d.n)+'<span class="sub">'+k.num+' / '+k.den+'</span></td><td class="num mono">'+(k.pct==null?"—":vxF(k.pct,1)+" %")+'</td><td>'+vxSt2([k.nv,k.cls])+'</td></tr>').join("")+'</tbody></table></div>';
 h+='<div class="panel"><h3>Uso por grupo farmacológico (pacientes en TAR)</h3>'+vxClasesChart(S)+'</div></div>';
 const top=act.map(p=>({p,a:vxAlertas(p,c)})).filter(x=>x.a.nivel==="roja").slice(0,12);
 h+='<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente en alerta roja</th><th>Motivos</th></tr></thead><tbody>'+(top.map(x=>'<tr class="click" data-x="pac|'+x.p.ID+'"><td>'+vxPacCell(x.p)+'</td><td><div class="chs">'+x.a.L.filter(l=>l.n==="roja").map(l=>vxChip("roja",l.t)).join("")+'</div></td></tr>').join("")||'<tr><td colspan="2" class="note">Sin alertas rojas.</td></tr>')+'</tbody></table></div>'+(top.length===12?'<p class="note"><button type="button" class="lnk" data-p="go|vih|ale">Ver todas las alertas</button></p>':'');
 return h;}
function vxClasesChart(S){const T=S.filter(s=>s.tar);if(!T.length)return'<p class="note">Sin pacientes en TAR.</p>';const cnt={};const anc={};
 T.forEach(s=>{const q=VXQ[s.tar.Esquema];const cl=new Set((q?q.c:[]).map(m=>VX_MED[m][1]));cl.forEach(k=>cnt[k]=(cnt[k]||0)+1);const a=cl.has("INI")&&cl.has("IP")?"IP + INI":cl.has("INI")?(q&&q.c.length===2?"INI dual (DTG/3TC)":"INI + 2 ITIAN"):cl.has("IP")?"IP potenciado + 2 ITIAN":cl.has("ITINN")?"ITINN + 2 ITIAN":"Sin especificar";anc[a]=(anc[a]||0)+1;});
 return'<p class="note" style="margin-top:0">Pacientes expuestos a cada grupo (un esquema suma en varios grupos)</p>'+hbars(VX_CLASES.map(([k,l])=>[l+" ("+k+")",cnt[k]||0]).filter(x=>x[1]))+'<p class="note">Base del esquema (tercer agente)</p>'+hbars(Object.entries(anc).sort((a,b)=>b[1]-a[1]));}

/* ---------- población ---------- */
function vxPob(){const c=vxCorte();const q=norm(VX.ui.q||"");const est=VX.ui.est||"act";
 const L=vxPacs().filter(p=>vxFiltro(p)).filter(p=>{const s=vxSt(p,c);return est==="todos"||(est==="act"?s.activo:!s.activo);}).filter(p=>!q||norm(p.ID+" "+vxNom(p)+" "+p.Documento).includes(q));
 let h='<div class="mhead" style="margin-top:6px"><div class="seg">'+[["act","Activos"],["egr","Egresados"],["todos","Todos"]].map(([k,l])=>'<button type="button" data-x="est|'+k+'" aria-pressed="'+(est===k)+'">'+l+'</button>').join("")+'</div><div class="copyrow"><label class="f" style="max-width:260px">Buscar<input type="text" id="vxq" value="'+esc(VX.ui.q||"")+'" placeholder="ID, nombre o documento"></label><button type="button" class="btn primary" data-x="pacnew">Nuevo paciente</button><button type="button" class="btn" data-x="rep|pob">Descargar población</button></div></div>';
 h+='<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th>Documento</th><th>Edad · sexo</th><th>EPS · régimen</th><th>Municipio</th><th>TAR al corte</th><th>Última CV</th><th>Último CD4</th><th>Alerta</th></tr></thead><tbody>'+
 L.slice(0,400).map(p=>{const s=vxSt(p,c);const a=vxAlertas(p,c);return'<tr class="click" data-x="pac|'+p.ID+'"><td>'+vxPacCell(p)+'</td><td class="mono" style="font-size:12.5px">'+esc(p.TipoDoc+" "+p.Documento)+'</td><td>'+(s.edad==null?"—":s.edad)+' · '+esc(String(p.Sexo||"").charAt(0))+'</td><td>'+esc(p.EPS)+'<span class="sub">'+esc(p.Regimen||"sin régimen")+'</span></td><td>'+esc(p.Municipio||"—")+'</td><td style="font-size:13px">'+(s.tar?esc(s.tar.Esquema):'<span class="bad-t">Sin TAR</span>')+'</td><td class="mono" style="font-size:12.5px">'+(s.cv?esc(vxFmtLab(s.cv))+'<span class="sub">'+iso(s.cv._d)+'</span>':'—')+'</td><td class="mono" style="font-size:12.5px">'+(s.cd4?vxF(vxVal(s.cd4),0)+'<span class="sub">'+iso(s.cd4._d)+'</span>':'—')+'</td><td>'+(a.nivel==="—"?'<span class="st base">'+esc(p.Estado)+'</span>':vxSt2([a.nivel,vxAlCls[a.nivel]]))+'</td></tr>';}).join("")+'</tbody></table></div><p class="note">'+L.length+' pacientes'+(L.length>400?' (se muestran 400; use el buscador)':'')+'.</p>';
 return h;}

/* ---------- caracterización ---------- */
function vxCount(L,f){const g={};L.forEach(p=>{const k=f(p)||"Sin dato";g[k]=(g[k]||0)+1;});return Object.entries(g).sort((a,b)=>b[1]-a[1]);}
function vxPiramide(L,c){const G=["Menor de 15","15 a 19","20 a 29","30 a 39","40 a 49","50 a 59","60 y más"];const m={},f={};L.forEach(p=>{const g=vxGrupoEtario(vxEdad(p,c));if(String(p.Sexo).startsWith("F"))f[g]=(f[g]||0)+1;else m[g]=(m[g]||0)+1;});const mx=Math.max(1,...G.map(g=>Math.max(m[g]||0,f[g]||0)));
 const W=520,rh=24,top=22,H=top+G.length*rh+6,cx=W/2,lw=70,sc=(cx-lw/2-30)/mx;
 return'<svg class="chart" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Pirámide de edad por sexo"><text x="'+(cx-lw/2-6)+'" y="14" text-anchor="end" class="ax">Masculino</text><text x="'+(cx+lw/2+6)+'" y="14" class="ax">Femenino</text>'+G.map((g,i)=>{const y=top+i*rh;const a=(m[g]||0)*sc,b=(f[g]||0)*sc;return'<rect x="'+(cx-lw/2-a)+'" y="'+y+'" width="'+a+'" height="'+(rh-6)+'" rx="3" fill="var(--accent)"/><rect x="'+(cx+lw/2)+'" y="'+y+'" width="'+b+'" height="'+(rh-6)+'" rx="3" fill="#7a9fb0"/><text x="'+cx+'" y="'+(y+13)+'" text-anchor="middle" class="ax">'+g+'</text>'+(m[g]?'<text x="'+(cx-lw/2-a-4)+'" y="'+(y+13)+'" text-anchor="end" class="val">'+m[g]+'</text>':'')+(f[g]?'<text x="'+(cx+lw/2+b+4)+'" y="'+(y+13)+'" class="val">'+f[g]+'</text>':'');}).join("")+'</svg>';}
function vxCar(){const c=vxCorte();const L=vxPacs().filter(p=>vxFiltro(p)&&vxSt(p,c).activo);const S=L.map(p=>vxSt(p,c));
 const E=["","Estadio 1 (CD4 500 o más)","Estadio 2 (CD4 200 a 499)","Estadio 3 (CD4 menor de 200 u oportunista)","Sin CD4 al diagnóstico"];
 const ed=S.map(s=>s.edad).filter(x=>x!=null).sort((a,b)=>a-b);const med=ed.length?ed[Math.floor(ed.length/2)]:null;
 let h=vxTiles([[L.length,"PVV activas"],[med==null?"—":med,"mediana de edad (años)"],[vxPctTxt(L.filter(p=>String(p.Sexo).startsWith("F")).length,L.length),"mujeres"],[vxPctTxt(L.filter(p=>p.Regimen==="S").length,L.length),"régimen subsidiado"],[vxPctTxt(L.filter(p=>p.Modalidad==="Telemedicina").length,L.length),"atención por telemedicina"],[vxPctTxt(S.filter(s=>s.estIni===3).length,L.length),"ingresaron en estadio 3"]]);
 h+='<div class="copyrow" style="justify-content:flex-end"><button type="button" class="btn" data-x="rep|car">Descargar caracterización</button></div>';
 const box=(t,b)=>'<div class="panel"><h3>'+t+'</h3>'+b+'</div>';
 h+='<div class="pxcols">'+box("Pirámide de edad y sexo",vxPiramide(L,c))+box("EPS",hbars(vxCount(L,p=>p.EPS)))+box("Régimen",hbars(vxCount(L,p=>(VX_REG.find(r=>r[0]===p.Regimen)||[0,""])[1])))+box("Municipio de residencia",hbars(vxCount(L,p=>p.Municipio)))+box("Población clave",hbars(vxCount(L,p=>p.PoblacionClave)))+box("Estadio inicial (CD4 al diagnóstico)",hbars(vxCount(S,s=>E[s.estIni])))+box("Estadio actual",hbars(vxCount(S,s=>E[s.estAct])))+box("Tiempo desde el diagnóstico",hbars(vxCount(S,s=>!s.dx?"Sin dato":dayDiff(s.dx,c)<365?"Menos de 1 año":dayDiff(s.dx,c)<365*5?"1 a 4 años":dayDiff(s.dx,c)<3650?"5 a 9 años":"10 años o más")))+box("Esquema TAR actual",hbars(vxCount(S,s=>s.tar?s.tar.Esquema:"Sin TAR")))+box("Modalidad de atención",hbars(vxCount(L,p=>p.Modalidad)))+box("Mecanismo de transmisión",hbars(vxCount(L,p=>p.Mecanismo)))+box("Tipo de ingreso",hbars(vxCount(L,p=>p.TipoIngreso)))+'</div>';
 return h;}

