/* ---------- ficha del paciente ---------- */
function vxSpark(pid){const C=vxL(pid,"lab").filter(r=>r.Examen==="CD4"&&num(r.Valor)!=null).slice(-8).map(r=>({d:r._d,v:num(r.Valor)}));if(C.length<2)return"";try{return'<p class="note" style="margin:8px 0 0">Tendencia de CD4</p>'+lineChart(C,{});}catch(e){return"";}}
/* ruta personal: etapas de GAO-PT-008 con su estado */
function vxRutaPaciente(p,s){const P=vxPeriodo(s.c);const D=s.disc;const ant=vxL(p.ID,"ant").length>0;const ini=vxL(p.ID,"cit").filter(x=>x.Estado==="Asistió");const has=d=>ini.some(x=>x.Disciplina===d);
 const st=[
  ["6.1 Identificación e ingreso",[["Datos de identificación y afiliación",!!(p.Documento&&p.EPS&&p.Regimen)],["Diagnóstico confirmado y fecha",!!p.FechaDx],["Apertura de historia y antecedentes",ant],["Programación de valoraciones",vxL(p.ID,"cit").length>0]]],
  ["6.2 Valoración interdisciplinaria inicial",[["Medicina / enfermería",has("Medicina experta VIH")||has("Enfermería")],["Trabajo social",has("Trabajo social")],["Psicología",has("Psicología")],["Nutrición",has("Nutrición")]]],
  ["6.3 Clasificación del riesgo y plan",[["Riesgo social registrado",s.val.some(v=>v.RiesgoSocial)],["Plan de atención en la última valoración",!!(s.lastVal&&s.lastVal.Plan)]]],
  ["6.4 Seguimiento interdisciplinario",[["Atención médica en 6 meses",ini.some(x=>["Medicina experta VIH","Infectología"].includes(x.Disciplina)&&vxD(x.Fecha)>=P.w6)],["CD4 y CV vigentes",!!(s.cv6&&s.cd46)],["Adherencia medida (SMAQ)",!!s.smaq],["TAR con entrega vigente",!!(s.cob&&s.cob>=s.c)]]],
  ["6.5 Inasistencias y riesgo de abandono",[["Inasistencias gestionadas",!vxL(p.ID,"cit").some(x=>x.Estado==="No asistió"&&!x.Gestion)],["Sin sospecha de abandono",!vxAlertas(p,s.c).L.some(l=>/abandono/.test(l.t))]]]];
 return'<div class="panel"><h3>Ruta del paciente · GAO-PT-008</h3><div class="vxruta">'+st.map(([t,I])=>{const ok=I.filter(x=>x[1]).length;const cls=ok===I.length?"ok":ok?"warn":"bad";return'<div class="vxst '+cls+'"><b>'+esc(t)+'</b><ul>'+I.map(([l,v])=>'<li class="'+(v?"y":"n")+'">'+esc(l)+'</li>').join("")+'</ul></div>';}).join("")+'</div></div>';}
function vxPacVac(p,s){const E=vxVacEstado(p);
 let h='<div class="copyrow" style="margin:8px 0"><button type="button" class="btn primary" data-x="vacnew|'+p.ID+'">Registrar dosis o antecedente</button><button type="button" class="btn" data-x="carnet|'+p.ID+'">Descargar carné</button></div>';
 h+='<div class="vxcarnet"><div class="vxcarnet-h"><div><b>Carné de vacunación · Programa VIH</b><span>'+esc(vxNom(p))+' · '+esc(p.TipoDoc+" "+p.Documento)+' · '+(s.edad==null?"":s.edad+" años")+'</span></div><div class="mono" style="font-size:12px">CD4 '+(s.cd4v==null?"sin dato":s.cd4v)+' · anti-HBs '+(vxVal(vxLast(p.ID,"AntiHBs"))==null?"sin dato":vxF(vxVal(vxLast(p.ID,"AntiHBs")),1))+'</div></div>'+
 E.map(e=>'<div class="vxvac '+e.cls+'"><div><b>'+esc(e.v.l)+'</b><span class="sub">'+esc(e.v.nota)+'</span></div><div class="vxdos">'+(e.D.map(d=>'<span class="ch" title="'+esc((d.Lote?"Lote "+d.Lote+" · ":"")+d.Estado)+'">'+esc((d.Dosis||"")+" "+(d.Fecha||""))+'</span>').join("")||'<span class="sd">sin dosis</span>')+'</div><div><span class="st '+e.cls+'">'+esc(e.est)+'</span>'+(e.acc?'<span class="sub">'+esc(e.acc)+'</span>':'')+'</div></div>').join("")+'</div><p class="note">Esquemas del carné por confirmar con el PAI vigente y la GPC VIH 2021. Las vacunas vivas se marcan contraindicadas con CD4 menor de 200.</p>';return h;}
function vxPacNov(p){const N=vxL(p.ID,"nov").slice().reverse();const A=vxL(p.ID,"ant").slice(-1)[0];
 return'<div class="copyrow" style="margin:8px 0"><button type="button" class="btn primary" data-x="antedit|'+p.ID+'">Actualizar antecedentes</button><button type="button" class="btn" data-x="novnew|'+p.ID+'">Registrar novedad</button></div><div class="pxcols"><div class="panel"><h3>Antecedentes'+(A?' · '+esc(A.Fecha):'')+'</h3>'+(A?'<dl class="ficha vxficha">'+VX_ANT.map(([k,l])=>A[k]?'<dt>'+esc(l)+'</dt><dd>'+esc(A[k])+'</dd>':'').join("")+'</dl>':'<p class="note">Sin antecedentes registrados.</p>')+'</div><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Fecha</th><th>Novedad</th><th>Detalle</th><th></th></tr></thead><tbody>'+(N.map(n=>'<tr><td class="mono">'+esc(n.Fecha)+(n.FechaFin?'<span class="sub">a '+esc(n.FechaFin)+'</span>':'')+'</td><td>'+esc(n.Tipo)+'</td><td style="font-size:13px">'+esc(n.Detalle||"")+'</td><td><button type="button" class="lnk" data-x="anular|nov|'+n.ID+'">Anular</button></td></tr>').join("")||'<tr><td colspan="4" class="note">Sin novedades.</td></tr>')+'</tbody></table></div></div>';}
const VX_ANT=[["Patologicos","Patológicos"],["Oportunistas","Enfermedades oportunistas"],["ITS","Otras ITS"],["TB","TB latente o activa"],["Quirurgicos","Quirúrgicos"],["FarmNoTAR","Farmacológicos no TAR"],["Toxicos","Tóxicos"],["Alergicos","Alérgicos"],["Transfusionales","Transfusionales"],["Traumaticos","Traumáticos"],["Psiquiatricos","Psiquiátricos"],["Psicosociales","Psicosociales"],["Discapacidad","Discapacidad"],["Familiares","Familiares"],["GrupoSanguineo","Grupo sanguíneo"],["Ginecoobstetricos","Ginecoobstétricos"]];
/* ================= v0.4 · PROGRAMA VIH · vistas (2/2) ================= */
/* ---------- laboratorios ---------- */
const vxLabMes=()=>VX.ui.lmes||ym(TODAY());
function vxLab(){const sub=VX.ui.lsub||"fal";
 let h='<div class="mhead" style="margin-top:6px"><div class="seg">'+[["fal","Faltantes y próximos"],["sol","Solicitud del mes"],["res","Resultados recientes"],["inm","Perfil inmunovirológico"],["met","Perfil metabólico y renal"],["tam","Tamizajes y serologías"]].map(([k,l])=>'<button type="button" data-x="lsub|'+k+'" aria-pressed="'+(sub===k)+'">'+l+'</button>').join("")+'</div><div class="copyrow"><button type="button" class="btn primary" data-x="labnew">Cargar resultados</button></div></div>';
 if(sub==="fal")return h+vxLabFaltantes();
 if(sub==="sol")return h+vxSolView("vih");
 if(sub==="res"){const L=VX.book.lab.filter(vxLive).filter(r=>vxP(r.Paciente)&&vxFiltro(vxP(r.Paciente))).sort((a,b)=>String(b.Registrado).localeCompare(a.Registrado)).slice(0,120);
  return h+'<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Toma</th><th>Paciente</th><th>Examen</th><th>Resultado</th><th>Registrado</th></tr></thead><tbody>'+L.map(r=>{const p=vxP(r.Paciente);return'<tr class="click" data-x="pac|'+p.ID+'"><td class="mono">'+esc(r.FechaToma)+'</td><td>'+vxPacCell(p)+'</td><td>'+esc((VXE[r.Examen]||{l:r.Examen}).l)+'</td><td class="mono">'+esc(vxFmtLab(r))+'</td><td class="mono" style="font-size:12px">'+esc(r.Registrado)+'<span class="sub">'+esc(r.Usuario||"")+'</span></td></tr>';}).join("")+'</tbody></table></div>';}
 const c=vxCorte();const P=vxPacs().filter(p=>vxFiltro(p)&&vxSt(p,c).activo);
 if(sub==="inm"){const S=P.map(p=>vxSt(p,c));const cv=S.filter(s=>s.cv6).length,cd=S.filter(s=>s.cd46).length,ind=S.filter(s=>s.cv6&&vxCVind(s.cv6)).length,b200=S.filter(s=>s.cd4v!=null&&s.cd4v<200).length;
  h+=vxTiles([[vxPctTxt(cv,P.length),"con CV en 6 meses"],[vxPctTxt(cd,P.length),"con CD4 en 6 meses"],[vxPctTxt(ind,cv),"indetectables entre los medidos"],[b200,"con último CD4 menor de 200",b200?"bad":""]])+'<div class="copyrow" style="justify-content:flex-end"><button type="button" class="btn" data-x="rep|inm">Descargar perfil inmunovirológico</button></div>';
  return h+'<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th>CV al diagnóstico</th><th>CD4 al diagnóstico</th><th>Última CV</th><th>Último CD4</th><th>Vigencia</th></tr></thead><tbody>'+S.map(s=>'<tr class="click" data-x="pac|'+s.id+'"><td>'+vxPacCell(s.p)+'</td><td class="mono">'+(s.cvdx?esc(vxFmtLab(s.cvdx)):"—")+'</td><td class="mono">'+(s.cd4dx?vxVal(s.cd4dx):"—")+'</td><td class="mono">'+(s.cv?esc(vxFmtLab(s.cv))+'<span class="sub">'+iso(s.cv._d)+'</span>':"—")+'</td><td class="mono">'+(s.cd4?vxVal(s.cd4)+'<span class="sub">'+iso(s.cd4._d)+'</span>':"—")+'</td><td>'+(s.cv6&&s.cd46?'<span class="st ok">Vigente</span>':'<span class="st bad">'+[!s.cv6&&"CV",!s.cd46&&"CD4"].filter(Boolean).join(" y ")+' vencido</span>')+'</td></tr>').join("")+'</tbody></table></div>';}
 if(sub==="met"){const K=["Cr","Glu","CT","LDL","HDL","TG","ALT","Hb"];
  return h+'<div class="copyrow" style="justify-content:flex-end"><button type="button" class="btn" data-x="rep|met">Descargar perfil metabólico</button></div><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th>'+K.map(k=>'<th class="num">'+esc(VXE[k].l)+'</th>').join("")+'<th class="num">TFG CKD-EPI 2021</th></tr></thead><tbody>'+P.map(p=>{const cr=vxLast(p.ID,"Cr",c);const tfg=cr?vxTFG(vxVal(cr),vxEdad(p,cr._d),p.Sexo):null;return'<tr class="click" data-x="pac|'+p.ID+'"><td>'+vxPacCell(p)+'</td>'+K.map(k=>{const r=vxLast(p.ID,k,c);const old=r&&r._d<addMonths(c,k==="CT"?-12:-6);return'<td class="num mono'+(old?' sd':'')+'" title="'+(r?iso(r._d):"")+'">'+(r?vxF(vxVal(r),k==="Cr"?2:0):"—")+'</td>';}).join("")+'<td class="num mono">'+(tfg?vxF(tfg,0):"—")+'</td></tr>';}).join("")+'</tbody></table></div><p class="note">En gris: resultado fuera de la ventana (6 meses; colesterol total 12 meses).</p>';}
 if(sub==="tam"){const K=[["VDRL",12],["AntiVHC",12],["HBsAg",12],["AntiHBs",12],["AntiHBc",0],["VHA",0],["Toxo",0]];
  return h+'<div class="copyrow" style="justify-content:flex-end"><button type="button" class="btn" data-x="rep|tam">Descargar tamizajes</button></div><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th>'+K.map(([k])=>'<th>'+esc(VXE[k].l)+'</th>').join("")+'<th>PPD / IGRA</th><th>Citología</th></tr></thead><tbody>'+P.map(p=>{const s=vxSt(p,c);const pr=vxL(p.ID,"prc").filter(x=>/Citolog|VPH/.test(x.Tipo)&&x.Estado!=="Ordenado").pop();return'<tr class="click" data-x="pac|'+p.ID+'"><td>'+vxPacCell(p)+'</td>'+K.map(([k,m])=>{const r=vxLast(p.ID,k,c);const old=r&&m&&r._d<addMonths(c,-m);return'<td class="mono'+(old?' sd':'')+'" style="font-size:12.5px">'+(r?esc(vxFmtLab(r))+'<span class="sub">'+iso(r._d)+'</span>':"—")+'</td>';}).join("")+'<td style="font-size:12.5px">'+(s.ppd?esc((s.ppd.Lectura||"")+" mm "+(s.ppd.Resultado||""))+'<span class="sub">'+esc(s.ppd.FechaLectura||s.ppd.Fecha)+'</span>':s.igra?esc(vxFmtLab(s.igra)):"—")+'</td><td style="font-size:12.5px">'+(pr?esc(pr.Tipo.replace("Citología ","")+" "+(pr.Resultado||pr.Estado))+'<span class="sub">'+esc(pr.Fecha)+'</span>':"—")+'</td></tr>';}).join("")+'</tbody></table></div>';}
 return h;}
/* solicitud del mes: la genera Laboratorio; el programa la ve y la corrige con motivo */
function vxSolView(ctx){const mes=vxLabMes();const R=vxSolRecs(mes).filter(r=>vxP(r.Paciente)&&(ctx==="lab"||vxFiltro(vxP(r.Paciente))));const gen=R.length>0;
 let h='<div class="panel" style="display:grid;gap:10px"><div class="mhead"><div><h3 style="margin:0">Solicitud de laboratorio · VIH · '+esc(mes)+'</h3><p class="note" style="margin:3px 0 0">Calculada con las frecuencias del contrato de cada EPS (guías rápidas adjuntas), los resultados vencidos y las condiciones clínicas (CD4, atazanavir, prueba reactiva).</p></div><div class="copyrow"><label class="f" style="max-width:160px">Mes<input type="month" id="vxlmes" value="'+esc(mes)+'"></label>'+(ctx==="lab"?'<button type="button" class="btn primary" data-x="solgen">'+(gen?"Agregar faltantes":"Generar solicitud")+'</button>':'')+'<button type="button" class="btn" data-x="soladd">Agregar examen</button><button type="button" class="btn" data-x="rep|sol">Descargar</button></div></div>';
 if(!gen){const prev=vxPacs().filter(p=>vxSt(p,monthEnd(pdate(mes+"-01"))).activo).reduce((a,p)=>a+vxDue(p,mes).length,0);return h+'<p class="note">Sin solicitud generada para '+esc(mes)+'. Previsto: '+prev+' exámenes. '+(ctx==="lab"?"":"La genera y valida Laboratorio clínico; aquí se ve y se corrige.")+'</p></div>';}
 const by={};R.forEach(r=>{(by[r.Paciente]=by[r.Paciente]||[]).push(r);});const tom=R.filter(r=>r.Estado==="Muestra tomada").length,res=R.filter(vxSolTieneRes).length;
 h+=vxTiles([[R.length,"exámenes solicitados"],[Object.keys(by).length,"pacientes"],[tom,"muestras tomadas"],[res,"con resultado cargado",res===R.length?"ok":""]]);
 h+='<div class="tablebox"><table><thead><tr><th>Paciente</th><th>Exámenes</th><th>Estado</th><th></th></tr></thead><tbody>'+Object.entries(by).map(([pid,L])=>{const p=vxP(pid);return'<tr><td>'+vxPacCell(p)+'<span class="sub">'+esc(p.EPS)+'</span></td><td style="font-size:13px">'+L.map(r=>'<span class="ch'+(vxSolTieneRes(r)?'':r.Estado==="No tomada"?' bad':'')+'" title="'+esc(r.Origen)+'">'+esc(r.Examen)+(vxSolTieneRes(r)?' ✓':'')+'</span> <button type="button" class="lnk" style="font-size:11px" data-x="solquitar|'+r.ID+'" title="Quitar con motivo">×</button>').join(" ")+'</td><td>'+[...new Set(L.map(r=>r.Estado))].map(esc).join(", ")+'</td><td>'+(ctx==="lab"?'<button type="button" class="btn sm" data-x="soltom|'+pid+'|'+mes+'">Muestra tomada</button> ':'')+'<button type="button" class="btn sm" data-x="labnew|'+pid+'">Cargar resultado</button></td></tr>';}).join("")+'</tbody></table></div></div>';return h;}

/* ---------- TAR ---------- */
function vxTarV(){const sub=VX.ui.tsub||"gru";const c=vxCorte();const P=vxPacs().filter(p=>vxFiltro(p)&&vxSt(p,c).activo);const S=P.map(p=>vxSt(p,c));
 let h='<div class="mhead" style="margin-top:6px"><div class="seg">'+[["gru","Grupos farmacológicos"],["esq","Esquemas por paciente"],["ent","Entregas"],["ped","Pedido de fin de mes"]].map(([k,l])=>'<button type="button" data-x="tsub|'+k+'" aria-pressed="'+(sub===k)+'">'+l+'</button>').join("")+'</div><div class="copyrow"><button type="button" class="btn" data-x="rep|tar">TAR por paciente</button><button type="button" class="btn" data-x="rep|ped">Pedido del mes</button></div></div>';
 if(sub==="gru"){const T=S.filter(s=>s.tar);const med={};T.forEach(s=>(VXQ[s.tar.Esquema]?VXQ[s.tar.Esquema].c:[]).forEach(m=>med[m]=(med[m]||0)+1));
  h+=vxTiles([[T.length,"pacientes en TAR"],[vxPctTxt(T.filter(s=>VXQ[s.tar.Esquema]&&VXQ[s.tar.Esquema].c.includes("DTG")).length,T.length),"con dolutegravir"],[vxPctTxt(T.filter(s=>VXQ[s.tar.Esquema]&&VXQ[s.tar.Esquema].c.some(m=>VX_MED[m][1]==="IP")).length,T.length),"con inhibidor de proteasa"],[vxPctTxt(T.filter(s=>VXQ[s.tar.Esquema]&&VXQ[s.tar.Esquema].c.some(m=>VX_MED[m][1]==="ITINN")).length,T.length),"con ITINN"],[vxPctTxt(T.filter(s=>VX_GPC_PREF.includes(s.tar.Esquema)).length,T.length),"en pauta de elección GPC 2021"]]);
  h+='<div class="pxcols"><div class="panel"><h3>Grupos farmacológicos</h3>'+vxClasesChart(S)+'</div><div class="panel"><h3>Medicamento (pacientes que lo reciben)</h3>'+hbars(Object.entries(med).sort((a,b)=>b[1]-a[1]).map(([m,n])=>[VX_MED[m][0]+" · "+VX_MED[m][1],n]))+'</div><div class="panel"><h3>Esquema</h3>'+hbars(vxCount(T,s=>s.tar.Esquema))+'</div><div class="panel"><h3>Línea de tratamiento</h3>'+hbars(vxCount(T,s=>s.tar.Linea||"Sin dato"))+'</div></div>';
  h+='<p class="note">Grupos: INI inhibidores de integrasa; ITIAN y ITINN inhibidores de transcriptasa reversa nucleósidos y no nucleósidos; IP inhibidores de proteasa. Pauta de elección: GPC VIH adultos Colombia 2021, recomendaciones 12 y 13. TDF/3TC/DTG no cuenta como pauta de elección (la GPC lista DTG + TDF/FTC; no se consideran equivalentes).</p>';return h;}
 if(sub==="esq")return h+'<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th>Esquema actual</th><th>Desde</th><th>Inicio de TAR</th><th class="num">Semanas</th><th>Última entrega</th><th>Cubre hasta</th></tr></thead><tbody>'+S.map(s=>'<tr class="click" data-x="pac|'+s.id+'"><td>'+vxPacCell(s.p)+'</td><td>'+(s.tar?esc(s.tar.Esquema):'<span class="bad-t">Sin TAR</span>')+'</td><td class="mono">'+(s.tar?esc(s.tar.Inicio):"")+'</td><td class="mono">'+(s.tarIni?iso(s.tarIni):"")+'</td><td class="num">'+(s.semTAR==null?"":s.semTAR)+'</td><td class="mono">'+(s.ent?esc(s.ent.Fecha):"—")+'</td><td class="mono'+(s.cob&&s.cob<TODAY()?' bad-t':'')+'">'+(s.cob?iso(s.cob):"—")+'</td></tr>').join("")+'</tbody></table></div>';
 if(sub==="ent"){const m=VX.ui.emes||ym(TODAY());const E=VX.book.ent.filter(vxLive).filter(e=>String(e.Fecha).startsWith(m)&&vxP(e.Paciente)&&vxFiltro(vxP(e.Paciente)));
  return h+'<div class="copyrow"><label class="f" style="max-width:160px">Mes<input type="month" id="vxemes" value="'+esc(m)+'"></label><button type="button" class="btn primary" data-x="entnew">Registrar entrega</button></div><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Fecha</th><th>Paciente</th><th>Esquema</th><th class="num">Meses</th><th class="num">Unidades</th><th>Lugar</th></tr></thead><tbody>'+(E.map(e=>'<tr><td class="mono">'+esc(e.Fecha)+'</td><td>'+vxPacCell(vxP(e.Paciente))+'</td><td>'+esc(e.Esquema)+'</td><td class="num">'+esc(e.Meses)+'</td><td class="num">'+esc(e.Unidades)+'</td><td>'+esc(e.Lugar||"")+'</td></tr>').join("")||'<tr><td colspan="6" class="note">Sin entregas en el mes.</td></tr>')+'</tbody></table></div>';}
 if(sub==="ped"){const PD=vxPedido();h+='<p class="note">Mes del pedido: <b>'+esc(PD.mes)+'</b>. Entra cada paciente activo en TAR cuya cobertura vence antes de terminar ese mes; la cantidad es tabletas por día × 30 × meses de dispensación de su última entrega. Las cantidades van en <b>unidades</b> (tabletas o cápsulas), sin convertir a cajas.</p>';
  h+='<div class="pxcols"><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Producto</th><th class="num">Pacientes</th><th class="num">Unidades</th></tr></thead><tbody>'+PD.cons.map(r=>'<tr><td>'+esc(r.prod)+'</td><td class="num">'+r.pac+'</td><td class="num mono">'+r.u.toLocaleString("es-CO")+'</td></tr>').join("")+'</tbody></table></div><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th>Esquema</th><th>Cubre hasta</th><th class="num">Meses</th></tr></thead><tbody>'+PD.rows.map(r=>'<tr><td>'+vxPacCell(r.p)+'</td><td>'+esc(r.esq)+'</td><td class="mono">'+iso(r.cob)+'</td><td class="num">'+r.meses+'</td></tr>').join("")+'</tbody></table></div></div>';return h;}
 return h;}
function vxPedido(mes){mes=mes||ym(addMonths(TODAY(),1));const me=monthEnd(pdate(mes+"-01"));const c=vxCorte();const rows=[];const cons={};
 vxPacs().filter(p=>vxFiltro(p)).forEach(p=>{const s=vxSt(p,TODAY()>c?TODAY():c);if(!s.activo||!s.tar)return;const q=VXQ[s.tar.Esquema];if(!q||!q.it.length)return;if(s.cob&&s.cob>me)return;const meses=num(s.ent&&s.ent.Meses)||1;rows.push({p,esq:s.tar.Esquema,cob:s.cob,meses});q.it.forEach(([prod,tpd])=>{const r=cons[prod]=cons[prod]||{prod,pac:0,u:0};r.pac++;r.u+=tpd*30*meses;});});
 return{mes,rows,cons:Object.values(cons).sort((a,b)=>b.u-a.u)};}

/* ---------- enfermería ---------- */
function vxEnf(emb){const sub=VX.ui.esub||"hoy";const d=VX.ui.ad||pxToday();
 let h=emb?'<div class="copyrow" style="margin-top:8px"><label class="f" style="max-width:160px">Fecha<input type="date" id="vxad" value="'+esc(d)+'"></label></div>':'<div class="mhead" style="margin-top:6px"><div class="seg">'+[["hoy","Citados con pendientes"],["ord","Procedimientos ordenados"],["reg","Registrado en el mes"]].map(([k,l])=>'<button type="button" data-x="esub|'+k+'" aria-pressed="'+(sub===k)+'">'+l+'</button>').join("")+'</div><div class="copyrow"><label class="f" style="max-width:160px">Fecha<input type="date" id="vxad" value="'+esc(d)+'"></label></div></div>';
 if(sub==="hoy"){const ids=[...new Set(VX.book.cit.filter(vxLive).filter(x=>x.Fecha===d&&x.Estado!=="Canceló").map(x=>x.Paciente))].map(vxP).filter(p=>p&&vxFiltro(p));
  const L=ids.map(p=>({p,v:vxVacEstado(p).filter(e=>e.acc&&e.cls==="warn"),pr:vxL(p.ID,"prc").filter(x=>["Ordenado","Aplicado","Tomada"].includes(x.Estado)),due:vxPrcPend(p).filter(x=>!/Ordenada|Tomada|Aplicada|leer/.test(x.est))})).filter(x=>x.v.length||x.pr.length||x.due.length);
  h+='<p class="note">Pacientes citados el '+esc(d)+' con vacunas o procedimientos pendientes. Lo que confirme se carga en la historia clínica.</p><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th>Vacunas pendientes</th><th>Procedimientos</th></tr></thead><tbody>'+(L.map(x=>'<tr><td>'+vxPacCell(x.p)+'</td><td style="font-size:13px">'+(x.v.map(e=>'<button type="button" class="ch" data-x="vacnew|'+x.p.ID+'|'+e.v.k+'" title="Confirmar aplicación">'+esc(e.v.l+" · "+e.acc)+'</button>').join(" ")||"—")+'</td><td style="font-size:13px">'+x.pr.map(r=>'<button type="button" class="ch" data-x="prcconf|'+r.ID+'">'+esc(r.Tipo+" · "+(r.Estado==="Ordenado"?"aplicar":"resultado"))+'</button>').join(" ")+(x.due.length?' <span class="sub">Por ordenar: '+x.due.map(d=>esc(d.t)).join(", ")+'</span>':'')+'</td></tr>').join("")||'<tr><td colspan="3" class="note">Sin pendientes para los citados de ese día.</td></tr>')+'</tbody></table></div>';}
 if(sub==="ord"){const L=VX.book.prc.filter(vxLive).filter(x=>["Ordenado","Aplicado","Tomada"].includes(x.Estado)&&vxP(x.Paciente)&&vxFiltro(vxP(x.Paciente))).sort((a,b)=>String(a.Ordenado).localeCompare(b.Ordenado));const t=TODAY();
  h+=vxTiles([[L.filter(x=>x.Estado==="Ordenado").length,"por aplicar o tomar"],[L.filter(x=>x.Tipo==="Tuberculina (PPD)"&&x.Estado==="Aplicado").length,"PPD por leer"],[L.filter(x=>x.Tipo==="Tuberculina (PPD)"&&x.Estado==="Aplicado"&&dayDiff(vxD(x.Fecha),t)>3).length,"PPD fuera de la ventana de lectura (más de 72 h)","bad"],[L.filter(x=>x.Estado==="Tomada").length,"citologías sin resultado"]]);
  h+='<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th>Procedimiento</th><th>Ordenado</th><th>Aplicado</th><th>Estado</th><th></th></tr></thead><tbody>'+(L.map(x=>'<tr><td>'+vxPacCell(vxP(x.Paciente))+'</td><td>'+esc(x.Tipo)+'</td><td class="mono">'+esc(x.Ordenado)+'</td><td class="mono">'+esc(x.Fecha||"—")+'</td><td>'+esc(x.Estado)+'</td><td><button type="button" class="btn sm" data-x="prcconf|'+x.ID+'">'+(x.Estado==="Ordenado"?"Confirmar aplicación":"Registrar resultado")+'</button></td></tr>').join("")||'<tr><td colspan="6" class="note">Sin procedimientos pendientes.</td></tr>')+'</tbody></table></div><p class="note">PPD: lectura entre 48 y 72 horas; en personas con VIH una induración de 5 mm o más se considera positiva.</p>';}
 if(sub==="reg"){const m=d.slice(0,7);const V=VX.book.vac.filter(vxLive).filter(v=>String(v.Fecha).startsWith(m)&&v.Estado==="Aplicada");const P=VX.book.prc.filter(vxLive).filter(x=>String(x.Fecha).startsWith(m)&&x.Estado!=="Ordenado");
  h+=vxTiles([[V.length,"dosis aplicadas en "+m],[P.filter(x=>/PPD/.test(x.Tipo)).length,"PPD aplicadas"],[P.filter(x=>/Citolog/.test(x.Tipo)).length,"citologías tomadas"]]);
  h+='<div class="pxcols"><div class="panel"><h3>Vacunas aplicadas</h3>'+hbars(vxCount(V,v=>(VXV[v.Vacuna]||{l:v.Vacuna}).l))+'</div><div class="panel"><h3>Procedimientos</h3>'+hbars(vxCount(P,x=>x.Tipo))+'</div></div>';}
 return h;}

/* ---------- vacunación (consolidado) ---------- */
function vxVacV(){const c=vxCorte();const P=vxPacs().filter(p=>vxFiltro(p)&&vxSt(p,c).activo);const E=P.map(p=>({p,e:vxVacEstado(p,c)}));
 const rows=VX_VAC.map(v=>{let ok=0,pe=0,na=0,ci=0;E.forEach(x=>{const e=x.e.find(y=>y.v.k===v.k);if(e.cls==="ok")ok++;else if(e.cls==="warn")pe++;else if(e.cls==="bad")ci++;else na++;});return{v,ok,pe,na,ci};});
 let h='<div class="copyrow" style="justify-content:flex-end;margin-top:8px"><button type="button" class="btn" data-x="rep|vac">Descargar estado de vacunación</button></div><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Vacuna</th><th class="num">Completa o inmune</th><th class="num">Pendiente</th><th class="num">Contraindicada hoy</th><th class="num">No aplica / valorar</th><th>Cobertura</th></tr></thead><tbody>'+rows.map(r=>{const den=r.ok+r.pe;return'<tr><td><b>'+esc(r.v.l)+'</b><span class="sub">'+esc(r.v.nota)+'</span></td><td class="num">'+r.ok+'</td><td class="num">'+r.pe+'</td><td class="num">'+r.ci+'</td><td class="num">'+r.na+'</td><td>'+(den?'<span class="mono">'+vxPctTxt(r.ok,den)+'</span><span class="bar"><span style="width:'+(r.ok/den*100)+'%"></span></span>':'—')+'</td></tr>';}).join("")+'</tbody></table></div>';
 const Pe=E.filter(x=>x.e.some(e=>e.cls==="warn"));h+='<h3 style="margin:16px 0 6px">Pacientes con vacunas pendientes ('+Pe.length+')</h3><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th>Pendientes</th></tr></thead><tbody>'+Pe.slice(0,200).map(x=>'<tr class="click" data-x="pac|'+x.p.ID+'|enf"><td>'+vxPacCell(x.p)+'</td><td><div class="chs">'+x.e.filter(e=>e.cls==="warn").map(e=>'<span class="ch">'+esc(e.v.l)+'</span>').join("")+'</div></td></tr>').join("")+'</tbody></table></div>';return h;}

