function vxInd(){const set=VX.ui.iset||"cac";const c=vxCorte();const D=VX_IND.filter(d=>d.set===set);const sel=VX.ui.iid&&VXI[VX.ui.iid]&&VXI[VX.ui.iid].set===set?VXI[VX.ui.iid]:null;const P=vxPer(c);
 let h='<div class="mhead" style="margin-top:6px"><div class="seg">'+[["cac","CAC · consenso 2023"],["neps","Nueva EPS · fichas"]].map(([k,l])=>'<button type="button" data-x="iset|'+k+'" aria-pressed="'+(set===k)+'">'+l+'</button>').join("")+'</div><div class="copyrow"><label class="f" style="max-width:170px">Inicio del periodo<input type="date" id="vxpini" value="'+iso(P.ini)+'"></label><button type="button" class="btn" data-x="rep|ind'+set+'">Descargar con anexo nominal</button></div></div>';
 h+='<p class="note">Corte '+iso(c)+' · periodo '+iso(P.ini)+' a '+iso(c)+' · ventana de 6 meses desde '+iso(P.w6)+'. '+(set==="cac"?'Fuente: CAC, Consenso basado en la evidencia: indicadores mínimos para la gestión del riesgo en PVV (actualización, marzo de 2023), Tabla 1. No se calculan 1 a 3 (binomio madre-hijo: requieren la cohorte de gestantes y expuestos).':'Fuente: fichas de indicadores de Nueva EPS (archivo adjunto). «Mes»: denominador de casos nuevos del mes del corte. Rangos semestrales según corte de junio o de diciembre. EPS Familiar: falta su ficha; use el conjunto CAC.')+' Dato faltante = no cumple.</p>';
 const R=D.map(d=>vxCalc(d,c));
 h+='<div class="panel tablebox" style="padding:0"><table class="pxind"><thead><tr><th>Indicador</th><th class="num">Num.</th><th class="num">Den.</th><th class="num">Resultado</th><th>Nivel</th><th>Últimos 6 meses</th><th>Rango</th></tr></thead><tbody>'+R.map(r=>'<tr class="click'+(sel&&sel.id===r.d.id?" sel":"")+'" data-x="ind|'+r.d.id+'"><td><span class="mono" style="font-size:11.5px">'+r.d.id+'</span> '+esc(r.d.n)+(r.d.per?' <span class="tag">'+(r.d.per==="mes"?"mes":"semestral")+'</span>':'')+'<span class="sub">'+esc(r.d.dom)+'</span></td><td class="num">'+r.num+'</td><td class="num">'+r.den+'</td><td class="num mono">'+(r.pct==null?"—":vxF(r.pct,1)+" %")+'</td><td>'+vxSt2([r.nv,r.cls])+'</td><td>'+vxSparkInd(vxTrend(r.d,6))+'</td><td style="font-size:12px;color:var(--muted)">'+esc(vxRngTxt(r.d,c))+'</td></tr>').join("")+'</tbody></table></div>';
 if(sel)h+=vxIndDet(sel,c);return h;}
function vxIndDet(d,c){const r=vxCalc(d,c);const no=r.rows.filter(x=>!x.ok&&x.res!=="Excluido"&&!d.inv),ev=d.inv?r.rows.filter(x=>x.ok):[];const fa=no.filter(x=>x.falta).length;
 const brk=(t,k)=>{const B=vxCalcBy(d,c,VX.ui.f,k);return'<div class="panel tablebox" style="padding:0"><table><thead><tr><th>'+t+'</th><th class="num">Num.</th><th class="num">Den.</th><th class="num">%</th><th>Nivel</th></tr></thead><tbody>'+B.filter(b=>b.den).map(b=>'<tr><td>'+esc(b.k)+'</td><td class="num">'+b.num+'</td><td class="num">'+b.den+'</td><td class="num mono">'+(b.pct==null?"—":vxF(b.pct,1))+'</td><td>'+vxSt2([b.nv,b.cls])+'</td></tr>').join("")+'</tbody></table></div>';};
 let h='<div class="panel inddet" style="margin-top:12px;display:grid;gap:10px"><div><p class="eyebrow">'+d.id+' · '+esc(d.dom)+'</p><h3 style="margin:2px 0;text-transform:none;letter-spacing:0;color:var(--ink);font-size:17px">'+esc(d.n)+'</h3><p class="note" style="margin:0">'+esc(d.nd)+'</p></div>'+
 vxTiles([[r.pct==null?"—":vxF(r.pct,1)+" %",r.num+" de "+r.den,r.cls],[d.inv?ev.length:no.length,d.inv?"con el evento":"no cumplen",d.inv?"":no.length?"bad":"ok"],[d.inv?"—":fa,"de ellos por dato faltante (registro, ventana o laboratorio sin cargar)"],[d.inv?"—":no.length-fa,"brecha clínica o de proceso con dato completo"],[r.rows.filter(x=>x.res==="Excluido").length,"excluidos por definición"]]);
 const by=(k)=>vxCalcBy(d,c,VX.ui.f,k).filter(b=>b.den);h+='<div class="pxcols"><div class="panel" style="grid-column:1/-1"><h3>Tendencia de los últimos 12 cortes mensuales</h3>'+vxTrendSVG(d,vxTrend(d,12))+'<p class="note" style="margin:4px 0 0">Cada barra es el resultado con corte al final del mes; color según el nivel. Líneas punteadas: umbrales Alto y Medio.</p></div><div class="panel"><h3>Por régimen</h3>'+vxBarsPct(by(p=>(VX_REG.find(x=>x[0]===p.Regimen)||[0,"Sin régimen"])[1]))+'</div><div class="panel"><h3>Por municipio</h3>'+vxBarsPct(by(p=>p.Municipio))+'</div><div class="panel"><h3>Por EPS</h3>'+vxBarsPct(by(p=>p.EPS))+'</div></div><details class="panel"><summary>Ver tablas de desagregación</summary><div class="pxcols" style="margin-top:8px">'+brk("Régimen",p=>(VX_REG.find(x=>x[0]===p.Regimen)||[0,"Sin régimen"])[1])+brk("Municipio",p=>p.Municipio)+brk("EPS",p=>p.EPS)+'</div></details>';
 const L=(d.inv?ev:no).concat(r.rows.filter(x=>x.res==="Excluido"));
 h+='<div class="tablebox"><table><thead><tr><th>Paciente</th><th>EPS · municipio</th><th>Resultado</th><th>Detalle</th><th>Causa</th></tr></thead><tbody>'+(L.map(x=>'<tr class="click" data-x="pac|'+x.p.ID+'"><td>'+vxPacCell(x.p)+'</td><td style="font-size:13px">'+esc(x.p.EPS)+'<span class="sub">'+esc(x.p.Municipio||"")+'</span></td><td>'+vxSt2([x.res,x.res==="Excluido"?"base":d.inv?"warn":"bad"])+'</td><td style="font-size:13px">'+esc(x.d||"")+'</td><td style="font-size:12.5px">'+(x.res==="Excluido"?"":x.falta?"Dato faltante":"Brecha clínica o de proceso")+'</td></tr>').join("")||'<tr><td colspan="5" class="note">Sin casos.</td></tr>')+'</tbody></table></div></div>';return h;}

/* ---------- alertas ---------- */
function vxAle(){const c=vxCorte();const nv=VX.ui.anv||"roja";const kd=VX.ui.akd||"";const P=vxPacs().filter(p=>vxFiltro(p)&&vxSt(p,c).activo).map(p=>({p,a:vxAlertas(p,c)}));
 const n={roja:0,amarilla:0,verde:0};P.forEach(x=>n[x.a.nivel]++);
 let h='<div class="mhead" style="margin-top:6px"><div class="seg">'+[["roja","Roja ("+n.roja+")"],["amarilla","Amarilla ("+n.amarilla+")"],["verde","Verde ("+n.verde+")"]].map(([k,l])=>'<button type="button" data-x="anv|'+k+'" aria-pressed="'+(nv===k)+'">'+l+'</button>').join("")+'</div><div class="copyrow"><div class="seg sm">'+[["","Todas"],["clin","Clínicas"],["dato","Dato faltante"]].map(([k,l])=>'<button type="button" data-x="akd|'+k+'" aria-pressed="'+(kd===k)+'">'+l+'</button>').join("")+'</div><button type="button" class="btn" data-x="rep|ale">Descargar alertas</button></div></div>';
 const L=P.filter(x=>x.a.nivel===nv).filter(x=>!kd||x.a.L.some(l=>l.k===kd&&(nv==="verde"||l.n===nv)));
 h+='<p class="note">Roja: sin TAR, CV de 200 o más, sin CV o CD4 vigente, CD4 menor de 200, sospecha de abandono, gestación, TB activa, riesgo de desabastecimiento, pendiente crítico CAC. Amarilla: laboratorio por vencer, tamizajes o vacunas incompletas, sin valoración multidisciplinaria, adherencia irregular, RCV o TFG sin calcular, perfil lipídico alterado. «Dato faltante» separa lo que es registro de lo que es brecha clínica.</p>';
 h+='<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th>EPS · municipio</th><th>Motivos</th></tr></thead><tbody>'+(L.map(x=>'<tr class="click" data-x="pac|'+x.p.ID+'"><td>'+vxPacCell(x.p)+'</td><td style="font-size:13px">'+esc(x.p.EPS)+'<span class="sub">'+esc(x.p.Municipio||"")+'</span></td><td><div class="chs">'+(x.a.L.filter(l=>!kd||l.k===kd).map(l=>vxChip(l.n,l.t+(l.k==="dato"?" · dato":""))).join("")||'<span class="st ok">Seguimiento adecuado</span>')+'</div></td></tr>').join("")||'<tr><td colspan="3" class="note">Sin pacientes en este nivel.</td></tr>')+'</tbody></table></div>';return h;}

