const VX_NOM_COLS=["CONSECUTIVO","IPS ESPECIALIZADA","COD HABILITACION_IPS ATENCION","FECHA DEL INFORME","FECHA INGRESO A LA IPS ","TIPO DE IDENTIFICACION","NUMERO DE IDENTIFICACION","PRIMER APELLIDO","SEGUNDO APELLIDO","PRIMER NOMBRE","SEGUNDO NOMBRE","POBLACION CLAVE","DEPARTAMENTO DE \nRESIDENCIA DEL PACIENTE","MUNICIPIO DE RESIDENCIA DEL PACIENTE","DIRECCIÓN DE RESIDENCIA","DATO DE CONTACTO","FECHA DIAGNÓSTICO","CIE 10 PRINCIPAL","FECHA CARGA VIRAL AL MOMENTO DEL DIAGNOSTICO ","RESULTADO CARGA VIRAL AL MOMENTO DEL DIAGNOSTICO","FECHA CONTEO DE LINFOCITOS CD4 AL MOMENTO DEL DIAGNOSTICO ","RESULTADO CD4 REALIZADO AL MOMENTO DEL DIAGNOSTICO","ESTADIO INICIAL","FECHA INICIO DE PRIMERA TAR ","FECHA  ULTIMO CD4","RESULTADO ULTIMO CD4","FECHA ULTIMA CARGA VIRAL","RESULTADO ULTIMA CARGA VIRAL","RECIBE TRATAMIENTO ANTIRETROVIRAL ACTUALMENTE","ESTADIO ACTUAL","FECHA TOMA PPD","RESULTADO PPD","FECHA TAMIZAJE SIFILIS","RESULTADO PRUEBA SIFILIS","COINFECCION TB","FECHA TAMIZAJE HEPATITIS C","RESULTADO HEPATITIS C","COINFECCION HEPATITIS C","GESTANTE","MODALIDAD ATENCION","NOVEDADES","FECHA DE LA ULTIMA ATENCION","SEDE"];
function vxNominalRows(eps){const c=vxCorte();const out=[];vxPacs().filter(p=>p.EPS===eps&&vxFiltro(Object.assign({},p,{EPS:eps}))).forEach(p=>{const r=vxNomRow(p,c);if(r)out.push({p,r});});out.forEach((x,i)=>x.r.CONSECUTIVO=i+1);return out;}
/* fila de la cohorte nominal de un paciente; force: aunque no esté activo (para verla en su ficha) */
function vxNomRow(p,c,force){const mi=monthStart(c);const W="1800-01-01";{const s=vxSt(p,c);const eg=vxD(p.FechaEgreso);if(!force&&!s.activo&&!(eg&&eg>=mi&&eg<=c))return null;
  const men=p.TipoIngreso==="Menor expuesto en seguimiento";const cvdx=s.cvdx,cd4dx=s.cd4dx;const cv=s.cv,cd4=s.cd4;
  const ppd=vxL(p.ID,"prc").filter(x=>x.Tipo==="Tuberculina (PPD)"&&["Aplicado","Leída"].includes(x.Estado)&&vxD(x.Fecha)<=c).pop();const sif=[vxLast(p.ID,"VDRL",c),vxLast(p.ID,"TREP",c)].filter(Boolean).sort((a,b)=>a._d-b._d).pop();const hc=vxLast(p.ID,"AntiVHC",c);
  const cits=vxL(p.ID,"cit").filter(x=>vxEnRango(vxD(x.Fecha),mi,c));const nov=s.p.Estado==="Fallecido"&&eg>=mi?"4.Fallecido durante el mes":p.Estado==="Desafiliado"&&eg>=mi?"5.Paciente desafiliado":p.Estado==="Trasladado"&&eg>=mi?"6.Traslado de IPS":p.Estado==="Alta"&&eg>=mi?"12.Alta del programa.":men?"10.Menor en seguimiento":s.dx&&s.dx>=mi&&p.TipoIngreso==="Nuevo diagnóstico"?"2.Paciente nuevo":vxHospVIH(p.ID,mi,c).length||vxNovAt(p.ID,/^Hospitalización/,c,mi).length?"8.Hospitalización":(s.ultAt&&dayDiff(s.ultAt,c)>90)?"9.Abandono Tratamiento (Paciente inasistente más de 3 meses)":cits.some(x=>x.Estado==="No asistió")&&!cits.some(x=>x.Estado==="Asistió")?"3.Inasistente durante el mes":"0.No presenta ninguna novedad";
  const r={};const set=(k,v)=>r[k]=v;
  set("IPS ESPECIALIZADA",vxCfg("ips_nombre","IPS POSMEDICA"));set("COD HABILITACION_IPS ATENCION",vxCfg("ips_hab","860010090801"));set("FECHA DEL INFORME",iso(c));set("FECHA INGRESO A LA IPS ",p.FechaIngresoIPS||"");set("TIPO DE IDENTIFICACION",p.TipoDoc);set("NUMERO DE IDENTIFICACION",p.Documento);set("PRIMER APELLIDO",p.PrimerApellido);set("SEGUNDO APELLIDO",p.SegundoApellido||"");set("PRIMER NOMBRE",p.PrimerNombre);set("SEGUNDO NOMBRE",p.SegundoNombre||"");set("POBLACION CLAVE",p.PoblacionClave||"");set("DEPARTAMENTO DE \nRESIDENCIA DEL PACIENTE","PUTUMAYO");set("MUNICIPIO DE RESIDENCIA DEL PACIENTE",norm(p.Municipio||""));set("DIRECCIÓN DE RESIDENCIA",p.Direccion||"");set("DATO DE CONTACTO",p.Telefono||"");
  set("FECHA DIAGNÓSTICO",men?W:(p.FechaDx||""));set("CIE 10 PRINCIPAL",p.CIE10||"B24X");
  set("FECHA CARGA VIRAL AL MOMENTO DEL DIAGNOSTICO ",cvdx?cvdx.FechaToma:W);set("RESULTADO CARGA VIRAL AL MOMENTO DEL DIAGNOSTICO",cvdx?(vxCVind(cvdx)?"0. Indetectable (menor de 50 copias)":"1. Detectable mayor a 50 copias"):"2. No tiene carga viral al momento del diagnostico");
  set("FECHA CONTEO DE LINFOCITOS CD4 AL MOMENTO DEL DIAGNOSTICO ",cd4dx?cd4dx.FechaToma:W);set("RESULTADO CD4 REALIZADO AL MOMENTO DEL DIAGNOSTICO",cd4dx?vxVal(cd4dx):9998);set("ESTADIO INICIAL",["","Estadio 1: Mayor 500","Estadio 2: 200-499","Estadio 3: Menor de 200 o Enfermedad oportunista","Usuarios sin laboratorios"][s.estIni]);
  set("FECHA INICIO DE PRIMERA TAR ",s.tarIni?iso(s.tarIni):W);set("FECHA  ULTIMO CD4",cd4?cd4.FechaToma:W);set("RESULTADO ULTIMO CD4",cd4?vxVal(cd4):9998);
  set("FECHA ULTIMA CARGA VIRAL",cv?cv.FechaToma:W);set("RESULTADO ULTIMA CARGA VIRAL",s.cv6?(vxCVind(s.cv6)?"0. Indetectable (menor de 50 copias)":"1. Detectable mayor a 50 copias"):"2. No tiene carga viral en los últimos 6 meses");
  set("RECIBE TRATAMIENTO ANTIRETROVIRAL ACTUALMENTE",s.recibeTAR?"SI":"NO");set("ESTADIO ACTUAL",["","1. Estadio 1","2. Estadio 2","3. Estadio 3","4. Por establecer"][s.estAct]);
  set("FECHA TOMA PPD",ppd?ppd.Fecha:W);set("RESULTADO PPD",ppd&&ppd.Resultado?(/Positiva/.test(ppd.Resultado)?"1. Positiva":"2. Negativa"):s.tbAlgunaVez?"3. No se realiza por que tiene o tuvo TB activa":"4. No se realizo");if(ppd&&!ppd.Resultado){r["FECHA TOMA PPD"]=W;r["RESULTADO PPD"]="4. No se realizo";}
  set("FECHA TAMIZAJE SIFILIS",sif?sif.FechaToma:W);set("RESULTADO PRUEBA SIFILIS",sif?(vxPos(sif)?"1. Positiva":"2. Negativa"):"4. No se realizo");set("COINFECCION TB",s.tbAct?"SI":"NO");
  set("FECHA TAMIZAJE HEPATITIS C",hc?hc.FechaToma:W);set("RESULTADO HEPATITIS C",hc?(vxPos(hc)?"1. Positiva":"2. Negativa"):"4. No se realizo");set("COINFECCION HEPATITIS C",s.vhc?"SI":"NO");
  set("GESTANTE",s.gest?"SI":"NO");set("MODALIDAD ATENCION",p.Modalidad||"Presencial");set("NOVEDADES",p.NovedadNominal||nov);set("FECHA DE LA ULTIMA ATENCION",s.ultAt?iso(s.ultAt):"");set("SEDE",p.Sede||vxCfg("sede","MOCOA"));
  return r;}}
function vxNominalValidar(rows){const E=[];const add=(x,campo,t)=>E.push({x,campo,t});
 rows.forEach(x=>{const r=x.r;["FECHA INGRESO A LA IPS ","POBLACION CLAVE","DIRECCIÓN DE RESIDENCIA","DATO DE CONTACTO","FECHA DIAGNÓSTICO","FECHA DE LA ULTIMA ATENCION"].forEach(k=>{if(!r[k])add(x,k.trim(),"Campo obligatorio vacío");});
  if(r["FECHA DIAGNÓSTICO"]==="1800-01-01"&&!/^7\./.test(r["POBLACION CLAVE"]))add(x,"FECHA DIAGNÓSTICO","Regla 2: comodín 1800-01-01 solo para menor en seguimiento");
  if(/^7\./.test(r["POBLACION CLAVE"])&&!/^10\./.test(r.NOVEDADES))add(x,"NOVEDADES","Regla 1: menor en seguimiento debe ir con novedad 10");
  const fv=r["FECHA ULTIMA CARGA VIRAL"],rv=r["RESULTADO ULTIMA CARGA VIRAL"];if(fv!=="1800-01-01"&&/^2/.test(rv))add(x,"RESULTADO ULTIMA CARGA VIRAL","Regla 8 vs regla del campo: fecha válida mayor de 6 meses con opción 2 (confirmar con la EPS cuál prima)");
  if(String(r["DATO DE CONTACTO"]).replace(/\D/g,"").length&&String(r["DATO DE CONTACTO"]).replace(/\D/g,"").length<7)add(x,"DATO DE CONTACTO","Teléfono incompleto");
  const e1=r["ESTADIO INICIAL"],a=r["ESTADIO ACTUAL"];if(/Estadio 3/.test(e1)&&!/^3/.test(a)&&!/^4/.test(a))add(x,"ESTADIO ACTUAL","Regla 7: inicial 3 debe seguir en 3");if(/Estadio 2/.test(e1)&&/^1/.test(a))add(x,"ESTADIO ACTUAL","Regla 7: inicial 2 no puede bajar a 1");
  if(r["COD HABILITACION_IPS ATENCION"].length>12)add(x,"COD HABILITACION","Más de 12 dígitos");});return E;}
async function vxNominalExport(){const eps=(VX.ui.f||{}).eps&&(VX.ui.f||{}).eps!=="NUEVA EPS"?null:"NUEVA EPS";if(!eps){toast("La cohorte nominal es de Nueva EPS: quite el filtro de otra EPS.");return;}const c=vxCorte();const rows=vxNominalRows(eps);if(!rows.length){toast("No hay pacientes de Nueva EPS para el corte.");return;}
 const MES=["ENERO","FEBRERO","MARZO","ABRIL","MAYO","JUNIO","JULIO","AGOSTO","SEPTIEMBRE","OCTUBRE","NOVIEMBRE","DICIEMBRE"][c.getMonth()];
 const aoa=[[],[null,null,null,null,null,null,null,null,null,null,"GERENCIA DE PRESTACION DE SERVICIOS"],[null,null,null,null,null,null,null,null,null,null,"JEFATURA ENFERMEDADES DE ALTO IMPACTO"],[],[],[],["AÑO DE REPORTE:",c.getFullYear(),null,"MES DE REPORTE:",MES],VX_NOM_COLS].concat(rows.map(x=>VX_NOM_COLS.map(k=>x.r[k]==null?"":x.r[k])));
 const wb=XLSX.utils.book_new();const ws=XLSX.utils.aoa_to_sheet(aoa);ws["!cols"]=VX_NOM_COLS.map(h=>({wch:Math.min(34,Math.max(10,h.length*0.8))}));XLSX.utils.book_append_sheet(wb,ws,"Plantilla de reporte");
 const E=vxNominalValidar(rows);XLSX.utils.book_append_sheet(wb,sheetFrom(E,[["Consecutivo",e=>e.x.r.CONSECUTIVO],["Documento",e=>e.x.p.Documento],["ID libro VIH",e=>e.x.p.ID],["Campo",e=>e.campo],["Hallazgo",e=>e.t]]),"Validaciones");
 await saveWb(wb,"Cohorte_nominal_VIH_NUEVA_EPS_"+iso(c)+".xlsx");toast(rows.length+" pacientes · "+E.length+" hallazgos de validación en la hoja «Validaciones».");}

/* ---------- reporte CAC (193 variables): arrastre + actualización ---------- */
function vxCACRows(eps){const c=vxCorte();const out=[];const tr=[];vxPacs().filter(p=>p.EPS===eps).forEach(p=>{const x=vxCACRow(p,c);if(!x)return;out.push({p,D:x.D});x.tr.forEach(t=>tr.push(t));});return{out,tr};}
/* fila CAC de un paciente: arrastre (o lo editado en «Datos y cohorte») + variables que calcula el sistema */
function vxCACRow(p,c,force){const P=vxPer(c);const code=vxCfg("epscode",VX_EPSCODE_DEF)[p.EPS]||"";const tr=[];{const s=vxSt(p,c);const eg=vxD(p.FechaEgreso);if(!force&&!s.activo&&!(eg&&eg>=P.ini))return null;const prev=vxIdx().cac[p.ID];let D={};try{D=prev?JSON.parse(prev.Datos):{};}catch(e){D={};}const nuevo=!prev;
  const up=(k,v,f)=>{if(v==null||v==="")return;const a=D[k]==null?"":String(D[k]);if(a!==String(v)){tr.push({p,k,a,v:String(v),f});D[k]=v;}};
  const NM=x=>norm(x).replace(/[^A-Z ]/g,"").trim();const fem=String(p.Sexo).startsWith("F");
  if(code)up("v1ideps",code,"Configuración EPS");up("v2regimen",p.Regimen,"Paciente");up("v3tipodocumentoidentificacionusu",p.TipoDoc,"Paciente");up("v4numerodeidentificacion",p.Documento,"Paciente");up("v5primeapellido",NM(p.PrimerApellido),"Paciente (instructivo var. 5)");up("v6segundoapellido",NM(p.SegundoApellido)||"NOAP","Paciente (instructivo var. 6: NOAP)");up("v7primernombre",NM(p.PrimerNombre),"Paciente (instructivo var. 7)");up("v8segundonombre",NM(p.SegundoNombre)||"NONE","Paciente (instructivo var. 8: NONE)");up("v9fechadenacimiento",p.FechaNac,"Paciente");up("v10sexo",fem?"M":String(p.Sexo).startsWith("M")?"H":String(p.Sexo).startsWith("I")?"I":"","Paciente (H/M/I)");
  const et={"Indígena":1,"ROM (gitano)":2,"Raizal":3,"Palenquero":4,"Negro, mulato, afrocolombiano":5,"Ninguna de las anteriores":6}[p.Etnia];if(et)up("v11codigopertenenciaetnica",et,"Paciente (var. 11)");
  const pc=vxPcCAC(p);if(pc)up("v12poblacionclave",pc,"Paciente (var. 12, homologación por confirmar)");up("v13codigomunicipioresidencia",p.CodMunicipio,"Paciente");
  const gest=vxNovAt(p.ID,/^Gestación/,c,P.ini);up("v15mujergestante",!fem?9:s.gest?1:gest.length?2:3,"Paciente y novedades (var. 15)");
  up("v16menorde12meseshijodemadrre",p.TipoIngreso==="Menor expuesto en seguimiento"&&s.edad!=null&&s.edad<1?1:0,"Paciente (var. 16)");
  const tb=vxNovAt(p.ID,/^Tuberculosis activa/,c,P.ini);up("v17personacontuberculosisactiva",s.tbAct?1:tb.length?2:3,"Novedades (var. 17)");
  up("v18condicionrespectodiagnostico",p.TipoIngreso==="Menor expuesto en seguimiento"?3:1,"Paciente (var. 18)");
  up("v32fechadxtuberculosisactivarepo",tb.length?tb[tb.length-1].Fecha:"1845-01-01","Novedades (var. 32)");
  if(!fem)["v19fechadiagnosticogestacion","v20fechatamizajevihprimertrimest","v21fechatamizajevihsegundotrimes","v22fechatamizajevihtercertrimest","v23fechadetamizajeparavihmomento","v246fechaculminaciongestacionrep"].forEach(k=>up(k,"1845-01-01","Hombre: no aplica (var. 19 a 24.6)"));
  const lp=(ex,fk,vk)=>{const r=vxLast(p.ID,ex,c,P.ini);if(!r)return;up(fk,r.FechaToma,"Laboratorio "+ex);if(num(r.Valor)!=null)up(vk,num(r.Valor),"Laboratorio "+ex);};
  lp("LDL","v56fechadeultimocolesterolldl","v561resultadodelultimocolesterol");lp("TG","v57fechadeultimoniveldetriglicer","v571resultadodelultimoniveldetri");lp("Hb","v58fechadeultimahemoglobinaseric","v581resultadodelaultimahemoglobi");lp("ALT","v59fechadelaultimaenzimaalaninaa","v591resultadodelaultimaaltotgpse");lp("Cr","v60fechadeultimacreatininaserica","v601resultadodelaultimacreatinin");lp("Glu","v61fechadeultimaglucemiasericaen","v611resultadodelaultimaglucemias");lp("CD4","v75fechadelultimoconteodelinfoci","v751valordelultimoconteodelinfoc");lp("CV","v76fechadelaultimacargaviralpara","v761valordelaultimacargaviralpar");
  const w=vxL(p.ID,"val").filter(v=>v.Peso&&vxEnRango(vxD(v.Fecha),P.ini,c)).pop();if(w){up("v62fechadeultimamediciondelpesoc",w.Fecha,"Valoración");up("v621resultadodelaultimamediciond",w.Peso,"Valoración");if(w.Talla)up("v63talla",w.Talla,"Valoración");}
  if(s.tarIni)up("v42fechadeiniciodelaterapiaantir",iso(s.tarIni),"TAR (primer esquema)");if(s.tar)up("v771fechadeiniciodelosmedicament",s.tar.Inicio,"TAR (esquema actual)");
  if(s.ing)up("v531fechadeingresoalaipsactualpa",iso(s.ing),"Paciente");if(s.dx)up("v36fechadeconfirmaciondedxinfecc",iso(s.dx),"Paciente");if(p.FechaAfiliacion)up("v14fechaafiliacionentidad",p.FechaAfiliacion,"Paciente");
  up("v98fechadecorte",iso(c),"Corte");if(nuevo)tr.push({p,k:"(todas)",a:"",v:"POR DILIGENCIAR",f:"Paciente sin arrastre CAC: completar las variables codificadas con el instructivo vigente"});
  return{D,tr,nuevo};}}
function vxPcCAC(p){const t=p.PoblacionClave||"";const f=String(p.Sexo).startsWith("F");if(/^1\./.test(t))return 4;if(/^2\./.test(t))return 1;if(/^3\./.test(t))return 8;if(/^5\./.test(t))return f?3:2;if(/^4\./.test(t))return f?9:4;if(/^[67]\./.test(t))return 9;return null;}
function vxCACValidar(out){const E=[];const c=vxCorte();out.forEach(x=>{const D=x.D;const fn=pdate(D.v9fechadenacimiento),fa=pdate(D.v14fechaafiliacionentidad);if(fn&&fa&&fn>fa)E.push({x,k:"v9",t:"Fecha de nacimiento posterior a la fecha de afiliación (var. 9)"});if(fn&&fn>=c)E.push({x,k:"v9",t:"Fecha de nacimiento no anterior al corte"});if(D.v10sexo==="H"&&String(D.v15mujergestante)!=="9")E.push({x,k:"v15",t:"Hombre con variable 15 distinta de 9"});["v5primeapellido","v7primernombre"].forEach(k=>{if(/[^A-Z ]/.test(String(D[k]||"")))E.push({x,k,t:"Caracteres no permitidos (tildes, símbolos o números)"});});if(!D.v14fechaafiliacionentidad)E.push({x,k:"v14",t:"Sin fecha de afiliación (no está en el libro VIH: completar desde BDUA)"});});return E;}
async function vxCACExport(eps){const{out,tr}=vxCACRows(eps);if(!out.length){toast("No hay pacientes de "+eps+" para el reporte CAC.");return;}const c=vxCorte();
 const wb=XLSX.utils.book_new();const aoa=[VX_CAC_COLS].concat(out.map(x=>VX_CAC_COLS.map(k=>x.D[k]==null?"":x.D[k])));XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(aoa),"CAC");
 XLSX.utils.book_append_sheet(wb,sheetFrom(vxCACValidar(out),[["ID libro VIH",e=>e.x.p.ID],["Documento",e=>e.x.p.Documento],["Variable",e=>e.k],["Hallazgo",e=>e.t]]),"Validaciones");
 XLSX.utils.book_append_sheet(wb,sheetFrom(tr,[["ID libro VIH",t=>t.p.ID],["Documento",t=>t.p.Documento],["Variable",t=>t.k],["Valor anterior (arrastre)",t=>t.a],["Valor nuevo",t=>t.v],["Fuente",t=>t.f]]),"Trazabilidad");
 XLSX.utils.book_append_sheet(wb,sheetFrom([{t:"Variables 1 a 18 y 32 según el instructivo de EPS Familiar adjunto: identificación en mayúsculas sin tildes, NOAP y NONE, sexo H/M/I, etnia, población clave (homologación de la lista de Nueva EPS a la de la CAC: por confirmar), municipio DIVIPOLA, gestante, menor expuesto, TB activa y condición frente al diagnóstico. Variables 19 a 24.6 en 1845-01-01 para hombres."},{t:"Además: LDL, triglicéridos, hemoglobina, ALT, creatinina, glucemia, peso y talla, último CD4, última carga viral y fecha de corte, con el último dato del periodo."},{t:"El instructivo recibido llega hasta la variable 34. Las demás (TAR y medicamentos, estadio, coinfecciones, profilaxis, novedades, costos) se conservan del último reporte cargado (arrastre) hasta recibir el resto del instructivo."},{t:"Pacientes sin arrastre aparecen con la marca POR DILIGENCIAR en Trazabilidad."}],[["Nota",x=>x.t]]),"Leame");
 await saveWb(wb,"CAC_VIH_"+eps.replace(/\W+/g,"_")+"_"+iso(c)+".xlsx");}
async function vxCarnet(pid){const p=vxP(pid);const E=vxVacEstado(p);const rows=[];E.forEach(e=>{if(e.D.length)e.D.forEach(d=>rows.push({v:e.v.l,d:d.Dosis,f:d.Fecha,l:d.Lote,s:d.Estado,e:e.est}));else rows.push({v:e.v.l,d:"",f:"",l:"",s:"",e:e.est});});
 await pxExport("Carne_vacunacion_"+p.ID+".xlsx",[["Carné",rows,[["Vacuna",r=>r.v],["Dosis",r=>r.d],["Fecha",r=>r.f],["Lote",r=>r.l],["Registro",r=>r.s],["Estado del esquema",r=>r.e]]]]);}

/* ---------- comparar con la base enviada (cohorte nominal) ---------- */
async function vxCompare(f){try{const wb=await vxReadFile(f);let rows=null;for(const sn of wb.SheetNames){const A=XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,raw:true,defval:null});const hi=A.findIndex(r=>r&&r.some(c=>vxNH(c)==="CONSECUTIVO"));if(hi<0)continue;const H=A[hi].map(vxNH);rows=A.slice(hi+1).filter(r=>r&&r[H.findIndex(h=>/NUMERO DE IDENTIFICACION/.test(h))]).map(r=>Object.fromEntries(H.map((h,i)=>[h,r[i]])));break;}
 if(!rows){toast("No se encontró la plantilla de la cohorte nominal en ese archivo.");return;}const mine=vxNominalRows("NUEVA EPS");const M=new Map(mine.map(x=>[String(x.p.Documento),x]));const B=new Map(rows.map(r=>[String(r["NUMERO DE IDENTIFICACION"]).replace(/\D/g,""),r]));
 const onlyB=[...B.keys()].filter(k=>!M.has(k)).length,onlyM=[...M.keys()].filter(k=>!B.has(k)).length;const both=[...B.keys()].filter(k=>M.has(k));const un=new Set([...B.keys(),...M.keys()]).size;
 const cmp=(n,f)=>{const d=both.filter(k=>f(B.get(k))!==f(M.get(k).r)).length;return{n,pct:both.length?d/both.length*100:0,det:d+" de "+both.length+" pacientes en ambas bases"};};
 VX.ui.cmp=[{n:"Pacientes presentes en una sola base",pct:un?(onlyB+onlyM)/un*100:0,det:onlyB+" solo en la enviada · "+onlyM+" solo en el libro"},cmp("Recibe TAR",r=>String(r["RECIBE TRATAMIENTO ANTIRETROVIRAL ACTUALMENTE"]||"").trim().toUpperCase()),cmp("Resultado de la última carga viral",r=>String(r["RESULTADO ULTIMA CARGA VIRAL"]||"").trim().charAt(0)),cmp("Fecha del último CD4",r=>vxDt(r["FECHA ULTIMO CD4"]||r["FECHA  ULTIMO CD4"]))];pxRender();toast("Comparación lista.");}catch(e){console.error(e);toast("No se pudo comparar: "+e.message);}}
/* ================= v0.5 · PROGRAMA VIH · navegación por grupos y ficha del paciente ================= */
/* Siete grupos en orden de trabajo: Inicio → Agenda → Pacientes → Gestión clínica → Indicadores → Reportes → Ruta.
   La ficha del paciente sigue el orden de la atención: resumen, datos y cohorte, valoraciones e HC, laboratorios, TAR, enfermería, historial. */
const VX_TABL={tab:"Inicio",age:"Agenda",pob:"Población",aud:"Auditoría de HC",car:"Caracterización",lab:"Laboratorios",prc:"Procedimientos y enfermería",tar:"TAR",vac:"Vacunación",ale:"Alertas",ind:"Indicadores",rep:"Descargas",fac:"Facturación",cal:"Calidad del dato",ruta:"Ruta y contrato"};
const VX_GRP=[["Inicio",["tab"]],["Agenda",["age"]],["Pacientes",["pob","aud","car"]],["Gestión clínica",["lab","prc","tar","vac","ale"]],["Indicadores",["ind"]],["Reportes",["rep","fac","cal"]],["Ruta y contrato",["ruta"]]];
function vxView(){if(!VX.book)return vxStart();const t=vxTab();let h=vxHead();
 try{h+=({tab:vxTablero,age:vxAgenda,pob:vxPob,aud:vxAud,car:vxCar,lab:vxLab,prc:vxPrc,tar:vxTarV,vac:vxVacV,ale:vxAle,ind:vxInd,rep:vxRep,fac:vxFac,cal:vxCal,ruta:vxRuta,pac:vxPac})[t]();}
 catch(e){console.error(e);h+='<div class="alert bad"><p>Error al dibujar esta vista: '+esc(e.message)+'</p></div>';}return h;}
function vxHead(){const c=vxCorte();const F=VX.ui.f||{};const t=vxTab();const pid=vxPid();const muns=[...new Set(vxPacs().map(p=>p.Municipio).filter(Boolean))].sort();
 const nRoja=vxPacs().filter(p=>vxFiltro(p)&&vxAlertas(p,c).nivel==="roja").length;const g=pid?2:VX_GRP.findIndex(x=>x[1].includes(t));
 let h='<div class="mhead"><div><p class="eyebrow">Programa misional'+(VX.demo?' · <span style="color:var(--warn)">datos ficticios</span>':'')+'</p><h2 class="mt">VIH</h2><p class="note" style="margin:3px 0 0">'+vxPacs().filter(p=>vxSt(p,c).activo).length+' activos al corte · libro '+(VX.dirty?'<b style="color:var(--warn)">con cambios sin descargar</b>':'sin cambios')+'</p></div>'+
 '<div class="copyrow"><label class="f" style="max-width:160px">Fecha de corte<input type="date" id="vxcorte" value="'+iso(c)+'"></label><button type="button" class="btn sm'+(VX.dirty?' warn':'')+'" data-x="bookexp">Descargar libro VIH</button><label class="btn sm" for="vximp2">Importar</label><input type="file" id="vximp2" accept=".xlsx,.xls" hidden multiple><button type="button" class="btn sm" data-x="unload">Cerrar libro</button></div></div>';
 h+='<details class="vxfd"'+(Object.values(F).some(Boolean)?' open':'')+'><summary>Filtros'+(Object.values(F).some(Boolean)?' <span class="tag">'+Object.values(F).filter(Boolean).map(esc).join(" · ")+'</span>':'')+'</summary><div class="filters vxfil"><label class="f">EPS<select id="vxf_eps">'+opt([...new Set(vxPacs().map(p=>p.EPS).filter(Boolean))].sort(),F.eps||"","Todas")+'</select></label><label class="f">Régimen<select id="vxf_reg">'+opt(VX_REG,F.reg||"","Todos")+'</select></label><label class="f">Municipio<select id="vxf_mun">'+opt(muns,F.mun||"","Todos")+'</select></label><label class="f">Sexo<select id="vxf_sexo">'+opt([["M","Masculino"],["F","Femenino"]],F.sexo||"","Todos")+'</select></label><label class="f">Población clave<select id="vxf_pc">'+opt(VX_PCLAVE,F.pc||"","Todas")+'</select></label><label class="f">Modalidad<select id="vxf_mod">'+opt(VX_MODAL,F.mod||"","Todas")+'</select></label></div></details>';
 h+='<nav class="nav vxnav" role="tablist">'+VX_GRP.map(([l,T],i)=>'<button type="button" role="tab" data-p="go|vih|'+T[0]+'" aria-selected="'+(g===i)+'">'+l+(l==="Gestión clínica"&&nRoja?' <span class="cnt" title="Pacientes en alerta roja">'+nRoja+'</span>':'')+'</button>').join("")+'</nav>';
 const G=VX_GRP[g];if(!pid&&G&&G[1].length>1)h+='<div class="seg vxsub">'+G[1].map(k=>'<button type="button" data-p="go|vih|'+k+'" aria-pressed="'+(t===k)+'">'+VX_TABL[k]+(k==="ale"&&nRoja?' <span class="cnt">'+nRoja+'</span>':'')+'</button>').join("")+'</div>';
 if(pid)h+='<p class="note vxcrumb"><button type="button" class="lnk" data-p="go|vih|pob">Pacientes</button> / '+esc(pid)+'</p>';
 return h;}

/* ---------- ficha del paciente ---------- */
const VX_PTABS=[["res","Resumen"],["dat","Datos y cohorte"],["val","Valoraciones e HC"],["lab","Laboratorios"],["tar","TAR"],["enf","Enfermería"],["his","Historial"]];
function vxPac(){const p=vxP(vxPid());if(!p)return'<div class="panel empty">Paciente no encontrado.</div>';const c=vxCorte();const s=vxSt(p,c);const a=vxAlertas(p,c);let pt=VX.ui.vedit?"val":(VX.ui.ptab||"res");if(!VX_PTABS.some(x=>x[0]===pt))pt="res";const au=vxAudit(p);
 let h='<div class="panel vxpac"><div class="mhead"><div><p class="eyebrow">'+esc(p.ID)+' · '+esc(p.TipoDoc+" "+p.Documento)+'</p><h2 class="mt">'+esc(vxNom(p))+'</h2><p class="note" style="margin:3px 0 0">'+(s.edad==null?"":s.edad+" años · ")+esc(p.Sexo||"")+' · '+esc(p.EPS)+' '+esc(p.Regimen||"")+' · '+esc(p.Municipio||"")+' · '+esc(p.PoblacionClave||"sin población clave")+' · '+esc(p.Estado)+'</p></div><div class="copyrow"><span class="vxaudchip '+au.cls+'" title="Lista de chequeo de auditoría CAC de la historia clínica">HC auditable <b>'+au.pct+' %</b></span><button type="button" class="btn sm primary" data-x="valnew|'+p.ID+'">Nueva valoración</button><button type="button" class="btn sm" data-x="citnew|'+p.ID+'">Programar cita</button><button type="button" class="btn sm" data-x="notif|'+p.ID+'">Notificar</button><button type="button" class="btn sm" data-x="spnew|'+p.ID+'">Evento de seguridad</button></div></div>'+
 (a.L.length?'<div class="chs" style="margin-top:8px">'+a.L.map(l=>vxChip(l.n,l.t)).join("")+'</div>':'<p class="note" style="color:var(--ok)">Alerta verde: sin pendientes críticos.</p>')+'</div>';
 h+='<div class="seg" style="margin-top:10px">'+VX_PTABS.map(([k,l])=>'<button type="button" data-x="ptab|'+k+'" aria-pressed="'+(pt===k)+'">'+l+'</button>').join("")+'</div>';
 h+=({res:vxPacRes,dat:vxPacDat,val:vxPacVal,lab:vxPacLab,tar:vxPacTar,enf:vxPacEnf,his:vxPacHis})[pt](p,s);return h;}
function vxPacRes(p,s){const c=s.c;const ag=VX_DISC.map(d=>vxAgEstado(p,d)).filter(x=>x.cls!=="ok");const lp=vxLabPlan(p);const lf=lp.filter(x=>["Faltante","Vencido"].includes(x.est));const nx=lp.filter(x=>x.next).sort((a,b)=>a.next-b.next)[0];const pr=vxPrcPend(p);
 let h='<div class="pxcols"><div class="panel"><h3>Programa</h3><dl class="ficha vxficha"><dt>Diagnóstico</dt><dd>'+esc(p.FechaDx||"—")+' · '+esc(p.TipoIngreso||"")+'</dd><dt>Ingreso IPS</dt><dd>'+esc(p.FechaIngresoIPS||"—")+'</dd><dt>TAR previo</dt><dd>'+esc(p.TARPrevio||"Sin documentar")+(p.TARPrevioDetalle?" · "+esc(p.TARPrevioDetalle):"")+'</dd><dt>Esquema</dt><dd>'+(s.tar?esc(s.tar.Esquema)+" desde "+esc(s.tar.Inicio)+(s.tar.Validacion?' <span class="st ok">validado</span>':' <span class="st warn">sin validar</span>'):'<span class="bad-t">Sin TAR al corte</span>')+'</dd><dt>Entrega</dt><dd>'+(s.ent?esc(s.ent.Fecha)+" · cubre hasta "+iso(s.cob):"—")+'</dd><dt>Estadio</dt><dd>Inicial '+(s.estIni===4?"sin CD4":s.estIni)+' · actual '+(s.estAct===4?"por establecer":s.estAct)+'</dd><dt>Teléfono</dt><dd>'+esc(p.Telefono||"—")+(p.ContactoRed?' · red: '+esc(p.ContactoRed):'')+'</dd></dl></div>';
 h+='<div class="panel"><h3>Perfil inmunovirológico</h3><dl class="ficha vxficha"><dt>Última CV</dt><dd>'+(s.cv?esc(vxFmtLab(s.cv))+" · "+iso(s.cv._d)+(s.cv6?"":' <span class="bad-t">vencida</span>'):"—")+'</dd><dt>Último CD4</dt><dd>'+(s.cd4?vxF(vxVal(s.cd4),0)+" cél/µL · "+iso(s.cd4._d)+(s.cd46?"":' <span class="bad-t">vencido</span>'):"—")+'</dd><dt>SMAQ</dt><dd>'+(s.smaq?esc(s.smaq.SMAQ+" · "+s.smaq.Fecha):"Sin medición en 6 meses")+'</dd><dt>RCV</dt><dd>'+(s.rcv?esc((s.rcv.RCV?s.rcv.RCV+" % ":"")+(s.rcv.RCVCat||"")+" · "+s.rcv.Fecha):(s.edad>=40?"Pendiente":"No aplica por edad"))+'</dd></dl>'+vxSpark(p.ID)+'</div>';
 h+='<div class="panel"><h3>Lo que falta y lo que sigue</h3><ul class="pxsrc"><li><b>Laboratorios:</b> '+(lf.length?lf.length+' faltantes o vencidos ('+lf.slice(0,5).map(x=>esc(VXE[x.k].l)).join(", ")+(lf.length>5?"…":"")+')':'al día')+(nx?'. Próxima toma: <b>'+iso(nx.next)+'</b> ('+lp.filter(x=>x.next&&iso(x.next)===iso(nx.next)).map(x=>esc(VXE[x.k].l)).join(", ")+')':'')+' · <button type="button" class="lnk" data-x="ptab|lab">ver</button></li><li><b>Procedimientos:</b> '+(pr.length?pr.map(x=>esc(x.t+": "+x.est)).join(" · "):"al día")+' · <button type="button" class="lnk" data-x="ptab|enf">ver</button></li><li><b>Agenda:</b> '+(ag.length?ag.map(x=>esc(x.d+": "+x.txt)).join(" · "):"al día")+'</li></ul></div></div>';
 h+=vxRutaPaciente(p,s);return h;}
/* historial: todo lo que le ha pasado al paciente, más reciente primero */
function vxPacHis(p){const E=[];const add=(f,t,d,x)=>{if(f)E.push({f:String(f),t,d,x});};
 vxL(p.ID,"cit").forEach(c=>{const v=vxL(p.ID,"val").find(v=>v.Cita===c.ID);add(c.Fecha,"Agenda",c.Disciplina+" · "+c.Estado+(c.Motivo?" · "+c.Motivo:""),v?'<button type="button" class="btn sm" data-x="valopen|'+v.ID+'">Ver atención</button>':c.Estado==="Asistió"||c.Estado==="Programada"?'<button type="button" class="btn sm" data-x="valcita|'+c.ID+'">'+(c.Estado==="Programada"?"Atender":"Registrar valoración")+'</button>':"");});
 vxL(p.ID,"val").filter(v=>!v.Cita).forEach(v=>add(v.Fecha,"Valoración",v.Disciplina+(v.Profesional?" · "+v.Profesional:""),'<button type="button" class="btn sm" data-x="valopen|'+v.ID+'">Ver atención</button>'));
 const lb={};vxL(p.ID,"lab").forEach(r=>{(lb[r.FechaToma]=lb[r.FechaToma]||[]).push(r.Examen);});Object.entries(lb).forEach(([f,L])=>add(f,"Laboratorio",L.join(", "),""));
 vxL(p.ID,"tar").forEach(t=>add(t.Inicio,"TAR","Inicio de "+t.Esquema+(t.Motivo?" · "+t.Motivo:""),""));vxL(p.ID,"ent").forEach(e=>add(e.Fecha,"Entrega TAR",e.Esquema+" · "+e.Meses+" mes(es) · "+(e.Lugar||""),""));
 vxL(p.ID,"prc").forEach(x=>add(x.Fecha||x.Ordenado,"Procedimiento",x.Tipo+" · "+x.Estado+(x.Resultado?" · "+x.Resultado:""),""));vxL(p.ID,"vac").forEach(v=>add(v.Fecha,"Vacuna",(VXV[v.Vacuna]||{l:v.Vacuna}).l+" "+(v.Dosis||"")+" · "+v.Estado,""));vxL(p.ID,"nov").forEach(n=>add(n.Fecha,"Novedad",n.Tipo+(n.Detalle?" · "+n.Detalle:""),""));
 E.sort((a,b)=>b.f.localeCompare(a.f));const tp=VX.ui.htip||"";const T=[...new Set(E.map(e=>e.t))];
 return'<div class="copyrow" style="margin:8px 0"><div class="seg sm">'+[""].concat(T).map(k=>'<button type="button" data-x="htip|'+esc(k)+'" aria-pressed="'+(tp===k)+'">'+(k||"Todo")+'</button>').join("")+'</div></div><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Detalle</th><th></th></tr></thead><tbody>'+E.filter(e=>!tp||e.t===tp).slice(0,300).map(e=>'<tr><td class="mono">'+esc(e.f)+'</td><td><span class="tag">'+esc(e.t)+'</span></td><td style="font-size:13.5px">'+esc(e.d)+'</td><td>'+e.x+'</td></tr>').join("")+'</tbody></table></div>';}

/* ---------- datos y cohorte: todo lo que se reporta, editable ---------- */
const VX_NOM_SRC={"FECHA INGRESO A LA IPS ":"dat","TIPO DE IDENTIFICACION":"dat","NUMERO DE IDENTIFICACION":"dat","PRIMER APELLIDO":"dat","SEGUNDO APELLIDO":"dat","PRIMER NOMBRE":"dat","SEGUNDO NOMBRE":"dat","POBLACION CLAVE":"dat","MUNICIPIO DE RESIDENCIA DEL PACIENTE":"dat","DIRECCIÓN DE RESIDENCIA":"dat","DATO DE CONTACTO":"dat","FECHA DIAGNÓSTICO":"dat","CIE 10 PRINCIPAL":"dat","FECHA CARGA VIRAL AL MOMENTO DEL DIAGNOSTICO ":"lab","RESULTADO CARGA VIRAL AL MOMENTO DEL DIAGNOSTICO":"lab","FECHA CONTEO DE LINFOCITOS CD4 AL MOMENTO DEL DIAGNOSTICO ":"lab","RESULTADO CD4 REALIZADO AL MOMENTO DEL DIAGNOSTICO":"lab","ESTADIO INICIAL":"lab","FECHA INICIO DE PRIMERA TAR ":"tar","FECHA  ULTIMO CD4":"lab","RESULTADO ULTIMO CD4":"lab","FECHA ULTIMA CARGA VIRAL":"lab","RESULTADO ULTIMA CARGA VIRAL":"lab","RECIBE TRATAMIENTO ANTIRETROVIRAL ACTUALMENTE":"tar","ESTADIO ACTUAL":"lab","FECHA TOMA PPD":"enf","RESULTADO PPD":"enf","FECHA TAMIZAJE SIFILIS":"lab","RESULTADO PRUEBA SIFILIS":"lab","COINFECCION TB":"nov","FECHA TAMIZAJE HEPATITIS C":"lab","RESULTADO HEPATITIS C":"lab","COINFECCION HEPATITIS C":"nov","GESTANTE":"dat","MODALIDAD ATENCION":"dat","NOVEDADES":"dat","FECHA DE LA ULTIMA ATENCION":"age","SEDE":"dat"};
const VX_SRC_TXT={dat:"Datos del paciente",lab:"Laboratorios",tar:"TAR",enf:"Enfermería (PPD)",nov:"Novedades",age:"Agenda"};
function vxPacDat(p,s){const sub=VX.ui.dsub||"pac";const c=vxCorte();
 let h='<div class="seg sm" style="margin:8px 0">'+[["pac","Paciente"],["nov","Antecedentes y novedades"],["nom","Cohorte Nueva EPS (43 campos)"],["cac","Variables CAC (193)"]].map(([k,l])=>'<button type="button" data-x="dsub|'+k+'" aria-pressed="'+(sub===k)+'">'+l+'</button>').join("")+'</div>';
 if(sub==="pac"){const G=[["Identificación",["TipoDoc","Documento","PrimerNombre","SegundoNombre","PrimerApellido","SegundoApellido","FechaNac","Sexo","Etnia","OrientacionSexual"]],["Afiliación y contacto",["EPS","Regimen","FechaAfiliacion","Municipio","CodMunicipio","Zona","Direccion","Telefono","ContactoRed","Sede","Modalidad"]],["Sociodemográficos",["NaturalDe","Escolaridad","Ocupacion","EstadoCivil","PoblacionClave","PracticaAnal","Barreras"]],["Diagnóstico e ingreso",["TipoIngreso","FechaDx","CIE10","DxOtraIPS","SoporteDx","MotivoTamizaje","PruebasDx","Mecanismo","OportunistaDx","FechaPresentacion","FechaIngresoIPS"]],["TAR previo",["TARPrevio","TARPrevioDetalle"]],["Estado",["Gestante","Estado","FechaEgreso","MotivoEgreso","NovedadNominal","Observaciones"]]];
  return h+'<div class="copyrow"><button type="button" class="btn primary" data-x="pacedit|'+p.ID+'">Editar datos del paciente</button></div><div class="pxcols" style="margin-top:8px">'+G.map(([t,F])=>'<div class="panel"><h3>'+t+'</h3><dl class="ficha vxficha">'+F.map(f=>'<dt>'+esc(VX_PLBL[f]||f)+'</dt><dd>'+(p[f]?esc(p[f]):'<span class="sd">sin dato</span>')+'</dd>').join("")+'</dl></div>').join("")+'</div>';}
 if(sub==="nov")return h+vxPacNov(p);
 if(sub==="nom"){const r=vxNomRow(p,c,true);
  return h+'<p class="note">Lo que se reportará para '+esc(p.ID)+' en la cohorte nominal de Nueva EPS con corte '+iso(c)+'. Cada campo se corrige donde nace: el botón lleva a esa pestaña.'+(p.EPS!=="NUEVA EPS"?' <b>El paciente es de '+esc(p.EPS)+'</b>: esta fila no entra en la cohorte de Nueva EPS.':'')+'</p><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Campo</th><th>Valor del reporte</th><th>Se corrige en</th></tr></thead><tbody>'+VX_NOM_COLS.filter(k=>k!=="CONSECUTIVO").map(k=>{const src=VX_NOM_SRC[k];const v=r[k];const vacio=v==null||v===""||v==="1800-01-01"||v===9998;return'<tr><td style="font-size:13px">'+esc(k.replace(/\s+/g," ").trim())+'</td><td class="mono" style="font-size:12.5px'+(vacio?';color:var(--warn)':'')+'">'+esc(v==null?"":v)+'</td><td>'+(src?(src==="nov"?'<button type="button" class="lnk" data-x="dsub|nov">'+VX_SRC_TXT[src]+'</button>':src==="dat"?'<button type="button" class="lnk" data-x="pacedit|'+p.ID+'">'+VX_SRC_TXT[src]+'</button>':src==="age"?'<button type="button" class="lnk" data-x="ptab|his">'+VX_SRC_TXT[src]+'</button>':'<button type="button" class="lnk" data-x="ptab|'+src+'">'+VX_SRC_TXT[src]+'</button>'):'<span class="sd">configuración / corte</span>')+'</td></tr>';}).join("")+'</tbody></table></div><p class="note">«NOVEDADES» se calcula con agenda, egresos y hospitalizaciones; si necesita forzarla, use «Novedad nominal (forzar)» en Editar datos.</p>';}
 const x=vxCACRow(p,c,true);const sys=new Set(x.tr.map(t=>t.k));const q=norm(VX.ui.cq||"");
 h+='<p class="note">Las 193 variables del reporte CAC (estructura del archivo de EPS Familiar). <b>Calculadas</b>: las arma el sistema con los datos del paciente, laboratorios, TAR y novedades; se corrigen en su origen. <b>Editables</b>: vienen del último reporte (arrastre) o se diligencian aquí con el instructivo vigente.'+(x.nuevo?' <b>Paciente sin arrastre</b>: diligencie las variables codificadas.':'')+'</p><div class="copyrow"><label class="f" style="max-width:260px">Buscar variable<input type="text" id="vxcq" value="'+esc(VX.ui.cq||"")+'" placeholder="número o palabra"></label><button type="button" class="btn primary" data-x="cacsave|'+p.ID+'">Guardar variables editadas</button></div>';
 const grp=[["Identificación (1 a 18)",1,18],["Gestación y menores expuestos (19 a 31)",19,31],["Tuberculosis y diagnóstico de VIH (32 a 45)",32,45],["TAR inicial y cambios (46 a 51)",46,51],["Eventos definitorios de sida (52)",52,52],["IPS, seguimiento y paraclínicos (53 a 63)",53,63],["Comorbilidades y coinfecciones (64 a 74)",64,74],["CD4, carga viral y TAR actual (75 a 79)",75,79],["Vacunas, tamizajes y profilaxis (80 a 93)",80,93],["Costos, hospitalizaciones y novedades (94 a 99)",94,99]];
 const vn=k=>{const m=/^v(\d+)/.exec(k);if(!m)return 0;const d=m[1];if(d.length>=3&&+d.slice(0,2)>=24&&+d.slice(0,2)<=99&&k.startsWith("v"+d.slice(0,2)))return +d.slice(0,2);return +d;};
 h+=grp.map(([t,a,b])=>{const K=VX_CAC_COLS.filter(k=>{const n=vxCacNum(k);return n>=a&&n<=b;}).filter(k=>!q||norm(k+" "+vxCacLbl(k)).includes(q));if(!K.length)return"";return'<details class="vxcac"'+(q||a===1?' open':'')+'><summary>'+t+' <span class="sub">'+K.length+' variables</span></summary><div class="vxcacg">'+K.map(k=>{const v=x.D[k]==null?"":x.D[k];const is=sys.has(k)||["v98fechadecorte"].includes(k);return'<label class="f'+(is?" sys":"")+'"><span><b class="mono">'+esc(vxCacCod(k))+'</b> '+esc(vxCacLbl(k))+'</span>'+(is?'<input type="text" value="'+esc(v)+'" disabled title="Calculada por el sistema">':'<input type="text" data-cac="'+esc(k)+'" value="'+esc(v)+'">')+'</label>';}).join("")+'</div></details>';}).join("");
 return h;}
const VX_PLBL={TipoDoc:"Tipo de documento",Documento:"Documento",PrimerNombre:"Primer nombre",SegundoNombre:"Segundo nombre",PrimerApellido:"Primer apellido",SegundoApellido:"Segundo apellido",FechaNac:"Nacimiento",Sexo:"Sexo",Etnia:"Etnia",OrientacionSexual:"Orientación sexual",EPS:"EPS",Regimen:"Régimen",FechaAfiliacion:"Afiliación a la EPS",Municipio:"Municipio",CodMunicipio:"Código DANE",Zona:"Zona",Direccion:"Dirección",Telefono:"Teléfono",ContactoRed:"Red de apoyo",Sede:"Sede",Modalidad:"Modalidad",NaturalDe:"Natural de",Escolaridad:"Escolaridad",Ocupacion:"Ocupación",EstadoCivil:"Estado civil",PoblacionClave:"Población clave",PracticaAnal:"Prácticas anales receptivas",Barreras:"Barreras de acceso",TipoIngreso:"Tipo de ingreso",FechaDx:"Confirmación dx",CIE10:"CIE-10",DxOtraIPS:"Dx en otra IPS/EPS",SoporteDx:"Soporte del dx",MotivoTamizaje:"Motivo del tamizaje",PruebasDx:"Pruebas del dx",Mecanismo:"Mecanismo",OportunistaDx:"Oportunista al dx",FechaPresentacion:"Asignación de cita",FechaIngresoIPS:"Ingreso a la IPS",TARPrevio:"TAR previo",TARPrevioDetalle:"Esquemas previos",Gestante:"Gestante",Estado:"Estado",FechaEgreso:"Egreso",MotivoEgreso:"Motivo de egreso",NovedadNominal:"Novedad nominal forzada",Observaciones:"Observaciones"};
