 let h='<div class="copyrow" style="margin:8px 0">'+VX_DISC.map(d=>'<button type="button" class="btn sm'+(d==="Medicina experta VIH"?" primary":"")+'" data-x="valnew|'+p.ID+'|'+esc(d)+'">'+esc(d==="Medicina experta VIH"?"Valoración médica":d)+'</button>').join("")+'</div>';
