 const ci=cita?VX.book.cit.find(x=>x.ID===cita):null;const fecha=g("Fecha")||(ci?ci.Fecha:pxToday());const prev=vxValPrev(p,disc,fecha);const A=vxL(p.ID,"ant").slice(-1)[0]||{};const secs=VX_VSEC[disc]||[];const has=k=>secs.includes(k);const s=vxSt(p,TODAY());
