function vxValSave(pid){const p=vxP(pid);const ed=VX.ui.vedit;let v=null,disc,cita="";if(ed.startsWith("new|")){const[,d,c]=ed.split("|");disc=d;cita=c||"";}else{v=VX.book.val.find(x=>x.ID===ed);disc=v.Disciplina;cita=v.Cita;}
 const G=id=>{const e=$(id);return e?String(e.value).trim():null;};const o={Paciente:pid,Fecha:G("vf_f"),Cita:cita,Disciplina:disc,Profesional:G("vf_pr"),Motivo:G("vf_mo")};
 const map={vf_ea:"EnfermedadActual",vf_rx:"RevisionSistemas",vf_tb:"TamizTB",vf_pas:"PAS",vf_pad:"PAD",vf_fc:"FC",vf_fr:"FR",vf_te:"Temp",vf_sa:"SatO2",vf_pe:"Peso",vf_ta:"Talla",vf_pa:"PerAbd",vf_ex:"ExamenFisico",vf_rc:"RCV",vf_rk:"RCVCat",vf_fu:"Fumador",vf_rs:"RiesgoSocial",vf_dx:"Diagnosticos",vf_an:"Analisis",vf_pl:"Plan"};Object.entries(map).forEach(([id,k])=>{const x=G(id);if(x!==null)o[k]=x;});
 if(!o.Fecha)return toast("Escriba la fecha de la valoración.");if(o.Fecha>pxToday())return toast("La valoración no puede tener fecha futura.");
 const txt=Object.values(o).join(" ");if(/[$#&≤]/.test(txt))return toast("Quite los símbolos $, #, & o ≤: el sistema de historia clínica no los acepta.");
 const pe=num(o.Peso),ta=num(o.Talla),pas=num(o.PAS);if(pe!=null&&(pe<2||pe>250))return toast("Revise el peso.");if(ta!=null&&(ta<40||ta>230))return toast("Revise la talla (en cm).");if(pas!=null&&(pas<50||pas>260))return toast("Revise la PA sistólica.");
 if(document.querySelector("[id^=vfs_q1]")){const SM={};VX_SMAQ.forEach(([k])=>SM[k]=G("vfs_"+k)||"");if(SM.q1){if(VX_SMAQ.slice(0,5).some(([k])=>!SM[k]))return toast("Complete las seis preguntas del SMAQ o déjelas todas vacías.");o.SMAQd=JSON.stringify(SM);o.SMAQ=vxSmaqRes(SM);}}
 const X={};document.querySelectorAll("[id^=vfx_]").forEach(el=>X[el.id.slice(4)]=String(el.value).trim());if(Object.keys(X).length)o.Extra=JSON.stringify(X);
 const eduEl=document.querySelectorAll("[data-edu]");if(eduEl.length)o.Educacion=[...eduEl].filter(e=>e.checked).map(e=>e.dataset.edu).join("; ");
 const pch={};document.querySelectorAll("[id^=vfp_]").forEach(el=>pch[el.id.slice(4)]=String(el.value).trim());if(Object.keys(pch).length)vxUpd("pac",p,pch);
 if(document.querySelector("[id^=vfa_]")){const A=vxL(pid,"ant").slice(-1)[0]||{};const n={};let cambio=false;VX_ANT.forEach(([k])=>{n[k]=G("vfa_"+k)||"";if(n[k]!==(A[k]||""))cambio=true;});if(cambio)vxAdd("ant","AN-",Object.assign({Paciente:pid,Fecha:o.Fecha},n));}
 let r;if(v){vxUpd("val",v,o);r=v;}else r=vxAdd("val","VL-",o);
 if(cita){const c=VX.book.cit.find(x=>x.ID===cita);if(c&&c.Estado!=="Asistió")vxUpd("cit",c,{Estado:"Asistió"});}
 VX.ui.vedit=null;VX.ui.ptab="val";pxRender();toast("Valoración guardada"+(cita?" y cita marcada como asistida":"")+". Use «Copiar nota» para llevarla al sistema.");}
function vxValCita(cid){const c=VX.book.cit.find(x=>x.ID===cid);const v=VX.book.val.find(x=>vxLive(x)&&x.Cita===cid);VX.ui.vedit=v?v.ID:"new|"+c.Disciplina+"|"+cid;VX.ui.ptab="val";pxGo("vih","pac:"+c.Paciente);}
