function vxEAAuto(p){const s=vxSt(p,TODAY());return"Paciente "+(String(p.Sexo).startsWith("F")?"femenina":"masculino")+" de "+(s.edad==null?"edad no registrada":s.edad+" años")+" con infección por VIH confirmada el "+(p.FechaDx||"(fecha pendiente)")+", en el programa desde "+(p.FechaIngresoIPS||"(fecha pendiente)")+". "+(s.tar?"En TAR con "+s.tar.Esquema+" desde "+s.tar.Inicio+".":"Sin TAR activa.")+" Última carga viral "+(s.cv?vxFmtLab(s.cv)+" ("+iso(s.cv._d)+")":"sin registro")+"; último CD4 "+(s.cd4?vxVal(s.cd4)+" células/µL ("+iso(s.cd4._d)+")":"sin registro")+". Adherencia: "+(s.smaq?s.smaq.SMAQ+" ("+s.smaq.Fecha+")":"sin SMAQ en 6 meses")+". ";}
function vxDxAuto(p){const t=vxHC(p,TODAY(),{});const L=t.split("\n");const i=L.indexOf("DIAGNÓSTICOS");if(i<0)return"";const out=[];for(let j=i+1;j<L.length&&!L[j].startsWith("****");j++)out.push(L[j]);return out.join("\n");}
function vxPendTexto(p){const out=[];const lp=vxLabPlan(p);const fal=lp.filter(x=>["Faltante","Vencido"].includes(x.est));if(fal.length)out.push("Solicitar: "+fal.map(x=>VXE[x.k].l.toLowerCase()).join(", ")+".");const nx=lp.filter(x=>x.next&&x.est==="Vigente").sort((a,b)=>a.next-b.next)[0];if(nx)out.push("Próxima toma de laboratorios: "+iso(nx.next)+" ("+lp.filter(x=>x.next&&iso(x.next)===iso(nx.next)).map(x=>VXE[x.k].l.toLowerCase()).join(", ")+").");
 vxPrcPend(p).forEach(x=>out.push(x.t+": "+x.est.toLowerCase()+(x.fecha?" ("+x.fecha+")":"")+"."));vxVacEstado(p).filter(e=>e.acc&&e.cls==="warn").forEach(e=>out.push("Vacuna "+e.v.l.toLowerCase()+": "+e.acc.toLowerCase()+"."));
 VX_DISC.forEach(d=>{const e=vxAgEstado(p,d);if(e.pr)out.push("Cita de "+d.toLowerCase()+": "+e.pr.Fecha+".");else if(e.cls!=="ok")out.push("Agendar "+d.toLowerCase()+" ("+e.txt+").");});
 const s=vxSt(p,TODAY());if(s.cob)out.push("Entrega de TAR cubre hasta "+iso(s.cob)+".");return out.join("\n");}

