function vxNota(v){const p=vxP(v.Paciente);if(["Medicina experta VIH","Infectología"].includes(v.Disciplina))return vxHC(p,vxD(v.Fecha)||TODAY(),v);if(v.Disciplina==="Enfermería")return vxNotaEnf(p,v);
 const s=vxSt(p,vxD(v.Fecha)||TODAY());let X={};try{X=JSON.parse(v.Extra||"{}");}catch(e){}const SEP="**********";const L=[];const P=t=>{if(t)L.push(t);};
 P(v.Disciplina.toUpperCase()+" · PROGRAMA ESPECIAL VIH");P("Fecha: "+v.Fecha+(v.Profesional?" | Profesional: "+v.Profesional:""));P("Paciente: "+vxNom(p)+" | "+p.TipoDoc+" "+p.Documento+" | "+(s.edad==null?"":s.edad+" años")+" | EPS: "+p.EPS);P(SEP);P("Motivo de la atención: "+(v.Motivo||"Control del programa")+".");
 const lbl={RiesgoNut:"Riesgo nutricional",Habitos:"Hábitos alimentarios",Conciliacion:"Conciliación medicamentosa",Interacciones:"Interacciones",PRM:"Problemas relacionados con medicamentos",RiesgoPsico:"Riesgo psicológico",Adaptacion:"Adaptación al diagnóstico",SPA:"Consumo de sustancias",Tamizaje:"Tamizajes",RedApoyo:"Red de apoyo",Vivienda:"Vivienda y situación económica",Hallazgos:"Hallazgos orales"};
 if(v.Peso||v.Talla){const imc=num(v.Peso)&&num(v.Talla)?num(v.Peso)/Math.pow(num(v.Talla)/100,2):null;P("Antropometría: "+[v.Peso&&"peso "+v.Peso+" kg",v.Talla&&"talla "+v.Talla+" cm",imc&&"IMC "+vxF(imc,1)+" kg/m²",v.PerAbd&&"perímetro abdominal "+v.PerAbd+" cm"].filter(Boolean).join(", ")+".");}
 if(v.RiesgoSocial)P("Riesgo social: "+v.RiesgoSocial+".");if(p.Barreras&&v.Disciplina==="Trabajo social")P("Barreras de acceso: "+p.Barreras+".");Object.entries(X).filter(([k,x])=>x).forEach(([k,x])=>P((lbl[k]||k)+": "+x+"."));
 if(v.SMAQ)P("Adherencia SMAQ: "+v.SMAQ+(v.SMAQd?" ("+vxSmaqTxt(v.SMAQd)+")":"")+".");if(v.Disciplina==="Química farmacéutica"&&s.tar)P("TAR actual: "+s.tar.Esquema+" desde "+s.tar.Inicio+(s.cob?"; cobertura hasta "+iso(s.cob):"")+".");
 P(SEP);P("ANÁLISIS");P(v.Analisis||"Sin análisis registrado.");P(SEP);P("PLAN");String(v.Plan||"").split("\n").filter(Boolean).forEach(x=>P(x));
 return L.join("\n").replace(/[$#&≤]/g,"");}
function vxNotaEnf(p,v){const s=vxSt(p,TODAY());const d=v.Fecha;const SEP="**********";const L=[];const P=t=>{if(t!=null&&t!=="")L.push(t);};
 P("NOTA DE ENFERMERÍA · PROGRAMA ESPECIAL VIH");P("Fecha: "+d+" | Modalidad: "+(p.Modalidad||"")+(v.Profesional?" | Enfermera(o): "+v.Profesional:""));P("Paciente: "+vxNom(p)+" | Identificación: "+p.TipoDoc+" "+p.Documento+" | Edad: "+(s.edad==null?"":s.edad+" años")+" | Sexo: "+(p.Sexo||"")+" | EPS: "+p.EPS);P(SEP);
 P("MOTIVO DE LA ATENCIÓN: "+(v.Motivo||"Control de enfermería del programa")+".");
 const imc=num(v.Peso)&&num(v.Talla)?num(v.Peso)/Math.pow(num(v.Talla)/100,2):null;P("SIGNOS VITALES Y ANTROPOMETRÍA: "+([v.PAS&&"PA "+v.PAS+"/"+(v.PAD||"")+" mmHg",v.FC&&"FC "+v.FC+" lpm",v.FR&&"FR "+v.FR+" rpm",v.Temp&&"T "+v.Temp+" °C",v.SatO2&&"SatO2 "+v.SatO2+" %",v.Peso&&"peso "+v.Peso+" kg",v.Talla&&"talla "+v.Talla+" cm",imc&&"IMC "+vxF(imc,1)].filter(Boolean).join(", ")||"no registrados")+".");
 P("SITUACIÓN ACTUAL: "+(s.tar?"en TAR con "+s.tar.Esquema+(s.cob?", entrega vigente hasta "+iso(s.cob):""):"sin TAR activa")+". Última carga viral "+(s.cv?vxFmtLab(s.cv)+" ("+iso(s.cv._d)+(s.cv6?"":", vencida")+")":"sin registro")+"; último CD4 "+(s.cd4?vxVal(s.cd4)+" ("+iso(s.cd4._d)+(s.cd46?"":", vencido")+")":"sin registro")+". Adherencia: "+(v.SMAQ?v.SMAQ+" (SMAQ de hoy)":s.smaq?s.smaq.SMAQ+" (SMAQ "+s.smaq.Fecha+")":"sin medición en 6 meses")+".");
 const PR=vxL(p.ID,"prc").filter(x=>x.Fecha===d||x.FechaLectura===d);const VA=vxL(p.ID,"vac").filter(x=>x.Fecha===d);
 P("PROCEDIMIENTOS REALIZADOS: "+((PR.map(x=>x.Tipo==="Tuberculina (PPD)"?(x.FechaLectura===d&&x.Estado==="Leída"?"lectura de PPD: "+x.Lectura+" mm, "+String(x.Resultado).toLowerCase():"aplicación de PPD intradérmica"+(x.Lote?" lote "+x.Lote:"")+", lectura programada entre "+iso(addDays(pdate(x.Fecha),2))+" y "+iso(addDays(pdate(x.Fecha),3))):x.Tipo.toLowerCase()+" "+(x.Estado==="Tomada"?"tomada, pendiente resultado":String(x.Resultado||x.Estado).toLowerCase())).concat(VA.map(x=>"vacuna "+(VXV[x.Vacuna]||{l:x.Vacuna}).l.toLowerCase()+" "+String(x.Dosis||"").toLowerCase()+(x.Lote?" lote "+x.Lote:"")))).join("; ")||"ninguno")+".");
 P("EDUCACIÓN BRINDADA: "+(v.Educacion||"no registrada")+".");P("VALORACIÓN DE ENFERMERÍA: "+(v.Analisis||"sin hallazgos adicionales")+".");P(SEP);
 P("PLANIFICACIÓN");String(v.Plan||"").split("\n").filter(Boolean).forEach(x=>P("- "+x));vxPendTexto(p).split("\n").filter(Boolean).forEach(x=>{if(!String(v.Plan||"").includes(x))P("- "+x);});
 P(SEP);P("Responsable: "+(v.Profesional||vxUser()));return L.join("\n").replace(/[$#&≤]/g,"");}
function vxCopy(t,msg){const done=()=>toast(msg||"Copiado.");try{navigator.clipboard.writeText(t).then(done,()=>vxCopyFallback(t,done));}catch(e){vxCopyFallback(t,done);}}
function vxCopyFallback(t,done){const a=document.createElement("textarea");a.value=t;document.body.appendChild(a);a.select();try{document.execCommand("copy");done();}catch(e){toast("No se pudo copiar: seleccione el texto.");}a.remove();}
async function vxHCDoc(pid){const p=vxP(pid);const t=vxHC(p,TODAY());const html='<html><head><meta charset="utf-8"><title>HC '+esc(p.ID)+'</title></head><body style="font-family:Arial;font-size:11pt">'+t.split("\n").map(l=>l.startsWith("****")?'<hr>':/^[A-ZÁÉÍÓÚÑ /().,0-9-]+$/.test(l)&&l.length<70?'<p><b>'+esc(l)+'</b></p>':'<p style="margin:0 0 4pt">'+esc(l)+'</p>').join("")+'</body></html>';
 const blob=new Blob(["﻿"+html],{type:"application/msword"});const name="HC_VIH_"+p.ID+"_"+pxToday()+".doc";if(DL){try{await DL.save({filename:name,data:blob});toast("Archivo listo: "+name);return;}catch(e){toast("Descarga cancelada.");return;}}const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();toast("Descarga iniciada: "+name);}

/* ---------- auditoría CAC de la historia clínica (lista de chequeo) ---------- */
function vxAudit(p,c){c=c||TODAY();const key="aud|"+p.ID+"|"+iso(c);if(VX.memo[key])return VX.memo[key];const s=vxSt(p,c);const P=vxPer(c);const I=[];const it=(n,st,det,acc,glosa)=>I.push({n,st,det:det||"",acc:acc||"",glosa:glosa||""});
 const vm=s.val.filter(v=>["Medicina experta VIH","Infectología"].includes(v.Disciplina)).pop();
 it("Diagnóstico confirmado con fecha y soporte",p.FechaDx&&p.SoporteDx==="Sí"?"Cumple":p.FechaDx?"Dato faltante":"No cumple",p.FechaDx?(p.SoporteDx==="Sí"?"":"sin soporte documental registrado"):"sin fecha de confirmación","Registre el soporte del diagnóstico en la valoración médica (soporte diagnóstico).","Diagnóstico sin soporte");
 it("TAR documentada y validada",s.tar?(s.tar.Validacion?"Cumple":"No cumple"):s.expuesto?"No aplica":"No cumple",s.tar?(s.tar.Validacion?s.tar.Esquema:"esquema sin validación de seguridad"):"sin esquema activo","Valide el esquema en la pestaña TAR.","TAR sin soporte de prescripción validada");
 it("TAR previo documentado",p.TARPrevio?"Cumple":"Dato faltante",p.TARPrevio||"","Documente si era naive o experimentado y los esquemas previos.");
 it("Adherencia medida (SMAQ) en 6 meses",s.smaq?"Cumple":"No cumple",s.smaq?s.smaq.SMAQ+" "+s.smaq.Fecha:"","Aplique el SMAQ en la próxima valoración médica, de enfermería o de química farmacéutica.","Indicador CAC 33");
 it("Carga viral en 6 meses",s.cv6?"Cumple":s.cv?"No cumple":"Dato faltante",s.cv?"última "+iso(s.cv._d):"sin registro","Solicite carga viral.","Indicadores CAC 7, 9 y 12");
 it("CD4 en 6 meses",s.cd46?"Cumple":s.cd4?"No cumple":"Dato faltante",s.cd4?"último "+iso(s.cd4._d):"sin registro","Solicite CD4.","Indicadores CAC 7 y 9");
 const sif=vxLabIn(p.ID,"VDRL",P.w12,c)||vxLabIn(p.ID,"TREP",P.w12,c);it("Tamizaje de sífilis en 12 meses",sif?"Cumple":"No cumple","","Solicite prueba no treponémica.","Indicador CAC 10");
 const tbx=s.tbAlgunaVez||vxL(p.ID,"prc").some(x=>/PPD/.test(x.Tipo)&&/Positiva/.test(x.Resultado||""));const tbok=vm&&vm.TamizTB&&(tbx||vxPrcIn(p.ID,/PPD/,P.w12,c)||vxLabIn(p.ID,"IGRA",P.w12,c));it("Tamizaje de TB (clínico y PPD o IGRA)",tbok?"Cumple":"No cumple",!vm||!vm.TamizTB?"sin tamizaje clínico en la valoración médica":"sin PPD o IGRA en 12 meses","Registre el tamizaje clínico y gestione la PPD en Procedimientos.","Indicador CAC 8");
 const ah=vxVal(vxLast(p.ID,"AntiHBs",c));const vhb=(ah!=null&&ah>=10)||s.vhb||["HBsAg","AntiHBs","AntiHBc"].some(k=>vxLabIn(p.ID,k,P.w12,c));const vhc=s.vhc||vxLabIn(p.ID,"AntiVHC",P.w12,c);it("Serologías de hepatitis B y C",vhb&&vhc?"Cumple":"No cumple",[!vhb&&"VHB",!vhc&&"VHC"].filter(Boolean).join(" y "),"Solicite las serologías pendientes.","Indicadores CAC 22 y 23");
 const VE=vxVacEstado(p,c);const vok=["VHB","INF","NEUC"].every(k=>{const e=VE.find(x=>x.v.k===k);return e&&(e.cls==="ok"||/No aplica/.test(e.est));});it("Vacunación (hepatitis B, influenza, neumococo)",vok?"Cumple":"No cumple",VE.filter(e=>["VHB","INF","NEUC"].includes(e.v.k)&&e.cls!=="ok").map(e=>e.v.l).join(", "),"Complete el carné en Enfermería.","Indicadores CAC 15 y 18");
 it("TFG calculada (creatinina en 6 meses)",vxLabIn(p.ID,"Cr",P.w6,c)?"Cumple":"No cumple","","Solicite creatinina.","Indicador CAC 16");
 it("Riesgo cardiovascular",s.edad==null||s.edad<40?"No aplica":s.rcv?"Cumple":"No cumple",s.edad<40?"menor de 40 años":"","Calcule Framingham ajustado en la valoración médica.","Indicador CAC 11");
 const fem=String(p.Sexo).startsWith("F")&&s.edad>=25&&s.edad<=65,an=vxHSH(p)||p.PracticaAnal==="Sí";const vph=(!fem||vxPrcIn(p.ID,/cervicovaginal|ADN-VPH/,P.w12,c))&&(!an||vxPrcIn(p.ID,/anal/,P.w12,c));it("Tamizaje de VPH o citología",!fem&&!an?"No aplica":vph?"Cumple":"No cumple",[fem&&"cervicovaginal",an&&"anal"].filter(Boolean).join(" y "),"Ordene la citología en Procedimientos.","Indicadores CAC 17 y 21");
 it("Atención por infectología en el periodo",s.disc.has("Infectología")?"Cumple":"No cumple","","Agende infectología.","Indicador CAC 6");
 const eq=["Trabajo social","Psicología","Nutrición","Química farmacéutica"].filter(d=>!s.disc.has(d));it("Equipo interdisciplinario en 12 meses",!eq.length?"Cumple":"No cumple",eq.length?"falta: "+eq.join(", ").toLowerCase():"","Agende las disciplinas faltantes.","Indicador CAC 20");
 const plan=vm&&vxD(vm.Fecha)>=P.w6&&vm.Plan&&vm.Analisis;it("Valoración médica con análisis y plan en 6 meses",plan?"Cumple":"No cumple",vm?"última "+vm.Fecha:"sin valoración médica","Registre la valoración médica completa.","HC incompleta");
 const fal=vxLabPlan(p,c).filter(x=>["Faltante","Vencido"].includes(x.est));const solM=vxSolRecs(ym(TODAY())).filter(r=>r.Paciente===p.ID).map(r=>r.Examen);const sinSol=fal.filter(x=>!solM.includes(x.k));it("Laboratorios pendientes solicitados",!fal.length||!sinSol.length?"Cumple":"No cumple",sinSol.length?sinSol.map(x=>VXE[x.k].l).join(", "):"","Agregue los exámenes a la solicitud del mes.","Seguimiento paraclínico");
 const sinReg=vxL(p.ID,"cit").filter(x=>x.Estado==="Asistió"&&vxD(x.Fecha)>=P.w12&&!VX.book.val.some(v=>vxLive(v)&&v.Cita===x.ID));it("Todas las atenciones con registro clínico",!sinReg.length?"Cumple":"No cumple",sinReg.length?sinReg.length+" atenciones sin valoración ("+sinReg.slice(-3).map(x=>x.Disciplina+" "+x.Fecha).join("; ")+")":"","Abra la cita en la Agenda y registre la valoración.","Atención facturada sin soporte");
 const ap=I.filter(i=>i.st!=="No aplica");const ok=ap.filter(i=>i.st==="Cumple").length;const pct=ap.length?Math.round(ok/ap.length*100):100;
 return VX.memo[key]={items:I,pct,cls:pct>=90?"ok":pct>=70?"warn":"bad"};}
function vxAud(){const P=vxPacs().filter(p=>vxFiltro(p)&&vxSt(p,vxCorte()).activo&&!vxSt(p,vxCorte()).expuesto).map(p=>({p,a:vxAudit(p)}));const umb=VX.ui.aumb||"todos";
 const items=P.length?P[0].a.items.map(i=>i.n):[];const by=items.map(n=>{let c=0,t=0;P.forEach(x=>{const i=x.a.items.find(y=>y.n===n);if(i&&i.st!=="No aplica"){t++;if(i.st==="Cumple")c++;}});return[n,t?Math.round(c/t*100):0];});
 const L=P.filter(x=>umb==="todos"||(umb==="bajo"?x.a.pct<70:umb==="medio"?x.a.pct>=70&&x.a.pct<90:x.a.pct>=90)).sort((a,b)=>a.a.pct-b.a.pct);
 let h=vxTiles([[P.length?Math.round(P.reduce((a,x)=>a+x.a.pct,0)/P.length)+" %":"—","cumplimiento promedio de la lista de chequeo"],[P.filter(x=>x.a.pct>=90).length,"historias con 90 % o más","ok"],[P.filter(x=>x.a.pct<70).length,"historias por debajo de 70 %","bad"]]);
 h+='<div class="pxcols"><div class="panel"><h3>Cumplimiento por ítem (% de pacientes)</h3>'+hbars(by.sort((a,b)=>a[1]-b[1]))+'</div><div class="panel"><h3>Cómo se usa</h3><ul class="pxsrc"><li>Cada historia se revisa con los ítems que audita la Cuenta de Alto Costo y la EPS: diagnóstico con soporte, TAR validada, adherencia, CV y CD4, tamizajes, serologías, vacunas, TFG, RCV, VPH, infectología, equipo interdisciplinario, plan y laboratorios solicitados.</li><li>«Dato faltante» indica que el hecho pudo ocurrir pero no está registrado; «No cumple», que no ocurrió en la ventana.</li><li>La acción correctiva de cada ítem está en la ficha del paciente, pestaña Valoraciones e HC.</li></ul></div></div>';
 h+='<div class="mhead"><div class="seg">'+[["todos","Todas"],["bajo","Menos de 70 %"],["medio","70 a 89 %"],["alto","90 % o más"]].map(([k,l])=>'<button type="button" data-x="aumb|'+k+'" aria-pressed="'+(umb===k)+'">'+l+'</button>').join("")+'</div><button type="button" class="btn" data-x="rep|aud">Descargar auditoría</button></div>';
 h+='<div class="panel tablebox" style="padding:0;margin-top:8px"><table><thead><tr><th>Paciente</th><th class="num">Cumplimiento</th><th>Ítems por corregir</th></tr></thead><tbody>'+L.map(x=>'<tr class="click" data-x="pac|'+x.p.ID+'|val"><td>'+vxPacCell(x.p)+'</td><td class="num"><span class="vxaudchip '+x.a.cls+'"><b>'+x.a.pct+' %</b></span></td><td><div class="chs">'+x.a.items.filter(i=>i.st==="No cumple"||i.st==="Dato faltante").map(i=>'<span class="ch'+(i.st==="No cumple"?" bad":"")+'">'+esc(i.n)+'</span>').join("")+'</div></td></tr>').join("")+'</tbody></table></div>';return h;}
/* ================= v0.5 · PROGRAMA VIH · plan de laboratorios, procedimientos (PPD, citologías), TAR, enfermería y gráficos de indicadores ================= */
/* ---------- plan de laboratorios: qué falta y qué sigue (contrato de la EPS + condiciones clínicas) ---------- */
const VX_FTXT={S:"Cada 6 meses",A:"Cada año",I:"Solo al ingreso",N:"Según condición"};
function vxLabPlan(p,ref){ref=ref||TODAY();const key="lp|"+p.ID+"|"+iso(ref);if(VX.memo[key])return VX.memo[key];const id=p.ID;const s=vxSt(p,ref);const C=vxContrato(p.EPS);const out=[];const last=k=>vxLast(id,k,ref);
 C.items.forEach(([k,f,txt,obs])=>{const e=VXE[k];if(!e||["CD4P","CD8"].includes(k))return;const r=last(k);const d=r?r._d:null;const row={k,f,txt,obs,last:d,next:null,est:"",mot:""};
  const per=(m)=>{row.next=d?addMonths(d,m):null;row.est=!d?"Faltante":row.next<=ref?"Vencido":row.next<=addDays(ref,30)?"Próximo":"Vigente";};
  if(s.expuesto){row.est="No aplica";row.mot="menor expuesto";out.push(row);return;}
  if(f==="S")per(6);
  else if(f==="A"){if((k==="AntiHBc"||k==="HBsAg")){const ah=vxVal(last("AntiHBs"));if(ah!=null&&ah>=10){row.est="No requerido";row.mot="anti-HBs protector";out.push(row);return;}}
   if(k==="VDRL"&&vxPos(r)){per(6);row.mot="prueba reactiva: seguimiento semestral";}else if(k==="AntiVHC"&&s.vhc){row.est="No aplica";row.mot="coinfección VHC: seguimiento con carga viral";}else per(12);}
  else if(f==="I"){row.est=r?"Realizado":"Faltante";row.mot=r?"solo al ingreso":"";}
  else{const cd=s.cd4v;let need=false;
   if(k==="Toxo"){need=cd!=null&&cd<200&&!r;row.mot="CD4 menor de 200";}
   if(k==="CrAg"){need=cd!=null&&cd<100&&(!d||d<addMonths(ref,-6));row.mot="CD4 menor de 100";}
   if(k==="Histo"){need=cd!=null&&cd<50&&(!d||d<addMonths(ref,-6));row.mot="CD4 menor de 50";}
   if(k==="BT"){need=!!(s.tar&&/ATV/.test(s.tar.Esquema))&&(!d||d<addMonths(ref,-6));row.mot="tratamiento con atazanavir";}
   if(k==="HLAB5701"){need=!!(s.tar&&/ABC/.test(s.tar.Esquema))&&!vxL(id,"lab").some(x=>x.Examen==="HLAB5701");row.mot="esquema con abacavir";}
   if(k==="GENO"){need=vxFalla(id,addMonths(ref,-12),ref)&&!vxLabIn(id,"GENO",addMonths(ref,-12),ref);row.mot="falla virológica";}
   if(k==="HbA1c"){need=false;}
   row.est=need?"Faltante":r?"Realizado":"Sin indicación";}
  if(k==="CV"&&s.cv6&&num(s.cv6.Valor)>=200&&row.est==="Vigente"){row.est="Faltante";row.mot="carga viral detectable: control";}
  out.push(row);});
 return VX.memo[key]=out;}
/* compatibilidad: solicitud del mes = faltantes y vencidos al final del mes */
function vxDue(p,mes){const me=monthEnd(pdate(mes+"-01"));return vxLabPlan(p,me).filter(x=>["Faltante","Vencido"].includes(x.est)).map(x=>({k:x.k,o:x.est+(x.mot?" · "+x.mot:x.last?" (último "+iso(x.last)+")":""),t:x.txt}));}
const VX_ESTCLS={Faltante:"bad",Vencido:"bad",Próximo:"warn",Vigente:"ok",Realizado:"ok","No requerido":"base","No aplica":"base","Sin indicación":"base"};
function vxPacLab(p){const L=vxLabPlan(p);const pend=L.filter(x=>["Faltante","Vencido"].includes(x.est));const nx=L.filter(x=>x.next&&x.est!=="Vencido").sort((a,b)=>a.next-b.next);const nd=nx[0]?nx[0].next:null;
 let h='<div class="copyrow" style="margin:8px 0"><button type="button" class="btn primary" data-x="labnew|'+p.ID+'">Cargar resultados</button><button type="button" class="btn" data-x="solpac|'+p.ID+'">Agregar faltantes a la solicitud del mes</button></div>';
 h+=vxTiles([[pend.length,"exámenes que faltan hoy",pend.length?"bad":"ok"],[nd?iso(nd):"—","próxima toma programada"],[nd?L.filter(x=>x.next&&iso(x.next)===iso(nd)).length:0,"exámenes en esa fecha"]]);
 h+='<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Examen</th><th>Frecuencia ('+esc(p.EPS)+')</th><th>Último</th><th>Próximo</th><th>Estado</th></tr></thead><tbody>'+L.sort((a,b)=>["Faltante","Vencido","Próximo","Vigente","Realizado","No requerido","No aplica","Sin indicación"].indexOf(a.est)-["Faltante","Vencido","Próximo","Vigente","Realizado","No requerido","No aplica","Sin indicación"].indexOf(b.est)).map(x=>'<tr><td><b>'+esc(VXE[x.k].l)+'</b>'+(VXE[x.k].c?' <span class="mono sub">CUPS '+esc(VXE[x.k].c)+'</span>':'')+'</td><td style="font-size:13px">'+esc(x.txt||VX_FTXT[x.f])+'</td><td class="mono">'+(x.last?iso(x.last):"—")+'</td><td class="mono">'+(x.next?iso(x.next):"—")+'</td><td>'+vxSt2([x.est,VX_ESTCLS[x.est]||"base"])+(x.mot?'<span class="sub">'+esc(x.mot)+'</span>':'')+'</td></tr>').join("")+'</tbody></table></div>';
 const R=vxL(p.ID,"lab").slice().reverse();const by={};R.forEach(r=>{(by[r.FechaToma]=by[r.FechaToma]||[]).push(r);});
 h+='<h3 style="margin:14px 0 6px">Resultados</h3><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Fecha</th><th>Resultados</th><th>Fuente</th><th></th></tr></thead><tbody>'+(Object.entries(by).map(([f,R2])=>'<tr><td class="mono">'+esc(f)+'</td><td style="font-size:13px">'+R2.map(r=>'<b>'+esc((VXE[r.Examen]||{l:r.Examen}).l)+'</b> '+esc(vxFmtLab(r))).join(" · ")+'</td><td style="font-size:12.5px">'+esc([...new Set(R2.map(r=>r.Fuente||""))].join(", "))+'</td><td>'+R2.map(r=>'<button type="button" class="lnk" style="font-size:11px" data-x="anular|lab|'+r.ID+'" title="Anular '+esc(r.Examen)+'">×'+esc(r.Examen)+'</button>').join(" ")+'</td></tr>').join("")||'<tr><td colspan="4" class="note">Sin laboratorios.</td></tr>')+'</tbody></table></div>';return h;}
function vxLabFaltantes(){const P=vxPacs().filter(p=>vxFiltro(p)&&vxSt(p,vxCorte()).activo&&!vxSt(p,vxCorte()).expuesto);const t=TODAY();const hz=+(VX.ui.lhz||30);
 const R=P.map(p=>{const L=vxLabPlan(p);const f=L.filter(x=>["Faltante","Vencido"].includes(x.est));const nx=L.filter(x=>x.next&&x.next>t).sort((a,b)=>a.next-b.next);return{p,f,nx:nx[0]?nx[0].next:null,nxL:nx[0]?L.filter(x=>x.next&&iso(x.next)===iso(nx[0].next)):[]};});
 const tot=R.reduce((a,r)=>a+r.f.length,0);const prox=R.filter(r=>r.nx&&r.nx<=addDays(t,hz));
 let h=vxTiles([[R.filter(r=>r.f.length).length,"pacientes con exámenes faltantes o vencidos","bad"],[tot,"exámenes por tomar hoy"],[prox.length,"pacientes con toma en los próximos "+hz+" días","warn"]]);
 h+='<div class="copyrow" style="margin:8px 0"><span class="note">Horizonte de «próximos»:</span><div class="seg sm">'+[15,30,60,90].map(d=>'<button type="button" data-x="lhz|'+d+'" aria-pressed="'+(hz===d)+'">'+d+' días</button>').join("")+'</div><button type="button" class="btn" data-x="rep|labplan">Descargar faltantes y próximos</button></div>';
 h+='<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th>Faltan hoy</th><th>Próxima toma</th><th>Exámenes de la próxima toma</th></tr></thead><tbody>'+R.filter(r=>r.f.length||(r.nx&&r.nx<=addDays(t,hz))).sort((a,b)=>b.f.length-a.f.length||(a.nx||0)-(b.nx||0)).map(r=>'<tr class="click" data-x="pac|'+r.p.ID+'|lab"><td>'+vxPacCell(r.p)+'</td><td><div class="chs">'+r.f.map(x=>'<span class="ch bad" title="'+esc(x.est+(x.mot?" · "+x.mot:""))+'">'+esc(x.k)+'</span>').join("")+'</div></td><td class="mono">'+(r.nx?iso(r.nx):"—")+'</td><td style="font-size:12.5px">'+esc(r.nxL.map(x=>VXE[x.k].l).join(", "))+'</td></tr>').join("")+'</tbody></table></div>';return h;}

/* ---------- procedimientos: PPD, citología cervicovaginal y anal ---------- */
function vxPPD(p,ref){ref=ref||TODAY();const s=vxSt(p,ref);const L=vxL(p.ID,"prc").filter(x=>x.Tipo==="Tuberculina (PPD)");const pos=L.find(x=>/Positiva/.test(x.Resultado||""))||(vxPos(vxLast(p.ID,"IGRA",ref))?{FechaLectura:iso(vxLast(p.ID,"IGRA",ref)._d),Lectura:"IGRA"}:null);const lt=L[L.length-1];
 if(s.expuesto)return{est:"No aplica",cls:"base"};
 if(s.tbAlgunaVez)return{est:"No indicada: TB activa o previa",cls:"base"};
 if(pos){const tto=vxPrfIn(p.ID,/TB latente/,addMonths(ref,-60),ref);return tto?{est:"Positiva en tratamiento o tratada de TB latente",cls:"ok",fecha:pos.FechaLectura}:{est:"Positiva sin tratamiento de TB latente",cls:"bad",fecha:pos.FechaLectura,acc:"prf"};}
 if(lt&&lt.Estado==="Ordenado")return{est:"Ordenada, por aplicar",cls:"warn",fecha:lt.Ordenado,x:lt};
 if(lt&&lt.Estado==="Aplicado"){const a=pdate(lt.Fecha);const dd=dayDiff(a,ref);return{est:dd<2?"Aplicada, leer entre "+iso(addDays(a,2))+" y "+iso(addDays(a,3)):dd<=3?"Por leer hoy (ventana 48 a 72 h)":"Lectura vencida (más de 72 h): repetir",cls:dd<=3?"warn":"bad",fecha:lt.Fecha,x:lt};}
 if(lt&&lt.Estado==="Leída"){const nx=addMonths(pdate(lt.FechaLectura||lt.Fecha),12);return nx<=ref?{est:"Vencida: repetir (anual)",cls:"bad",fecha:iso(nx)}:{est:"Negativa, próxima "+iso(nx),cls:"ok",fecha:iso(nx),next:nx};}
 return{est:"Pendiente: nunca realizada",cls:"bad"};}
function vxCit(p,tipo,ref){ref=ref||TODAY();const s=vxSt(p,ref);const fem=String(p.Sexo).startsWith("F");const ed=s.edad;
 const apl=tipo==="Citología cervicovaginal"?(fem&&ed!=null&&ed>=25&&ed<=65):(vxHSH(p)||p.PracticaAnal==="Sí"||/^5\./.test(p.PoblacionClave||""));
 if(s.expuesto||!apl){if(tipo==="Citología anal"&&!p.PracticaAnal&&ed>=18&&!vxHSH(p))return{est:"Caracterizar prácticas sexuales",cls:"info",car:true};return{est:"No aplica",cls:"base"};}
 const L=vxL(p.ID,"prc").filter(x=>x.Tipo===tipo||(x.Tipo==="ADN-VPH"&&tipo==="Citología cervicovaginal"));const lt=L[L.length-1];
 if(!lt)return{est:"Pendiente: sin tamizaje",cls:"bad"};
 if(lt.Estado==="Ordenado")return{est:"Ordenada, por tomar",cls:"warn",fecha:lt.Ordenado,x:lt};
 if(lt.Estado==="Tomada")return{est:"Tomada, resultado pendiente",cls:"warn",fecha:lt.Fecha,x:lt};
 const anor=lt.Resultado&&!/^Negativo|ADN-VPH negativo/.test(lt.Resultado)&&!/insatisfactoria/i.test(lt.Resultado);
 if(/insatisfactoria/i.test(lt.Resultado||""))return{est:"Muestra insatisfactoria: repetir",cls:"bad",fecha:lt.FechaLectura||lt.Fecha};
 if(anor&&!lt.Conducta)return{est:"Anormal ("+lt.Resultado+") sin conducta registrada",cls:"bad",fecha:lt.FechaLectura||lt.Fecha,x:lt,acc:"cond"};
 const nx=addMonths(pdate(lt.FechaLectura||lt.Fecha),12);if(anor)return{est:"Anormal en seguimiento: "+lt.Conducta,cls:"warn",fecha:lt.FechaLectura};
 return nx<=ref?{est:"Vencida: repetir (anual)",cls:"bad",fecha:iso(nx)}:{est:"Negativa, próxima "+iso(nx),cls:"ok",fecha:iso(nx),next:nx};}
function vxPrcPend(p){const o=[];const a=vxPPD(p);if(["bad","warn"].includes(a.cls))o.push({t:"Tuberculina (PPD)",est:a.est,fecha:a.fecha});["Citología cervicovaginal","Citología anal"].forEach(t=>{const c=vxCit(p,t);if(["bad","warn"].includes(c.cls)||c.car)o.push({t,est:c.est,fecha:c.fecha});});return o;}
function vxPrcBtn(p,t,e){if(e.x&&e.x.Estado==="Ordenado")return'<button type="button" class="btn sm" data-x="prcconf|'+e.x.ID+'">Confirmar '+(t==="Tuberculina (PPD)"?"aplicación":"toma")+'</button>';if(e.x&&["Aplicado","Tomada"].includes(e.x.Estado))return'<button type="button" class="btn sm" data-x="prcconf|'+e.x.ID+'">'+(t==="Tuberculina (PPD)"?"Registrar lectura":"Registrar resultado")+'</button>';if(e.acc==="prf")return'<button type="button" class="btn sm" data-x="prfnew|'+p.ID+'">Iniciar TB latente</button>';if(e.acc==="cond")return'<button type="button" class="btn sm" data-x="prccond|'+e.x.ID+'">Registrar conducta</button>';if(e.car)return'<button type="button" class="btn sm" data-x="pacedit|'+p.ID+'">Caracterizar</button>';if(e.cls==="bad")return'<button type="button" class="btn sm primary" data-x="prcord|'+p.ID+'|'+esc(t)+'">Ordenar</button>';return"";}
function vxPrc(){const sub=VX.ui.psub||"ruta";const P=vxPacs().filter(p=>vxFiltro(p)&&vxSt(p,vxCorte()).activo);
 let h='<div class="mhead" style="margin-top:6px"><div class="seg">'+[["ruta","Pendientes de la ruta"],["ppd","Tuberculina (PPD)"],["ccv","Citología cervicovaginal"],["can","Citología anal"],["hoy","Enfermería del día"],["reg","Registro del mes"]].map(([k,l])=>'<button type="button" data-x="psub|'+k+'" aria-pressed="'+(sub===k)+'">'+l+'</button>').join("")+'</div><button type="button" class="btn" data-x="rep|prc">Descargar procedimientos</button></div>';
 if(sub==="hoy"||sub==="reg"){VX.ui.esub=sub;return h+vxEnf(true);}
 if(sub==="ruta"){const R=P.map(p=>({p,a:vxPPD(p),c:vxCit(p,"Citología cervicovaginal"),n:vxCit(p,"Citología anal")})).filter(r=>[r.a,r.c,r.n].some(e=>["bad","warn"].includes(e.cls)||e.car));
  h+='<p class="note">Procedimientos que la ruta exige según la GPC VIH 2021, el contrato de la EPS y los indicadores CAC: PPD anual si la previa fue negativa y no hay TB; citología cervicovaginal anual en mujeres de 25 a 65 años (CAC 17); citología anal anual en HSH, mujeres trans o con prácticas anales receptivas (guía de la EPS, CAC 21).</p>';
  h+=vxTiles([[R.filter(r=>["bad","warn"].includes(r.a.cls)).length,"pendientes de PPD"],[R.filter(r=>["bad","warn"].includes(r.c.cls)).length,"pendientes de citología cervicovaginal"],[R.filter(r=>["bad","warn"].includes(r.n.cls)).length,"pendientes de citología anal"],[P.filter(p=>vxCit(p,"Citología anal").car).length,"sin caracterizar prácticas sexuales","info"]]);
  const cell=(p,t,e)=>'<td><span class="st '+e.cls+'">'+esc(e.est)+'</span><div class="vxacts" style="margin-top:4px">'+vxPrcBtn(p,t,e)+'</div></td>';
  return h+'<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th>Tuberculina</th><th>Citología cervicovaginal</th><th>Citología anal</th></tr></thead><tbody>'+R.map(r=>'<tr><td>'+vxPacCell(r.p)+'<span class="sub">'+esc((r.p.Sexo||"")+" · "+(r.p.PoblacionClave||""))+'</span></td>'+cell(r.p,"Tuberculina (PPD)",r.a)+cell(r.p,"Citología cervicovaginal",r.c)+cell(r.p,"Citología anal",r.n)+'</tr>').join("")+'</tbody></table></div>';}
 const T={ppd:"Tuberculina (PPD)",ccv:"Citología cervicovaginal",can:"Citología anal"}[sub];const F=sub==="ppd"?vxPPD:(p=>vxCit(p,T));const R=P.map(p=>({p,e:F(p)})).filter(r=>r.e.cls!=="base");
 const grp={};R.forEach(r=>{const g=r.e.cls==="ok"?"Al día":r.e.cls==="info"?"Por caracterizar":/por aplicar|por tomar/.test(r.e.est)?"Ordenadas":/leer|Lectura|resultado pendiente/.test(r.e.est)?(sub==="ppd"?"Por leer":"Resultado pendiente"):/Positiva sin|Anormal|insatisfactoria/.test(r.e.est)?"Requieren conducta":"Por ordenar";(grp[g]=grp[g]||[]).push(r);});
 const ord=["Por ordenar","Ordenadas","Por leer","Resultado pendiente","Requieren conducta","Por caracterizar","Al día"];
 h+=vxTiles(ord.filter(g=>grp[g]).map(g=>[grp[g].length,g.toLowerCase(),g==="Al día"?"ok":g==="Requieren conducta"||g==="Por ordenar"?"bad":g==="Por caracterizar"?"info":"warn"]));
 if(grp["Por ordenar"])h+='<div class="copyrow" style="margin:8px 0"><button type="button" class="btn primary" data-x="prcbulk|'+esc(T)+'">Ordenar a los '+grp["Por ordenar"].length+' pendientes</button><span class="note">Quedan en la lista de enfermería.</span></div>';
 h+=ord.filter(g=>grp[g]&&g!=="Al día").map(g=>'<h3 style="margin:14px 0 6px">'+g+' ('+grp[g].length+')</h3><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th>Estado</th><th>Fecha</th><th></th></tr></thead><tbody>'+grp[g].map(r=>'<tr><td>'+vxPacCell(r.p)+'</td><td><span class="st '+r.e.cls+'">'+esc(r.e.est)+'</span></td><td class="mono">'+esc(r.e.fecha||"")+'</td><td class="vxacts">'+vxPrcBtn(r.p,T,r.e)+'<button type="button" class="btn sm" data-x="pac|'+r.p.ID+'|enf">Ficha</button></td></tr>').join("")+'</tbody></table></div>').join("");
 if(grp["Al día"])h+='<details class="panel" style="margin-top:12px"><summary>Al día ('+grp["Al día"].length+')</summary><ul class="pxsrc">'+grp["Al día"].map(r=>'<li>'+esc(r.p.ID+" · "+vxNom(r.p)+" · "+r.e.est)+'</li>').join("")+'</ul></details>';
 h+='<p class="note">'+(sub==="ppd"?"PPD: lectura entre 48 y 72 horas; en personas con VIH una induración de 5 mm o más es positiva y obliga a descartar TB activa y valorar tratamiento de TB latente.":sub==="can"?"Citología anal: resultado anormal (ASC-US o más) requiere conducta registrada (anoscopia de alta resolución o remisión a coloproctología, según la ruta institucional).":"Citología cervicovaginal: resultado anormal requiere conducta registrada (colposcopia según la guía vigente).")+'</p>';return h;}
function vxDlgPrcCond(id){const x=VX.book.prc.find(r=>r.ID===id);openDlg("Conducta · "+x.Tipo+" · "+x.Paciente,'<p class="note">Resultado: '+esc(x.Resultado)+' ('+esc(x.FechaLectura||x.Fecha)+')</p><div class="form">'+vxFld("pk_c","Conducta","sel","",x.Tipo==="Citología anal"?["Anoscopia de alta resolución","Remisión a coloproctología","Repetir citología en 6 meses","Otra"]:["Colposcopia","Remisión a ginecología","Repetir citología en 6 meses","Otra"])+vxFld("pk_f","Fecha de la orden o cita","date",pxToday())+vxFld("pk_n","Detalle","text","",null,"wide")+'</div>',"Guardar",()=>{if(!vxGv("pk_c"))return"Elija la conducta.";vxUpd("prc",x,{Conducta:vxGv("pk_c")+(vxGv("pk_n")?": "+vxGv("pk_n"):""),ProximaFecha:vxGv("pk_f")});pxRender();toast("Conducta registrada.");});}
function vxPrcBulk(t){let n=0;vxPacs().filter(p=>vxFiltro(p)&&vxSt(p,vxCorte()).activo).forEach(p=>{const e=t==="Tuberculina (PPD)"?vxPPD(p):vxCit(p,t);if(e.cls==="bad"&&!e.x&&!e.acc&&!e.car){vxAdd("prc","PR-",{Paciente:p.ID,Tipo:t,Ordenado:pxToday(),OrdenadoPor:vxUser(),Fecha:"",Lote:"",FechaLectura:"",Lectura:"",Resultado:"",Conducta:"",ProximaFecha:"",Estado:"Ordenado"});n++;}});pxRender();toast(n+" órdenes de "+t.toLowerCase()+" creadas para enfermería.");}

