 P.filter(p=>p.EPS==="FAMILIAR DE COLOMBIA").forEach(p=>{const D=Object.assign({},VX_CAC_DEMO,{v1ideps:"CCF033",v2regimen:p.Regimen,v3tipodocumentoidentificacionusu:p.TipoDoc,v4numerodeidentificacion:p.Documento,v5primeapellido:p.PrimerApellido,v6segundoapellido:p.SegundoApellido||"NONE",v7primernombre:p.PrimerNombre,v8segundonombre:p.SegundoNombre||"NONE",v9fechadenacimiento:p.FechaNac,v10sexo:p.Sexo==="Femenino"?"M":"H",v13codigomunicipioresidencia:p.CodMunicipio,v98fechadecorte:"2026-01-31"});b.cac.push({Paciente:p.ID,Corte:"2026-01-31",Fuente:"Demostración",Datos:JSON.stringify(D)});});
 b.tar.forEach(t=>{const p=b.pac.find(x=>x.ID===t.Paciente);t.TARPrevio=p.TARPrevio;if(R()<(t.Fin?0.5:0.85)){t.Validacion=JSON.stringify({c1:true,c2:true,c3:true,c4:true,c5:/ABC/.test(t.Esquema),c6:p.Sexo==="Femenino",c7:t.Motivo==="Falla virológica",c8:true});t.ValidadoPor=pick(["Químico farmacéutico (ficticio)","Médico experto (ficticio)"]);t.FechaValidacion=t.Inicio;}});
 b.cfg.push({Clave:"contrato",Valor:JSON.stringify(VX_CONTRATO_DEF)});b.cfg.push({Clave:"epscode",Valor:JSON.stringify(VX_EPSCODE_DEF)});
 VX.dirty=false;vxChanged();VX.dirty=false;
 /* solicitud de laboratorio del mes en curso, generada por Laboratorio */
