/* agenda */
function ceAgenda(){const A=CE.ui.ag||(CE.ui.ag={modo:"dia",fecha:ceHoy(),esp:"",prof:"",mod:""});const hoy=ceHoy();let desde,hasta,tit;
 const lunes=f=>ceSumar(f,-((pdate(f).getDay()+6)%7));
 if(A.modo==="dia"){desde=hasta=A.fecha;tit=pxFD(A.fecha)+" · "+["domingo","lunes","martes","miércoles","jueves","viernes","sábado"][pdate(A.fecha).getDay()];}
 else if(A.modo==="sem"){desde=lunes(A.fecha);hasta=ceSumar(desde,6);tit="Semana del "+ceFD(desde)+" al "+ceFD(hasta);}
 else{const ms=monthStart(pdate(A.fecha));desde=lunes(iso(ms));hasta=ceSumar(lunes(iso(monthEnd(ms))),6);tit=pxMesTxt(ym(ms));}
 const J=CE.book.jor.filter(j=>j.Estado==="ABIERTA"&&ceVisJor(j)&&j.Fecha>=desde&&j.Fecha<=hasta&&(!A.esp||j.Especialidad===A.esp)&&(!A.prof||j.Profesional===A.prof)&&(!A.mod||j.Modalidad===A.mod)).sort((a,b)=>(a.Fecha+a.HoraInicio).localeCompare(b.Fecha+b.HoraInicio));
 const as=CE.ui.asig?ceIdx().sol.get(CE.ui.asig):null;
 let h='<div class="mhead" style="margin-top:12px"><div class="seg">'+[["dia","Día"],["sem","Semana"],["mes","Mes"]].map(([k,l])=>'<button type="button" data-ce="amodo|'+k+'" aria-pressed="'+(A.modo===k)+'">'+l+'</button>').join("")+'</div><div class="copyrow">'+(cePuede("abrir")?'<button type="button" class="btn primary" data-ce="fjor">Abrir jornadas</button>':'')+'</div></div>';
 if(as&&ceVisSol(as))h+='<div class="alert warn" style="margin-top:10px"><p>Buscando cupo para la solicitud '+esc(as.ID)+': <b>'+esc(ceNom(ceIdx().pac.get(as.Paciente)))+'</b> · '+esc(ceEspN(as.Especialidad))+' · '+esc(CE_MODAL[as.Modalidad])+'. Abra un cupo libre para asignarlo. <button type="button" class="btn sm" data-ce="asigfin">Terminar</button></p></div>';
 h+='<div class="filters" style="margin-top:10px"><div class="calbar"><button type="button" class="btn sm" data-ce="amov|-1" aria-label="Anterior">‹</button><span class="calmt">'+esc(tit)+'</span><button type="button" class="btn sm" data-ce="amov|1" aria-label="Siguiente">›</button><button type="button" class="btn sm" data-ce="amov|0">Hoy</button></div><label class="f" style="max-width:160px">Fecha<input type="date" id="ce_af" value="'+esc(A.fecha)+'"></label>'+
  '<label class="f">Especialidad<select id="ce_aesp">'+opt(CE.book.esp.filter(e=>ceVisEsp(e.Codigo)).map(e=>[e.Codigo,e.Nombre]),A.esp,"Todas")+'</select></label><label class="f">Profesional<select id="ce_apro">'+opt(CE.book.pro.map(p=>[p.ID,p.Nombre]),A.prof,"Todos")+'</select></label><label class="f">Modalidad<select id="ce_amod">'+opt([["PRESENCIAL","Presencial"],["TELEMEDICINA","Telemedicina"]],A.mod,"Todas")+'</select></label></div>';
 h+='<div class="celeg"><span><i class="ce-c-DISPONIBLE"></i>Disponible</span><span><i class="ce-c-ASIGNADO"></i>Asignado</span><span><i class="ce-c-CONFIRMADO"></i>Confirmado</span><span><i class="ce-c-ATENDIDO"></i>Atendido</span><span><i class="ce-c-INASISTENCIA"></i>Inasistencia</span><span><i class="ce-c-BLOQUEADO"></i>Bloqueado</span></div>';
 const lib=j=>ceJorCupos(j).filter(c=>ceCupoEstado(c)==="DISPONIBLE"&&!cePasado(c.Fecha,c.Hora)).length;
 if(A.modo==="dia"){h+=J.length?J.map(j=>{const C=ceJorCupos(j);const con=ceIdx().con.get(j.Consultorio);
   return'<section class="panel cejor"><div class="mhead"><div><b>'+esc(ceProfN(j.Profesional))+'</b> · '+esc(ceEspN(j.Especialidad))+' <span class="tag'+(j.Modalidad==="TELEMEDICINA"?" ce-vio":"")+'">'+esc(CE_MODAL[j.Modalidad])+'</span>'+(j.Extraordinaria==="SI"?' <span class="tag warn">Extraordinaria</span>':'')+'<span class="sub">'+esc(j.HoraInicio+"–"+j.HoraFin+" · "+(con?con.Nombre+(con.Plataforma?" ("+con.Plataforma+")":""):"")+" · cupos de "+j.Duracion+" min"+(j.Agendas==="2"?" · agenda espejo A/B":"")+(j.EPS?" · solo "+j.EPS:""))+'</span></div><div class="copyrow"><span class="note">'+lib(j)+' libres de '+C.length+'</span>'+(cePuede("bloquearJornada")?'<button type="button" class="btn sm danger" data-ce="fbj|'+j.ID+'">Bloquear libres</button>':'')+'</div></div>'+
    '<div class="cecupos">'+C.map(c=>{const e=ceCupoEstado(c);const ci=(ceIdx().citC[c.ID]||[])[0];const p=ci?ceIdx().pac.get(ci.Paciente):null;
     return'<button type="button" class="cecupo ce-'+e+(cePasado(c.Fecha,c.Hora)?" pas":"")+'" data-ce="cup|'+c.ID+'"><span class="h">'+esc(c.Hora)+(j.Agendas==="2"?" · "+c.Agenda:"")+'</span><span class="e">'+esc({DISPONIBLE:"Disponible",ASIGNADO:"Asignado",CONFIRMADO:"Confirmado",ATENDIDO:"Atendido",INASISTENCIA:"Inasistencia",BLOQUEADO:"Bloqueado",CANCELADO:"Cancelado"}[e])+'</span>'+(p?'<span class="p">'+esc(ceNom(p))+'</span>':c.BloqueoMotivo?'<span class="p">'+esc(c.BloqueoMotivo)+'</span>':'')+'</button>';}).join("")+'</div></section>';}).join(""):'<p class="empty">No hay jornadas abiertas este día con esos filtros.</p>';}
 else if(A.modo==="sem"){h+='<div class="cesem">'+Array.from({length:7},(_,i)=>ceSumar(desde,i)).map(f=>'<div class="ceday'+(f===hoy?" hoy":"")+'"><h4>'+CE_DIAS[pdate(f).getDay()]+' '+f.slice(8)+'/'+f.slice(5,7)+'</h4>'+(J.filter(j=>j.Fecha===f).map(j=>'<button type="button" class="cemini'+(j.Modalidad==="TELEMEDICINA"?" tele":"")+'" data-ce="aday|'+f+'">'+esc(j.HoraInicio+"–"+j.HoraFin)+'<br>'+esc(ceProfN(j.Profesional))+'<span class="sub">'+esc(ceEspN(j.Especialidad))+' · '+lib(j)+' libres</span></button>').join("")||'<span class="note">—</span>')+'</div>').join("")+'</div>';}
 else{const mes=A.fecha.slice(0,7);let k="";for(let f=desde;f<=hasta;f=ceSumar(f,1)){const L=J.filter(j=>j.Fecha===f);const l=L.reduce((a,j)=>a+lib(j),0),o=L.reduce((a,j)=>a+ceJorCupos(j).filter(c=>["ASIGNADO","CONFIRMADO","ATENDIDO","INASISTENCIA"].includes(ceCupoEstado(c))).length,0);
   k+='<button type="button" class="calday'+(f.slice(0,7)!==mes?" out":"")+(f===hoy?" today":"")+'" data-ce="aday|'+f+'"><span class="calnum">'+(+f.slice(8))+'</span>'+(L.length?'<span class="sub">'+L.length+' jornada(s)</span><span class="tag fav">'+l+' libres</span><span class="tag">'+o+' citas</span>':'')+'</button>';}
  h+='<div class="panel" style="padding:0;overflow:hidden;margin-top:10px"><div class="calgrid calhead">'+["Lun","Mar","Mié","Jue","Vie","Sáb","Dom"].map(x=>'<div>'+x+'</div>').join("")+'</div><div class="calgrid">'+k+'</div></div>';}
 return h;}

function ceDlgCupo(cid){const I=ceIdx();const c=I.cup.get(cid);if(!c)return;const j=I.jor.get(c.Jornada);if(!ceVisJor(j))return;const e=ceCupoEstado(c);const tit="Cupo "+c.Hora+" · "+ceFD(c.Fecha);
 const sub='<p class="note">'+esc(ceProfN(j.Profesional)+" · "+ceEspN(j.Especialidad)+" · "+CE_MODAL[j.Modalidad]+" · "+ceConN(j.Consultorio))+'</p>';
 if(e==="DISPONIBLE"&&!cePasado(c.Fecha,c.Hora)){const C=cePuede("asignar")?ceCandidatos(cid).slice(0,30):[];const as=CE.ui.asig;
  let body=sub+(as?'<div class="alert warn"><p>Solicitud seleccionada: '+esc(as)+'. '+(C.some(s=>s.ID===as)?'Está entre los candidatos (resaltada).':'No figura entre los candidatos de este cupo: '+esc(ceIncompat(cid,as)||"revise los datos")+'.')+'</p></div>':'');
  if(cePuede("asignar"))body+='<h3>Candidatos en orden ('+C.length+')</h3><p class="note">Prioridad clínica validada → fecha clínica límite → antigüedad. Asignar a otro que no sea el primero exige motivo.</p><ul class="cecand">'+(C.map((s,i)=>{const p=I.pac.get(s.Paciente);const a=ceAut(s.ID);
   return'<li'+(s.ID===as?' class="sel"':'')+'><span class="o">'+(i+1)+'</span><span><b>'+esc(ceNom(p))+'</b> '+cePrioTag(s.Prioridad)+'<span class="sub">'+esc(p.Documento+" · "+p.EPS+" · "+CE_TIPO[s.TipoConsulta]+" · "+CE_MODAL[s.Modalidad]+" · "+ceDias(s.FechaSolicitud,ceHoy())+" días · Tel. "+p.Telefono)+'</span><span class="sub">'+ceAutTag(a?a.Situacion:"NO_REQUIERE")+(a&&a.FechaVencimiento?" vence "+ceFD(a.FechaVencimiento):"")+(s.FechaLimiteClinica?" · límite clínico "+ceFD(s.FechaLimiteClinica):"")+'</span></span><button type="button" class="btn sm'+(i===0?" primary":"")+'" data-ce="asig|'+cid+'|'+s.ID+'|'+(i+1)+'">Asignar</button></li>';}).join("")||'<li class="note">No hay solicitudes compatibles esperando este cupo.</li>')+'</ul><div id="ce_zona"></div>';
  else body+='<p class="note">Su rol consulta la agenda; la asignación la hacen Admisiones y Coordinación.</p>';
  if(cePuede("bloquear"))body+='<details class="cedet"><summary>Bloquear este cupo</summary><div class="form" style="margin-top:8px"><label class="f wide">Motivo *<input type="text" id="cz_bm"></label></div><div class="copyrow"><button type="button" class="btn sm danger" data-ce="okbloq|'+cid+'">Bloquear</button></div></details>';
  openDlg(tit,body+'<p class="note" id="cz_msg" style="color:var(--bad)"></p>',"Cerrar",()=>{});ceDlgAncho();$("dlgx").hidden=true;return;}
 if(e==="BLOQUEADO"){openDlg(tit,sub+'<div class="alert warn"><p>Bloqueado ('+esc((c.BloqueoTipo||"").toLowerCase())+'): '+esc(c.BloqueoMotivo)+' · '+esc(c.BloqueadoPor)+'</p></div>'+(cePuede("bloquear")?'<div class="form"><label class="f wide">Motivo del desbloqueo *<input type="text" id="cz_dm"></label></div><p class="note" id="cz_msg" style="color:var(--bad)"></p><div class="copyrow"><button type="button" class="btn sm primary" data-ce="okdesb|'+cid+'">Desbloquear</button></div>':''),"Cerrar",()=>{});$("dlgx").hidden=true;return;}
 const ci=(I.citC[cid]||[])[0];const p=ci?I.pac.get(ci.Paciente):null;
 openDlg(tit,sub+(ci?'<dl class="cedl"><dt>Estado</dt><dd>'+esc(e)+'</dd><dt>Paciente</dt><dd>'+esc(ceNom(p))+' · '+esc(p.Documento)+'</dd><dt>Origen</dt><dd>'+esc(ci.Origen)+'</dd><dt>Asignada</dt><dd>'+esc(ci.AsignadaEn+" · "+ci.AsignadaPor)+'</dd>'+(ci.SaltoOrdenMotivo?'<dt>Salto de orden</dt><dd>'+esc(ci.SaltoOrdenMotivo)+'</dd>':'')+'</dl><div class="copyrow"><button type="button" class="btn sm" data-ce="sol|'+ci.Solicitud+'">Ver solicitud</button></div>':'<p class="note">Cupo '+esc(e.toLowerCase())+'.</p>')+'<p class="note">Confirmación, llegada, atención, cancelación e inasistencia se registran en la Fase 2.</p>',"Cerrar",()=>{});$("dlgx").hidden=true;}

function ceDlgJor(){const hoy=ceHoy();const pros=CE.book.pro.filter(p=>ceSN(p.Activo)&&String(p.Especialidades).split(",").some(e=>e&&ceVisEsp(e)));
 const body='<div class="form"><label class="f wide">Profesional *<select id="cj_pro">'+opt(pros.map(p=>[p.ID,p.Nombre]),"","—")+'</select></label><label class="f">Especialidad *<select id="cj_esp"></select></label><label class="f">Modalidad *<select id="cj_mod"></select></label><label class="f wide">Consultorio *<select id="cj_con"></select></label>'+
  '<label class="f">Desde *<input type="date" id="cj_d1" min="'+hoy+'" value="'+hoy+'"></label><label class="f">Hasta<input type="date" id="cj_d2" min="'+hoy+'"></label>'+
  '<div class="f wide"><span>Días</span><div class="chips-in">'+[1,2,3,4,5,6,7].map(d=>'<label class="chk-chip"><input type="checkbox" class="cj_dia" value="'+d+'"'+(d<=5?" checked":"")+'><span>'+CE_DIAS[d%7]+'</span></label>').join("")+'</div></div>'+
  '<label class="f">Hora inicio *<input type="time" id="cj_hi" value="08:00"></label><label class="f">Hora fin *<input type="time" id="cj_hf" value="12:00"></label><label class="f">Duración del cupo (min) *<input type="number" id="cj_du" min="5" max="120"></label>'+
  '<p class="note wide" id="cj_dua"></p><label class="f">Agendas<select id="cj_ag">'+opt([["1","Una agenda"],["2","Espejo A/B (dos por franja)"]],"1")+'</select></label><label class="f">Solo para EPS<select id="cj_eps">'+opt(CE.book.eps.map(e=>[e.Codigo,e.Nombre]),"","Todas")+'</select></label>'+
  '<label class="f">Pausa desde<input type="time" id="cj_p1"></label><label class="f">Pausa hasta<input type="time" id="cj_p2"></label><label class="f">Motivo de la pausa<input type="text" id="cj_pm" value="Pausa activa"></label>'+
  '<label class="f"><span>Jornada extraordinaria</span><select id="cj_ex">'+opt([["","No"],["SI","Sí"]],"")+'</select></label><label class="f wide">Observación<input type="text" id="cj_ob" maxlength="200"></label></div><p class="alert" id="cj_prev" style="margin:0"></p><div id="cj_res"></div>';
 openDlg("Abrir jornadas",'<p class="note">Por rango de fechas. Si un solo día se cruza, no se abre ninguna.</p>'+body,"Abrir jornadas",()=>{const r=ceAbrirJornadas(ceJorLeer());if(!r.ok){$("cj_res").innerHTML='<div class="alert bad"><p>'+esc(r.mensaje)+'</p>'+(r.conflictos?'<ul>'+r.conflictos.map(x=>'<li>'+esc(x)+'</li>').join("")+'</ul>':'')+'</div>';return" ";}
  const f=ceGv("cj_d1");CE.ui.ag=Object.assign(CE.ui.ag||{},{fecha:f,modo:r.jornadas>1?"sem":"dia"});pxRender();toast(r.mensaje);});ceDlgAncho();
 const actP=()=>{const p=ceIdx().pro.get(ceGv("cj_pro"));$("cj_esp").innerHTML=p?opt(String(p.Especialidades).split(",").filter(e=>e&&ceVisEsp(e)).map(e=>[e,ceEspN(e)]),""):"";actE();};
 const actE=()=>{const e=ceEsp(ceGv("cj_esp"));const m=e?ceModsHab(e.Codigo):[];$("cj_mod").innerHTML=m.length?opt(m.map(x=>[x,CE_MODAL[x]]),m[0]):'<option value="">Sin modalidades habilitadas</option>';
  $("cj_dua").textContent=e?(e.MinPrimeraVez||e.MinControl?"Coordinación fijó: primera vez "+(e.MinPrimeraVez?e.MinPrimeraVez+" min":"sin definir")+", control "+(e.MinControl?e.MinControl+" min":"sin definir")+". Puede cambiarla para esta jornada.":"Coordinación no ha fijado la duración para esta especialidad: indíquela para esta jornada."):"";
  const du=$("cj_du");if(e&&!du.dataset.t)du.value=e.MinControl||e.MinPrimeraVez||"";actM();};
 const actM=()=>{const m=ceGv("cj_mod");const t=m==="TELEMEDICINA"?"VIRTUAL":"FISICO";$("cj_con").innerHTML=opt(CE.book.con.filter(c=>ceSN(c.Activo)&&c.Tipo===t).map(c=>[c.ID,c.Nombre+" · "+c.Sede+(c.Plataforma?" · "+c.Plataforma:"")]),"")||'<option value="">No hay consultorios de ese tipo</option>';prev();};
 const prev=()=>{const p=ceJorLeer();const hi=ceM(p.HoraInicio),hf=ceM(p.HoraFin),du=+p.Duracion;const el=$("cj_prev");if(!el)return;if(!du||hi==null||hf==null||hf<=hi){el.textContent="Complete horario y duración.";return;}
  let n=0,b=0;for(let t=hi;t+du<=hf;t+=du){n++;if(p.Pausas.some(z=>t<ceM(z.Fin)&&t+du>ceM(z.Inicio)))b++;}let nd=0;if(p.Desde)for(let f=p.Desde;f<=(p.Hasta||p.Desde)&&nd<200;f=ceSumar(f,1))if(p.Dias.includes(pdate(f).getDay()||7))nd++;const ag=+p.Agendas;
  el.textContent="Vista previa: "+nd+" jornada(s) × "+n*ag+" cupo(s) = "+nd*n*ag+" cupos, "+nd*b*ag+" bloqueados por la pausa. Se confirma al guardar.";};
 $("cj_pro").addEventListener("change",actP);$("cj_esp").addEventListener("change",actE);$("cj_mod").addEventListener("change",actM);$("cj_du").addEventListener("input",e=>{e.target.dataset.t="1";prev();});
 document.querySelectorAll("#dlg input,#dlg select").forEach(x=>x.addEventListener("change",prev));actP();}
function ceJorLeer(){const p1=ceGv("cj_p1"),p2=ceGv("cj_p2");return{Profesional:ceGv("cj_pro"),Especialidad:ceGv("cj_esp"),Modalidad:ceGv("cj_mod"),Consultorio:ceGv("cj_con"),Desde:ceGv("cj_d1"),Hasta:ceGv("cj_d2"),
 Dias:[...document.querySelectorAll(".cj_dia:checked")].map(x=>+x.value),HoraInicio:ceGv("cj_hi"),HoraFin:ceGv("cj_hf"),Duracion:ceGv("cj_du"),Agendas:ceGv("cj_ag"),EPS:ceGv("cj_eps"),Extraordinaria:ceGv("cj_ex")==="SI",Observacion:ceGv("cj_ob"),
 Pausas:p1&&p2?[{Inicio:p1,Fin:p2,Motivo:ceGv("cj_pm")}]:[]};}

/* autorizaciones */
function ceAutAlerta(s){const a=ceAut(s.ID);const hoy=ceHoy();const c=ceCitaAct(s.ID);const av=ceCfg("aviso_autorizacion_dias");if(!a)return"NO_REQUIERE";
 if(["PENDIENTE","VALIDACION_ADMIN"].includes(a.Situacion))return"PENDIENTE";if(a.Situacion==="NEGADA")return"NEGADA";if(a.Situacion!=="APROBADA")return"NO_REQUIERE";
 if(a.FechaVencimiento<hoy)return"VENCIDA";if(c&&a.FechaVencimiento<c.Fecha)return"VENCE_ANTES_DE_LA_CITA";if(av!=null&&a.FechaVencimiento<=ceSumar(hoy,+av))return"POR_VENCER";return"VIGENTE";}
function ceAutV(){const AL={PENDIENTE:["Pendiente","warn"],NEGADA:["Negada","bad"],VENCIDA:["Vencida","bad"],VENCE_ANTES_DE_LA_CITA:["Vence antes de la cita","bad"],POR_VENCER:["Por vencer","warn"],VIGENTE:["Vigente","ok"]};const F=CE.ui.aal||"";
 const S=ceSolsAbiertas().filter(s=>ceAutAlerta(s)!=="NO_REQUIERE").map(s=>({s,al:ceAutAlerta(s),a:ceAut(s.ID)}));const I=ceIdx();
 let h='<p class="note" style="margin-top:12px">Solicitudes abiertas que requieren autorización.'+(ceCfg("aviso_autorizacion_dias")==null?' El aviso «por vencer» está apagado hasta que Coordinación fije los días.':'')+'</p><div class="tiles mini-tiles">'+Object.entries(AL).map(([k,[l,c]])=>'<button type="button" class="tile '+c+'" data-ce="aal|'+k+'"'+(F===k?' style="outline:2px solid var(--accent)"':'')+'><span class="tv">'+S.filter(x=>x.al===k).length+'</span><span class="tl">'+l+'</span></button>').join("")+'</div>';
 h+='<div class="panel tablebox" style="padding:0;margin-top:10px"><table><thead><tr><th>Paciente</th><th>Especialidad</th><th>Situación</th><th>Número</th><th>Vence</th><th>Alerta</th><th>Solicitud</th><th>Cita</th></tr></thead><tbody>'+
  (S.filter(x=>!F||x.al===F).sort((a,b)=>(a.a.FechaVencimiento||"0").localeCompare(b.a.FechaVencimiento||"0")).map(({s,al,a})=>{const p=I.pac.get(s.Paciente);const c=ceCitaAct(s.ID);
   return'<tr class="click" data-ce="sol|'+s.ID+'"><td><b>'+esc(ceNom(p))+'</b><span class="sub">'+esc(p.Documento+" · "+p.EPS)+'</span></td><td>'+esc(ceEspN(s.Especialidad))+'</td><td>'+ceAutTag(a.Situacion)+'</td><td class="mono">'+esc(a.Numero||"—")+'</td><td>'+(a.FechaVencimiento?ceFD(a.FechaVencimiento)+'<span class="sub">'+ceDias(ceHoy(),a.FechaVencimiento)+' días</span>':'—')+'</td><td><span class="tag '+AL[al][1].replace("ok","fav")+'">'+AL[al][0]+'</span></td><td>'+ceEstTag(s)+'</td><td>'+(c?ceFD(c.Fecha)+" "+esc(c.Hora):"—")+'</td></tr>';}).join("")||'<tr><td colspan="8" class="empty">Sin registros.</td></tr>')+'</tbody></table></div>';
 return h;}

/* pacientes */
function cePacV(){const q=ceUp(CE.ui.pq);const vis=pid=>CE.book.sol.filter(s=>s.Paciente===pid&&s.Estado!=="CERRADA"&&ceVisSol(s)).length;
 const L=q.length>=3?CE.book.pac.filter(p=>ceNom(p).includes(q)||p.Documento.includes(q)).slice(0,60):[];
 return'<p class="note" style="margin-top:12px">Maestro único: un registro por tipo y número de documento. Sin datos clínicos.</p><div class="filters"><label class="f" style="min-width:280px">Documento o nombre (mínimo 3 caracteres)<input type="text" id="ce_pq" value="'+esc(CE.ui.pq||"")+'"></label></div>'+
  (q.length>=3?'<div class="panel tablebox" style="padding:0;margin-top:10px"><table><thead><tr><th>Documento</th><th>Nombre</th><th>Teléfono</th><th>EPS</th><th>Municipio</th><th>Solicitudes abiertas</th></tr></thead><tbody>'+(L.map(p=>'<tr class="click" data-ce="pac|'+p.ID+'"><td class="mono">'+esc(p.TipoDoc+" "+p.Documento)+'</td><td>'+esc(ceNom(p))+'</td><td>'+esc(p.Telefono)+'</td><td>'+esc(p.EPS)+'</td><td>'+esc(p.Municipio)+'</td><td class="mono">'+vis(p.ID)+'</td></tr>').join("")||'<tr><td colspan="6" class="empty">Sin resultados.</td></tr>')+'</tbody></table></div>':'');}
function ceDlgPac(pid){const p=ceIdx().pac.get(pid);if(!p)return;const S=CE.book.sol.filter(s=>s.Paciente===pid&&ceVisSol(s));
 openDlg(ceNom(p),'<p class="note">'+esc(p.TipoDoc+" "+p.Documento+" · nacimiento "+ceFD(p.FechaNac))+'</p>'+(cePuede("paciente")?'<div class="form"><label class="f">Teléfono<input type="text" id="cp_te" value="'+esc(p.Telefono)+'"></label><label class="f">Teléfono alterno<input type="text" id="cp_t2" value="'+esc(p.Telefono2)+'"></label><label class="f">Municipio<input type="text" id="cp_mu" value="'+esc(p.Municipio)+'"></label><label class="f">EPS<select id="cp_eps">'+opt(CE.book.eps.map(e=>[e.Codigo,e.Nombre]),p.EPS)+'</select></label></div><p class="note">El valor anterior queda en la bitácora.</p>':'')+
  '<h3>Solicitudes</h3><ul class="cehist">'+(S.map(s=>'<li><button type="button" class="lnk" data-ce="sol|'+s.ID+'">'+esc(s.ID)+'</button> · '+esc(ceEspN(s.Especialidad)+" · "+CE_TIPO[s.TipoConsulta]+" · "+ceFD(s.FechaSolicitud))+' · '+ceEstTag(s)+'</li>').join("")||'<li>Sin solicitudes.</li>')+'</ul>',cePuede("paciente")?"Guardar contacto":"Cerrar",()=>{if(!cePuede("paciente"))return;
  const t=ceGv("cp_te");if(!/^[0-9 +()-]{7,20}$/.test(t))return"Teléfono no válido.";ceUpd("pac",p,{Telefono:t,Telefono2:ceGv("cp_t2"),Municipio:ceUp(ceGv("cp_mu")),EPS:ceGv("cp_eps")});pxRender();toast("Paciente actualizado.");});}

/* calidad del dato */
function ceCalV(){const R=ceCalidad();return'<p class="note" style="margin-top:12px">Revisión del libro: lo que una pantalla no puede impedir cuando varias personas trabajan copias del libro.</p>'+R.map(r=>'<details class="panel" style="margin-top:8px"'+(r.n&&r.grave?' open':'')+'><summary><b>'+esc(r.k)+'</b> <span class="tag'+(r.n?(r.grave?" bad":" warn"):" fav")+'">'+r.n+'</span></summary><p class="note">'+esc(r.d)+'</p>'+(r.L.length?'<ul class="cehist">'+r.L.slice(0,100).map(x=>'<li class="mono">'+esc(x)+'</li>').join("")+'</ul>':'')+'</details>').join("");}

/* administración */
function ceAdm(){const rol=ceRol();if(!["coordinacion","calidad"].includes(rol))return'<div class="alert warn" style="margin-top:12px"><p>Administración la hacen Coordinación y Calidad.</p></div>';
 const T=[["esp","Especialidades"],["pro","Profesionales"],["con","Consultorios"],["eps","EPS"],["par","Parámetros"],["rol","Roles"],["log","Bitácora"]].filter(([k])=>rol==="coordinacion"||["esp","log"].includes(k));const t=T.some(x=>x[0]===CE.ui.at)?CE.ui.at:T[0][0];
 let h='<div class="seg" style="margin-top:12px">'+T.map(([k,l])=>'<button type="button" data-ce="at|'+k+'" aria-pressed="'+(t===k)+'">'+l+'</button>').join("")+'</div>';
 if(t==="esp")h+='<p class="note" style="margin-top:10px">Habilite una modalidad solo si consta en el REPS vigente de la sede y registre la fuente. La duración de la consulta la fija Coordinación: no hay valores precargados; al abrir una jornada se propone y se puede cambiar.</p><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Especialidad</th><th>Presencial</th><th>Telemedicina</th><th>Fuente (REPS)</th><th>Primera vez (min)</th><th>Control (min)</th><th>Actualizado</th><th></th></tr></thead><tbody>'+
  CE.book.esp.map(e=>'<tr><td>'+esc(e.Nombre)+(ceSN(e.Reservada)?' <span class="tag ce-vio">reservada</span>':'')+(ceSN(e.ReportaRes256)?' <span class="tag">Res. 256</span>':'')+'</td><td><input type="checkbox" id="ea_p_'+e.Codigo+'"'+(ceSN(e.Presencial)?" checked":"")+'></td><td><input type="checkbox" id="ea_t_'+e.Codigo+'"'+(ceSN(e.Telemedicina)?" checked":"")+'></td><td><input type="text" id="ea_f_'+e.Codigo+'" value="'+esc(e.FuenteREPS)+'"></td><td><input type="number" min="5" max="120" id="ea_1_'+e.Codigo+'" value="'+esc(e.MinPrimeraVez)+'"'+(rol!=="coordinacion"?" disabled":"")+' style="max-width:90px"></td><td><input type="number" min="5" max="120" id="ea_2_'+e.Codigo+'" value="'+esc(e.MinControl)+'"'+(rol!=="coordinacion"?" disabled":"")+' style="max-width:90px"></td><td class="sub">'+esc(e.DuracionActualizadaPor||"sin definir")+'</td><td><button type="button" class="btn sm primary" data-ce="gesp|'+e.Codigo+'">Guardar</button></td></tr>').join("")+'</tbody></table></div>';
 if(t==="pro")h+='<div class="panel tablebox" style="padding:0;margin-top:10px"><table><thead><tr><th>Nombre</th><th>Documento</th><th>Registro</th><th>Especialidades</th><th>Activo</th><th></th></tr></thead><tbody>'+CE.book.pro.map(p=>'<tr><td>'+esc(p.Nombre)+'</td><td class="mono">'+esc(p.TipoDoc+" "+p.Documento)+'</td><td>'+esc(p.Registro)+'</td><td>'+esc(String(p.Especialidades).split(",").filter(Boolean).map(ceEspN).join(", "))+'</td><td>'+(ceSN(p.Activo)?"Sí":"No")+'</td><td><button type="button" class="btn sm" data-ce="proact|'+p.ID+'">'+(ceSN(p.Activo)?"Desactivar":"Activar")+'</button></td></tr>').join("")+'</tbody></table></div>'+
  '<div class="panel" style="margin-top:10px"><h3>Nuevo profesional</h3><div class="form"><label class="f">Tipo doc.<select id="ap_td">'+opt(["CC","CE","PA","PT"],"CC")+'</select></label><label class="f">Documento<input type="text" id="ap_doc"></label><label class="f">Nombre<input type="text" id="ap_no"></label><label class="f">Registro profesional<input type="text" id="ap_re"></label><div class="f wide"><span>Especialidades</span><div class="chips-in">'+CE.book.esp.map(e=>'<label class="chk-chip"><input type="checkbox" class="ap_esp" value="'+e.Codigo+'"><span>'+esc(e.Nombre)+'</span></label>').join("")+'</div></div></div><p class="note" id="ap_msg" style="color:var(--bad)"></p><div class="copyrow"><button type="button" class="btn primary" data-ce="pronew">Guardar</button></div></div>';
 if(t==="con")h+='<div class="panel tablebox" style="padding:0;margin-top:10px"><table><thead><tr><th>Sede</th><th>Nombre</th><th>Tipo</th><th>Plataforma</th><th>Activo</th><th></th></tr></thead><tbody>'+CE.book.con.map(c=>'<tr><td>'+esc(c.Sede)+'</td><td>'+esc(c.Nombre)+'</td><td>'+(c.Tipo==="VIRTUAL"?'<span class="tag ce-vio">Virtual</span>':'<span class="tag">Físico</span>')+'</td><td>'+esc(c.Plataforma)+'</td><td>'+(ceSN(c.Activo)?"Sí":"No")+'</td><td><button type="button" class="btn sm" data-ce="conact|'+c.ID+'">'+(ceSN(c.Activo)?"Desactivar":"Activar")+'</button></td></tr>').join("")+'</tbody></table></div>'+
  '<div class="panel" style="margin-top:10px"><h3>Nuevo consultorio</h3><div class="form"><label class="f">Sede<input type="text" id="ac_se" value="Mocoa"></label><label class="f">Nombre<input type="text" id="ac_no"></label><label class="f">Tipo<select id="ac_ti">'+opt([["FISICO","Físico"],["VIRTUAL","Virtual (telemedicina)"]],"FISICO")+'</select></label><label class="f">Plataforma (solo el nombre)<input type="text" id="ac_pl"></label></div><p class="note">Nunca registre usuarios, claves ni enlaces con clave de la plataforma.</p><p class="note" id="ac_msg" style="color:var(--bad)"></p><div class="copyrow"><button type="button" class="btn primary" data-ce="connew">Guardar</button></div></div>';
 if(t==="eps")h+='<div class="panel tablebox" style="padding:0;margin-top:10px"><table><thead><tr><th>Código</th><th>Nombre</th><th>Activa</th><th></th></tr></thead><tbody>'+CE.book.eps.map(e=>'<tr><td class="mono">'+esc(e.Codigo)+'</td><td>'+esc(e.Nombre)+'</td><td>'+(ceSN(e.Activa)?"Sí":"No")+'</td><td><button type="button" class="btn sm" data-ce="epsact|'+esc(e.Codigo)+'">'+(ceSN(e.Activa)?"Desactivar":"Activar")+'</button></td></tr>').join("")+'</tbody></table></div>'+
  '<div class="panel" style="margin-top:10px"><h3>Nueva EPS</h3><div class="form"><label class="f">Código<input type="text" id="ae_co"></label><label class="f">Nombre<input type="text" id="ae_no"></label></div><p class="note" id="ae_msg" style="color:var(--bad)"></p><div class="copyrow"><button type="button" class="btn primary" data-ce="epsnew">Guardar</button></div></div>';
 if(t==="par"){const D={umbral_espera_dias:"Días de espera desde la solicitud a partir de los cuales se marca «sobre umbral»",aviso_autorizacion_dias:"Días antes del vencimiento de una autorización aprobada para avisar «por vencer»",asignar_sin_autorizacion:"Permite asignar con autorización pendiente (1 = sí; vacío = no)"};
  h+='<p class="note" style="margin-top:10px">Vacío = alerta apagada. Registre la fuente (acta, contrato, norma). Un parámetro institucional no es un límite legal.</p><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Parámetro</th><th>Valor</th><th>Fuente</th><th></th></tr></thead><tbody>'+CE.book.cfg.filter(r=>D[r.Clave]).map(r=>'<tr><td>'+esc(D[r.Clave])+'<span class="sub mono">'+esc(r.Clave)+'</span></td><td><input type="number" min="0" id="pa_v_'+r.Clave+'" value="'+esc(r.Valor)+'" style="max-width:100px"></td><td><input type="text" id="pa_f_'+r.Clave+'" value="'+esc(r.Fuente)+'"></td><td><button type="button" class="btn sm primary" data-ce="gpar|'+r.Clave+'">Guardar</button></td></tr>').join("")+'</tbody></table></div>';}
 if(t==="rol"){const U=(PX.book?PX.book.usr:[]).filter(u=>u.Activo!=="NO");
  h+='<p class="note" style="margin-top:10px">El rol decide qué hace cada persona en Consulta Externa. «Ve reservadas» permite ver y gestionar infectología y oncología: concédalo solo a quien lo necesita por su función. Nadie cambia su propio rol; queda en la bitácora con el motivo.</p><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Usuario</th><th>Rol en Consulta Externa</th><th>Ve reservadas</th><th>Motivo</th><th></th></tr></thead><tbody>'+
   U.map(u=>{const r=CE.book.rol.find(x=>x.Usuario===u.Usuario);const k=esc(u.Usuario);return'<tr><td>'+esc(u.Nombre)+'<span class="sub">'+k+' · '+esc(u.Cargo)+'</span></td><td><select id="ro_r_'+k+'">'+opt(Object.entries(CE_ROLES),r?r.Rol:"consulta")+'</select></td><td><input type="checkbox" id="ro_v_'+k+'"'+(r&&r.VeReservadas==="SI"?" checked":"")+'></td><td><input type="text" id="ro_m_'+k+'" value="'+esc(r?r.Motivo:"")+'"></td><td><button type="button" class="btn sm primary" data-ce="grol|'+k+'">Guardar</button></td></tr>';}).join("")+'</tbody></table></div>';}
 if(t==="log")h+='<div class="panel tablebox" style="padding:0;margin-top:10px"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Hoja / registro</th><th>Detalle</th></tr></thead><tbody>'+CE.book.log.slice(-200).reverse().map(l=>'<tr><td class="mono">'+esc(l.FechaHora)+'</td><td>'+esc(l.Usuario)+'</td><td>'+esc(l.Accion)+'</td><td>'+esc(l.Hoja+" "+l.Registro)+'</td><td class="sub" style="max-width:480px">'+esc(l.Detalle)+'</td></tr>').join("")+'</tbody></table></div><p class="note">Últimos 200 registros. La bitácora viaja dentro del libro.</p>';
 return h;}

