 const F=CE.ui.lf||(CE.ui.lf={});const map={ce_fesp:"esp",ce_fest:"est",ce_fprio:"prio",ce_faut:"aut",ce_fver:"ver"};if(map[t.id]){F[map[t.id]]=t.value;pxRender();return;}
 const A=CE.ui.ag;const am={ce_af:"fecha",ce_aesp:"esp",ce_apro:"prof",ce_amod:"mod"};if(am[t.id]&&A){if(t.id==="ce_af"&&!t.value)return;A[am[t.id]]=t.value;pxRender();return;}
 if(t.id==="cn_esp"){CE.ui.nd.esp=t.value;const keep=["cn_tipo","cn_fs","cn_ca","cn_te","cn_t2","cn_eps","cn_n1","cn_n2","cn_a1","cn_a2","cn_fn","cn_sx","cn_mu"].map(i=>[i,ceGv(i)]);pxRender();keep.forEach(([i,v])=>{const el=$(i);if(el&&v)el.value=v;});return;}
