const v6pn=(prog,pid)=>{if(!pid)return"";if(prog==="dp"){const p=dpPac(pid);return p?dpNombre(p):pid;}if(hdOn()){ensureIdx();const p=IDX.pac.get(pid);if(p)return nombre(p);}return pid;};

/* ---------- libro institucional: hojas nuevas ---------- */
PSH.mic=["Microbiologia",["ID","Programa","Paciente","Episodio","Muestra","FechaSolicitud","FechaToma","HoraToma","Laboratorio","Integracion","Soporte","Estado","FechaResultado","Resultado","Gram","Microorganismo","Antibiograma","Fenotipo","Nota","Usuario","Registrado","Anulado","MotivoAnulacion"]];
PSH.icl=["IAASClasificacion",["ID","Fuente","Ref","Programa","Paciente","Estado","Criterio","Atribucion","Version","Clasificador","Fecha","Nota","Usuario","Registrado"]];
PSH.cie=["IndicadoresCierre",["ID","Matriz","Periodo","Indicador","Numerador","Denominador","Valor","Estado","Disponibilidad","Version","Fuentes","Nota","CerradoPor","Fecha","Vigente"]];
PSH.man[1].push("Responsable","MotivoExcepcional");
PSH.prv[1].splice(PSH.prv[1].indexOf("Nota"),0,"AjusteRenal");
["mic","icl","cie"].forEach(k=>{if(!PKEYS.includes(k))PKEYS.splice(PKEYS.indexOf("log"),0,k);});
function pxEnsureSheets(){if(!PX.book)return;PKEYS.forEach(k=>{if(!Array.isArray(PX.book[k]))PX.book[k]=[];});}

/* =================== dispositivos de acceso vascular (libro HD) =================== */
const DSP_TIPOS=["CVC tunelizado","CVC temporal","FAV","Injerto"];
const DSP_SITIOS=["Yugular interna derecha","Yugular interna izquierda","Subclavia derecha","Subclavia izquierda","Femoral derecha","Femoral izquierda","Antebrazo izquierdo","Antebrazo derecho","Brazo izquierdo","Brazo derecho","Otro"];
const DSP_RETIRO=["Cambio de acceso","Disfunción","Infección","Trombosis","Fin de uso (FAV o injerto funcional)","Salida accidental","Egreso de la unidad","Otro"];
const DSP_LUGAR=["UNO-P (sala de procedimientos)","Otra institución","Desconocido"];
function dspAll(){return hdOn()&&ST.book.dsp?ST.book.dsp.filter(lv):[];}
function dspOf(pid){return dspAll().filter(d=>d.Paciente===pid).sort((a,b)=>(a.FechaInsercion||0)-(b.FechaInsercion||0));}
function dspCVC(pid){return dspOf(pid).filter(d=>isCVC(d.Tipo));}
function dspFind(id){return id?dspAll().find(d=>d.ID===id):null;}
const dspOpen=d=>!d.FechaRetiro&&d.Estado!=="Retirado";
function cdMet(){return Object.assign({},CFG_DEF.cdMet,(ST.book&&ST.book.cfgv.cdMet)||{});}
function dspCovers(d,day,met){if(!d.FechaInsercion||d.FechaInsercion>day)return false;if(!d.FechaRetiro)return d.Estado!=="Retirado";return met&&met.retiro==="excluye"?day<d.FechaRetiro:day<=d.FechaRetiro;}
function hospOn(p,d){return p._nov.some(n=>n.Tipo==="Hospitalización"&&n.Inicio<=d&&(!n.Fin||d<=n.Fin));}
function dspAdd(o){const r=addRec("dsp","DS-",Object.assign({Estado:"Activo",Origen:"Registro directo",Validado:"SI",ValidadoPor:ST.user,ValidadoFecha:TODAY()},o));return r;}
/* Días-catéter: para cada catéter, días calendario entre inserción y retiro que caen en [a,b] y en los que el paciente
   está activo en la unidad. Si falta un dato que impide establecer la exposición, el resultado no es calculable. */
function cdCalc(a,b,eps,onlyPid){
  const met=cdMet();const R={days:0,per:[],block:[],warn:[],pend:[],recs:[],met,a,b,complete:true};
  if(!hdOn())return R;ensureIdx();
  pacs().filter(p=>(!onlyPid||p.ID===onlyPid)&&(!eps||p.EPS===eps)&&overlaps(p,a,b)).forEach(p=>{
    const D=dspCVC(p.ID);let n=0,dup=0;const used=new Set();
    D.forEach(d=>{const inP=(!d.FechaInsercion||d.FechaInsercion<=b)&&(!d.FechaRetiro||d.FechaRetiro>=a);if(!inP)return;
      if(!d.FechaInsercion)R.block.push({p,d,t:"Catéter "+d.ID+" ("+d.Tipo+") sin fecha de inserción",fix:"Registrar la fecha de inserción (o la primera fecha documentada) en el registro de dispositivos"});
      else if(d.Estado==="Retirado"&&!d.FechaRetiro)R.block.push({p,d,t:"Catéter "+d.ID+" marcado como retirado sin fecha de retiro",fix:"Registrar la fecha de retiro"});
      else if(d.FechaRetiro&&d.FechaRetiro<d.FechaInsercion)R.block.push({p,d,t:"Catéter "+d.ID+" con retiro anterior a la inserción",fix:"Corregir las fechas"});
      if(d.Validado!=="SI")R.pend.push({p,d});});
    const valid=D.filter(d=>d.FechaInsercion&&!(d.Estado==="Retirado"&&!d.FechaRetiro)&&!(d.FechaRetiro&&d.FechaRetiro<d.FechaInsercion));
    for(let d=new Date(a);d<=b;d=addDays(d,1)){if(!activeAt(p,d))continue;if(met.hosp==="excluye"&&hospOn(p,d))continue;const c=valid.filter(x=>dspCovers(x,d,met));if(c.length){n++;c.forEach(x=>used.add(x.ID));const real=c.filter(x=>!(x.FechaRetiro&&iso(x.FechaRetiro)===iso(d)&&c.some(y=>y!==x&&y.FechaInsercion&&iso(y.FechaInsercion)===iso(d))));if(real.length>1)dup++;}}
    if(dup)R.warn.push({p,t:dup+(dup===1?" día":" días")+" con dos catéteres activos a la vez (se cuentan una vez); revise si falta registrar un retiro"});
    const S=p._ses.filter(s=>s.Estado==="Realizada"&&s.Fecha>=a&&s.Fecha<=b&&isCVC(s.Acceso));
    const sinD=S.filter(s=>!D.some(x=>x.FechaInsercion&&dspCovers(x,s.Fecha,{retiro:"incluye"})));
    if(sinD.length)R.block.push({p,t:sinD.length+" sesiones con catéter sin un dispositivo registrado que las cubra (primera: "+fd(sinD[0].Fecha)+")",fix:"Registrar el catéter con su fecha de inserción, o corregir el acceso de la sesión en el Turno",ses:sinD.map(s=>s.ID)});
    const favS=p._ses.filter(s=>s.Estado==="Realizada"&&s.Fecha>=a&&s.Fecha<=b&&s.Acceso&&!isCVC(s.Acceso));
    const cvcOnFav=favS.filter(s=>valid.some(x=>dspCovers(x,s.Fecha,met)));
    if(cvcOnFav.length)R.warn.push({p,t:cvcOnFav.length+" sesiones por FAV/injerto mientras figura un catéter activo: confirme si el catéter sigue in situ (se cuentan sus días)"});
    if(n||D.length||S.length)R.per.push({p,days:n,devs:[...used],ses:S.length});R.days+=n;used.forEach(id=>R.recs.push(id));});
  R.complete=!R.block.length;return R;}
/* propuesta de dispositivos desde el historial (ingreso, sesiones, acceso actual y novedades): queda sin validar */
function dspPropuestas(){if(!hdOn())return[];ensureIdx();const out=[];
  pacs().forEach(p=>{if(dspOf(p.ID).length)return;const pts=[];const st=p.IngresoUnidad||p.InicioTRR;
    if(st&&p.AccesoInicial)pts.push({d:st,a:p.AccesoInicial,w:"acceso al ingreso"});
    p._ses.filter(s=>s.Estado==="Realizada"&&s.Acceso).forEach(s=>pts.push({d:s.Fecha,a:s.Acceso,w:"sesión"}));
    if(p.AccesoActual&&p.AccesoDesde)pts.push({d:p.AccesoDesde,a:p.AccesoActual,w:"acceso actual desde"});
    p._acn.forEach(n=>{if(n.AccesoResultante)pts.push({d:n.Fecha,a:n.AccesoResultante,w:"novedad "+n.Tipo});if(n.Tipo==="Recambio de catéter")pts.push({d:n.Fecha,a:"__REC__",w:"recambio"});});
    pts.sort((x,y)=>x.d-y.d);const seg=[];
    pts.forEach(x=>{const cur=seg[seg.length-1];if(x.a==="__REC__"){if(cur&&isCVC(cur.a)){cur.fin=x.d;cur.finW="recambio "+fd(x.d);seg.push({a:cur.a,ini:x.d,iniW:"recambio "+fd(x.d),fin:null});}return;}
      if(!cur||cur.a!==x.a){if(cur&&!cur.fin){cur.fin=x.d;cur.finW="primera evidencia de "+x.a+" ("+x.w+") "+fd(x.d);}seg.push({a:x.a,ini:x.d,iniW:x.w+" "+fd(x.d),fin:null});}});
    seg.forEach(s=>{if(!DSP_TIPOS.includes(s.a))return;out.push({Paciente:p.ID,Tipo:s.a,FechaInsercion:s.ini,FechaRetiro:s.fin,Estado:s.fin?"Retirado":"Activo",MotivoRetiro:s.fin?"Cambio de acceso":"",Origen:"Propuesto desde el historial",Validado:"NO",Nota:"Inserción aproximada: "+s.iniW+(s.fin?" · retiro aproximado: "+s.finW:"")+". Confirmar contra la historia clínica."});});});
  return out;}

/* =================== microbiología (libro institucional, proceso Laboratorio) =================== */
const MIC_MUESTRAS=["Hemocultivo periférico","Hemocultivo de catéter","Líquido peritoneal (efluente)","Secreción del orificio de salida","Punta de catéter","Urocultivo","Otra"];
const MIC_SANGRE=["Hemocultivo periférico","Hemocultivo de catéter"];
const MIC_EST=["Solicitado","Tomado","En proceso","Preliminar","Final","No procesado","Rechazado"];
const MIC_RES=["Pendiente","Positivo","Negativo","Contaminado"];
const MIC_FEN=["Ninguno detectado","SAMR","BLEE","Carbapenemasa","Otro multirresistente","Sin antibiograma"];
const MIC_FEN_ALERTA=["SAMR","BLEE","Carbapenemasa","Otro multirresistente"];
const MIC_INT=["Transcrito del informe del laboratorio de apoyo","Registrado por el laboratorio de UNO-P","Importado (archivo)"];
const MIC_ATB=["Oxacilina","Cefoxitina","Vancomicina","Linezolid","Daptomicina","Clindamicina","Eritromicina","Trimetoprim-sulfametoxazol","Rifampicina","Gentamicina","Amikacina","Ampicilina","Ampicilina-sulbactam","Piperacilina-tazobactam","Cefazolina","Ceftriaxona","Ceftazidima","Cefepime","Ertapenem","Meropenem","Ciprofloxacina","Colistina","Fluconazol"];
function micAll(){return typeof PX!=="undefined"&&PX.book&&PX.book.mic?PX.book.mic.filter(lv):[];}
function micOfEp(ref){return micAll().filter(m=>m.Episodio===ref);}
function micOfPac(prog,pid){return micAll().filter(m=>m.Programa===prog&&m.Paciente===pid);}
const micPos=m=>m.Resultado==="Positivo"&&["Preliminar","Final"].includes(m.Estado);
function micAB(m){try{const a=JSON.parse(m.Antibiograma||"[]");return Array.isArray(a)?a:[];}catch(e){return[];}}
/* confirmación de laboratorio de un evento infeccioso de HD (el resultado lo registra Laboratorio; IAAS no lo edita) */
function itsConf(e){const M=micOfEp("HD:"+e.ID).filter(m=>MIC_SANGRE.includes(m.Muestra));const pos=M.filter(micPos);
  if(pos.length)return{st:"Confirmada",src:"lab",m:M,org:[...new Set(pos.map(m=>m.Microorganismo).filter(Boolean))].join(", ")};
  const fin=M.filter(m=>["Final","No procesado","Rechazado"].includes(m.Estado));
  if(M.length&&fin.length===M.length){const proc=M.filter(m=>m.Estado==="Final");return{st:proc.length?"No confirmada":"Muestra no procesada",src:"lab",m:M};}
  if(M.length)return{st:"Cultivo en proceso",src:"lab",m:M};
  if(e.Hemocultivo==="Positivo")return{st:"Confirmada",src:"heredado",m:[],org:e.Microorganismo||""};
  if(e.Hemocultivo==="Negativo")return{st:"No confirmada",src:"heredado",m:[]};
  if(e.Hemocultivo==="No tomado")return{st:"Sin cultivo",src:"hd",m:[]};
  return{st:"Cultivo sin registro en laboratorio",src:"hd",m:[]};}

/* =================== episodios infecciosos (HD y DP) + clasificación IAAS =================== */
const INF_HD=[ITS,"Infección del sitio de salida o túnel","Infección de FAV o injerto","Fiebre / escalofríos"];
const ICL_EST=["Pendiente","Caso IAAS confirmado","No cumple criterio de caso","Descartado"];
const ICL_ATR=["Asociada a la atención en UNO-P","Adquirida en otra institución","Comunitaria","No determinable"];
const ICL_VER="IAAS-CLS-2026.10-v1";
function iclOf(ref){if(!PX.book||!PX.book.icl)return null;const L=PX.book.icl.filter(c=>c.Ref===ref);return L.length?L[L.length-1]:null;}
function epAll(desde){const out=[];
  if(hdOn()){ensureIdx();ST.book.evt.filter(lv).filter(e=>INF_HD.includes(e.Tipo)&&(!desde||e.Fecha>=desde)).forEach(e=>{const p=IDX.pac.get(e.Paciente);const ref="HD:"+e.ID;const k=e.Tipo===ITS?itsConf(e):null;
    out.push({ref,src:"HD",prog:"hd",rec:e,id:e.ID,pid:e.Paciente,pn:p?nombre(p):e.Paciente,fecha:e.Fecha,tipo:e.Tipo,clin:(e.Resuelto==="Sí"?"Resuelto":"Abierto · "+(e.Resuelto||"sin estado")),conf:k,mic:micOfEp(ref),atb:ST.book.atb.filter(lv).filter(a=>a.Evento===e.ID),cls:iclOf(ref)});});}
  if(dpOn())DP.book.epi.filter(lv).filter(e=>!desde||v6d(e.Fecha)>=desde).forEach(e=>{const p=dpPac(e.Paciente);const ref="DP:"+e.ID;const cr=dpCriterios(e);
    out.push({ref,src:"DP",prog:"dp",rec:e,id:e.ID,pid:e.Paciente,pn:p?dpNombre(p):e.Paciente,fecha:v6d(e.Fecha),tipo:e.Tipo,clin:(e.DxClinico||"En estudio")+(e.Desenlace?" · "+e.Desenlace:""),conf:{st:e.DxClinico||"En estudio",cr},mic:micOfEp(ref),atb:DP.book.atb.filter(lv).filter(a=>a.Episodio===e.ID),cls:iclOf(ref)});});
  return out.sort((a,b)=>b.fecha-a.fecha);}
const epCountable=ep=>!ep.cls||!["No cumple criterio de caso","Descartado"].includes(ep.cls.Estado)&&ep.cls.Atribucion!=="Adquirida en otra institución";

/* =================== tratamientos antimicrobianos (prescripción de HD y DP) =================== */
function trtAll(){const out=[];
  if(hdOn())ST.book.atb.filter(lv).forEach(a=>out.push({ref:"HD:"+a.ID,fu:"HD",prog:"hd",rec:a,id:a.ID,pid:a.Paciente,pn:v6pn("hd",a.Paciente),drug:a.Antimicrobiano,dose:a.Dosis,via:a.Via,ind:a.Indicacion,tipo:a.Tipo,ini:v6d(a.Inicio),fin:v6d(a.Fin),dur:num(a.DuracionPrevista),ev:a.Evento?"HD:"+a.Evento:"",presc:a.Prescriptor||"",cultDecl:a.CultivoPrevio||"",ajCult:a.Ajustado||""}));
  if(dpOn())DP.book.atb.filter(lv).forEach(a=>out.push({ref:"DP:"+a.ID,fu:"DP",prog:"dp",rec:a,id:a.ID,pid:a.Paciente,pn:v6pn("dp",a.Paciente),drug:a.Antimicrobiano,dose:a.Dosis,via:a.Via,ind:a.Indicacion,tipo:a.Tipo,ini:v6d(a.Inicio),fin:v6d(a.Fin),dur:num(a.DuracionPrevista),ev:a.Episodio?"DP:"+a.Episodio:"",presc:a.Prescriptor||"",cultDecl:"",ajCult:""}));
  return out.sort((a,b)=>(b.ini||0)-(a.ini||0));}
function trtAudit(t){if(!PX.book)return null;const L=PX.book.prv.filter(r=>r.Fuente===t.fu&&r.Ref===t.id);return L.length?L[L.length-1]:null;}
/* cultivo previo verificado en Laboratorio: toma entre 7 días antes y el día de inicio (no hay horas en ninguno de los dos registros) */
function trtCultivo(t){if(!t.ini)return{st:"sin fecha de inicio"};const M=micOfPac(t.prog,t.pid).filter(m=>{const d=v6d(m.FechaToma);return d&&d<=t.ini&&dayDiff(d,t.ini)<=7&&!["Solicitado","Rechazado"].includes(m.Estado);});
  if(M.length)return{st:"verificado",m:M};if(t.cultDecl==="Sí")return{st:"declarado sin soporte",m:[]};return{st:"sin cultivo registrado",m:[]};}

/* =================== higiene de manos (Seguridad del paciente) =================== */
function hhCfg(){return Object.assign({meses:[3,6,9,12],meta:90,servicios:["hd","dp","vih","qt","ce","lab"]},pxCfg("hh_prog",{})||{});}
function hhRecs(){return PX.book?PX.book.lst.filter(x=>x.Lista==="hm"&&pxNoAnul(x)):[];}
function hhQuarterOf(m){return Math.floor((m-1)/3);} /* 0..3 */
/* medición trimestral: se atribuye al mes programado del trimestre; las observaciones de cualquier mes del trimestre suman */
function hhPeriod(per){const C=hhCfg();const y=+per.slice(0,4),m=+per.slice(5);const q=hhQuarterOf(m);const prog=C.meses.find(x=>hhQuarterOf(x)===q);
  const qs=new Date(y,q*3,1),qe=monthEnd(new Date(y,q*3+2,1));const R=hhRecs().filter(x=>{const d=pdate(x.Fecha);return d&&d>=qs&&d<=qe;});
  const obs=R.reduce((a,x)=>a+(num(x.Aplicables)||0),0),cum=R.reduce((a,x)=>a+(num(x.Cumplidos)||0),0);
  const pm=prog?new Date(y,prog-1,1):null;const st=!prog?"sin":m!==prog?"nprog":obs?"ok":(monthEnd(pm)<TODAY()?"vencida":"plazo");
  return{y,q,prog,pm,qs,qe,R,obs,cum,st};}

/* =================== limpieza y desinfección de hemodiálisis =================== */
const TER_ITEMS=["Retiro de residuos y elementos del área antes de iniciar","Limpieza de arriba hacia abajo y de lo limpio a lo sucio","Paredes, ventanas y puertas","Sillones, camillas y mesas auxiliares (todas sus caras)","Interruptores, tomas, lámparas y superficies de alto contacto","Lavamanos y dispensadores","Pisos con la técnica institucional","Desinfectante a la concentración indicada y tiempo de contacto respetado","Elementos de aseo exclusivos del área, limpios al terminar","Registro de producto, concentración y responsable"];
const LIM_PROC={MAQ_EXT:"Máquina · limpieza y desinfección externa",MAQ_INT:"Máquina · desinfección interna (instrucciones del fabricante)",TERMINAL:"Limpieza terminal de sala"};
function maqList(){const C=hdOn()?ST.book.cfgv.maquinas:null;if(Array.isArray(C)&&C.length)return C;const n=(hdOn()&&ST.book.cfgv.puestos)||13;return Array.from({length:n},(_,i)=>({id:"M"+String(i+1).padStart(2,"0"),serie:"",puesto:i+1,hbs:"NO",activa:"SI",gen:true}));}
function maqOfPuesto(n){return maqList().find(m=>+m.puesto===+n&&m.activa!=="NO")||null;}
function limAll(){return hdOn()&&ST.book.lim?ST.book.lim.filter(lv):[];}
function limTer(){return Object.assign({},CFG_DEF.limTer,(hdOn()&&ST.book.cfgv.limTer)||{});}
/* desinfección del puesto después de cada uso: exigible por cada sesión realizada hasta el corte */
function limRutina(a,b){const lim=b<TODAY()?b:addDays(TODAY(),-1);const S=hdOn()?ST.book.ses.filter(lv).filter(s=>s.Estado==="Realizada"&&s.Fecha>=a&&s.Fecha<=lim):[];const sin=S.filter(s=>s.LimpiezaPuesto!=="SI");return{exig:S.length,ok:S.length-sin.length,sin};}
/* desinfección interna de máquina: exigible por día de uso de la máquina (máquina asignada al puesto en el catálogo) */
function limMaqInt(a,b){const lim=b<TODAY()?b:addDays(TODAY(),-1);const need=new Map();const sinMaq=new Set();
  if(hdOn())ST.book.ses.filter(lv).filter(s=>s.Estado==="Realizada"&&s.Fecha>=a&&s.Fecha<=lim).forEach(s=>{const m=maqOfPuesto(s.Puesto);if(!m){sinMaq.add(String(s.Puesto||"sin puesto"));return;}need.set(iso(s.Fecha)+"|"+m.id,{d:s.Fecha,m:m.id});});
  const done=new Set(limAll().filter(r=>r.Proceso==="MAQ_INT").map(r=>iso(v6d(r.Fecha))+"|"+r.Maquina));
  const L=[...need.values()];const sin=L.filter(x=>!done.has(iso(x.d)+"|"+x.m));return{exig:L.length,ok:L.length-sin.length,sin,sinMaq:[...sinMaq]};}
/* cronograma quincenal de limpieza terminal */
function terSlots(a,b){const C=limTer();const st=pdate(C.inicio);if(!st)return[];const step=+C.cada||15;const out=[];const recs=limAll().filter(r=>r.Proceso==="TERMINAL");
  for(let d=new Date(st),i=0;d<=b&&i<500;d=addDays(st,step*(++i))){if(d<a)continue;const due=addDays(d,+C.tol||0);const ex=recs.find(r=>iso(v6d(r.FechaProgramada))===iso(d));
    let es;if(ex)es=v6d(ex.Fecha)<=due?"En plazo":"Fuera de plazo";else es=TODAY()>due?"Vencida":"Programada";
    out.push({d:new Date(d),due,ex,es,sup:ex?(ex.SupResultado||"Pendiente de supervisión"):""});}
  return out;}
function terResumen(a,b){const S=terSlots(a,b).filter(s=>s.due<=b&&s.due<TODAY()||s.ex&&s.due<=b);const ex=S.filter(s=>s.ex);const enp=S.filter(s=>s.es==="En plazo");const ven=S.filter(s=>s.es==="Vencida");
  const doc=ex.filter(s=>s.ex.Ejecuto&&s.ex.Producto&&s.ex.Actividades&&s.ex.Actividades!=="[]");return{S,exig:S.length,ex:ex.length,enp:enp.length,ven:ven.length,doc:doc.length};}
/* adherencia técnica: auditorías de técnica de desinfección del puesto (lista CDC) + supervisión de limpieza terminal */
function limTecnica(a,b){let cum=0,apl=0,n=0;const src=[];
  if(PX.book)PX.book.lst.filter(x=>x.Lista==="des"&&pxNoAnul(x)).forEach(x=>{const d=pdate(x.Fecha);if(!d||d<a||d>b)return;cum+=num(x.Cumplidos)||0;apl+=num(x.Aplicables)||0;n++;src.push({ref:"LST:"+x.ID,fecha:d,serv:"Hemodiálisis",det:"Auditoría lista CDC "+x.Cumplidos+"/"+x.Aplicables,val:"Registrada"});});
  limAll().filter(r=>r.Proceso==="TERMINAL"&&r.SupItems).forEach(r=>{const d=v6d(r.SupFecha)||v6d(r.Fecha);if(!d||d<a||d>b)return;let it={};try{it=JSON.parse(r.SupItems);}catch(e){}Object.values(it).forEach(v=>{if(v!=="NA"){apl++;if(v==="S")cum++;}});n++;src.push({ref:"HD:"+r.ID,fecha:d,serv:"Hemodiálisis",det:"Supervisión de limpieza terminal · "+(r.SupResultado||""),val:r.SupPor?"Supervisada":"Sin supervisión"});});
  return{cum,apl,n,src};}

/* =================== v0.6 · Hemodiálisis: indicador ITS-CVC con días-catéter del registro de dispositivos =================== */
function v6Its(x,soloConf){const C=cdCalc(x.ps,x.c,x.eps);let ev=0,sus=0;const list=[];
  popPer(x.ps,x.c,x.eps).forEach(p=>p._evt.filter(e=>e.Tipo===ITS&&e.Fecha>=x.ps&&e.Fecha<=x.c).forEach(e=>{const k=itsConf(e);
    if(k.st==="Confirmada"){ev++;list.push(pv(p,fd(e.Fecha)+" · confirmada"+(k.src==="heredado"?" (dato heredado del evento, sin cultivo en Laboratorio)":" por Laboratorio")+(k.org?" · "+k.org:"")));}
    else{if(!soloConf)ev++;else sus++;list.push(pv(p,fd(e.Fecha)+" · "+k.st.toLowerCase()+(soloConf?" (no cuenta)":"")));}}));
  if(!C.complete)return{ev,exp:C.days,val:null,list,nc:true,cd:C,expl:"Indicador no calculable: información de exposición a catéter incompleta ("+C.block.length+" pendiente"+(C.block.length===1?"":"s")+" en Acceso vascular → Registro de dispositivos)."};
  return{ev,exp:C.days,val:C.days?ev/C.days*1000:null,list,cd:C,expl:(C.days?ev+(soloConf?" confirmadas":" episodios")+" / "+C.days.toLocaleString("es-CO")+" días-catéter":"Sin exposición a catéter en el periodo")+(C.pend.length?" · provisional: "+C.pend.length+" catéter"+(C.pend.length===1?"":"es")+" sin validar":"")+(sus?" · "+sus+" sin confirmar":"")+" · método "+C.met.ver};}

/* =================== v0.6 · Acceso vascular: registro de dispositivos =================== */
function dspKind(t){return({"Inserción de catéter tunelizado":"ins","Inserción de catéter temporal":"ins","Recambio de catéter":"rec","Retiro de catéter":"ret","Creación de FAV":"fav","Pérdida de FAV":"perfav"})[t]||"";}
function dspNovFields(k,act){if(!k)return"";
  const sit='<label class="f">Sitio<select id="an_ds">'+opt(DSP_SITIOS,"","—")+'</select></label>',lug='<label class="f">Lugar de inserción<select id="an_dl">'+opt(DSP_LUGAR,DSP_LUGAR[0])+'</select></label>';
  const which=act.length?'<label class="f wide">Catéter que se retira<select id="an_dref">'+opt(act.map(d=>[d.ID,d.ID+" · "+d.Tipo+" · desde "+(d.FechaInsercion?fd(d.FechaInsercion):"fecha desconocida")]),act[act.length-1].ID)+'</select></label>':'<p class="note wide" style="color:var(--warn)">No hay catéter activo en el registro de dispositivos.</p>';
  if(k==="ins")return sit+lug;
  if(k==="rec")return which+'<label class="f">Tipo del nuevo catéter<select id="an_dt">'+opt(["CVC tunelizado","CVC temporal"],act.length?act[act.length-1].Tipo:"CVC tunelizado")+'</select></label>'+sit+lug;
  if(k==="ret")return which+'<label class="f">Motivo del retiro<select id="an_dm">'+opt(DSP_RETIRO,"","—")+'</select></label>';
  if(k==="fav")return'<label class="f">Tipo<select id="an_dt">'+opt(["FAV","Injerto"],"FAV")+'</select></label>'+sit;
  return"";}
function dlgAccNov(pid){const p=IDX.pac.get(pid);const act=dspCVC(pid).filter(dspOpen);
  openDlg("Novedad del acceso · "+pid+" · "+nombre(p),'<div class="form"><label class="f">Novedad<select id="an_t">'+opt(ACC_NOV,"","Seleccione…")+'</select></label><label class="f">Fecha<input type="date" id="an_f" value="'+iso(TODAY())+'"></label><label class="f">Acceso resultante<select id="an_a">'+opt(ACCESOS,"","Sin cambio")+'</select></label><label class="f wide">Detalle<input type="text" id="an_d" placeholder="Hallazgo, conducta, remisión"></label></div><div id="an_dsp" class="form" style="margin-top:6px"></div><p class="note">Acceso actual: '+esc(accessAt(p,ST.corte)||"sin registro")+'. La inserción, el recambio y el retiro de catéter, y la creación o pérdida de una FAV, actualizan en este mismo paso el registro de dispositivos, que es la fuente de los días-catéter. Si la novedad cambia el acceso que se usa en diálisis, elija el acceso resultante.</p>',"Registrar",()=>{
    if(needUser())return"Falta el usuario que registra.";const t=$("an_t").value,f=pdate($("an_f").value);if(!t)return"Elija la novedad.";if(!f)return"Fecha inválida.";if(f>TODAY())return"La fecha no puede ser futura.";
    const k=dspKind(t);const g=id=>{const el=$(id);return el?el.value:"";};
    if((k==="ret"||k==="rec")&&!act.length)return"No hay catéter activo en el registro de dispositivos. Regístrelo primero (Acceso vascular → Registro de dispositivos → Nuevo dispositivo).";
    if(k==="ret"&&!g("an_dm"))return"Indique el motivo del retiro.";
    const dref=(k==="ret"||k==="rec")?(dspFind(g("an_dref"))||act[act.length-1]):null;if(dref&&dref.FechaInsercion&&f<dref.FechaInsercion)return"La fecha es anterior a la inserción del catéter ("+fd(dref.FechaInsercion)+").";
    const res=$("an_a").value||ACC_NOV_RES[t]||"";const n=addRec("acn","AC-",{Paciente:pid,Fecha:f,Tipo:t,Detalle:$("an_d").value.trim(),AccesoResultante:res});
    if(k==="ins")dspAdd({Paciente:pid,Tipo:t==="Inserción de catéter temporal"?"CVC temporal":"CVC tunelizado",Sitio:g("an_ds"),FechaInsercion:f,LugarInsercion:g("an_dl"),Novedad:n.ID});
    if(k==="fav")dspAdd({Paciente:pid,Tipo:g("an_dt")||"FAV",Sitio:g("an_ds"),FechaInsercion:f,LugarInsercion:"UNO-P (sala de procedimientos)",Novedad:n.ID,Nota:"Fecha de creación"});
    if(k==="ret"||k==="rec"){const d=dref;updRec("dsp",d,{FechaRetiro:f,MotivoRetiro:k==="rec"?"Recambio":g("an_dm"),Estado:"Retirado"});
      if(k==="rec")dspAdd({Paciente:pid,Tipo:g("an_dt")||d.Tipo,Sitio:g("an_ds")||d.Sitio,FechaInsercion:f,LugarInsercion:g("an_dl"),Reemplaza:d.ID,Novedad:n.ID});}
    if(k==="perfav"){const d=dspOf(pid).filter(x=>!isCVC(x.Tipo)&&dspOpen(x)).pop();if(d)updRec("dsp",d,{FechaRetiro:f,MotivoRetiro:"Pérdida de FAV o injerto",Estado:"Retirado"});}
    if(res)updRec("pac",p,{AccesoActual:res,AccesoDesde:f});if(t==="Creación de FAV")updRec("pac",p,{RutaAcceso:"FAV creada, en maduración",FechaRuta:f});if(t==="Remisión a cirugía vascular")updRec("pac",p,{RutaAcceso:"Remitido a cirugía vascular",FechaRuta:f});
    reindex();render();toast("Novedad registrada"+(k?" y registro de dispositivos actualizado":"")+".");});
  $("an_t").onchange=()=>{$("an_dsp").innerHTML=dspNovFields(dspKind($("an_t").value),act);};}
function dchip(d){return'<span class="dchip '+(isCVC(d.Tipo)?"cvc":"fav")+(d.Validado!=="SI"?" nv":"")+'" title="'+esc((d.Sitio||"sitio sin dato")+(d.Nota?" · "+d.Nota:""))+'">'+esc(d.ID)+' · '+esc(d.Tipo)+' · '+(d.FechaInsercion?fd(d.FechaInsercion):"<b>sin inserción</b>")+' → '+(d.FechaRetiro?fd(d.FechaRetiro):dspOpen(d)?"activo":"<b>sin fecha de retiro</b>")+(d.Validado!=="SI"?" · sin validar":"")+'</span>';}
function dspPanel(){ensureIdx();const c=ST.corte,a=ST.ps;const C=cdCalc(a,c,ST.eps);const met=C.met;
  const rows=pacs().filter(p=>epsOk(p)&&(overlaps(p,a,c))).map(p=>{const D=dspOf(p.ID);const per=C.per.find(r=>r.p.ID===p.ID);const bl=C.block.filter(b=>b.p.ID===p.ID);const wa=C.warn.filter(b=>b.p.ID===p.ID);return{p,D,per,bl,wa,acc:accessAt(p,c)};})
   .filter(r=>r.D.length||isCVC(r.acc)||r.bl.length).sort((x,y)=>y.bl.length-x.bl.length||(y.D.some(d=>d.Validado!=="SI")?1:0)-(x.D.some(d=>d.Validado!=="SI")?1:0)||String(x.p.ID).localeCompare(y.p.ID));
  const act=dspAll().filter(d=>isCVC(d.Tipo)&&dspOpen(d)).filter(d=>{const p=IDX.pac.get(d.Paciente);return p&&epsOk(p)&&activeAt(p,c);}).length;const nv=dspAll().filter(d=>d.Validado!=="SI").length;
  let h='<div class="panel"><div class="mhead"><div><h3 style="margin:0">Registro de dispositivos · fuente de los días-catéter</h3><p class="note" style="margin:3px 0 0">Lo registra el proceso de acceso vascular (enfermería y nefrología). IAAS-02 y el indicador CAC dia_33 toman de aquí los días de exposición; no hay una segunda matriz en IAAS. Periodo: '+fd(a)+' a '+fd(c)+'.</p></div><div class="copyrow"><button type="button" class="btn sm primary" data-a="v6dspnew">Nuevo dispositivo</button>'+(dspPropuestas().length?'<button type="button" class="btn sm" data-a="v6dsprec">Proponer desde el historial ('+dspPropuestas().length+' pacientes sin registro)</button>':'')+'<button type="button" class="btn sm" data-a="v6dspexp">Exportar</button></div></div>';
  h+='<div class="tiles"><div class="tile"><span class="tv">'+act+'</span><span class="tl">catéteres activos al corte</span></div><div class="tile '+(C.complete?(C.pend.length?"warn":"ok"):"bad")+'"><span class="tv">'+(C.complete?C.days.toLocaleString("es-CO"):"No calculable")+'</span><span class="tl">'+(C.complete?"días-catéter del periodo"+(C.pend.length?" (provisional: "+C.pend.length+" sin validar)":""):"días-catéter: "+C.block.length+" pendiente"+(C.block.length===1?"":"s")+" impiden establecer la exposición")+'</span></div><div class="tile '+(nv?"warn":"ok")+'"><span class="tv">'+nv+'</span><span class="tl">dispositivos sin validar contra la historia clínica</span></div></div>';
  if(C.block.length)h+='<div class="alert warn"><p><strong>Indicador no calculable: información de exposición a catéter incompleta.</strong> '+C.block.slice(0,6).map(b=>esc(b.p.ID)+": "+esc(b.t)).join(" · ")+(C.block.length>6?" · y "+(C.block.length-6)+" más":"")+'</p></div>';
  h+='<div class="tablebox"><table class="dense"><thead><tr><th>Paciente</th><th>Acceso al corte</th><th>Dispositivos</th><th class="num">Días-catéter del periodo</th><th>Pendientes</th><th></th></tr></thead><tbody>'+
   (rows.map(r=>'<tr><td><strong>'+esc(r.p.ID)+'</strong><span class="sub">'+esc(nombre(r.p))+'</span></td><td>'+(r.acc?'<span class="tag '+(isCVC(r.acc)?"cvc":"fav")+'">'+esc(r.acc)+'</span>':'<span class="sd">sin dato</span>')+'</td><td>'+(r.D.map(d=>'<button type="button" class="lnk" data-a="v6dspedit|'+d.ID+'">'+dchip(d)+'</button>').join("")||'<span class="sd">sin dispositivos</span>')+'</td><td class="num mono">'+(r.bl.length?"—":(r.per?r.per.days:0))+'</td><td style="font-size:12.5px">'+(r.bl.map(b=>'<span style="color:var(--bad)">'+esc(b.t)+'</span>').join("<br>")+(r.wa.length?(r.bl.length?"<br>":"")+r.wa.map(w=>'<span style="color:var(--warn)">'+esc(w.t)+'</span>').join("<br>"):"")||'<span class="sd">—</span>')+'</td><td><button type="button" class="btn sm" data-a="v6dspnew|'+r.p.ID+'">Agregar</button></td></tr>').join("")||'<tr><td colspan="6" class="note">Sin pacientes con catéter ni dispositivos en el periodo.</td></tr>')+'</tbody></table></div>';
  h+='<details class="hist" style="margin-top:8px"><summary>Método de conteo vigente: '+esc(met.ver)+' · día de retiro '+(met.retiro==="excluye"?"no cuenta":"cuenta")+' · días hospitalizado '+(met.hosp==="excluye"?"no cuentan":"cuentan")+'</summary><div class="form" style="margin-top:6px"><label class="f">Día de retiro<select id="cd_r">'+opt([["incluye","Cuenta"],["excluye","No cuenta"]],met.retiro)+'</select></label><label class="f">Días hospitalizado fuera de la unidad<select id="cd_h">'+opt([["cuenta","Cuentan"],["excluye","No cuentan"]],met.hosp)+'</select></label><div class="copyrow" style="align-self:end"><button type="button" class="btn sm" data-a="v6cdsave">Guardar como nueva versión del método</button></div></div><p class="note">Se cuentan días calendario con el catéter in situ en los que el paciente está activo en la unidad; nunca días posteriores al retiro ni sesiones como sustituto de días. Las dos opciones son decisiones institucionales pendientes de la Coordinación (la ficha CAC de dia_33 debe cotejarse antes de reportar). Cambiar el método crea una versión nueva; los meses cerrados en IAAS conservan la versión con la que se calcularon.'+(met.por?' Última versión registrada por '+esc(met.por)+' el '+esc(met.fecha)+'.':'')+'</p></details></div>';
  return h;}
function dlgDsp(id,pid){const d=id?dspFind(id):null;const o=d||{Paciente:pid||"",Tipo:"CVC tunelizado",Estado:"Activo",LugarInsercion:DSP_LUGAR[0]};ensureIdx();
  const P=pacs().filter(p=>activeAt(p,ST.corte)||p.ID===o.Paciente||overlaps(p,ST.ps,ST.corte));
  openDlg(d?"Dispositivo "+d.ID:"Nuevo dispositivo de acceso vascular",'<div class="form"><label class="f wide">Paciente<select id="ds_p"'+(d?" disabled":"")+'>'+opt(P.map(p=>[p.ID,p.ID+" · "+nombre(p)]),o.Paciente,"Seleccione…")+'</select></label><label class="f">Tipo<select id="ds_t">'+opt(DSP_TIPOS,o.Tipo)+'</select></label><label class="f">Sitio<select id="ds_s">'+opt(DSP_SITIOS,o.Sitio||"","—")+'</select></label><label class="f">Fecha de inserción o creación<input type="date" id="ds_i" value="'+(o.FechaInsercion?iso(o.FechaInsercion):"")+'"></label><label class="f">Lugar<select id="ds_l">'+opt(DSP_LUGAR,o.LugarInsercion||"")+'</select></label><label class="f">Estado<select id="ds_e">'+opt(["Activo","Retirado"],o.Estado||"Activo")+'</select></label><label class="f">Fecha de retiro<input type="date" id="ds_r" value="'+(o.FechaRetiro?iso(o.FechaRetiro):"")+'"></label><label class="f">Motivo del retiro<select id="ds_m">'+opt(DSP_RETIRO.concat(["Recambio","Pérdida de FAV o injerto"]),o.MotivoRetiro||"","—")+'</select></label><label class="f wide">Nota (soporte en la historia clínica)<input type="text" id="ds_n" value="'+esc(o.Nota||"")+'"></label><label class="chk wide" style="font-size:14px"><input type="checkbox" id="ds_v"'+(o.Validado==="SI"||!d?" checked":"")+'> Confirmo que las fechas corresponden a la historia clínica (dispositivo validado)</label></div>'+(d?'<p class="note">Origen: '+esc(d.Origen||"")+(d.ValidadoPor?' · validado por '+esc(d.ValidadoPor):'')+'. Registró '+esc(d.Usuario||"")+' el '+esc(d.Registrado||"")+'.</p>':'')+'<p class="note">Si no se conoce la fecha exacta de inserción de un catéter que llegó colocado, registre la primera fecha documentada y anótelo: los días antes del ingreso a la unidad no se cuentan.</p>'+(d?'<button type="button" class="lnk" data-a="anul|dsp|'+d.ID+'" style="color:var(--bad)">Anular este registro</button>':''),"Guardar",()=>{
    if(needUser())return"Falta el usuario que registra.";const p=d?d.Paciente:$("ds_p").value;if(!p)return"Elija el paciente.";const i=pdate($("ds_i").value),r=pdate($("ds_r").value);const e=$("ds_e").value;
    if(i&&i>TODAY())return"La inserción no puede ser futura.";if(r&&r>TODAY())return"El retiro no puede ser futuro.";if(i&&r&&r<i)return"El retiro no puede ser anterior a la inserción.";if(e==="Retirado"&&!r)return"Un dispositivo retirado necesita la fecha de retiro.";if(r&&e!=="Retirado")return"Con fecha de retiro, el estado debe ser «Retirado».";
    const v=$("ds_v").checked;const ch={Tipo:$("ds_t").value,Sitio:$("ds_s").value,FechaInsercion:i,LugarInsercion:$("ds_l").value,Estado:e,FechaRetiro:r,MotivoRetiro:r?$("ds_m").value:"",Nota:$("ds_n").value.trim(),Validado:v?"SI":"NO"};
    if(v&&(!d||d.Validado!=="SI")){ch.ValidadoPor=ST.user;ch.ValidadoFecha=TODAY();}
    if(d)updRec("dsp",d,ch);else addRec("dsp","DS-",Object.assign({Paciente:p,Origen:"Registro directo"},ch));reindex();render();toast("Dispositivo guardado.");});}
function dlgDspRec(){const L=dspPropuestas();if(!L.length){toast("Todos los pacientes tienen dispositivos registrados.");return;}const np=new Set(L.map(x=>x.Paciente)).size;
  openDlg("Proponer dispositivos desde el historial",'<p class="note">Se crearán '+L.length+' dispositivos para '+np+' pacientes sin registro, a partir del acceso al ingreso, el acceso de cada sesión, el acceso actual y las novedades del acceso. Quedan <strong>sin validar</strong>: los indicadores que los usan se muestran como «pendiente de validación» hasta que enfermería confirme cada fecha contra la historia clínica. Las fechas son aproximadas (primera y última evidencia).</p><div class="tablebox" style="max-height:260px"><table class="mini"><tbody>'+L.slice(0,80).map(x=>'<tr><td>'+esc(x.Paciente)+'</td><td>'+esc(x.Tipo)+'</td><td class="mono">'+fd(x.FechaInsercion)+' → '+(x.FechaRetiro?fd(x.FechaRetiro):"activo")+'</td></tr>').join("")+'</tbody></table></div>',"Crear propuestas",()=>{if(needUser())return"Falta el usuario que registra.";L.forEach(x=>addRec("dsp","DS-",x));reindex();render();toast(L.length+" dispositivos propuestos. Valídelos uno por uno.");});}
function dspExport(){ensureIdx();const C=cdCalc(ST.ps,ST.corte,ST.eps);exportSheets("Dispositivos_acceso_"+iso(ST.corte)+".xlsx",[["Dispositivos",dspAll().filter(d=>{const p=IDX.pac.get(d.Paciente);return p&&epsOk(p);}),[["ID",d=>d.ID],["Paciente",d=>d.Paciente],["Nombre",d=>nombre(IDX.pac.get(d.Paciente))],["Tipo",d=>d.Tipo],["Sitio",d=>d.Sitio],["Inserción",d=>d.FechaInsercion],["Lugar",d=>d.LugarInsercion],["Retiro",d=>d.FechaRetiro],["Motivo retiro",d=>d.MotivoRetiro],["Estado",d=>d.Estado],["Reemplaza",d=>d.Reemplaza],["Origen",d=>d.Origen],["Validado",d=>d.Validado],["Validó",d=>d.ValidadoPor],["Nota",d=>d.Nota]]],
  ["Exposición del periodo",C.per,[["Paciente",r=>r.p.ID],["Nombre",r=>nombre(r.p)],["Días-catéter",r=>C.block.some(b=>b.p.ID===r.p.ID)?"no calculable":r.days],["Dispositivos usados",r=>r.devs.join(", ")],["Sesiones con catéter",r=>r.ses]]],
  ["Pendientes",C.block.concat(C.warn),[["Paciente",b=>b.p.ID],["Pendiente",b=>b.t],["Cómo se corrige",b=>b.fix||""]]]]);}

/* =================== v0.6 · Hemodiálisis: Infecciones y antimicrobianos (proceso clínico propietario) =================== */
function vInf(){ensureIdx();const c=ST.corte;const desde=addMonths(c,-6);const E=epAll(desde).filter(e=>e.src==="HD"&&(()=>{const p=IDX.pac.get(e.pid);return p&&epsOk(p);})());
  const A=trtAll().filter(t=>t.fu==="HD"&&(!t.fin||t.fin>=addDays(c,-90))&&(()=>{const p=IDX.pac.get(t.pid);return p&&epsOk(p);})());
  let h=head("Infecciones y antimicrobianos","Lo clínico se registra aquí: el evento infeccioso (en el Turno o fuera de sesión), la toma del hemocultivo y la prescripción antimicrobiana. El resultado del cultivo lo registra Laboratorio → Microbiología. IAAS clasifica el episodio y PROA audita el tratamiento leyendo estos mismos registros, sin volver a digitarlos.",'<button type="button" class="btn" data-a="v6infnew">Registrar infección fuera de sesión</button><button type="button" class="btn primary" data-a="atbnew">Prescribir antimicrobiano</button>');
  const its=E.filter(e=>e.tipo===ITS);const sinLab=its.filter(e=>["Cultivo sin registro en laboratorio","Cultivo en proceso"].includes(e.conf.st));
  h+='<div class="tiles"><div class="tile"><span class="tv">'+E.length+'</span><span class="tl">eventos infecciosos en 6 meses</span></div><div class="tile '+(sinLab.length?"warn":"ok")+'"><span class="tv">'+sinLab.length+'</span><span class="tl">sospechas de ITS-CVC con cultivo pendiente o sin registro en Laboratorio</span></div><div class="tile"><span class="tv">'+A.filter(t=>!t.fin).length+'</span><span class="tl">antimicrobianos en curso</span></div></div>';
  h+='<div class="panel"><h3>Eventos infecciosos (últimos 6 meses)</h3><div class="tablebox"><table class="dense"><thead><tr><th>Fecha</th><th>Paciente</th><th>Evento</th><th>Laboratorio</th><th>Antimicrobianos</th><th>Estado clínico</th><th>Clasificación IAAS</th><th></th></tr></thead><tbody>'+
   (E.map(e=>'<tr><td class="mono">'+fd(e.fecha)+'</td><td><strong>'+esc(e.pid)+'</strong><span class="sub">'+esc(e.pn)+'</span></td><td>'+esc(e.tipo)+'<span class="sub">'+esc(e.rec.Severidad||"")+(e.rec.Conducta?" · "+esc(v6clip(e.rec.Conducta,60)):"")+'</span></td><td style="font-size:12.5px">'+v6labTxt(e)+'</td><td style="font-size:12.5px">'+(e.atb.map(a=>esc(a.Antimicrobiano)+(a.Fin?"":" (en curso)")).join("<br>")||'<span class="sd">—</span>')+'</td><td>'+esc(e.clin)+'</td><td>'+v6clsBadge(e.cls)+'</td><td><div class="copyrow"><button type="button" class="btn sm" data-a="atbnew|'+e.pid+'|'+e.id+'">Antimicrobiano</button>'+(e.rec.Resuelto!=="Sí"?'<button type="button" class="btn sm" data-a="evclose|'+e.id+'">Cerrar</button>':'')+'</div></td></tr>').join("")||'<tr><td colspan="8" class="note">Sin eventos infecciosos en el periodo.</td></tr>')+'</tbody></table></div><p class="note">«Dato heredado»: el evento trae un resultado escrito antes de v0.6 y no tiene cultivo en Laboratorio; cuenta, pero conviene transcribir el cultivo para tener la trazabilidad completa.</p></div>';
  h+='<div class="panel"><h3>Prescripciones antimicrobianas (en curso y últimos 90 días)</h3><div class="tablebox"><table class="dense"><thead><tr><th>Paciente</th><th>Antimicrobiano</th><th>Indicación</th><th>Inicio</th><th class="num">Día</th><th>Duración prevista</th><th>Fin</th><th>Prescriptor</th><th>Auditoría PROA</th><th></th></tr></thead><tbody>'+
   (A.map(t=>{const au=trtAudit(t);const dia=t.ini?dayDiff(t.ini,t.fin||TODAY())+1:null;return'<tr><td><strong>'+esc(t.pid)+'</strong><span class="sub">'+esc(t.pn)+'</span></td><td>'+esc(t.drug)+(pxRestr().includes(t.drug)?' <span class="tag bad">restringido</span>':'')+'<span class="sub">'+esc(t.dose||"")+" · "+esc(t.via||"")+'</span></td><td>'+esc(t.ind||"")+'<span class="sub">'+esc(t.tipo||"")+'</span></td><td class="mono">'+fd(t.ini)+'</td><td class="num mono">'+(dia||"—")+'</td><td>'+(t.dur?t.dur+" días":'<span class="sd">sin dato</span>')+'</td><td class="mono">'+(t.fin?fd(t.fin):'<button type="button" class="lnk" data-a="atbend|'+t.id+'">terminar</button>')+'</td><td>'+esc(t.presc||"—")+'</td><td>'+(au?'<span class="st ok">Auditada</span>':'<span class="st warn">Sin auditar</span>')+'</td><td><button type="button" class="lnk" data-a="anul|atb|'+t.id+'">anular</button></td></tr>';}).join("")||'<tr><td colspan="10" class="note">Sin prescripciones en el periodo.</td></tr>')+'</tbody></table></div><p class="note">Validación farmacéutica, dispensación y administración no tienen registro en el SIGC (no hay módulo de farmacia ni registro de administración en el turno). PROA lo muestra como «fuente inexistente»; no se infiere de la prescripción.</p></div>';
  return h;}
function v6labTxt(e){if(e.src==="HD"&&e.tipo===ITS){const k=e.conf;const cls=k.st==="Confirmada"?"ok":k.st==="No confirmada"?"base":"warn";return'<span class="st '+cls+'">'+esc(k.st)+(k.src==="heredado"?" · dato heredado":"")+'</span>'+(k.org?'<span class="sub">'+esc(k.org)+'</span>':'')+(e.mic.length?'<span class="sub">'+e.mic.length+' cultivo'+(e.mic.length>1?"s":"")+' en Laboratorio</span>':'');}
  if(!e.mic.length)return'<span class="sd">sin cultivo registrado</span>';return e.mic.map(m=>esc(m.Muestra)+": "+esc(m.Estado)+(m.Resultado&&m.Resultado!=="Pendiente"?" · "+esc(m.Resultado):"")+(m.Microorganismo?" · "+esc(m.Microorganismo):"")).join("<br>");}
function v6clsBadge(c){if(!c)return'<span class="st warn">Pendiente</span>';const k=c.Estado==="Caso IAAS confirmado"?"bad":c.Estado==="Pendiente"?"warn":"base";return'<span class="st '+k+'">'+esc(c.Estado)+'</span>'+(c.Atribucion?'<span class="sub">'+esc(c.Atribucion)+'</span>':'');}
function dlgInfEvt(){ensureIdx();const act=pacs().filter(p=>activeAt(p,ST.corte));
  openDlg("Infección registrada fuera de sesión",'<div class="form"><label class="f wide">Paciente<select id="ie_p">'+opt(act.map(p=>[p.ID,p.ID+" · "+nombre(p)]),"","Seleccione…")+'</select></label><label class="f">Fecha<input type="date" id="ie_f" value="'+iso(TODAY())+'"></label><label class="f wide">Evento<select id="ie_t">'+opt(INF_HD,ITS)+'</select></label><label class="f">Severidad<select id="ie_s">'+opt(SEV,"Moderada")+'</select></label><label class="f">Hemocultivo<select id="ie_h">'+opt([["Pendiente","Tomado (resultado en Laboratorio)"],["No tomado","No tomado"]],"Pendiente")+'</select></label><label class="f wide">Conducta<input type="text" id="ie_c"></label><label class="chk wide" style="font-size:14px"><input type="checkbox" id="ie_sp"> Reportar también a Seguridad del paciente</label></div><p class="note">Use esta opción solo cuando la infección se detecta fuera de una sesión (consulta, llamada, egreso hospitalario). Si ocurre en la sesión, regístrela en el Turno del día.</p>',"Registrar",()=>{
    if(needUser())return"Falta el usuario que registra.";const p=$("ie_p").value,f=pdate($("ie_f").value),t=$("ie_t").value;if(!p||!f)return"Paciente y fecha son obligatorios.";if(f>TODAY())return"La fecha no puede ser futura.";
    const e=addRec("evt","E-",{Fecha:f,Paciente:p,Sesion:"",Tipo:t,Severidad:$("ie_s").value,Conducta:$("ie_c").value.trim(),Resuelto:"En seguimiento",Hemocultivo:t===ITS?$("ie_h").value:"",FechaCierre:null});
    if($("ie_sp").checked)addRec("seg","SP-",{Fecha:f,Paciente:p,Clasificacion:"Por clasificar",Categoria:"Infección asociada a la atención",Severidad:"",Descripcion:t+(e.Conducta?" · "+e.Conducta:""),AccionInmediata:e.Conducta,Estado:"Abierto",Evento:e.ID});
    reindex();render();toast("Evento registrado. Laboratorio registrará el cultivo y IAAS lo clasificará.");});}
function dlgAtb(pid,evId){ensureIdx();const act=pacs().filter(p=>activeAt(p,ST.corte)||p.ID===pid);const ev=ST.book.evt.filter(lv).filter(e=>INF_HD.includes(e.Tipo)&&(!pid||e.Paciente===pid)).slice(-40).reverse();
  openDlg("Prescripción antimicrobiana · Hemodiálisis",'<div class="form"><label class="f wide">Paciente<select id="ab_p">'+opt(act.map(p=>[p.ID,p.ID+" · "+nombre(p)]),pid||"","Seleccione…")+'</select></label><label class="f">Antimicrobiano<select id="ab_a">'+opt(ATB,"")+'</select></label><label class="f">Dosis<input type="text" id="ab_d" placeholder="p. ej. 1 g pos-HD"></label><label class="f">Vía<select id="ab_v">'+opt(["IV","Oral","Intracatéter (sello)","Tópica"],"IV")+'</select></label><label class="f">Indicación<select id="ab_i">'+opt(ATB_IND,"")+'</select></label><label class="f">Tipo<select id="ab_t">'+opt(["Empírico","Dirigido","Profilaxis"],"Empírico")+'</select></label><label class="f">Inicio<input type="date" id="ab_s" value="'+iso(TODAY())+'"></label><label class="f">Duración prevista (días)<input type="number" id="ab_du" min="1" max="120"></label><label class="f">Fin (si ya terminó)<input type="date" id="ab_f"></label><label class="f">Prescriptor<input type="text" id="ab_pr" value="'+esc(ST.user)+'"></label><label class="f wide">Evento infeccioso relacionado<select id="ab_e">'+opt(ev.map(e=>[e.ID,fd(e.Fecha)+" · "+e.Paciente+" · "+e.Tipo]),evId||"","Ninguno")+'</select></label><label class="f wide">Nota<input type="text" id="ab_n"></label></div><p class="note">El cultivo previo no se declara aquí: PROA lo verifica en Laboratorio → Microbiología. Antimicrobianos restringidos: '+esc(pxRestr().join(", "))+'.</p>',"Guardar",()=>{
    if(needUser())return"Falta el usuario que registra.";const p=$("ab_p").value,s=pdate($("ab_s").value),f=pdate($("ab_f").value),du=num($("ab_du").value);if(!p||!s)return"Paciente y fecha de inicio son obligatorios.";if(s>TODAY())return"El inicio no puede ser futuro.";if(f&&f<s)return"El fin no puede ser antes del inicio.";if(du!=null&&(du<1||du>120))return"Duración prevista entre 1 y 120 días.";
    addRec("atb","AB-",{Paciente:p,Inicio:s,Fin:f,Antimicrobiano:$("ab_a").value,Dosis:$("ab_d").value.trim(),Via:$("ab_v").value,Indicacion:$("ab_i").value,Tipo:$("ab_t").value,CultivoPrevio:"",Ajustado:"Pendiente",DuracionPrevista:du,Prescriptor:$("ab_pr").value.trim(),Evento:$("ab_e").value,Nota:$("ab_n").value.trim()});reindex();render();toast("Prescripción registrada. PROA la verá para auditoría.");});}

/* =================== v0.6 · Hemodiálisis: Limpieza y desinfección =================== */
function limCell(p,r,re){return'<label class="chk" style="font-size:13px" title="Desinfección del puesto después de este uso (procedimiento institucional)"><input type="checkbox" data-t="'+p.ID+'|lim"'+(r.lim==="SI"?" checked":"")+(re?"":" disabled")+'> Sí</label>';}
function vLim(){const mes=ST.ui.limmes||ym(ST.corte);const{ms,me}=v6per(mes);const R=limRutina(ms,me),M=limMaqInt(ms,me),T=terResumen(ms,me),Q=limTecnica(ms,me);const C=limTer();
  let h=head("Limpieza y desinfección","Tres procesos distintos, cada uno con su responsable: desinfección del puesto después de cada uso (operativo de la sala, se marca en el Turno del día), limpieza de máquinas (enfermería) y limpieza terminal de la sala cada 15 días (servicios generales, con supervisión de enfermería). IAAS lee estos registros; no los vuelve a pedir.",'<label class="f" style="max-width:170px">Mes<input type="month" id="limmes" value="'+mes+'"></label><button type="button" class="btn" data-a="v6limexp">Exportar</button>');
  const pc=(a,b)=>b?f1(a/b*100,1)+" %":"—";const cl=(a,b,t)=>!b?"base":a/b>=(t||0.9)?"ok":a/b>=0.7?"warn":"bad";
  h+='<div class="tiles"><div class="tile '+cl(R.ok,R.exig)+'"><span class="tv">'+pc(R.ok,R.exig)+'</span><span class="tl">desinfección del puesto con registro · '+R.ok+' de '+R.exig+' sesiones realizadas (cobertura documental)</span></div>'+
   '<div class="tile '+cl(M.ok,M.exig)+'"><span class="tv">'+pc(M.ok,M.exig)+'</span><span class="tl">desinfección interna de máquinas · '+M.ok+' de '+M.exig+' días-máquina con uso</span></div>'+
   '<div class="tile '+(!pdate(C.inicio)?"base":cl(T.enp,T.exig,1))+'"><span class="tv">'+(!pdate(C.inicio)?"Sin cronograma":pc(T.enp,T.exig))+'</span><span class="tl">'+(!pdate(C.inicio)?"limpieza terminal: configure la fecha de inicio del cronograma quincenal":"limpieza terminal en plazo · "+T.enp+" de "+T.exig+" programadas exigibles"+(T.ven?" · "+T.ven+" vencida"+(T.ven>1?"s":""):""))+'</span></div>'+
   '<div class="tile '+cl(Q.cum,Q.apl)+'"><span class="tv">'+pc(Q.cum,Q.apl)+'</span><span class="tl">adherencia técnica en auditorías · '+Q.n+' auditorías y supervisiones (IAAS-06)</span></div></div>';
  h+='<p class="note">Cobertura documental, cumplimiento del cronograma y adherencia técnica son mediciones distintas y no se suman. La limpieza terminal no reemplaza la desinfección entre pacientes.</p>';
  /* terminal */
  const slots=terSlots(addDays(ms,-31),addDays(me,31));
  h+='<div class="panel"><div class="mhead"><div><h3 style="margin:0">Limpieza terminal de la sala · cada 15 días</h3><p class="note" style="margin:3px 0 0">Ejecuta y registra: servicios generales. Supervisa: enfermería. Denominador: actividades programadas y exigibles del cronograma, nunca las sesiones.</p></div></div>'+
   '<div class="form"><label class="f">Inicio del cronograma<input type="date" id="lt_i" value="'+esc(C.inicio||"")+'"></label><label class="f">Periodicidad<input type="text" value="Cada '+(+C.cada||15)+' días (decisión institucional del piloto)" disabled></label><label class="f">Tolerancia (días)<input type="number" id="lt_t" min="0" max="5" value="'+(+C.tol||0)+'"></label><label class="chk" style="align-self:end;font-size:14px"><input type="checkbox" id="lt_v"'+(C.validado==="SI"?" checked":"")+'> Cronograma validado por enfermería / Coordinación</label><div class="copyrow" style="align-self:end"><button type="button" class="btn sm" data-a="v6ltsave">Guardar cronograma</button></div></div>'+(C.validado==="SI"?'<p class="note">Validado por '+esc(C.por||"")+' el '+esc(C.fecha||"")+'.</p>':'<p class="note" style="color:var(--warn)">Cronograma sin validar: el cumplimiento se muestra, pero queda como pendiente de validación en IAAS.</p>')+
   (slots.length?'<div class="slots">'+slots.map(s=>{const k=s.es==="En plazo"?"ok":s.es==="Fuera de plazo"?"warn":s.es==="Vencida"?"bad":"fut";return'<button type="button" class="slot '+k+'" data-a="'+(s.ex?"v6tersup|"+s.ex.ID:"v6terex|"+iso(s.d))+'" title="'+esc(s.es+(s.ex?" · ejecutada "+fd(v6d(s.ex.Fecha))+" · "+s.sup:""))+'"><b>'+fd(s.d).slice(0,5)+'</b><span>'+esc(s.es)+'</span>'+(s.ex?'<span class="sub">'+esc(s.sup)+'</span>':'')+'</button>';}).join("")+'</div><p class="note">Pulse una fecha sin ejecutar para registrar la ejecución (servicios generales), o una ejecutada para registrar la supervisión (enfermería). Vencida: no se ejecutó dentro de la fecha programada más la tolerancia.</p>':'<p class="note">Sin cronograma: escriba la fecha de inicio y guarde.</p>')+'</div>';
  /* máquinas */
  const MQ=maqList();const recM=limAll().filter(r=>r.Proceso==="MAQ_INT"||r.Proceso==="MAQ_EXT").sort((a,b)=>v6d(b.Fecha)-v6d(a.Fecha));
  h+='<div class="grid2"><div class="panel"><div class="mhead"><h3 style="margin:0">Máquinas de hemodiálisis</h3><button type="button" class="btn sm primary" data-a="v6maq">Registrar limpieza de máquina</button></div><p class="note">Registra enfermería. La desinfección interna sigue las instrucciones del fabricante y se diferencia de la limpieza externa. Exigible: una desinfección interna por día de uso (configuración por defecto; ajústela al manual del equipo).</p>'+
   (MQ.some(m=>m.gen)?'<p class="note" style="color:var(--warn)">Catálogo generado (una máquina por puesto). Cargue el catálogo real: serie y puesto de cada máquina.</p>':'')+
   '<div class="tablebox"><table class="mini"><thead><tr><th>Máquina</th><th>Serie</th><th>Puesto</th><th>HBsAg+</th><th>Activa</th></tr></thead><tbody>'+MQ.map((m,i)=>'<tr><td><input type="text" data-mq="'+i+'|id" value="'+esc(m.id)+'" style="width:70px"></td><td><input type="text" data-mq="'+i+'|serie" value="'+esc(m.serie||"")+'" style="width:110px"></td><td><input type="number" data-mq="'+i+'|puesto" value="'+esc(m.puesto)+'" style="width:60px"></td><td><select data-mq="'+i+'|hbs">'+opt(["NO","SI"],m.hbs||"NO")+'</select></td><td><select data-mq="'+i+'|activa">'+opt(["SI","NO"],m.activa||"SI")+'</select></td></tr>').join("")+'</tbody></table></div><div class="copyrow" style="margin-top:6px"><button type="button" class="btn sm" data-a="v6maqadd">Agregar máquina</button><button type="button" class="btn sm" data-a="v6maqsave">Guardar catálogo</button></div>'+
   (M.sinMaq.length?'<p class="note" style="color:var(--warn)">Puestos con sesiones y sin máquina en el catálogo: '+esc(M.sinMaq.join(", "))+'.</p>':'')+'</div>'+
   '<div class="panel"><h3>Días-máquina sin desinfección interna registrada · '+esc(mes)+' ('+M.sin.length+')</h3>'+(M.sin.length?'<div class="tablebox" style="max-height:240px"><table class="mini"><tbody>'+M.sin.slice(-60).reverse().map(x=>'<tr><td class="mono">'+fd(x.d)+'</td><td>'+esc(x.m)+'</td><td><button type="button" class="lnk" data-a="v6maq|'+x.m+'|'+iso(x.d)+'">registrar</button></td></tr>').join("")+'</tbody></table></div>':'<p class="note">Sin pendientes.</p>')+
   '<h3 style="margin-top:12px">Últimos registros de máquinas</h3>'+(recM.length?'<div class="tablebox" style="max-height:220px"><table class="mini"><tbody>'+recM.slice(0,25).map(r=>'<tr><td class="mono">'+fd(v6d(r.Fecha))+'</td><td>'+esc(r.Maquina)+'</td><td>'+esc(r.Proceso==="MAQ_INT"?"Interna":"Externa")+'<span class="sub">'+esc([r.Producto,r.Concentracion,r.Parametros].filter(Boolean).join(" · "))+'</span></td><td>'+esc(r.Ejecuto||r.Usuario)+'</td></tr>').join("")+'</tbody></table></div>':'<p class="note">Sin registros.</p>')+'</div></div>';
  /* desinfección por sesión */
  const by={};R.sin.forEach(s=>{const k=iso(s.Fecha)+"|"+(s.Turno||"");(by[k]=by[k]||[]).push(s);});
  h+='<div class="grid2"><div class="panel"><h3>Desinfección del puesto sin registro · '+esc(mes)+' ('+R.sin.length+' sesiones)</h3><p class="note">Se marca en el Turno del día, columna «Desinf. puesto», al terminar cada uso. Si se hizo y no se marcó, corríjalo en el turno de esa fecha.</p>'+(R.sin.length?'<div class="tablebox" style="max-height:240px"><table class="mini"><tbody>'+Object.entries(by).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,40).map(([k,L])=>{const[d,t]=k.split("|");return'<tr><td class="mono">'+fd(pdate(d))+'</td><td>'+esc(t)+'</td><td>Puestos '+esc(L.map(s=>s.Puesto||"?").join(", "))+'</td><td><button type="button" class="lnk" data-a="v6goturno|'+d+'|'+esc(t)+'">abrir turno</button></td></tr>';}).join("")+'</tbody></table></div>':'<p class="note">Todas las sesiones realizadas tienen registro.</p>')+'</div>'+
   '<div class="panel"><div class="mhead"><h3 style="margin:0">Auditoría de técnica de desinfección del puesto</h3><button type="button" class="btn sm" data-p="lst|des|hd">Registrar auditoría (lista CDC)</button></div><p class="note">Auditoría periódica de cómo se hace la desinfección (no es el registro de cada uso). Alimenta IAAS-06 junto con la supervisión de la limpieza terminal.</p>'+(Q.src.length?'<div class="tablebox" style="max-height:220px"><table class="mini"><tbody>'+Q.src.slice(-20).reverse().map(s=>'<tr><td class="mono">'+fd(s.fecha)+'</td><td>'+esc(s.det)+'</td></tr>').join("")+'</tbody></table></div>':'<p class="note">Sin auditorías en el mes.</p>')+'</div></div>';
  return h;}
function dlgTerEx(slotIso){const C=limTer();
  openDlg("Limpieza terminal · programada "+fd(pdate(slotIso)),'<div class="form"><label class="f">Fecha de ejecución<input type="date" id="te_f" value="'+iso(TODAY())+'"></label><label class="f">Área<input type="text" id="te_a" value="Sala de hemodiálisis"></label><label class="f">Ejecutó (nombre)<input type="text" id="te_e"></label><label class="f">Cargo<input type="text" id="te_c" value="Servicios generales"></label><label class="f">Producto<input type="text" id="te_p" placeholder="nombre comercial o principio activo"></label><label class="f">Concentración<input type="text" id="te_k" placeholder="p. ej. 5.000 ppm"></label><label class="f">Tiempo de contacto<input type="text" id="te_t" placeholder="p. ej. 10 min"></label></div><p class="note" style="margin:8px 0 4px">Actividades realizadas</p><div class="chkcol">'+TER_ITEMS.map((it,i)=>'<label class="chk"><input type="checkbox" data-tei="'+i+'"> '+esc(it)+'</label>').join("")+'</div><div class="form" style="margin-top:6px"><label class="f wide">Observaciones<input type="text" id="te_o"></label><label class="f wide">Evidencia (formato físico, foto, número de registro)<input type="text" id="te_v"></label></div><p class="note">Lista de actividades propuesta: ajústela al protocolo institucional de limpieza y desinfección. Programada el '+fd(pdate(slotIso))+(+C.tol?" con "+C.tol+" días de tolerancia":"")+'.</p>',"Registrar ejecución",()=>{
    if(needUser())return"Falta el usuario que registra.";const f=pdate($("te_f").value);if(!f||f>TODAY())return"Revise la fecha de ejecución.";const e=$("te_e").value.trim();if(e.length<3)return"Escriba quién ejecutó.";
    const acts=[...document.querySelectorAll("[data-tei]:checked")].map(x=>TER_ITEMS[+x.dataset.tei]);if(!acts.length)return"Marque las actividades realizadas.";
    if(limAll().some(r=>r.Proceso==="TERMINAL"&&iso(v6d(r.FechaProgramada))===slotIso))return"Esa fecha programada ya tiene ejecución registrada.";
    addRec("lim","LI-",{Proceso:"TERMINAL",Fecha:f,FechaProgramada:pdate(slotIso),Area:$("te_a").value.trim(),Ejecuto:e,Cargo:$("te_c").value.trim(),Actividades:JSON.stringify(acts),Producto:$("te_p").value.trim(),Concentracion:$("te_k").value.trim(),TiempoContacto:$("te_t").value.trim(),Observacion:$("te_o").value.trim(),Evidencia:$("te_v").value.trim(),SupResultado:""});render();toast("Limpieza terminal registrada. Queda pendiente la supervisión de enfermería.");});}
function dlgTerSup(id){const r=ST.book.lim.find(x=>x.ID===id);let it={};try{it=JSON.parse(r.SupItems||"{}");}catch(e){}let acts=[];try{acts=JSON.parse(r.Actividades||"[]");}catch(e){}
  openDlg("Supervisión de limpieza terminal · "+fd(v6d(r.Fecha)),'<p class="note">Ejecutó '+esc(r.Ejecuto||"")+' ('+esc(r.Cargo||"")+') · programada '+fd(v6d(r.FechaProgramada))+' · producto '+esc([r.Producto,r.Concentracion,r.TiempoContacto].filter(Boolean).join(" · ")||"sin dato")+' · actividades registradas: '+acts.length+' de '+TER_ITEMS.length+'.</p><div class="pxitems">'+TER_ITEMS.map((x,i)=>'<div class="pxit"><span>'+esc(x)+'</span><div class="seg sm" role="group">'+[["S","Sí"],["N","No"],["NA","N/A"]].map(([v,l])=>'<button type="button" data-lsi="'+i+'|'+v+'" aria-pressed="'+((it[i]||"S")===v)+'">'+l+'</button>').join("")+'</div></div>').join("")+'</div><div class="form" style="margin-top:6px"><label class="f">Resultado<select id="ts_r">'+opt(["Conforme","No conforme"],r.SupResultado||"")+'</select></label><label class="f wide">Observaciones de la supervisión<input type="text" id="ts_o" value="'+esc(r.SupObs||"")+'"></label></div>',"Guardar supervisión",()=>{
    if(needUser())return"Falta el usuario que registra.";const res={};let no=0;TER_ITEMS.forEach((x,i)=>{const b=document.querySelector('[data-lsi^="'+i+'|"][aria-pressed="true"]');const v=b?b.dataset.lsi.split("|")[1]:"S";res[i]=v;if(v==="N")no++;});
    const out=$("ts_r").value||(no?"No conforme":"Conforme");if(out==="Conforme"&&no)return"Hay ítems no cumplidos: el resultado no puede ser «Conforme».";
    updRec("lim",r,{SupItems:JSON.stringify(res),SupResultado:out,SupPor:ST.user,SupFecha:TODAY(),SupObs:$("ts_o").value.trim()});render();toast("Supervisión registrada.");});}
function dlgMaq(mid,diso){const MQ=maqList();
  openDlg("Limpieza o desinfección de máquina",'<div class="form"><label class="f">Máquina<select id="mq_m">'+opt(MQ.filter(m=>m.activa!=="NO").map(m=>[m.id,m.id+(m.serie?" · "+m.serie:"")+" · puesto "+m.puesto+(m.hbs==="SI"?" · HBsAg+":"")]),mid||"")+'</select></label><label class="f">Fecha<input type="date" id="mq_f" value="'+(diso||iso(TODAY()))+'"></label><label class="f">Turno<select id="mq_t">'+opt(["Mañana","Tarde","Noche","Cierre del día"],"Cierre del día")+'</select></label><label class="f wide">Procedimiento<select id="mq_p">'+opt([["MAQ_INT",LIM_PROC.MAQ_INT],["MAQ_EXT",LIM_PROC.MAQ_EXT]],"MAQ_INT")+'</select></label><label class="f">Producto o método<input type="text" id="mq_pr" placeholder="ácido cítrico, hipoclorito, térmico…"></label><label class="f">Concentración<input type="text" id="mq_k"></label><label class="f">Tiempo de contacto<input type="text" id="mq_tc"></label><label class="f wide">Parámetros del equipo (programa, temperatura, ciclo)<input type="text" id="mq_pa"></label><label class="f wide">Observación<input type="text" id="mq_o"></label></div>',"Registrar",()=>{
    if(needUser())return"Falta el usuario que registra.";const f=pdate($("mq_f").value);if(!f||f>TODAY())return"Revise la fecha.";const m=$("mq_m").value,p=$("mq_p").value;
    if(limAll().some(r=>r.Proceso===p&&r.Maquina===m&&iso(v6d(r.Fecha))===iso(f)&&r.Turno===$("mq_t").value))return"Ya existe ese registro para la máquina, fecha y turno.";
    addRec("lim","LI-",{Proceso:p,Fecha:f,Turno:$("mq_t").value,Maquina:m,Area:"Sala de hemodiálisis",Ejecuto:ST.user,Cargo:"Enfermería",Producto:$("mq_pr").value.trim(),Concentracion:$("mq_k").value.trim(),TiempoContacto:$("mq_tc").value.trim(),Parametros:$("mq_pa").value.trim(),Observacion:$("mq_o").value.trim()});render();toast("Registro de máquina guardado.");});}
function limExport(){const mes=ST.ui.limmes||ym(ST.corte);const{ms,me}=v6per(mes);const R=limRutina(ms,me),M=limMaqInt(ms,me);
  exportSheets("Limpieza_HD_"+mes+".xlsx",[["Registros",limAll(),[["ID",r=>r.ID],["Proceso",r=>LIM_PROC[r.Proceso]||r.Proceso],["Fecha",r=>r.Fecha],["Programada",r=>r.FechaProgramada],["Turno",r=>r.Turno],["Máquina",r=>r.Maquina],["Área",r=>r.Area],["Ejecutó",r=>r.Ejecuto],["Cargo",r=>r.Cargo],["Actividades",r=>r.Actividades],["Producto",r=>r.Producto],["Concentración",r=>r.Concentracion],["Tiempo de contacto",r=>r.TiempoContacto],["Parámetros",r=>r.Parametros],["Supervisión",r=>r.SupResultado],["Supervisó",r=>r.SupPor],["Fecha supervisión",r=>r.SupFecha],["Registró",r=>r.Usuario]]],
   ["Puesto sin registro",R.sin,[["Fecha",s=>s.Fecha],["Turno",s=>s.Turno],["Puesto",s=>s.Puesto],["Sesión",s=>s.ID],["Paciente",s=>s.Paciente]]],
   ["Máquina sin interna",M.sin,[["Fecha",x=>x.d],["Máquina",x=>x.m]]],
   ["Cronograma terminal",terSlots(addMonths(ms,-3),addMonths(me,1)),[["Programada",s=>s.d],["Vence",s=>s.due],["Estado",s=>s.es],["Ejecutada",s=>s.ex?v6d(s.ex.Fecha):""],["Ejecutó",s=>s.ex?s.ex.Ejecuto:""],["Supervisión",s=>s.sup]]]]);}

/* =================== v0.6 · calidad del dato de HD: dispositivos y limpieza =================== */
function v6Calidad(add,c){const C=cdCalc(ST.ps,c,"");C.block.forEach(b=>add("Dispositivos",b.p,b.t+". "+(b.fix||""),"bad"));C.warn.forEach(b=>add("Dispositivos",b.p,b.t,"warn"));
  dspAll().filter(d=>d.Validado!=="SI").forEach(d=>add("Dispositivos",IDX.pac.get(d.Paciente)||{ID:d.Paciente},"Dispositivo "+d.ID+" ("+d.Tipo+") sin validar contra la historia clínica","warn"));
  ST.book.evt.filter(lv).filter(e=>e.Tipo===ITS&&e.Hemocultivo==="Positivo").forEach(e=>{const k=itsConf(e);if(k.src==="lab"&&k.st!=="Confirmada")add("Eventos",IDX.pac.get(e.Paciente)||{ID:e.Paciente},"ITS-CVC del "+fd(e.Fecha)+": el evento dice hemocultivo positivo y Laboratorio registra «"+k.st+"». Prevalece Laboratorio; revise.","bad");});}

/* =================== v0.6 · acciones nuevas de Hemodiálisis =================== */
function v6HdAction(a,x,y,z,el){
  switch(a){
   case"v6dspnew":dlgDsp(null,x||"");return true;
   case"v6dspedit":dlgDsp(x);return true;
   case"v6dsprec":dlgDspRec();return true;
   case"v6dspexp":dspExport();return true;
   case"v6cdsave":{if(needUser())return true;const m=cdMet();const r=$("cd_r").value,hh=$("cd_h").value;if(r===m.retiro&&hh===m.hosp){toast("Sin cambios en el método.");return true;}const vn=+(String(m.ver).split("-v").pop())||1;const nv={retiro:r,hosp:hh,ver:"CD-"+ym(TODAY()).replace("-",".")+"-v"+(vn+1),por:ST.user,fecha:iso(TODAY())};ST.book.cfgv.cdMet=nv;logW("MODIFICA","cfg","cdMet","Método de días-catéter "+m.ver+" → "+nv.ver+" (retiro "+r+", hospitalización "+hh+")");changed();render();toast("Método de conteo guardado como "+nv.ver+".");return true;}
   case"v6infnew":dlgInfEvt();return true;
   case"atbnew":dlgAtb(x||"",y||"");return true;
   case"v6limexp":limExport();return true;
   case"v6ltsave":{if(needUser())return true;const i=$("lt_i").value,t=num($("lt_t").value)||0,v=$("lt_v").checked;if(!pdate(i)){toast("Escriba la fecha de inicio del cronograma.");return true;}const C=limTer();const n=Object.assign({},C,{inicio:i,tol:Math.max(0,Math.min(5,t)),validado:v?"SI":"NO"});if(v&&C.validado!=="SI"){n.por=ST.user;n.fecha=iso(TODAY());}if(!v){n.por="";n.fecha="";}ST.book.cfgv.limTer=n;logW("MODIFICA","cfg","limTer",JSON.stringify(n));changed();render();toast("Cronograma de limpieza terminal guardado.");return true;}
   case"v6terex":dlgTerEx(x);return true;
   case"v6tersup":dlgTerSup(x);return true;
   case"v6maq":dlgMaq(x,y);return true;
   case"v6maqadd":{const L=maqList().map(m=>Object.assign({},m));L.forEach(m=>delete m.gen);L.push({id:"M"+String(L.length+1).padStart(2,"0"),serie:"",puesto:"",hbs:"NO",activa:"SI"});ST.book.cfgv.maquinas=L;render();toast("Máquina agregada. Complete los datos y guarde el catálogo.");return true;}
   case"v6maqsave":{if(needUser())return true;const L=maqList().map(m=>Object.assign({},m));document.querySelectorAll("[data-mq]").forEach(e=>{const[i,f]=e.dataset.mq.split("|");if(L[+i])L[+i][f]=f==="puesto"?num(e.value):e.value.trim();});L.forEach(m=>delete m.gen);const ids=L.map(m=>m.id);if(ids.some(x=>!x)||new Set(ids).size!==ids.length){toast("Cada máquina necesita un identificador único.");return true;}ST.book.cfgv.maquinas=L;logW("MODIFICA","cfg","maquinas",L.length+" máquinas");changed();render();toast("Catálogo de máquinas guardado.");return true;}
   case"v6goturno":ST.ui.tdate=x;ST.ui.tturno=y;ST.ui.tdraft=null;ST.view="turno";render();window.scrollTo(0,0);return true;
  }
  return false;}
function v6HdChange(t){if(t.id==="limmes"){ST.ui.limmes=t.value;render();return true;}return false;}

/* =================== v0.6 · DIÁLISIS PERITONEAL (módulo nativo, libro propio) ===================
   Alcance de esta versión: censo con tiempo en DP (tiempo en riesgo), episodios infecciosos propios de la modalidad
   (peritonitis, infección del orificio de salida y del túnel) con criterios ISPD, y prescripción antimicrobiana.
   Es la fuente de IAAS-09 y de los tratamientos DP que sigue PROA. Adecuación, entrenamiento y visitas: fases siguientes. */
const DP={book:null,demo:false,dirty:false,src:"",ui:{}};
const DPS={
 pac:["Pacientes",["ID","TipoDoc","Documento","Nombres","Apellidos","FechaNac","Sexo","EPS","Municipio","Telefono","Modalidad","FechaCateter","FechaInicioDP","FechaFinDP","MotivoFin","Obs","Usuario","Registrado","Anulado","MotivoAnulacion"]],
 epi:["Episodios",["ID","Paciente","Tipo","Fecha","Sintomas","Leucocitos","PMN","PermanenciaH","DxClinico","Clasificacion","EpisodioPrevio","Tratamiento","FechaResolucion","Desenlace","Seguimiento","Usuario","Registrado","Anulado","MotivoAnulacion"]],
 atb:["Antimicrobianos",["ID","Paciente","Episodio","Inicio","Fin","Antimicrobiano","Dosis","Via","Indicacion","Tipo","DuracionPrevista","Prescriptor","Nota","Usuario","Registrado","Anulado","MotivoAnulacion"]],
 log:["Bitacora",["FechaHora","Usuario","Accion","Hoja","Registro","Detalle"]],
 cfg:["Config",["Clave","Valor"]]};
const DPK=Object.keys(DPS);
const DP_DATE=new Set(["FechaNac","FechaCateter","FechaInicioDP","FechaFinDP","Fecha","FechaResolucion","Inicio","Fin"]);
const DP_NUM=new Set(["Leucocitos","PMN","PermanenciaH","DuracionPrevista"]);
const DP_TIPOS=["Peritonitis","Infección del orificio de salida","Infección del túnel"];
const DP_SINT=["Dolor abdominal","Efluente turbio","Fiebre","Náuseas o vómito","Diarrea","Eritema del orificio de salida","Secreción purulenta del orificio de salida","Dolor, eritema o induración del túnel"];
const DP_DX=["En estudio","Confirmada","Descartada"];
const DP_CLS=["Sin clasificar","Primer episodio","Recurrente","Recaída","Repetida","Refractaria","Relacionada con catéter"];
const DP_DES=["En tratamiento","Curación","Recaída posterior","Retiro del catéter","Transferencia temporal a HD","Transferencia definitiva a HD","Muerte relacionada con la infección","Muerte por otra causa"];
const DP_FIN=["Trasplante","Transferencia a hemodiálisis","Fallecimiento","Recuperación de función","Traslado a otra unidad","Abandono","Otro"];
const DP_VIAS=["Intraperitoneal","IV","Oral","Tópica"];
const DP_IND=["Peritonitis","Infección del orificio de salida","Infección del túnel","Profilaxis (implante o procedimiento)","Profilaxis (contaminación por contacto)","Otra"];
function dpOn(){return typeof DP!=="undefined"&&!!DP.book;}
function dpNewBook(){const b={};DPK.forEach(k=>b[k]=[]);return b;}
function dpRow(r){const o={};for(const k in r){let v=r[k];if(DP_DATE.has(k))v=pdate(v);else if(DP_NUM.has(k))v=num(v);else if(v!=null&&typeof v==="string")v=v.trim();o[k]=v;}return o;}
function dpParse(wb){const b=dpNewBook();DPK.forEach(k=>{if(k==="cfg"){const r=readSheet(wb,DPS.cfg[0])||[];b.cfg=r.map(x=>({Clave:x.Clave,Valor:x.Valor}));return;}const rows=readSheet(wb,DPS[k][0])||[];b[k]=rows.map(dpRow).filter(o=>Object.values(o).some(v=>v!=null&&v!==""));});b.pac.forEach(p=>{p.ID=String(p.ID||"").trim();});return b;}
function dpIsBook(wb){return!!wb.SheetNames.find(n=>norm(n)==="EPISODIOS")&&!!wb.SheetNames.find(n=>norm(n)==="PACIENTES")&&!wb.SheetNames.find(n=>norm(n)==="SESIONES");}
function dpBuildWb(){const wb=XLSX.utils.book_new();DPK.forEach(k=>{const[n,cols]=DPS[k];const aoa=[cols].concat(DP.book[k].map(r=>cols.map(c=>{const v=r[c];return v instanceof Date?iso(v):v==null?"":v;})));XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(aoa),n);});return wb;}
function dpNext(k,pre){let mx=0;DP.book[k].forEach(o=>{const m=/(\d+)$/.exec(o.ID||"");if(m)mx=Math.max(mx,+m[1]);});return pre+String(mx+1).padStart(5,"0");}
function dpLog(acc,k,id,det){DP.book.log.push({FechaHora:nowTs(),Usuario:v6who(),Accion:acc,Hoja:DPS[k]?DPS[k][0]:k,Registro:id||"",Detalle:det||""});DP.dirty=true;}
function dpAdd(k,pre,o){const r=Object.assign({ID:dpNext(k,pre)},o,{Usuario:o.Usuario||v6who(),Registrado:o.Registrado||nowTs()});DP.book[k].push(r);dpLog("CREA",k,r.ID,"");return r;}
function dpUpd(k,r,ch){const det=[];for(const f in ch){const a=r[f],b=ch[f];const sa=a instanceof Date?iso(a):(a==null?"":String(a)),sb=b instanceof Date?iso(b):(b==null?"":String(b));if(sa!==sb){det.push(f+": "+sa+" → "+sb);r[f]=b;}}if(det.length)dpLog("MODIFICA",k,r.ID,det.join("; "));return det.length;}
function dpPac(id){return dpOn()?DP.book.pac.find(p=>p.ID===id&&lv(p)):null;}
const dpNombre=p=>p?((p.Nombres||"")+" "+(p.Apellidos||"")).trim()||p.ID:"";
function dpCfg(k,d){if(!DP.book)return d;const r=DP.book.cfg.find(x=>x.Clave===k);if(!r)return d;try{return JSON.parse(r.Valor);}catch(e){return r.Valor;}}
function dpSint(e){try{const a=JSON.parse(e.Sintomas||"[]");return Array.isArray(a)?a:[];}catch(x){return[];}}
/* criterios ISPD 2022 para peritonitis: al menos 2 de (1) dolor abdominal y/o efluente turbio; (2) leucocitos del efluente > 100/µL
   con > 50 % de PMN tras permanencia ≥ 2 h; (3) cultivo del efluente positivo. El cultivo sale de Laboratorio → Microbiología. */
function dpCriterios(e){const s=dpSint(e);const c1=s.includes("Dolor abdominal")||s.includes("Efluente turbio");const lk=num(e.Leucocitos),pm=num(e.PMN),ph=num(e.PermanenciaH);
  const c2=lk!=null&&pm!=null?(lk>100&&pm>50):null;const M=micOfEp("DP:"+e.ID).filter(m=>m.Muestra==="Líquido peritoneal (efluente)");
  const c3=M.some(micPos)?true:(M.length&&M.every(m=>m.Estado==="Final")?false:null);const n=[c1,c2,c3].filter(x=>x===true).length;
  return{c1,c2,c3,n,ph,cumple:n>=2,M,neg:M.length&&M.every(m=>m.Estado==="Final"&&m.Resultado==="Negativo"),nota:ph!=null&&ph<2&&pm!=null&&pm>50?"Permanencia corta: con DPA de ciclos rápidos la ISPD indica valorar el porcentaje de PMN aunque el recuento sea menor de 100/µL.":""};}
/* tasa de peritonitis (ISPD 2022): episodios / tiempo en riesgo. Las recaídas no se cuentan como episodio nuevo. */
function dpPerit(a,b){const R={days:0,block:[],num:[],rel:[],est:[],sinCrit:[],E:[],neg:0};if(!dpOn())return R;
  DP.book.pac.filter(lv).forEach(p=>{const d=dpDias(p,a,b);if(d==null){R.block.push({p,t:"Paciente "+p.ID+" sin fecha de inicio de DP: no se puede establecer su tiempo en riesgo"});return;}R.days+=d;});
  R.E=DP.book.epi.filter(lv).filter(e=>e.Tipo==="Peritonitis"&&v6d(e.Fecha)>=a&&v6d(e.Fecha)<=b);
  R.E.forEach(e=>{if(e.DxClinico==="Confirmada"){if(e.Clasificacion==="Recaída")R.rel.push(e);else R.num.push(e);const c=dpCriterios(e);if(!c.cumple)R.sinCrit.push(e);if(c.neg)R.neg++;}else if(!e.DxClinico||e.DxClinico==="En estudio")R.est.push(e);});
  R.meses=R.days/30.4375;R.anos=R.days/365.25;R.tasa=R.anos?R.num.length/R.anos:null;return R;}
function dpOrificio(a,b){if(!dpOn())return{n:0,anos:0};const E=DP.book.epi.filter(lv).filter(e=>e.Tipo!=="Peritonitis"&&e.DxClinico==="Confirmada"&&v6d(e.Fecha)>=a&&v6d(e.Fecha)<=b);let d=0;DP.book.pac.filter(lv).forEach(p=>{d+=dpDias(p,a,b)||0;});return{n:E.length,anos:d/365.25,tasa:d?E.length/(d/365.25):null};}

/* ---------- vistas ---------- */
function dpCritTxt(e){if(e.Tipo!=="Peritonitis")return'<span class="sd">no aplica</span>';const c=dpCriterios(e);const t=(v,l)=>'<span class="dchip '+(v===true?"fav":v===false?"":"nv")+'">'+l+(v===true?" ✓":v===false?" ✕":" ?")+'</span>';return t(c.c1,"clínico")+t(c.c2,"efluente")+t(c.c3,"cultivo")+'<span class="sub">'+c.n+' de 3'+(c.cumple?" · cumple ISPD":"")+'</span>';}
function dpEpis(){const f=PX.ui.dpf||"abiertos";const E=DP.book.epi.filter(lv).filter(e=>f==="todos"||e.DxClinico!=="Descartada"&&(!e.Desenlace||e.Desenlace==="En tratamiento"||!e.DxClinico||e.DxClinico==="En estudio")).sort((a,b)=>v6d(b.Fecha)-v6d(a.Fecha));
  let h='<div class="panel"><div class="mhead"><div class="seg" role="group">'+[["abiertos","En estudio o en tratamiento"],["todos","Todos"]].map(([k,l])=>'<button type="button" data-p="dpf|'+k+'" aria-pressed="'+(f===k)+'">'+l+'</button>').join("")+'</div><button type="button" class="btn sm primary" data-p="dpepi">Nuevo episodio</button></div>';
  h+='<div class="tablebox"><table class="dense"><thead><tr><th>Fecha</th><th>Paciente</th><th>Episodio</th><th>Criterios ISPD</th><th>Laboratorio</th><th>Diagnóstico y clasificación</th><th>Antimicrobianos</th><th>Desenlace</th><th>IAAS</th><th></th></tr></thead><tbody>'+
   (E.map(e=>{const p=dpPac(e.Paciente);const A=DP.book.atb.filter(lv).filter(a=>a.Episodio===e.ID);const M=micOfEp("DP:"+e.ID);return'<tr><td class="mono">'+fd(v6d(e.Fecha))+'</td><td><strong>'+esc(e.Paciente)+'</strong><span class="sub">'+esc(dpNombre(p))+'</span></td><td>'+esc(e.Tipo)+'<span class="sub">'+esc(dpSint(e).join(", "))+'</span></td><td>'+dpCritTxt(e)+'</td><td style="font-size:12.5px">'+(M.map(m=>esc(m.Muestra.replace(" (efluente)",""))+": "+esc(m.Estado)+(m.Resultado&&m.Resultado!=="Pendiente"?" · "+esc(m.Resultado):"")+(m.Microorganismo?" · "+esc(m.Microorganismo):"")).join("<br>")||'<span class="sd">sin cultivo registrado</span>')+'</td><td>'+esc(e.DxClinico||"En estudio")+'<span class="sub">'+esc(e.Clasificacion||"Sin clasificar")+'</span></td><td style="font-size:12.5px">'+(A.map(a=>esc(a.Antimicrobiano)+" "+esc(a.Via||"")+(a.Fin?"":" (en curso)")).join("<br>")||'<span class="sd">—</span>')+'</td><td>'+esc(e.Desenlace||"En tratamiento")+(e.FechaResolucion?'<span class="sub">'+fd(v6d(e.FechaResolucion))+'</span>':'')+'</td><td>'+v6clsBadge(iclOf("DP:"+e.ID))+'</td><td><div class="copyrow"><button type="button" class="btn sm" data-p="dpepi|'+e.ID+'">Editar</button><button type="button" class="btn sm" data-p="dpatb|||'+e.ID+'">Antimicrobiano</button></div></td></tr>';}).join("")||'<tr><td colspan="10" class="note">Sin episodios.</td></tr>')+'</tbody></table></div><p class="note">El diagnóstico clínico lo confirma el médico de DP; la clasificación epidemiológica (caso IAAS y atribución) la hace IAAS sobre este mismo episodio, sin crear otro caso.</p></div>';
  return h;}
function dpAtbs(){const A=DP.book.atb.filter(lv).sort((a,b)=>v6d(b.Inicio)-v6d(a.Inicio));
  return'<div class="panel"><div class="mhead"><h3 style="margin:0">Prescripciones antimicrobianas de DP</h3><button type="button" class="btn sm primary" data-p="dpatb">Prescribir antimicrobiano</button></div><div class="tablebox"><table class="dense"><thead><tr><th>Paciente</th><th>Antimicrobiano</th><th>Indicación</th><th>Inicio</th><th>Duración prevista</th><th>Fin</th><th>Episodio</th><th>Auditoría PROA</th><th></th></tr></thead><tbody>'+
   (A.map(a=>{const t={fu:"DP",id:a.ID};const au=trtAudit(t);return'<tr><td><strong>'+esc(a.Paciente)+'</strong><span class="sub">'+esc(dpNombre(dpPac(a.Paciente)))+'</span></td><td>'+esc(a.Antimicrobiano)+(pxRestr().includes(a.Antimicrobiano)?' <span class="tag bad">restringido</span>':'')+'<span class="sub">'+esc(a.Dosis||"")+" · "+esc(a.Via||"")+'</span></td><td>'+esc(a.Indicacion||"")+'<span class="sub">'+esc(a.Tipo||"")+'</span></td><td class="mono">'+fd(v6d(a.Inicio))+'</td><td>'+(a.DuracionPrevista?a.DuracionPrevista+" días":'<span class="sd">sin dato</span>')+'</td><td class="mono">'+(a.Fin?fd(v6d(a.Fin)):"en curso")+'</td><td>'+esc(a.Episodio||"—")+'</td><td>'+(au?'<span class="st ok">Auditada</span>':'<span class="st warn">Sin auditar</span>')+'</td><td><button type="button" class="btn sm" data-p="dpatb|'+a.ID+'">Editar</button></td></tr>';}).join("")||'<tr><td colspan="9" class="note">Sin prescripciones.</td></tr>')+'</tbody></table></div><p class="note">Validación farmacéutica, dispensación y administración no tienen registro estructurado en el SIGC.</p></div>';}
function dpRef(){return'<div class="panel"><h3>Definiciones usadas (ISPD)</h3><ul class="v6list"><li><strong>Peritonitis</strong>: al menos 2 de 3 — (1) dolor abdominal y/o efluente turbio; (2) leucocitos del efluente &gt; 100/µL con &gt; 50 % de polimorfonucleares tras una permanencia de al menos 2 horas; (3) cultivo del efluente positivo.</li><li><strong>Recurrente</strong>: dentro de las 4 semanas siguientes al fin del tratamiento de un episodio previo, con otro microorganismo.</li><li><strong>Recaída</strong>: dentro de las 4 semanas siguientes al fin del tratamiento de un episodio previo, con el mismo microorganismo o con cultivo estéril. No se cuenta como episodio nuevo en la tasa.</li><li><strong>Repetida</strong>: más de 4 semanas después del fin del tratamiento de un episodio previo, con el mismo microorganismo.</li><li><strong>Refractaria</strong>: el efluente no se aclara tras 5 días de antibiótico apropiado.</li><li><strong>Relacionada con catéter</strong>: peritonitis junto con infección del orificio de salida o del túnel por el mismo microorganismo.</li><li><strong>Tasa de peritonitis</strong>: episodios / años en riesgo en DP. Referencia ISPD 2022: no más de 0,40 episodios por año en riesgo.</li><li><strong>Infección del orificio de salida</strong>: secreción purulenta, con o sin eritema de la piel en la interfase catéter-epidermis. <strong>Infección del túnel</strong>: signos inflamatorios o colección a lo largo del túnel subcutáneo (clínica o ecográfica).</li></ul><p class="note">Fuentes: Li PKT, Chow KM, Cho Y, et al. ISPD peritonitis guideline recommendations: 2022 update on prevention and treatment. Perit Dial Int. 2022;42(2):110-153. Chow KM, Li PKT, Cho Y, et al. ISPD catheter-related infection recommendations: 2023 update. Perit Dial Int. 2023;43(3):201-219. La guía institucional GAG-GU-003 (peritonitis) figura «por confirmar» en el listado maestro: si difiere, prevalece la aprobada por el Comité.</p></div>';}

/* ---------- diálogos ---------- */
function dpDlgEpi(id,pid){const e=id?DP.book.epi.find(x=>x.ID===id):null;const o=e||{Paciente:pid||"",Tipo:"Peritonitis",Fecha:TODAY(),DxClinico:"En estudio",Clasificacion:"Sin clasificar",Desenlace:"En tratamiento"};const s=e?dpSint(e):[];const P=DP.book.pac.filter(lv);
  const prev=DP.book.epi.filter(lv).filter(x=>x.Paciente===o.Paciente&&(!e||x.ID!==e.ID));const c=e?dpCriterios(e):null;
  openDlg(e?"Episodio "+e.ID:"Nuevo episodio infeccioso de DP",'<div class="form"><label class="f wide">Paciente<select id="ep_p"'+(e?" disabled":"")+'>'+opt(P.map(p=>[p.ID,p.ID+" · "+dpNombre(p)]),o.Paciente,"Seleccione…")+'</select></label><label class="f">Tipo<select id="ep_t">'+opt(DP_TIPOS,o.Tipo)+'</select></label><label class="f">Fecha de presentación<input type="date" id="ep_f" value="'+iso(v6d(o.Fecha))+'"></label></div><p class="note" style="margin:8px 0 4px">Síntomas y signos</p><div class="chkcol">'+DP_SINT.map((x,i)=>'<label class="chk"><input type="checkbox" data-eps="'+i+'"'+(s.includes(x)?" checked":"")+'> '+esc(x)+'</label>').join("")+'</div>'+
   '<div class="form" style="margin-top:6px"><label class="f">Leucocitos del efluente (/µL)<input type="number" id="ep_l" min="0" value="'+esc(o.Leucocitos??"")+'"></label><label class="f">PMN (%)<input type="number" id="ep_pm" min="0" max="100" value="'+esc(o.PMN??"")+'"></label><label class="f">Permanencia (horas)<input type="number" id="ep_ph" min="0" step="0.5" value="'+esc(o.PermanenciaH??"")+'"></label><label class="f">Diagnóstico clínico<select id="ep_dx">'+opt(DP_DX,o.DxClinico)+'</select></label><label class="f">Clasificación (ISPD)<select id="ep_c">'+opt(DP_CLS,o.Clasificacion)+'</select></label><label class="f">Episodio previo relacionado<select id="ep_pr">'+opt(prev.map(x=>[x.ID,x.ID+" · "+fd(v6d(x.Fecha))+" · "+x.Tipo]),o.EpisodioPrevio||"","Ninguno")+'</select></label><label class="f wide">Tratamiento (resumen; los antimicrobianos se prescriben aparte)<input type="text" id="ep_tx" value="'+esc(o.Tratamiento||"")+'"></label><label class="f">Desenlace<select id="ep_d">'+opt(DP_DES,o.Desenlace||"En tratamiento")+'</select></label><label class="f">Fecha de resolución<input type="date" id="ep_fr" value="'+(o.FechaResolucion?iso(v6d(o.FechaResolucion)):"")+'"></label><label class="f wide">Seguimiento<input type="text" id="ep_sg" value="'+esc(o.Seguimiento||"")+'"></label></div>'+
   (c?'<p class="note">Criterios ISPD con los datos guardados: '+c.n+' de 3 (clínico '+(c.c1?"sí":"no")+', efluente '+(c.c2===null?"sin dato":c.c2?"sí":"no")+', cultivo '+(c.c3===null?"sin resultado final":c.c3?"positivo":"negativo")+'). '+esc(c.nota)+'</p>':'')+'<p class="note">El cultivo del efluente o del orificio lo registra Laboratorio → Microbiología vinculado a este episodio. La recaída no se cuenta como episodio nuevo en la tasa (ISPD 2022).</p>',"Guardar",()=>{
    const p=e?e.Paciente:$("ep_p").value;const f=pdate($("ep_f").value);if(!p||!f)return"Paciente y fecha son obligatorios.";if(f>TODAY())return"La fecha no puede ser futura.";const pp=dpPac(p);if(pp&&v6d(pp.FechaInicioDP)&&f<v6d(pp.FechaInicioDP))return"La fecha es anterior al inicio de DP del paciente.";
    const ss=[...document.querySelectorAll("[data-eps]:checked")].map(x=>DP_SINT[+x.dataset.eps]);const ch={Tipo:$("ep_t").value,Fecha:f,Sintomas:JSON.stringify(ss),Leucocitos:num($("ep_l").value),PMN:num($("ep_pm").value),PermanenciaH:num($("ep_ph").value),DxClinico:$("ep_dx").value,Clasificacion:$("ep_c").value,EpisodioPrevio:$("ep_pr").value,Tratamiento:$("ep_tx").value.trim(),Desenlace:$("ep_d").value,FechaResolucion:pdate($("ep_fr").value),Seguimiento:$("ep_sg").value.trim()};
    if(ch.PMN!=null&&(ch.PMN<0||ch.PMN>100))return"PMN entre 0 y 100 %.";if(ch.FechaResolucion&&ch.FechaResolucion<f)return"La resolución no puede ser antes de la presentación.";if(["Recurrente","Recaída","Repetida"].includes(ch.Clasificacion)&&!ch.EpisodioPrevio)return"Recurrente, recaída y repetida requieren el episodio previo relacionado.";
    if(e)dpUpd("epi",e,ch);else dpAdd("epi","EP-",Object.assign({Paciente:p},ch));pxRefresh();toast("Episodio guardado."+(ch.DxClinico==="Confirmada"&&ch.Tipo==="Peritonitis"&&!dpCriterios(Object.assign({ID:e?e.ID:"__"},ch)).cumple?" Atención: confirmada sin 2 criterios ISPD documentados.":""));});}
function dpDlgAtb(id,pid,epId){const a=id?DP.book.atb.find(x=>x.ID===id):null;const o=a||{Paciente:pid||(epId?(DP.book.epi.find(x=>x.ID===epId)||{}).Paciente:""),Episodio:epId||"",Via:"Intraperitoneal",Tipo:"Empírico",Inicio:TODAY()};const P=DP.book.pac.filter(lv);
  const E=DP.book.epi.filter(lv).filter(x=>!o.Paciente||x.Paciente===o.Paciente);
  openDlg(a?"Prescripción "+a.ID:"Prescripción antimicrobiana · DP",'<div class="form"><label class="f wide">Paciente<select id="da_p"'+(a?" disabled":"")+'>'+opt(P.map(p=>[p.ID,p.ID+" · "+dpNombre(p)]),o.Paciente,"Seleccione…")+'</select></label><label class="f wide">Episodio<select id="da_e">'+opt(E.map(x=>[x.ID,x.ID+" · "+x.Paciente+" · "+fd(v6d(x.Fecha))+" · "+x.Tipo]),o.Episodio||"","Ninguno (profilaxis u otra)")+'</select></label><label class="f">Antimicrobiano<input type="text" id="da_a" list="da_al" value="'+esc(o.Antimicrobiano||"")+'"><datalist id="da_al">'+ATB.concat(["Ceftriaxona","Mupirocina tópica","Gentamicina tópica"]).map(x=>'<option value="'+esc(x)+'">').join("")+'</datalist></label><label class="f">Dosis<input type="text" id="da_d" value="'+esc(o.Dosis||"")+'"></label><label class="f">Vía<select id="da_v">'+opt(DP_VIAS,o.Via)+'</select></label><label class="f">Indicación<select id="da_i">'+opt(DP_IND,o.Indicacion||"")+'</select></label><label class="f">Tipo<select id="da_t">'+opt(["Empírico","Dirigido","Profilaxis"],o.Tipo)+'</select></label><label class="f">Inicio<input type="date" id="da_s" value="'+iso(v6d(o.Inicio))+'"></label><label class="f">Duración prevista (días)<input type="number" id="da_du" min="1" max="120" value="'+esc(o.DuracionPrevista??"")+'"></label><label class="f">Fin<input type="date" id="da_f" value="'+(o.Fin?iso(v6d(o.Fin)):"")+'"></label><label class="f">Prescriptor<input type="text" id="da_pr" value="'+esc(o.Prescriptor||v6who())+'"></label><label class="f wide">Nota<input type="text" id="da_n" value="'+esc(o.Nota||"")+'"></label></div>',"Guardar",()=>{
    const p=a?a.Paciente:$("da_p").value,s=pdate($("da_s").value),f=pdate($("da_f").value),du=num($("da_du").value);const am=$("da_a").value.trim();if(!p||!s||!am)return"Paciente, antimicrobiano e inicio son obligatorios.";if(s>TODAY())return"El inicio no puede ser futuro.";if(f&&f<s)return"El fin no puede ser antes del inicio.";
    const ep=$("da_e").value;if(ep){const x=DP.book.epi.find(y=>y.ID===ep);if(x&&x.Paciente!==p)return"El episodio es de otro paciente.";}
    const ch={Episodio:ep,Antimicrobiano:am,Dosis:$("da_d").value.trim(),Via:$("da_v").value,Indicacion:$("da_i").value,Tipo:$("da_t").value,Inicio:s,DuracionPrevista:du,Fin:f,Prescriptor:$("da_pr").value.trim(),Nota:$("da_n").value.trim()};
    if(a)dpUpd("atb",a,ch);else dpAdd("atb","DA-",Object.assign({Paciente:p},ch));pxRefresh();toast("Prescripción guardada.");});}


