function dpEnsure(){if(!DP.book)return;DPK.forEach(k=>{if(!Array.isArray(DP.book[k]))DP.book[k]=[];});}

/* ---------- utilidades ---------- */
const dpR=k=>DP.book&&DP.book[k]?DP.book[k].filter(lv):[];
const dpJ=(s,def)=>{if(s==null||s==="")return def;if(typeof s==="object")return s;try{const v=JSON.parse(s);return v==null?def:v;}catch(e){return def;}};
const dpTxt=v=>v instanceof Date?fd(v):v==null?"":String(v);
const dpDocKey=(td,doc)=>(td?norm(td):"ND")+"-"+String(doc||"").replace(/\D/g,"");
const dpEdad=(p,d)=>{const n=v6d(p&&p.FechaNac);if(!n)return null;d=d||TODAY();let a=d.getFullYear()-n.getFullYear();if(d.getMonth()<n.getMonth()||(d.getMonth()===n.getMonth()&&d.getDate()<n.getDate()))a--;return a;};
const dpMesTxt=m=>{const[a,b]=String(m).split("-");return["enero","febrero","marzo","abril","mayo","junio","julio","agosto","septiembre","octubre","noviembre","diciembre"][+b-1]+" "+a;};
const dpNum=(v,n)=>v==null||v===""||isNaN(v)?"—":f1(Number(v),n==null?1:n);
function dpNextId(k,pre){return dpNext(k,pre);}
function dpCfgSet(k,v){const s=JSON.stringify(v);let r=DP.book.cfg.find(x=>x.Clave===k);if(r){if(r.Valor!==s){dpLog("MODIFICA","cfg",k,"→ "+s.slice(0,180));r.Valor=s;}}else{DP.book.cfg.push({Clave:k,Valor:s});dpLog("CREA","cfg",k,s.slice(0,180));}DP.dirty=true;}

/* ---------- roles y permisos del módulo (hoja RolesDP) ---------- */
const DP_ROLES={dir:"Dirección Médica",coord:"Coordinación de Unidad Renal",nefro:"Nefrología",med:"Médico autorizado",enf:"Enfermería profesional",aux:"Auxiliar de enfermería",multi:"Nutrición, psicología o trabajo social",lab:"Laboratorio",adm:"Administrativo y logística",cons:"Solo consulta o auditoría"};
/* acciones: pac (registro maestro y transiciones), val (valoración), valfin (finalizar/corregir valoración), pre (prescripción DP),
   lab (registrar resultado), labval (revisar/validar resultado y Kt/V), age (agenda), seg (catéter, educación, hospitalización, trasplante, CVRS, episodios),
   ins (insumos y entregas), imp (importar), apr (aprobar plan de laboratorio, verificar heredados, aprobar corte CAC), exp (exportar), cfg (roles y parámetros) */
const DP_ACC={pac:"registrar o modificar datos del paciente",val:"registrar valoraciones",valfin:"finalizar o corregir valoraciones",pre:"prescribir diálisis peritoneal",lab:"registrar resultados de laboratorio",labval:"revisar y validar resultados",age:"gestionar la agenda",seg:"registrar eventos de tratamiento y seguridad",ins:"gestionar insumos y entregas",imp:"importar archivos",apr:"aprobar o verificar",exp:"exportar información",cfg:"administrar roles y parámetros"};
const DP_PERM={dir:"*",coord:"pac val valfin lab labval age seg ins imp apr exp cfg",nefro:"pac val valfin pre lab labval age seg exp",med:"val valfin lab age seg exp",enf:"pac val valfin lab age seg ins exp",aux:"age ins lab",multi:"val valfin age",lab:"lab",adm:"pac age ins exp",cons:"exp"};
function dpRole(){if(!PX.user)return null;if(pxAdmin())return"dir";const r=DP.book&&DP.book.rol?DP.book.rol.find(x=>String(x.Usuario).toLowerCase()===String(PX.user.Usuario).toLowerCase()&&x.Activo!=="NO"):null;return r&&DP_ROLES[r.Rol]?r.Rol:"cons";}
function dpCan(a){const r=dpRole();if(!r)return false;const P=DP_PERM[r];return P==="*"||P.split(" ").includes(a);}
function dpGuard(a){if(dpCan(a))return true;toast("Su rol en Diálisis peritoneal ("+DP_ROLES[dpRole()]+") no permite "+DP_ACC[a]+". Lo asigna Dirección Médica o Coordinación en Reportes → Roles.");return false;}
const dpWho=()=>v6who()+(PX.user?" ["+(DP_ROLES[dpRole()]||"")+"]":"");

/* ---------- bitácora encadenada: detecta alteraciones hechas por fuera del sistema ---------- */
async function dpSha(s){try{if(typeof crypto!=="undefined"&&crypto.subtle){const b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(s));return Array.from(new Uint8Array(b)).map(x=>x.toString(16).padStart(2,"0")).join("");}}catch(e){}let h=2166136261>>>0;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)>>>0;}return h.toString(16).padStart(8,"0").repeat(8);}
const dpLogStr=r=>[r.FechaHora,r.Usuario,r.Accion,r.Hoja,r.Registro,r.Detalle].map(x=>x==null?"":String(x)).join("|");
async function dpChain(){if(!DP.book)return;let prev="";for(const r of DP.book.log){if(!r.Hash)r.Hash=await dpSha(prev+"|"+dpLogStr(r));prev=r.Hash;}}
async function dpVerifyChain(){if(!DP.book)return null;let prev="";let i=0;for(const r of DP.book.log){i++;if(!r.Hash){prev="";continue;}const h=await dpSha(prev+"|"+dpLogStr(r));if(h!==r.Hash)return{ok:false,fila:i,reg:r};prev=r.Hash;}return{ok:true,n:i};}

/* ---------- registro maestro: estados del programa, intervalos en DP, índice institucional ---------- */
const DP_ESTADOS=["Candidato","Preparación","Activo","Reentrenamiento","Suspendido temporal","Transición a HD","Egreso"];
const DP_EN=["Activo","Reentrenamiento","Suspendido temporal"];
const DP_ETIO=CAC_ETIO;const DP_COMORB=["HTA","Diabetes mellitus","Cardiopatía","EPOC o enfermedad respiratoria crónica","Enfermedad hepática","VIH","Hepatitis B","Hepatitis C","Neoplasia activa","Otra"];
function dpEstado(p){return p&&p.EstadoPrograma?p.EstadoPrograma:(p&&v6d(p.FechaInicioDP)?(v6d(p.FechaFinDP)&&v6d(p.FechaFinDP)<TODAY()?"Egreso":"Activo"):"Activo");}
/* intervalos en DP: inicio de DP → fin, partidos por las transiciones registradas (salida a HD o egreso, y reingresos) */
function dpIntervals(p){const s=v6d(p.FechaInicioDP);if(!s)return null;const T=dpR("est").filter(t=>t.Paciente===p.ID&&v6d(t.Fecha)).sort((a,b)=>v6d(a.Fecha)-v6d(b.Fecha));
  const out=[];let cur=s;T.forEach(t=>{const d=v6d(t.Fecha);if(d<s)return;const sale=["Transición a HD","Egreso"].includes(t.EstadoNuevo);const entra=DP_EN.includes(t.EstadoNuevo);
    if(sale&&cur){out.push([cur,addDays(d,-1)]);cur=null;}else if(entra&&!cur)cur=d;});
  const fin=v6d(p.FechaFinDP);if(cur){out.push([cur,fin&&fin>=cur?fin:null]);}return out;}
function dpDias(p,a,b){const I=dpIntervals(p);if(!I)return null;let n=0;I.forEach(([x,y])=>{const s=x>a?x:a,e=y&&y<b?y:b;if(e>=s)n+=dayDiff(s,e)+1;});return n;}
function dpEnDP(p,d){const I=dpIntervals(p);if(!I){/* sin fecha de inicio: solo se puede afirmar el estado actual */return d>=addDays(TODAY(),-1)&&DP_EN.includes(dpEstado(p));}return I.some(([x,y])=>x<=d&&(!y||y>=d));}
const dpActivo=(p,d)=>dpEnDP(p,d||TODAY());
/* tiempo acumulado en diálisis (cualquier modalidad, Res. 2463/2014 citada en el consenso): desde el inicio de TRR si se conoce, si no desde el inicio de DP */
function dpDiasDialisis(p,d){const s=v6d(p.FechaInicioTRR)||v6d(p.FechaInicioDP);return s?dayDiff(s,d)+1:null;}
/* índice maestro calculado: el mismo documento en los libros abiertos de HD, CE, VIH y DP */
function dpMPI(p){const out=[];if(!p||!p.Documento)return out;const doc=String(p.Documento).replace(/\D/g,"");const eq=x=>String(x||"").replace(/\D/g,"")===doc;
  try{if(hdOn()){const h=ST.book.pac.find(x=>eq(x.Documento));if(h)out.push({prog:"hd",n:"Hemodiálisis",id:h.ID,det:(activeAt(h,TODAY())?"activo":"no activo hoy")+(h.TipoDoc&&p.TipoDoc&&h.TipoDoc!==p.TipoDoc?" · tipo de documento distinto ("+h.TipoDoc+")":""),rec:h});}}catch(e){}
  try{if(typeof CE!=="undefined"&&CE.book){const c=CE.book.pac.find(x=>eq(x.Documento));if(c){const ci=CE.book.cit.filter(x=>x.Paciente===c.ID);out.push({prog:"ce",n:"Consulta externa",id:c.ID,det:ci.length+" citas",rec:c,cit:ci});}}}catch(e){}
  try{if(typeof VX!=="undefined"&&VX.book){const v=VX.book.pac.find(x=>eq(x.Documento));if(v)out.push({prog:"vih",n:"VIH",id:v.ID,det:"en cohorte",rec:v});}}catch(e){}
  return out;}

