  if(kt&&kt.Estado==="Pendiente de validación")adv.push({k:"v50",m:"Kt/V sin validación profesional"});
  v.v51=98;const en12=dpDias(p,per,c);v.v52=en12?dpR("epi").filter(e=>e.Paciente===p.ID&&e.Tipo==="Peritonitis"&&e.DxClinico==="Confirmada"&&e.Clasificacion!=="Recaída"&&v6d(e.Fecha)>=per&&v6d(e.Fecha)<=c).length:(en12===0?98:need("v52","","Peritonitis 12 meses (var 52): sin fecha de inicio de DP"));
  v.tperit=v.v52;v.v53="";adv.push({k:"v53",m:"Costo de la DP (var 53 y 77): no lo calcula el SIGC; lo diligencia la EPS o la conciliación de Producción"});
