  if(v.v62===2&&!contra.size)blk.push({k:"c1",m:"Contraindicación de trasplante sin especificar (var 62.1-62.11)"});for(let i=1;i<=11;i++)v["c"+i]=v.v62===2?(contra.has(String(i))?1:2):v.v62===1?2:v.v62;
  v.v63=tx==="En lista de espera"?iso(v6d(txr.Fecha)):tx==="Idóneo, en estudio"?D1800:D1845;v.v63_1=tx==="En lista de espera"?need("v63_1",txr.Centro,"IPS de la lista de espera (var 63.1)"):tx==="Idóneo, en estudio"?99:98;
  const hadTx=dpR("trp").some(t=>t.Paciente===p.ID&&t.Estado==="Trasplantado");v.v64=hadTx?3:5;if(hadTx)blk.push({k:"v64",m:"Antecedente de trasplante: revisar variables 64 a 75 manualmente"});
