  v.v79=K.novedad||(fall?1:aband?7:98);v.v80=fall?(K.causaMuerte||99):98;v.v80_1=fall?iso(v6d(eg.Fecha)):D1845;v.v81=need("v81",K.bdua,"Código BDUA (var 81)");v.v82=iso(c);
