function dpCacRun(c,ps,eps,sel){const P=DP.book.pac.filter(lv).filter(p=>(!eps||p.EPS===eps)&&(dpDias(p,ps,c)||(!dpIntervals(p)&&DP_EN.includes(dpEstado(p))))).filter(p=>!sel||sel.has(p.ID)).sort((a,b)=>String(a.ID).localeCompare(b.ID));
  return P.map(p=>({p,v:dpCacVals(p,c,ps)}));}
async function dpCacGenerate(c,ps,eps,sel){if(!dpGuard("exp"))return;const R=dpCacRun(c,ps,eps,sel);if(!R.length){toast("No hay pacientes de DP en ese periodo con ese filtro.");return;}
  const H=CAC_H_ERC,M=CAC_MAP_ERC;const rows=[H];const inc=[["Paciente","Documento","Nombre","Campo","Encabezado CAC","Valor","Severidad","Hallazgo"]];let nb=0,na=0;
  R.forEach(({p,v})=>{rows.push(M.map(k=>v[k]===undefined?"":v[k]));v._blk.forEach(x=>{nb++;inc.push([p.ID,p.Documento,dpNombre(p),x.k,H[M.indexOf(x.k)]||"",v[x.k]??"","Bloqueante",x.m]);});v._adv.forEach(x=>{na++;inc.push([p.ID,p.Documento,dpNombre(p),x.k,H[M.indexOf(x.k)]||"",v[x.k]??"","Advertencia",x.m]);});});
  const prev=dpR("cac").filter(x=>iso(v6d(x.FechaCorte))===iso(c)&&(x.EPS||"")===(eps||""));const ver=prev.length+1;const id=dpNext("cac","CAC-");
  const name="CAC_ERC_DP_"+norm(eps||"TODAS").replace(/\s+/g,"_")+"_"+iso(c).replace(/-/g,"")+"_v"+ver+"_PREVALIDACION.xlsx";
  const dic=[["Campo","Encabezado CAC","Fuente en el SIGC"]].concat(M.map((k,i)=>[k,H[i],DP_CAC_DIC[k]||"Constante o código igual al usado por el módulo HD"]));
  const wb=XLSX.utils.book_new();const ws=XLSX.utils.aoa_to_sheet(rows);ws["!cols"]=H.map(()=>({wch:16}));XLSX.utils.book_append_sheet(wb,ws,CAC_SHEET_ERC.slice(0,31));
  XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(inc.length>1?inc:[["Sin inconsistencias detectadas por las reglas institucionales"]]),"Inconsistencias");
  XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(dic),"Diccionario");
  XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([["Corte",id+" · versión "+ver],["Generado",nowTs()+" por "+v6who()],["Fecha de corte",iso(c)],["Inicio del periodo",iso(ps)],["EPS",eps||"Todas"],["Pacientes",R.length],["Bloqueantes",nb],["Advertencias",na],["Estructura",DP_CAC_ESTR],["Advertencia","PREVALIDACIÓN INSTITUCIONAL. No se ha verificado contra la versión vigente de la estructura de reporte, el instructivo ni las reglas de validación de la CAC. No presentar como archivo oficialmente compatible."]]),"Leame");
  const ok=await saveWb(wb,name);if(!ok)return;
  const prevSnap=prev.length?Object.fromEntries(dpR("cacd").filter(d=>d.Corte===prev[prev.length-1].ID).map(d=>[d.Paciente,dpJ(d.Datos,{})])):null;let cambios=0;
  R.forEach(({p,v})=>{const o={};M.forEach(k=>o[k]=v[k]===undefined?"":v[k]);if(prevSnap&&prevSnap[p.ID])M.forEach(k=>{if(String(prevSnap[p.ID][k]??"")!==String(o[k]))cambios++;});DP.book.cacd.push({Corte:id,Paciente:p.ID,Datos:JSON.stringify(o)});});
  DP.book.cac.push({ID:id,FechaCorte:c,InicioPeriodo:ps,EPS:eps||"",Pacientes:R.length,Version:ver,Estructura:DP_CAC_ESTR,Estado:nb?"Prevalidación con bloqueantes":"Prevalidación sin bloqueantes",Bloqueantes:nb,Advertencias:na,Archivo:name,Nota:prevSnap?cambios+" valores cambiaron frente a la versión "+(ver-1):"",Usuario:v6who(),Registrado:nowTs()});
  dpLog("EXPORTA","cac",id,name+" · "+R.length+" pacientes · "+nb+" bloqueantes · "+na+" advertencias");DP.dirty=true;pxRefresh();}


/* =================== v0.8 · DP · vistas =================== */
const DP_AREAS=[["res","Resumen"],["pac","Pacientes"],["val","Valoraciones"],["age","Agenda"],["lab","Laboratorios"],["tra","Tratamiento y seguridad"],["ind","Indicadores"],["rep","Reportes"]];
const DP_OLD={cen:"pac",epi:"tra",atb:"tra",ref:"ind"};
function dpTab(area,def){DP.ui.tab=DP.ui.tab||{};return DP.ui.tab[area]||def;}
function dpTabs(area,tabs,cur){return'<div class="seg d8tabs" role="group" aria-label="Secciones">'+tabs.map(([k,l])=>'<button type="button" data-p="d8tab|'+area+'|'+k+'" aria-pressed="'+(cur===k)+'">'+l+'</button>').join("")+'</div>';}
const dpBtn=(act,l,cls,dis)=>'<button type="button" class="btn '+(cls||"sm")+'" data-p="'+act+'"'+(dis?' disabled title="'+esc(dis)+'"':'')+'>'+l+'</button>';
const dpCanBtn=(acc,act,l,cls)=>dpCan(acc)?dpBtn(act,l,cls):'';
const dpPacLink=(p,extra)=>p?'<button type="button" class="lnk" data-p="d8ficha|'+esc(p.ID)+'">'+esc(p.ID)+'</button><span class="sub">'+esc(dpNombre(p))+(extra?' · '+extra:'')+'</span>':'<span class="sd">sin paciente</span>';
