function dpPacOpts(sel,blank,onlyAct){const P=DP.book.pac.filter(lv).filter(p=>!onlyAct||dpActivo(p)).sort((a,b)=>String(a.ID).localeCompare(b.ID));return opt(P.map(p=>[p.ID,p.ID+" · "+dpNombre(p)]),sel||"",blank);}
const dpStChip=(t,cls)=>'<span class="st '+(cls||"base")+'">'+esc(t)+'</span>';

function dpView(){let sub=PX.ui.sub||"res";if(DP_OLD[sub]){if(sub==="epi"||sub==="atb"){DP.ui.tab=DP.ui.tab||{};DP.ui.tab.tra="inf";}sub=DP_OLD[sub];PX.ui.sub=sub;}
  const role=dpRole();
  let h='<div class="mhead"><div><p class="eyebrow">Programa misional · v0.8</p><h2 class="mt">Diálisis peritoneal</h2><p class="note" style="margin:3px 0 0">Registro maestro, valoraciones, agenda, laboratorios, tratamiento y seguridad, indicadores CAC 2026 y reporte CAC. Los episodios infecciosos siguen alimentando IAAS-09, PROA y Microbiología sin doble registro.</p></div><div class="copyrow">'+
   (DP.book?'<span class="tag" title="Rol en este módulo">'+esc(DP_ROLES[role]||"")+'</span><button type="button" class="btn'+(DP.dirty?" warn":"")+'" data-p="dpexp">Descargar libro DP</button><button type="button" class="btn" data-p="dpclose">Cerrar libro</button>':'')+'</div></div>';
  if(!DP.book)return h+dpStart();dpEnsure();
  if(DP.demo)h+='<div class="demo-banner">Libro DP con <strong>datos ficticios</strong>. Ninguna cifra corresponde a pacientes reales. La importación de datos reales está bloqueada en este libro.</div>';
  else if(PX.demo)h+='<div class="alert bad"><p>Está en la <strong>demostración</strong> del sistema (usuarios ficticios) con un libro DP que no es de demostración. No registre datos reales aquí: abra el libro institucional real.</p></div>';
  if(DP.ui.chain&&!DP.ui.chain.ok)h+='<div class="alert bad"><p><strong>La bitácora del libro DP no coincide con su cadena de verificación desde la fila '+DP.ui.chain.fila+'.</strong> El archivo pudo ser modificado por fuera del sistema. Revise Reportes → Bitácora antes de seguir.</p></div>';
  h+='<nav class="d8nav" aria-label="Áreas del módulo">'+DP_AREAS.map(([k,l])=>'<button type="button" data-p="go|dp|'+k+'" aria-current="'+(sub===k?"page":"false")+'">'+l+'</button>').join("")+'</nav>';
  const V={res:dpResumen,pac:dpPacientes,val:dpValView,age:dpAgeView,lab:dpLabView,tra:dpTraView,ind:dpIndView,rep:dpRepView}[sub]||dpResumen;
  try{return h+V();}catch(e){console.error(e);return h+'<div class="alert bad"><p>Error al dibujar esta sección: '+esc(e.message)+'</p></div>';}}
function dpStart(){return'<div class="start">'+
  '<div class="panel"><h3>Ya tengo el libro de DP</h3><p class="note">Cargue el archivo «DP_libro_….xlsx» que descargó la última vez. Es donde quedan los pacientes, las valoraciones y todo el histórico.</p><label class="btn primary" for="dpfile" style="justify-self:start">Cargar libro DP</label><input type="file" id="dpfile" accept=".xlsx" hidden></div>'+
  (PX.demo?'':'<div class="panel"><h3>Primera vez: importar el censo</h3><p class="note">Seleccione el «Control de valoraciones - Diálisis peritoneal.xlsx» y, si lo tiene, la «Dashboard_POSMEDICA_DP_Plantilla.xlsx». Verá una vista previa antes de escribir nada.</p><label class="btn" for="d8imp" style="justify-self:start">Importar archivos</label><input type="file" id="d8imp" accept=".xlsx" multiple hidden></div>')+
  '<div class="panel"><h3>Empezar vacío</h3><p class="note">Libro DP nuevo sin pacientes.</p><button type="button" class="btn" data-p="dpnew" style="justify-self:start">Crear libro DP nuevo</button></div>'+
  (PX.demo?'<div class="panel"><h3>Demostración</h3><p class="note">Cohorte ficticia con valoraciones, laboratorios y agenda para probar el módulo.</p><button type="button" class="btn" data-p="dpdemo" style="justify-self:start">Cargar datos ficticios</button></div>':'')+'</div>'+
  '<p class="note">El libro DP se lee y se descarga en este navegador; no hay servidor. Mientras no exista la base de datos institucional, el respaldo es el archivo descargado: descárguelo al terminar cada jornada.</p>';}

/* ------------------------------ 1. Resumen ------------------------------ */
function dpResumen(){const T=TODAY();const P=DP.book.pac.filter(lv);const act=P.filter(p=>dpActivo(p,T));const A=dpAlerts();const a12=addDays(addMonths(T,-12),1);
  const nDPCA=act.filter(p=>p.Modalidad==="DPCA").length,nDPA=act.filter(p=>p.Modalidad==="DPA").length,nSin=act.length-nDPCA-nDPA;
  const AG=dpR("age");const prox=AG.filter(a=>DP_AGE_OPEN.includes(a.Estado)&&v6d(a.Fecha)>=T&&v6d(a.Fecha)<=addDays(T,14));const venc=AG.filter(a=>dpAgeEst(a)==="Vencida");
  const per=dpR("epi").filter(e=>e.Tipo==="Peritonitis"&&v6d(e.Fecha)>=a12);const perAb=per.filter(e=>!e.Desenlace||e.Desenlace==="En tratamiento"||e.DxClinico==="En estudio");const orif=dpR("epi").filter(e=>e.Tipo!=="Peritonitis"&&(!e.Desenlace||e.Desenlace==="En tratamiento"));
  const hos=dpR("hos").filter(h=>h.Estado!=="Cerrada");const hos12=dpR("hos").filter(h=>v6d(h.FechaIngreso)>=a12);const trf=dpR("est").filter(t=>t.EstadoNuevo==="Transición a HD"&&v6d(t.Fecha)>=a12);
  const cacR=dpCacRun(T,a12,"");const cacOk=cacR.filter(x=>!x.v._blk.length).length;
  const nU=A.filter(a=>a.sev==="u").length,nC=A.filter(a=>a.sev==="c").length,nAd=A.filter(a=>a.sev==="a").length,nD=A.filter(a=>a.sev==="d").length;
  let h='<div class="tiles">'+
   '<button type="button" class="tile" data-p="go|dp|pac"><span class="tv">'+act.length+'</span><span class="tl">activos · DPCA '+nDPCA+' · DPA '+nDPA+(nSin?' · sin modalidad '+nSin:'')+'</span></button>'+
   '<button type="button" class="tile '+(nU?"bad":nC?"warn":"ok")+'" data-p="d8tab|res|al"><span class="tv">'+(nU+nC)+'</span><span class="tl">alertas clínicas'+(nU?' ('+nU+' urgentes)':'')+' · '+nAd+' administrativas · '+nD+' de dato</span></button>'+
   '<button type="button" class="tile '+(venc.length?"bad":"ok")+'" data-p="d8tab|age|lst"><span class="tv">'+venc.length+'</span><span class="tl">actividades vencidas · '+prox.length+' programadas en 14 días</span></button>'+
   '<button type="button" class="tile '+(perAb.length?"warn":"ok")+'" data-p="d8tab|tra|inf"><span class="tv">'+per.length+'</span><span class="tl">peritonitis en 12 meses · '+perAb.length+' abiertas · '+orif.length+' infecciones de orificio o túnel abiertas</span></button>'+
   '<button type="button" class="tile '+(hos.length?"warn":"ok")+'" data-p="d8tab|tra|hos"><span class="tv">'+hos12.length+'</span><span class="tl">hospitalizaciones en 12 meses · '+hos.length+' abiertas · '+trf.length+' transferencias a HD</span></button>'+
   '<button type="button" class="tile '+(cacR.length&&cacOk===cacR.length?"ok":"warn")+'" data-p="d8tab|rep|cac"><span class="tv">'+cacOk+'/'+cacR.length+'</span><span class="tl">pacientes sin bloqueantes para el reporte CAC (corte hoy)</span></button></div>';
  const t=dpTab("res","res");
  if(t==="al")return h+dpTabs("res",[["res","Resumen"],["al","Todas las alertas"]],t)+dpAlertList(A);
  h+=dpTabs("res",[["res","Resumen"],["al","Todas las alertas ("+A.length+")"]],t);
  h+='<div class="grid2 d8two"><div class="panel"><div class="mhead"><h3 style="margin:0">Pendientes prioritarios</h3><button type="button" class="lnk" data-p="d8tab|res|al">Ver todas</button></div>'+dpAlertList(A,true)+'</div>';
  const D={};prox.concat(venc).forEach(a=>{const k=iso(v6d(a.Fecha));(D[k]=D[k]||[]).push(a);});
  h+='<div class="panel"><div class="mhead"><h3 style="margin:0">Próximos 14 días y vencidas</h3><button type="button" class="lnk" data-p="go|dp|age">Abrir agenda</button></div>'+(Object.keys(D).length?'<div class="d8mini">'+Object.keys(D).sort().map(k=>'<div class="d8day'+(k<iso(T)?" late":k===iso(T)?" today":"")+'"><b class="mono">'+fd(pdate(k)).slice(0,5)+'</b>'+D[k].map(a=>{const p=dpPac(a.Paciente);return'<button type="button" class="d8ev '+DP_AGE_CLS[dpAgeEst(a)]+'" data-p="d8age|'+a.ID+'">'+esc((a.Hora||"")+" "+a.Tipo)+'<span>'+esc(p?dpNombre(p):a.Paciente)+' · '+esc(dpAgeEst(a))+'</span></button>';}).join("")+'</div>').join("")+'</div>':'<p class="note">Sin actividades en los próximos 14 días.</p>')+'</div></div>';
  const sel=dpPerSel();const prio=DP_IND8.filter(d=>d.prio);const ev=prio.map(d=>({d,r:dpEval(d,sel.c,sel.ps,{})}));
  h+='<div class="panel"><div class="mhead"><h3 style="margin:0">Indicadores CAC prioritarios · '+esc(sel.l)+'</h3><button type="button" class="lnk" data-p="go|dp|ind">Ver tablero</button></div><div class="d8hb">'+ev.map(({d,r})=>'<button type="button" class="d8hbr" data-p="d8nom|'+d.c+'"><span class="d8hbl">'+esc(d.n)+' <span class="tag cac">'+d.c.replace("_adul","")+'</span></span><span class="d8hbt">'+(d.t==="pct"&&r.val!=null?'<i class="'+DP_ST_CLS[r.status]+'" style="width:'+Math.max(2,r.val)+'%"></i>':'')+'</span><span class="d8hbv mono">'+(r.val==null?"sin datos":d.t==="pct"?f1(r.val,1)+" %":f1(r.val,2))+'</span><span class="st '+DP_ST_CLS[r.status]+'">'+DP_ST_TXT[r.status]+'</span></button>').join("")+'</div><p class="note">Barra = resultado del periodo. Tasas en episodios por paciente-año. «Sin datos» significa que falta información para calcular, no que el resultado sea cero: el detalle muestra qué falta.</p></div>';
  return h;}
function dpAlertList(A,compact){if(!A.length)return'<p class="note">Sin alertas.</p>';if(compact){const G=[];const idx={};A.forEach(a=>{const k=a.sev+'|'+a.txt.replace(/\d+/g,'#');if(idx[k]==null){idx[k]=G.length;G.push({a,L:[]});}G[idx[k]].L.push(a);});if(G.length<A.length)return'<ul class="d8al">'+G.slice(0,10).map(g=>g.L.length===1?dpAlertLi(g.a):'<li><span class="st '+DP_SEV[g.a.sev][1]+'">'+DP_SEV[g.a.sev][0]+'</span> <strong>'+g.L.length+' pacientes</strong> · '+esc(g.a.txt)+' <span class="sub">'+g.L.map(x=>'<button type="button" class="lnk" data-p="d8ficha|'+esc(x.pid)+'">'+esc(x.pid)+'</button>').join(' ')+'</span></li>').join('')+'</ul>';}return'<ul class="d8al">'+A.map(a=>dpAlertLi(a)).join('')+'</ul>';}
function dpAlertLi(a){return'<li><span class="st '+DP_SEV[a.sev][1]+'">'+DP_SEV[a.sev][0]+'</span> '+(a.pid?'<button type="button" class="lnk" data-p="d8ficha|'+esc(a.pid)+'">'+esc(a.pid)+'</button> '+esc(a.pn)+' · ':'')+esc(a.txt)+' <button type="button" class="lnk" data-p="d8goal|'+esc(a.go)+'">Ir</button></li>';}

/* ------------------------------ 2. Pacientes ------------------------------ */
function dpPacientes(){if(DP.ui.pid&&dpPac(DP.ui.pid))return dpFicha(DP.ui.pid);const t=dpTab("pac","cen");const nh=dpR("her").filter(h=>h.Estado==="Pendiente de verificación").length+dpR("ins").filter(i=>/por confirmar|Sin paciente/.test(i.Estado||"")).length;
  let h=dpTabs("pac",[["cen","Censo nominal"],["con","Conciliación e importación"+(nh?" ("+nh+")":"")],["dat","Datos pendientes"]],t);
  if(t==="con")return h+dpConcil();if(t==="dat")return h+dpDatos();
  const T=TODAY();const P=DP.book.pac.filter(lv);const f=DP.ui.cf||"act";const L=P.filter(p=>f==="todos"||(f==="act"?dpActivo(p,T)||(!v6d(p.FechaInicioDP)&&DP_EN.includes(dpEstado(p))):!dpActivo(p,T))).sort((a,b)=>String(a.ID).localeCompare(b.ID));const A=dpAlerts();
  h+='<div class="panel"><div class="mhead"><div class="seg sm" role="group">'+[["act","En el programa"],["fuera","Fuera de DP"],["todos","Todos"]].map(([k,l])=>'<button type="button" data-p="d8cf|'+k+'" aria-pressed="'+(f===k)+'">'+l+'</button>').join("")+'</div><div class="copyrow">'+dpCanBtn("pac","dppac","Nuevo paciente","sm primary")+(dpCan("imp")&&!DP.demo&&!PX.demo?'<label class="btn sm" for="d8imp">Importar archivos</label><input type="file" id="d8imp" accept=".xlsx" multiple hidden>':'')+'</div></div>';
  h+=dpTbl([["Paciente",p=>dpPacLink(p,(p.TipoDoc?esc(p.TipoDoc):'<span style="color:var(--warn)">tipo doc. pendiente</span>')+' '+esc(p.Documento||""))],["EPS · municipio",p=>(p.EPS?esc(p.EPS):'<span class="sd">sin EPS</span>')+'<span class="sub">'+esc(p.Municipio||"—")+'</span>'],
   ["Modalidad",p=>esc(p.Modalidad||"—")+(p.ModalidadFuente?'<span class="sub">fuente: '+esc(p.ModalidadFuente)+'</span>':'')],["Estado",p=>dpStChip(dpEstado(p),DP_EN.includes(dpEstado(p))?"ok":"base")+'<span class="sub">'+(v6d(p.FechaInicioDP)?"en DP desde "+fd(v6d(p.FechaInicioDP)):'<span style="color:var(--bad)">sin fecha de inicio</span>')+'</span>'],
   ["Última valoración",p=>{const v=dpR("val").filter(x=>x.Paciente===p.ID&&/Finalizada/.test(x.Estado||"")).sort((a,b)=>v6d(b.Fecha)-v6d(a.Fecha))[0];return v?fd(v6d(v.Fecha))+'<span class="sub">'+esc(v.Tipo)+'</span>':'<span class="sd">ninguna</span>';}],
   ["Próxima actividad",p=>{const a=dpR("age").filter(x=>x.Paciente===p.ID&&DP_AGE_OPEN.includes(x.Estado)).sort((a,b)=>v6d(a.Fecha)-v6d(b.Fecha))[0];return a?'<span class="st '+DP_AGE_CLS[dpAgeEst(a)]+'">'+fd(v6d(a.Fecha))+'</span><span class="sub">'+esc(a.Tipo)+'</span>':'<span class="sd">—</span>';}],
   ["Alertas",p=>{const n=A.filter(a=>a.pid===p.ID);const u=n.filter(a=>a.sev==="u"||a.sev==="c").length;return n.length?'<span class="st '+(u?"bad":"warn")+'">'+n.length+'</span>':'<span class="st ok">0</span>';},"num"],
   ["",p=>dpBtn("d8ficha|"+p.ID,"Abrir ficha")]],L,"Sin pacientes en este filtro.");
  return h+'<p class="note">El identificador institucional es tipo + número de documento ('+esc(L[0]?L[0].IdInst||"":"")+'…); cuando falta el tipo queda con prefijo ND hasta verificarlo. Nunca se reasigna el ID de programa.</p></div>';}
function dpDatos(){const P=DP.book.pac.filter(lv);const C=["tipo de documento","fecha de nacimiento","sexo","EPS","inicio de DP","inicio de diálisis","municipio"];
  return'<div class="panel"><p class="note">Datos maestros que impiden calcular indicadores o generar el reporte CAC. Se completan en la ficha del paciente → «Editar datos». No se infieren.</p>'+dpTbl([["Paciente",p=>dpPacLink(p)]].concat(C.map(c=>[c.replace(/^./,x=>x.toUpperCase()),p=>dpMissing(p).includes(c)?'<span class="st bad">falta</span>':'<span class="st ok">✓</span>'])).concat([["",p=>dpCanBtn("pac","dppac|"+p.ID,"Editar datos")]]),P)+'</div>';}
function dpConcil(){const I=dpR("imp").sort((a,b)=>String(b.FechaHora).localeCompare(String(a.FechaHora)));const H=dpR("her");const N=dpR("ins").filter(i=>!i.Paciente||/por confirmar|Sin paciente/.test(i.Estado||""));
  let h='<div class="panel"><div class="mhead"><h3 style="margin:0">Importaciones</h3>'+(dpCan("imp")&&!DP.demo&&!PX.demo?'<label class="btn sm primary" for="d8imp">Importar archivos</label><input type="file" id="d8imp" accept=".xlsx" multiple hidden>':'')+'</div>'+
   dpTbl([["Importación",i=>esc(i.ID)+'<span class="sub">'+esc(i.FechaHora)+' · '+esc(i.Usuario)+'</span>'],["Archivos",i=>'<span style="font-size:12.5px">'+esc(i.Archivos)+'</span>'],["Importados",i=>i.Importados,"num"],["Omitidos",i=>i.Omitidos,"num"],["Duplicados",i=>i.Duplicados,"num"],["Pendientes",i=>i.Pendientes,"num"],["",i=>dpBtn("d8impexp|"+i.ID,"Informe de conciliación")]],I,"Sin importaciones. La importación es repetible: un segundo intento no duplica pacientes, heredados ni insumos.")+'</div>';
  const G={};N.forEach(i=>{(G[i.NombreFuente]=G[i.NombreFuente]||[]).push(i);});
  h+='<div class="panel"><h3>Insumos heredados por asociar ('+N.length+' filas, '+Object.keys(G).length+' nombres)</h3><p class="note">Vienen de la hoja «Hoja 1» de la plantilla: nombre abreviado, insumo y cantidad, sin fecha ni periodo. No se asocian solos: se confirma una vez por nombre, con la ficha del paciente y la formulación vigente.</p>'+
   dpTbl([["Nombre en la fuente",([n,L])=>'<strong>'+esc(n)+'</strong><span class="sub">'+esc(L[0].Origen)+'</span>'],["Insumos y cantidades",([n,L])=>'<span style="font-size:12.5px">'+L.map(i=>esc(i.Insumo)+' · '+esc(i.Cantidad??"")+(/4,5 no|«4,5»/.test(i.Nota||"")?' <span class="tag warn">verificar concentración</span>':'')).join("<br>")+'</span>'],["Sugerencia",([n,L])=>L[0].Sugerido?dpPacLink(dpPac(L[0].Sugerido))+'<span class="sub">'+esc(L[0].Confianza)+'</span>':'<span class="sd">'+esc(L[0].Confianza||"sin coincidencia")+'</span>'],["Estado",([n,L])=>dpStChip(L[0].Estado,/Sin paciente/.test(L[0].Estado)?"bad":"warn")],["",([n,L])=>dpCanBtn("ins","d8insas|"+L[0].ID,"Asociar o descartar")]],Object.entries(G),"Todos los insumos heredados están resueltos.")+'</div>';
  const pend=H.filter(x=>x.Estado==="Pendiente de verificación");
  h+='<div class="panel"><h3>Registros heredados del archivo de control ('+pend.length+' pendientes de '+H.length+')</h3><p class="note">Fechas y marcas («YA», «JUNIO», «NO», «X») tal como estaban. No cuentan como atención realizada mientras no se verifiquen con soporte (historia clínica, acta, registro). Al verificar se puede crear la actividad realizada en la agenda.</p>'+
   dpTbl([["Paciente",x=>x.Paciente?dpPacLink(dpPac(x.Paciente)):'<span class="sd">general</span>'],["Tipo",x=>esc(x.Tipo)],["Contenido en la fuente",x=>'<span style="font-size:12.5px">'+esc(x.Anotacion)+'</span><span class="sub">'+esc(x.Fuente)+'</span>'],["Estado",x=>dpStChip(x.Estado,x.Estado==="Pendiente de verificación"?"warn":x.Estado==="Descartado"?"base":"ok")+(x.Verificacion?'<span class="sub">'+esc(x.Verificacion)+'</span>':'')],["",x=>x.Estado==="Pendiente de verificación"?dpCanBtn("apr","d8herv|"+x.ID,"Verificar o descartar"):""]],H.sort((a,b)=>String(a.Paciente).localeCompare(String(b.Paciente))))+'</div>';
  return h;}

/* ---------- ficha individual ---------- */
function dpFicha(pid){const p=dpPac(pid);const T=TODAY();const ed=dpEdad(p);const vf=dpJ(p.Verif,{});const st=dpEstado(p);const A=dpAlerts().filter(a=>a.pid===pid);
  let h='<div class="copyrow"><button type="button" class="btn sm" data-p="d8ficha|">‹ Censo</button></div><div class="panel d8head"><div><p class="eyebrow">'+esc(p.ID)+' · '+esc(p.IdInst||"")+'</p><h2 class="mt">'+esc(dpNombre(p))+'</h2><p class="note" style="margin:2px 0 0">'+
   [(p.TipoDoc||'<span style="color:var(--warn)">tipo pendiente</span>')+" "+esc(p.Documento||""),ed!=null?ed+" años":'<span style="color:var(--warn)">edad sin dato</span>',esc(p.EPS||"EPS sin dato"),esc(p.Municipio||"municipio sin dato"),"<strong>"+esc(p.Modalidad||"modalidad sin dato")+"</strong>","ingreso "+(v6d(p.FechaIngresoPrograma)?fd(v6d(p.FechaIngresoPrograma)):"sin dato")].join(" · ")+'</p></div><div class="copyrow">'+dpStChip(st,DP_EN.includes(st)?"ok":"base")+
   dpCanBtn("pac","dppac|"+pid,"Editar datos")+dpCanBtn("pac","d8tr|"+pid,"Cambiar estado o modalidad")+dpCanBtn("val","d8vnew|"+pid,"Nueva valoración","sm primary")+dpCanBtn("age","d8agenew|"+pid,"Programar actividad")+dpCanBtn("lab","d8labnew|"+pid,"Registrar laboratorio")+'</div></div>';
  const pend=Object.entries(vf).filter(([k,v])=>/Pendiente|verificar|Homologada/i.test(v));if(pend.length)h+='<div class="alert warn"><p><strong>Por verificar:</strong> '+pend.map(([k,v])=>esc(v)).join(" · ")+(p.Origen?'<span class="sub">Origen: '+esc(p.Origen)+'</span>':'')+'</p></div>';
  if(A.length)h+='<div class="panel"><h3>Alertas ('+A.length+')</h3>'+dpAlertList(A)+'</div>';
  const pre=dpPreVig(pid);const lastV=dpR("val").filter(x=>x.Paciente===pid&&/Finalizada/.test(x.Estado||"")).sort((a,b)=>v6d(b.Fecha)-v6d(a.Fecha))[0];const dv=lastV?dpJ(lastV.Datos,{}):{};
  const diu=dpLast(pid,"Diuresis"),uf=dpLast(pid,"UF");const cs=dpCatState(pid);const es=dpEduState(pid);const tx=dpTxAt(pid);
  const lab=["Hb","Alb","P","Ca","PTH","K","KtV"].map(k=>{const l=dpLast(pid,k);return'<tr><td>'+esc(DPX[k].l)+'</td><td class="num mono">'+(l?esc(l.Valor)+(DPX[k].u?' <span class="sub" style="display:inline">'+esc(DPX[k].u)+'</span>':''):'—')+'</td><td class="mono">'+(l?fd(v6d(l.FechaToma)):'')+(l&&l.Estado==="Pendiente de validación"?' <span class="st warn">sin validar</span>':'')+'</td></tr>';}).join("");
  const epi=dpR("epi").filter(e=>e.Paciente===pid).sort((a,b)=>v6d(b.Fecha)-v6d(a.Fecha));
  h+='<div class="grid2 d8two"><div class="panel"><h3>Resumen clínico</h3><dl class="d8dl"><dt>Etiología de la ERC</dt><dd>'+esc((DP_ETIO.find(e=>e[0]===String(p.Etiologia))||[0,"sin dato"])[1])+'</dd><dt>Comorbilidades</dt><dd>'+esc(dpJ(p.Comorbilidades,[]).join(", ")||"sin registro")+'</dd><dt>Prescripción vigente</dt><dd>'+esc(dpPreTxt(pre))+(pre?' <span class="sub">desde '+fd(v6d(pre.VigenteDesde))+' · '+esc(pre.Prescriptor||"")+'</span>':'')+'</dd>'+
   '<dt>Diuresis residual</dt><dd>'+(diu?esc(diu.Valor)+' mL/24 h · '+fd(v6d(diu.FechaToma)):dv.diuresis?esc(dv.diuresis)+' mL/24 h ('+esc(dv.diuresis_f||"")+') en valoración':'sin dato')+'</dd><dt>Ultrafiltración</dt><dd>'+(uf?esc(uf.Valor)+' mL/24 h · '+fd(v6d(uf.FechaToma)):dv.uf?esc(dv.uf)+' mL/24 h en valoración':'sin dato')+'</dd>'+
   '<dt>Catéter</dt><dd>'+(cs.activo?esc(cs.tipo||"tipo sin dato")+' · '+cs.dias+' días':'sin implante registrado')+(cs.lin?'<span class="sub">último cambio de línea '+fd(v6d(cs.lin.Fecha))+(cs.prox?' · próximo '+fd(cs.prox):cs.iv?'':' · intervalo sin parametrizar')+'</span>':'')+'</dd>'+
   '<dt>Complicaciones</dt><dd>'+(epi.length?epi.slice(0,3).map(e=>esc(e.Tipo)+' '+fd(v6d(e.Fecha))+' ('+esc(e.DxClinico||"")+')').join("<br>"):'sin episodios')+'</dd><dt>Trasplante</dt><dd>'+esc(tx?tx.Estado+" · "+fd(v6d(tx.Fecha)):"Sin evaluar")+'</dd></dl>'+
   '<table class="dense mini"><tbody>'+lab+'</tbody></table></div>';
  const nx=dpR("age").filter(x=>x.Paciente===pid&&DP_AGE_OPEN.includes(x.Estado)).sort((a,b)=>v6d(a.Fecha)-v6d(b.Fecha));const pendLab=DP_EX.filter(e=>dpLabOverdue(p,e.k)).map(e=>e.l);
  const multi=["Nutrición","Psicología","Trabajo social","Enfermería"].map(t=>{const v=dpValsOf(pid,t).pop();return'<dt>'+t+'</dt><dd>'+(v?fd(v6d(v.Fecha)):'<span class="sd">sin valoración finalizada</span>')+'</dd>';}).join("");
  h+='<div class="panel"><h3>Resumen asistencial</h3><dl class="d8dl"><dt>Última valoración</dt><dd>'+(lastV?fd(v6d(lastV.Fecha))+' · '+esc(lastV.Tipo)+' · '+esc(lastV.Profesional||""):'ninguna en el SIGC')+'</dd><dt>Próximas actividades</dt><dd>'+(nx.length?nx.slice(0,4).map(a=>'<button type="button" class="lnk" data-p="d8age|'+a.ID+'">'+fd(v6d(a.Fecha))+' '+esc(a.Tipo)+'</button> <span class="st '+DP_AGE_CLS[dpAgeEst(a)]+'">'+dpAgeEst(a)+'</span>').join("<br>"):'ninguna programada')+'</dd>'+
   '<dt>Laboratorios vencidos</dt><dd>'+(pendLab.length?esc(pendLab.join(", ")):dpR("plab").some(x=>x.Estado==="Validado")?'ninguno':'<span class="sd">plan de laboratorio sin validar</span>')+'</dd>'+multi+'<dt>Entrenamiento</dt><dd>'+esc(es.res)+(es.ult?' · '+fd(v6d(es.ult.Fecha)):'')+'</dd><dt>Visita domiciliaria</dt><dd>'+(es.vis?fd(v6d(es.vis.Fecha))+' · '+esc(es.vis.Resultado||""):'sin registro')+'</dd></dl>';
  const M=dpMPI(p);h+='<h3 style="margin-top:12px">Otros programas (mismo documento)</h3>'+(M.length?'<ul class="v6list">'+M.map(m=>'<li><strong>'+esc(m.n)+'</strong> · '+esc(m.id)+' · '+esc(m.det)+'</li>').join("")+'</ul>':'<p class="note">No aparece en los libros abiertos de Hemodiálisis, Consulta externa ni VIH. Nefroprotección vive en su propio libro embebido: el cruce con ese programa no está disponible en esta versión.</p>')+'</div></div>';
  h+=dpTimeline(p);return h;}
/* línea de tiempo integrada: cada elemento abre su registro original */
function dpTlItems(p){const pid=p.ID;const I=[];const add=(f,src,t,d,ref,u)=>{if(f)I.push({f:v6d(f),src,t,d,ref,u});};
  dpR("val").filter(x=>x.Paciente===pid).forEach(v=>add(v.Fecha,"Valoración",v.Tipo+" · "+v.Estado,(v.Profesional||"")+(v.VersionDe?" · corrige "+v.VersionDe:""),"val|"+v.ID,v.Usuario));
  dpR("lab").filter(x=>x.Paciente===pid).forEach(l=>add(l.FechaToma,"Laboratorio",(DPX[l.Examen]||{l:l.Examen}).l+": "+l.Valor+" "+((DPX[l.Examen]||{}).u||""),l.Estado+(l.Metodo?" · "+l.Metodo:""),"lab|"+l.ID,l.Usuario));
  dpR("age").filter(x=>x.Paciente===pid).forEach(a=>add(a.FechaRealizacion||a.Fecha,"Agenda",a.Tipo,dpAgeEst(a)+(a.Profesional?" · "+a.Profesional:""),"age|"+a.ID,a.Usuario));
  dpR("pre").filter(x=>x.Paciente===pid).forEach(r=>add(r.VigenteDesde,"Prescripción","Versión "+r.Version+" · "+r.Modalidad,r.Motivo||"","pre|"+r.ID,r.Usuario));
  dpR("cat").filter(x=>x.Paciente===pid).forEach(r=>add(r.Fecha,"Catéter",r.Tipo+(r.Clasificacion?" · "+r.Clasificacion:""),r.Estado||"","cat|"+r.ID,r.Usuario));
  dpR("edu").filter(x=>x.Paciente===pid).forEach(r=>add(r.Fecha,"Educación",r.Tipo,r.Resultado||"","edu|"+r.ID,r.Usuario));
  dpR("hos").filter(x=>x.Paciente===pid).forEach(r=>add(r.FechaIngreso,"Hospitalización",r.Causa||"Hospitalización",(r.Institucion||"")+" · "+(r.Estado||""),"hos|"+r.ID,r.Usuario));
  dpR("est").filter(x=>x.Paciente===pid).forEach(r=>add(r.Fecha,"Estado",r.EstadoAnterior+" → "+r.EstadoNuevo+(r.ModalidadNueva&&r.ModalidadNueva!==r.ModalidadAnterior?" · "+(r.ModalidadAnterior||"—")+" → "+r.ModalidadNueva:""),r.Motivo||"","est|"+r.ID,r.Usuario));
  dpR("epi").filter(x=>x.Paciente===pid).forEach(e=>add(e.Fecha,"Infección",e.Tipo+" · "+(e.DxClinico||"En estudio"),(e.Clasificacion||"")+(iclOf("DP:"+e.ID)?" · IAAS: "+iclOf("DP:"+e.ID).Estado:""),"epi|"+e.ID,e.Usuario));
  dpR("atb").filter(x=>x.Paciente===pid).forEach(a=>add(a.Inicio,"Antimicrobiano",a.Antimicrobiano+" "+(a.Via||""),(a.Indicacion||"")+(trtAudit({fu:"DP",id:a.ID})?" · auditado PROA":""),"atb|"+a.ID,a.Usuario));
  micOfPac("dp",pid).forEach(m=>add(m.FechaToma||m.FechaSolicitud,"Microbiología",m.Muestra+" · "+m.Estado,(m.Resultado||"")+(m.Microorganismo?" · "+m.Microorganismo:""),"mic|"+m.ID,m.Usuario));
  dpR("ent").filter(x=>x.Paciente===pid).forEach(e=>add(e.FechaEntrega||e.FechaProgramada,"Insumos","Entrega "+e.Periodo,e.Estado,"ent|"+e.ID,e.Usuario));
  dpR("trp").filter(x=>x.Paciente===pid).forEach(t=>add(t.Fecha,"Trasplante",t.Estado,t.Centro||"","trp|"+t.ID,t.Usuario));
  dpR("cvr").filter(x=>x.Paciente===pid).forEach(c=>add(c.Fecha,"Calidad de vida",c.Escala,(c.Momento||"")+" · puntaje "+(c.Puntaje??""),"cvr|"+c.ID,c.Usuario));
  dpR("her").filter(x=>x.Paciente===pid&&x.FechaFuente).forEach(x=>add(x.FechaFuente,"Heredado",x.Tipo+" (archivo de control)",x.Estado,"her|"+x.ID,x.Usuario));
  dpMPI(p).filter(m=>m.prog==="ce").forEach(m=>(m.cit||[]).forEach(c=>add(c.Fecha,"Consulta externa","Cita "+(c.Hora||""),c.Estado||"","ce|"+c.ID,c.AsignadaPor)));
  return I.sort((a,b)=>b.f-a.f);}
function dpTimeline(p){const I=dpTlItems(p);const srcs=[...new Set(I.map(i=>i.src))];const f=DP.ui.tlf||"";const L=I.filter(i=>!f||i.src===f);
  return'<div class="panel"><div class="mhead"><h3 style="margin:0">Histórico integrado ('+I.length+')</h3><div class="seg sm" role="group"><button type="button" data-p="d8tlf|" aria-pressed="'+(!f)+'">Todo</button>'+srcs.map(s=>'<button type="button" data-p="d8tlf|'+esc(s)+'" aria-pressed="'+(f===s)+'">'+esc(s)+'</button>').join("")+'</div></div>'+
   (L.length?'<ol class="d8tl">'+L.slice(0,150).map(i=>'<li><span class="mono d8tld">'+fd(i.f)+'</span><span class="tag">'+esc(i.src)+'</span><button type="button" class="lnk" data-p="d8rec|'+esc(i.ref)+'">'+esc(i.t)+'</button><span class="sub">'+esc(i.d)+(i.u?' · '+esc(i.u):'')+'</span></li>').join("")+'</ol>':'<p class="note">Sin actuaciones registradas todavía. Lo heredado del archivo de control sin fecha está en «Conciliación».</p>')+'</div>';}

/* ------------------------------ 3. Valoraciones ------------------------------ */
const DP_VAL_TIPOS=["Control de nefrología","Ingreso al programa","Valoración urgente","Enfermería","Nutrición","Psicología","Trabajo social","Medicina general u otra"];
const DP_MED=["Control de nefrología","Ingreso al programa","Valoración urgente","Medicina general u otra"];
function dpValView(){if(DP.ui.vedit)return dpValEditor();const t=dpTab("val","reg");let h=dpTabs("val",[["reg","Registro"],["aud","Auditoría de completitud"]],t);if(t==="aud")return h+dpValAudit();
  const F=DP.ui.vf||{};const V=dpR("val").filter(v=>(!F.p||v.Paciente===F.p)&&(!F.t||v.Tipo===F.t)&&(!F.e||v.Estado===F.e)).sort((a,b)=>(v6d(b.Fecha)||0)-(v6d(a.Fecha)||0)||String(b.ID).localeCompare(a.ID));
  h+='<div class="panel"><div class="mhead"><div class="copyrow"><label class="f" style="min-width:200px">Paciente<select id="d8vfp">'+dpPacOpts(F.p,"Todos")+'</select></label><label class="f">Tipo<select id="d8vft">'+opt(DP_VAL_TIPOS,F.t||"","Todos")+'</select></label><label class="f">Estado<select id="d8vfe">'+opt(["Borrador","Finalizada","Finalizada (corrección)","Reemplazada"],F.e||"","Todos")+'</select></label></div>'+dpCanBtn("val","d8vnew|"+(F.p||""),"Nueva valoración","sm primary")+'</div>';
  h+=dpTbl([["Fecha",v=>'<span class="mono">'+fd(v6d(v.Fecha))+'</span><span class="sub">'+esc(v.ID)+(v.Version>1?' · v'+v.Version:'')+'</span>'],["Paciente",v=>dpPacLink(dpPac(v.Paciente))],["Tipo",v=>esc(v.Tipo)],["Profesional",v=>esc(v.Profesional||"")],["Estado",v=>dpStChip(v.Estado,v.Estado==="Borrador"?"warn":v.Estado==="Reemplazada"?"base":"ok")+(v.VersionDe?'<span class="sub">corrige '+esc(v.VersionDe)+'</span>':'')],["Completitud",v=>{const c=num(v.Completitud);return c==null?"—":'<span class="st '+(c>=90?"ok":c>=70?"warn":"bad")+'">'+c+' %</span>';},"num"],["",v=>dpBtn("d8vopen|"+v.ID,v.Estado==="Borrador"&&dpCan("val")?"Continuar":"Ver")]],V,"Sin valoraciones registradas.");
  return h+'<p class="note">El borrador se puede guardar incompleto. Al finalizar queda en solo lectura; una corrección crea una versión nueva con su motivo y la anterior se conserva como «Reemplazada».</p></div>';}


/* ---------- valoración: definición de campos (reutiliza la lógica de auditoría por criterios de Nefroprotección, adaptada a DP) ---------- */
const DPV_SINT=["Náusea o vómito","Anorexia","Prurito","Alteración del sueño","Astenia o fatiga","Disnea","Edema","Dolor abdominal","Efluente turbio","Fiebre","Calambres","Ninguno"];
const DPV_ND=["No evaluado","Sin dato"];
/* t: tipo · ty: tipos de valoración donde aparece ("med" = médicas) · r: exigido para completitud · e: esencial para finalizar · cac: variable CAC relacionada */
const DPV=[
 ["Atención",[{k:"hora",l:"Hora",t:"time",ty:"all",r:"all"},{k:"modo",l:"Modalidad de atención",t:"sel",o:["Presencial","Domiciliaria","Telemedicina"],ty:"all",r:"all"}]],
 ["Motivo y enfermedad actual",[{k:"motivo",l:"Motivo de consulta",t:"area",ty:"all",r:"all",e:1},{k:"ea",l:"Enfermedad actual y síntomas relevantes",t:"area",ty:["med","Psicología"],r:"med"},{k:"sint",l:"Síntomas",t:"chk",o:DPV_SINT,ty:["med","Enfermería"],r:"med"}]],
 ["Antecedentes y tratamiento",[{k:"antec",l:"Antecedentes relevantes",t:"area",ty:["Control de nefrología","Ingreso al programa","Medicina general u otra"],r:["Ingreso al programa"]},{k:"comorb",l:"Comorbilidades",t:"chk",o:DP_COMORB,ty:["Control de nefrología","Ingreso al programa","Medicina general u otra"],r:["Ingreso al programa","Control de nefrología"],cac:"Var 18 y 20 (HTA, DM)"},{k:"meds",l:"Tratamiento farmacológico (conciliación)",t:"area",ty:["Control de nefrología","Ingreso al programa","Medicina general u otra","Enfermería"],r:["Control de nefrología","Ingreso al programa"],cac:"Var 36 y 37 (IECA, ARA II)"}]],
 ["Signos vitales, volumen y examen físico",[{k:"ta_s",l:"TA sistólica (mmHg)",t:"num",min:50,max:260,ty:["med","Enfermería"],r:["med","Enfermería"],cac:"Var 25"},{k:"ta_d",l:"TA diastólica (mmHg)",t:"num",min:20,max:160,ty:["med","Enfermería"],r:["med","Enfermería"],cac:"Var 26"},{k:"fc",l:"FC (lpm)",t:"num",min:20,max:250,ty:["med","Enfermería"],r:["Valoración urgente"]},{k:"temp",l:"Temperatura (°C)",t:"num",min:30,max:43,ty:["med","Enfermería"],r:["Valoración urgente"]},
   {k:"peso",l:"Peso (kg)",t:"num",min:20,max:250,ty:["med","Enfermería","Nutrición"],r:["Control de nefrología","Ingreso al programa","Nutrición","Enfermería"],cac:"Var 23"},{k:"talla",l:"Talla (cm)",t:"num",min:100,max:230,ty:["Ingreso al programa","Nutrición"],r:["Ingreso al programa","Nutrición"],cac:"Var 24"},
   {k:"edema",l:"Edema",t:"sel",o:["Ausente","+","++","+++","No evaluado"],ty:["med","Enfermería"],r:["Control de nefrología","Ingreso al programa","Enfermería"]},{k:"volumen",l:"Estado de volumen",t:"sel",o:["Euvolémico","Sobrecarga","Depleción","Incierto","No evaluado"],ty:["med","Enfermería"],r:["Control de nefrología","Ingreso al programa"]},{k:"examen",l:"Examen físico pertinente",t:"area",ty:["med"],r:["Control de nefrología","Ingreso al programa","Valoración urgente"]}]],
 ["Catéter y orificio de salida",[{k:"orificio",l:"Orificio de salida",t:"sel",o:["Normal","Inflamación sin infección","Infección del orificio","Infección del túnel","Incierta","No evaluado"],ty:["med","Enfermería"],r:["med","Enfermería"]},{k:"orificio_d",l:"Descripción del orificio y del túnel",t:"text",ty:["med","Enfermería"]},{k:"cat_func",l:"Funcionamiento del catéter",t:"sel",o:["Adecuado","Drenaje lento","Obstrucción","Fuga","Dolor de infusión o drenaje","No evaluado"],ty:["med","Enfermería"],r:["Control de nefrología","Ingreso al programa","Enfermería"]}]],
 ["Diálisis peritoneal",[{k:"modalidad",l:"Modalidad",t:"sel",o:["DPCA","DPA"],ty:["med","Enfermería"],r:["Control de nefrología","Ingreso al programa"],cac:"Var 49"},{k:"presc_conc",l:"Terapia frente a la prescripción vigente",t:"sel",o:["Concordante","Con ajustes del paciente","No adherente","No evaluado"],ty:["med","Enfermería"],r:["Control de nefrología"]},
   {k:"diuresis",l:"Diuresis residual (mL/24 h)",t:"num",min:0,max:6000,ty:["med","Enfermería"],r:["Control de nefrología","Ingreso al programa"],cac:"Var 35 (código según diuresis)"},{k:"diuresis_f",l:"Fuente de la diuresis",t:"sel",o:["Medida (recolección de 24 h)","Referida por el paciente","Anuria documentada","Sin dato"],ty:["med","Enfermería"],r:["Control de nefrología","Ingreso al programa"]},
   {k:"uf",l:"Ultrafiltración neta (mL/24 h)",t:"num",min:-3000,max:6000,ty:["med","Enfermería"],r:["Control de nefrología"]},{k:"adec",l:"Análisis de adecuación (síntomas, volumen, depuración, FRR)",t:"area",ty:["Control de nefrología","Ingreso al programa"],r:["Control de nefrología"]}]],
 ["Paraclínicos",[{k:"paracl",l:"Revisión de paraclínicos con fecha y evolución",t:"area",ty:["med","Nutrición"],r:["Control de nefrología","Ingreso al programa","Nutrición"],cac:"Var 59-61 (Hb, albúmina, fósforo)"}]],
 ["Anemia, nutrición, mineral-óseo y complicaciones",[{k:"anemia",l:"Anemia",t:"area",ty:["Control de nefrología","Ingreso al programa"],r:["Control de nefrología"]},{k:"nutri",l:"Estado nutricional",t:"area",ty:["Control de nefrología","Ingreso al programa","Nutrición"],r:["Control de nefrología","Nutrición"]},{k:"mo",l:"Alteraciones mineral-óseas",t:"area",ty:["Control de nefrología","Ingreso al programa"],r:["Control de nefrología"]},{k:"complic",l:"Complicaciones",t:"area",ty:["med"],r:[]}]],
 ["Adherencia, educación y condiciones del tratamiento",[{k:"adher",l:"Adherencia",t:"sel",o:["Adecuada","Parcial","No adherente","No evaluada"],ty:["med","Enfermería","Psicología","Trabajo social"],r:["Control de nefrología","Enfermería"]},{k:"educ",l:"Educación dada",t:"area",ty:["med","Enfermería","Nutrición"],r:["Enfermería"]},{k:"cond",l:"Condiciones de realización del tratamiento (domicilio, cuidador, red de apoyo)",t:"area",ty:["Control de nefrología","Ingreso al programa","Enfermería","Trabajo social","Psicología"],r:["Ingreso al programa","Trabajo social"]}]],
 ["Trasplante renal",[{k:"tx_eval",l:"Evaluación de trasplante en esta atención",t:"sel",o:["No aplica en esta atención","Sin cambios","Idóneo, en estudio","Remitido a IPS trasplantadora","En lista de espera","No idóneo (contraindicación)","Disentimiento","Cuidados paliativos","No evaluado"],ty:["Control de nefrología","Ingreso al programa"],r:["Ingreso al programa"],cac:"Var 62 (el estado oficial se registra en Tratamiento → Trasplante)"}]],
 ["Diagnósticos, análisis y plan",[{k:"dx",l:"Diagnósticos (CIE-10)",t:"area",ty:"all",r:["med"]},{k:"analisis",l:"Análisis",t:"area",ty:"all",r:"all",e:1},{k:"plan",l:"Plan integral",t:"area",ty:"all",r:"all",e:1}]],
 ["Órdenes, remisiones y seguimiento",[{k:"ordenes",l:"Órdenes (laboratorios, medicamentos, procedimientos)",t:"area",ty:["med"],r:[]},{k:"remis",l:"Remisiones e interconsultas",t:"area",ty:["med","Enfermería","Nutrición","Psicología","Trabajo social"],r:[]},{k:"recom",l:"Recomendaciones",t:"area",ty:"all",r:[]},{k:"alarma",l:"Signos de alarma explicados",t:"sel",o:["Sí, explicados y comprendidos","No","No aplica"],ty:["med","Enfermería"],r:["med","Enfermería"]},{k:"prox",l:"Próximo control",t:"date",ty:"all",r:["Control de nefrología","Ingreso al programa"]}]],
 ["Profesional responsable",[{k:"firma",l:"Nombre del profesional",t:"text",ty:"all",r:"all",e:1},{k:"registro",l:"Registro profesional",t:"text",ty:"all",r:"all"}]]];
const dpVType=(f,tipo)=>{const ty=f.ty;if(ty==="all")return true;const L=Array.isArray(ty)?ty:[ty];return L.includes(tipo)||(L.includes("med")&&DP_MED.includes(tipo));};
const dpVReq=(f,tipo)=>{const r=f.r;if(!r)return false;if(r==="all")return true;const L=Array.isArray(r)?r:[r];return L.includes(tipo)||(L.includes("med")&&DP_MED.includes(tipo));};
function dpVAudit(tipo,D){const out=[];DPV.forEach(([sec,F])=>F.forEach(f=>{if(!dpVType(f,tipo)||!dpVReq(f,tipo))return;const v=D[f.k];const empty=v==null||v===""||(Array.isArray(v)&&!v.length);
  const st=empty?"Ausente":(DPV_ND.includes(v)||v==="No evaluada"||(f.k==="diuresis_f"&&v==="Referida por el paciente"))?"Pendiente de verificación":"Completo";out.push({f,sec,st});}));
  const n=out.length,c=out.filter(x=>x.st==="Completo").length;return{L:out,pct:n?Math.round(c/n*100):100,miss:out.filter(x=>x.st!=="Completo")};}
function dpValNew(pid,tipo,ageId){if(!dpGuard("val"))return;const p=dpPac(pid);const D={modo:"Presencial",firma:PX.user?PX.user.Nombre:"",talla:p&&p.Talla?String(p.Talla):"",comorb:p?dpJ(p.Comorbilidades,[]):[],modalidad:p?p.Modalidad||"":""};
  DP.ui.vedit={id:null,pid:pid||"",tipo:tipo||"Control de nefrología",fecha:iso(TODAY()),D,age:ageId||""};PX.ui.sub="val";pxGo("dp","val");}
function dpValOpen(id){const v=DP.book.val.find(x=>x.ID===id);if(!v)return;DP.ui.vedit={id,pid:v.Paciente,tipo:v.Tipo,fecha:iso(v6d(v.Fecha)),D:dpJ(v.Datos,{}),age:v.Agenda||""};pxGo("dp","val");}
function dpValEditor(){const E=DP.ui.vedit;const v=E.id?DP.book.val.find(x=>x.ID===E.id):null;const ro=v&&v.Estado!=="Borrador";const p=dpPac(E.pid);const tipo=E.tipo;const D=E.D;const au=dpVAudit(tipo,D);
  let h='<div class="copyrow"><button type="button" class="btn sm" data-p="d8vclose">‹ Volver al registro</button>'+(p?'<button type="button" class="btn sm" data-p="d8ficha|'+p.ID+'">Ficha del paciente</button>':'')+'</div>';
  h+='<div class="panel d8head"><div><p class="eyebrow">'+(v?esc(v.ID)+(v.Version>1?' · versión '+v.Version:'')+' · '+esc(v.Estado):'Nueva valoración')+(v&&v.VersionDe?' · corrige '+esc(v.VersionDe):'')+'</p><h2 class="mt">'+esc(tipo)+(p?' · '+esc(dpNombre(p)):'')+'</h2>'+(v&&v.MotivoCorreccion?'<p class="note">Motivo de la corrección: '+esc(v.MotivoCorreccion)+'</p>':'')+'</div><div class="d8score '+(au.pct>=90?"ok":au.pct>=70?"warn":"bad")+'"><b>'+au.pct+' %</b><span>completitud</span></div></div>';
  if(ro){h+=dpValRead(v,p,D,au);return h;}
  h+='<div class="panel"><div class="form"><label class="f">Paciente *<select id="vf__p"'+(E.id?" disabled":"")+'>'+dpPacOpts(E.pid,"Seleccione…")+'</select></label><label class="f">Tipo de atención *<select id="vf__t">'+opt(DP_VAL_TIPOS,tipo)+'</select></label><label class="f">Fecha *<input type="date" id="vf__f" value="'+esc(E.fecha)+'" max="'+iso(TODAY())+'"></label></div>'+
   (tipo==="Valoración urgente"?'<p class="note">Valoración urgente: para finalizar solo se exigen motivo, análisis, plan y profesional. Lo demás se audita, pero no bloquea.</p>':'')+'</div>';
  const pre=p?dpPreVig(p.ID):null;
  DPV.forEach(([sec,F])=>{const fs=F.filter(f=>dpVType(f,tipo));if(!fs.length)return;
    h+='<details class="panel d8sec" open><summary><h3 style="display:inline">'+esc(sec)+'</h3></summary>';
    if(sec==="Diálisis peritoneal"&&p){const kt=dpLast(p.ID,"KtV"),pet=dpLast(p.ID,"PET");h+='<p class="note">Prescripción vigente: <strong>'+esc(dpPreTxt(pre))+'</strong> · último Kt/V total: '+(kt?esc(kt.Valor)+' ('+fd(v6d(kt.FechaToma))+')':'sin dato')+' · PET: '+(pet?esc(pet.Valor)+' '+dpPET(num(pet.Valor)):'sin dato')+'</p>';}
    if(sec==="Paraclínicos"&&p){h+='<div class="tablebox"><table class="dense mini"><thead><tr><th>Examen</th><th>Último</th><th>Anterior</th><th>Evolución</th></tr></thead><tbody>'+["Hb","Alb","P","Ca","PTH","K","Ferritina","TSAT","KtV","Diuresis"].map(k=>{const L=dpLabs(p.ID,k).filter(l=>num(l.Valor)!=null);const a=L[L.length-1],b=L[L.length-2];
      return'<tr><td>'+esc(DPX[k].l)+'</td><td class="mono">'+(a?esc(a.Valor)+' · '+fd(v6d(a.FechaToma)):'—')+'</td><td class="mono">'+(b?esc(b.Valor)+' · '+fd(v6d(b.FechaToma)):'—')+'</td><td>'+(a&&b?(num(a.Valor)>num(b.Valor)?"↑":num(a.Valor)<num(b.Valor)?"↓":"=")+" "+f1(num(a.Valor)-num(b.Valor),2):'')+'</td></tr>';}).join("")+'</tbody></table></div>';}
    h+='<div class="form">'+fs.map(f=>dpVField(f,D[f.k],tipo)).join("")+'</div></details>';});
  h+='<div class="panel d8sticky"><div class="copyrow"><button type="button" class="btn" data-p="d8vsave|draft">Guardar borrador</button>'+(dpCan("valfin")?'<button type="button" class="btn primary" data-p="d8vsave|fin">Finalizar valoración</button>':'<span class="note">Su rol no finaliza valoraciones.</span>')+'<span class="note">Faltan '+au.miss.length+' de '+au.L.length+' ítems auditados'+(au.miss.length?': '+esc(au.miss.slice(0,6).map(x=>x.f.l).join(", "))+(au.miss.length>6?"…":""):"")+'</span></div></div>';
  return h;}
function dpVField(f,v,tipo){const id="vf_"+f.k;const req=dpVReq(f,tipo);const lab='<span class="d8lab">'+esc(f.l)+(f.e?" *":req?' <span class="d8req" title="Auditado para completitud">●</span>':"")+(f.cac?' <span class="tag cac" title="'+esc(f.cac)+'">CAC</span>':"")+'</span>';
  if(f.t==="area")return'<label class="f wide">'+lab+'<textarea id="'+id+'" rows="3">'+esc(v||"")+'</textarea></label>';
  if(f.t==="chk"){const S=new Set(Array.isArray(v)?v:[]);return'<fieldset class="f wide d8fs"><legend>'+lab+'</legend><div class="chkcol">'+f.o.map((o,i)=>'<label class="chk"><input type="checkbox" data-vchk="'+f.k+'" value="'+esc(o)+'"'+(S.has(o)?" checked":"")+'> '+esc(o)+'</label>').join("")+'</div></fieldset>';}
  if(f.t==="sel")return'<label class="f">'+lab+'<select id="'+id+'">'+opt(f.o,v||"","—")+'</select></label>';
  if(f.t==="num")return'<label class="f">'+lab+'<input type="number" step="any" id="'+id+'" value="'+esc(v??"")+'"'+(f.min!=null?' min="'+f.min+'"':'')+(f.max!=null?' max="'+f.max+'"':'')+'></label>';
  return'<label class="f'+(f.t==="text"?" wide":"")+'">'+lab+'<input type="'+(f.t==="date"?"date":f.t==="time"?"time":"text")+'" id="'+id+'" value="'+esc(v||"")+'"></label>';}
function dpValCollect(){const E=DP.ui.vedit;const D=Object.assign({},E.D);DPV.forEach(([s,F])=>F.forEach(f=>{if(f.t==="chk"){const el=document.querySelectorAll('[data-vchk="'+f.k+'"]');if(el.length)D[f.k]=[...el].filter(x=>x.checked).map(x=>x.value);return;}const el=$("vf_"+f.k);if(el)D[f.k]=el.value.trim();}));
  if($("vf__p")&&!E.id)E.pid=$("vf__p").value;if($("vf__t"))E.tipo=$("vf__t").value;if($("vf__f"))E.fecha=$("vf__f").value;E.D=D;return D;}
function dpValSave(mode){const E=DP.ui.vedit;const D=dpValCollect();if(!dpGuard(mode==="fin"?"valfin":"val"))return;
  if(!E.pid){toast("Elija el paciente.");return;}const f=pdate(E.fecha);if(!f){toast("La fecha es obligatoria.");return;}if(f>TODAY()){toast("La fecha no puede ser futura.");return;}
  const errs=[];DPV.forEach(([s,F])=>F.forEach(x=>{if(x.t==="num"&&D[x.k]!==""&&D[x.k]!=null){const n=num(D[x.k]);if(n==null||(x.min!=null&&n<x.min)||(x.max!=null&&n>x.max))errs.push(x.l+" fuera de rango");}}));if(errs.length){toast(errs.join(" · "));return;}
  const au=dpVAudit(E.tipo,D);
  if(mode==="fin"){const ess=[];DPV.forEach(([s,F])=>F.forEach(x=>{if(x.e&&dpVType(x,E.tipo)&&!String(D[x.k]||"").trim())ess.push(x.l);}));if(ess.length){toast("Para finalizar faltan: "+ess.join(", ")+".");return;}}
  let v=E.id?DP.book.val.find(x=>x.ID===E.id):null;const base={Paciente:E.pid,Fecha:f,Tipo:E.tipo,Profesional:D.firma||v6who(),Datos:JSON.stringify(D),Completitud:au.pct};
  if(!v){v=dpAdd("val","V-",Object.assign(base,{Estado:"Borrador",Version:E.ver||1,VersionDe:E.de||"",MotivoCorreccion:E.motivo||"",Agenda:E.age||""}));E.id=v.ID;}else dpUpd("val",v,base);
  if(mode==="fin"){dpUpd("val",v,{Estado:v.VersionDe?"Finalizada (corrección)":"Finalizada",FinalizadaPor:dpWho(),FinalizadaEn:nowTs()});
    if(v.VersionDe){const o=DP.book.val.find(x=>x.ID===v.VersionDe);if(o)dpUpd("val",o,{Estado:"Reemplazada"});}
    if(v.Agenda){const a=DP.book.age.find(x=>x.ID===v.Agenda);if(a&&a.Estado!=="Realizada"){dpPushHist(a,{de:a.Estado,a:"Realizada",m:"Valoración "+v.ID+" finalizada"});dpUpd("age",a,{Estado:"Realizada",FechaRealizacion:f,Registro:"val|"+v.ID,Resultado:"Valoración finalizada"});}}
    toast("Valoración "+v.ID+" finalizada. Completitud "+au.pct+" %.");}else toast("Borrador "+v.ID+" guardado.");
  DP.dirty=true;pxRefresh();}
function dpValCorrect(id){if(!dpGuard("valfin"))return;const v=DP.book.val.find(x=>x.ID===id);
  openDlg("Corregir valoración "+id,'<p class="note">La versión finalizada no se modifica: se crea una versión nueva con los mismos datos para corregir. Al finalizarla, la anterior queda como «Reemplazada» y ambas se conservan.</p><label class="f wide">Motivo de la corrección *<input type="text" id="vc_m"></label>',"Crear versión de corrección",()=>{const m=$("vc_m").value.trim();if(m.length<6)return"Describa el motivo (mínimo 6 caracteres).";
   if(DP.book.val.some(x=>x.VersionDe===id&&x.Estado==="Borrador"&&lv(x)))return"Ya hay una corrección en borrador de esta valoración.";
   DP.ui.vedit={id:null,pid:v.Paciente,tipo:v.Tipo,fecha:iso(v6d(v.Fecha)),D:dpJ(v.Datos,{}),age:"",ver:(num(v.Version)||1)+1,de:v.ID,motivo:m};setTimeout(()=>{dpValSave("draft");},0);});}
function dpValRead(v,p,D,au){let h='<div class="grid2 d8two"><div class="panel"><h3>Contenido</h3><dl class="d8dl">'+DPV.flatMap(([s,F])=>F.filter(f=>dpVType(f,v.Tipo)&&D[f.k]!=null&&D[f.k]!==""&&!(Array.isArray(D[f.k])&&!D[f.k].length)).map(f=>'<dt>'+esc(f.l)+'</dt><dd>'+esc(Array.isArray(D[f.k])?D[f.k].join(", "):D[f.k])+'</dd>')).join("")+'</dl><p class="note">Fecha '+fd(v6d(v.Fecha))+' · registró '+esc(v.Usuario||"")+' · '+esc(v.Registrado||"")+(v.FinalizadaPor?' · finalizó '+esc(v.FinalizadaPor)+' '+esc(v.FinalizadaEn||""):"")+'</p></div>';
  h+='<div class="panel"><h3>Auditoría de completitud</h3>'+dpTbl([["Ítem",x=>esc(x.f.l)+'<span class="sub">'+esc(x.sec)+'</span>'],["Estado",x=>dpStChip(x.st,x.st==="Completo"?"ok":x.st==="Ausente"?"bad":"warn")],["CAC",x=>x.f.cac?'<span class="tag cac">'+esc(x.f.cac)+'</span>':""]],au.L)+'</div></div>';
  const ver=DP.book.val.filter(x=>x.ID===v.VersionDe||x.VersionDe===v.ID);
  h+='<div class="panel"><div class="mhead"><h3 style="margin:0">Texto para la historia clínica (SIIS)</h3><div class="copyrow"><button type="button" class="btn sm" data-p="d8vcopy|'+v.ID+'">Copiar</button>'+(v.Estado!=="Reemplazada"?dpCanBtn("valfin","d8vcor|"+v.ID,"Registrar corrección"):'')+'</div></div><pre class="d8hc" id="d8hc">'+esc(dpHC(v,p,D))+'</pre>'+(ver.length?'<p class="note">Otras versiones: '+ver.map(x=>'<button type="button" class="lnk" data-p="d8vopen|'+x.ID+'">'+esc(x.ID)+' ('+esc(x.Estado)+')</button>').join(" · ")+'</p>':'')+'<p class="note">El SIGC propone el texto auditado; la historia clínica oficial sigue siendo SIIS.</p></div>';return h;}
function dpHC(v,p,D){const L=[];const ln=(t,x)=>{if(x!=null&&x!==""&&!(Array.isArray(x)&&!x.length))L.push(t+": "+(Array.isArray(x)?x.join(", "):x));};
  L.push(v.Tipo.toUpperCase()+" · DIÁLISIS PERITONEAL · "+fd(v6d(v.Fecha))+(D.hora?" "+D.hora:"")+" · "+(D.modo||""));if(p)L.push("Paciente: "+dpNombre(p)+" · "+(p.TipoDoc||"")+" "+(p.Documento||"")+(dpEdad(p,v6d(v.Fecha))!=null?" · "+dpEdad(p,v6d(v.Fecha))+" años":""));
  ln("Motivo",D.motivo);ln("Enfermedad actual",D.ea);ln("Síntomas",D.sint);ln("Antecedentes",D.antec);ln("Comorbilidades",D.comorb);ln("Tratamiento",D.meds);
  const sv=[D.ta_s?"TA "+D.ta_s+"/"+(D.ta_d||"?")+" mmHg":"",D.fc?"FC "+D.fc:"",D.temp?"T "+D.temp+" °C":"",D.peso?"peso "+D.peso+" kg":"",D.talla?"talla "+D.talla+" cm":"",D.edema?"edema "+D.edema:"",D.volumen?"volumen: "+D.volumen:""].filter(Boolean).join(", ");ln("Signos vitales y volumen",sv);ln("Examen físico",D.examen);
  ln("Orificio de salida",[D.orificio,D.orificio_d].filter(Boolean).join(". "));ln("Catéter",D.cat_func);
  if(p){const pre=dpPreVig(p.ID,v6d(v.Fecha));ln("Diálisis",(D.modalidad||p.Modalidad||"")+" · prescripción: "+dpPreTxt(pre)+(D.presc_conc?" · "+D.presc_conc:""));}
  ln("Diuresis residual",D.diuresis?D.diuresis+" mL/24 h ("+(D.diuresis_f||"fuente sin dato")+")":D.diuresis_f);ln("UF neta",D.uf?D.uf+" mL/24 h":"");ln("Adecuación",D.adec);
  if(p){const pc=["Hb","Alb","P","Ca","PTH","K","KtV"].map(k=>{const l=dpLast(p.ID,k,null,v6d(v.Fecha));return l?DPX[k].l+" "+l.Valor+" ("+fd(v6d(l.FechaToma))+")":"";}).filter(Boolean).join("; ");ln("Paraclínicos",pc);}
  ln("Revisión de paraclínicos",D.paracl);ln("Anemia",D.anemia);ln("Nutrición",D.nutri);ln("Mineral-óseo",D.mo);ln("Complicaciones",D.complic);ln("Adherencia",D.adher);ln("Educación",D.educ);ln("Condiciones del tratamiento",D.cond);ln("Trasplante",D.tx_eval);
  ln("Diagnósticos",D.dx);ln("Análisis",D.analisis);ln("Plan",D.plan);ln("Órdenes",D.ordenes);ln("Remisiones",D.remis);ln("Recomendaciones",D.recom);ln("Signos de alarma",D.alarma);ln("Próximo control",D.prox?fd(pdate(D.prox)):"");
  L.push("Profesional: "+(D.firma||v.Profesional||"")+(D.registro?" · RM "+D.registro:""));return L.join("\n");}
function dpValAudit(){const T=TODAY();const ms=addDays(addMonths(T,-3),1);const V=dpR("val").filter(v=>/Finalizada/.test(v.Estado||"")&&v6d(v.Fecha)>=ms);const agg={};
  V.forEach(v=>dpVAudit(v.Tipo,dpJ(v.Datos,{})).L.forEach(x=>{const k=x.f.k;const a=agg[k]=agg[k]||{f:x.f,n:0,ok:0,aus:0,pv:0};a.n++;if(x.st==="Completo")a.ok++;else if(x.st==="Ausente")a.aus++;else a.pv++;}));
  const act=DP.book.pac.filter(lv).filter(p=>dpActivo(p,T));
  let h='<div class="panel"><h3>Por paciente: última valoración finalizada</h3>'+dpTbl([["Paciente",p=>dpPacLink(p)],["Última valoración",p=>{const v=dpValsOf(p.ID).pop();return v?fd(v6d(v.Fecha))+'<span class="sub">'+esc(v.Tipo)+'</span>':'<span class="st bad">ninguna</span>';}],["Completitud",p=>{const v=dpValsOf(p.ID).pop();if(!v)return"—";const a=dpVAudit(v.Tipo,dpJ(v.Datos,{}));return'<span class="st '+(a.pct>=90?"ok":a.pct>=70?"warn":"bad")+'">'+a.pct+' %</span>';},"num"],["Faltantes",p=>{const v=dpValsOf(p.ID).pop();if(!v)return"";return'<span style="font-size:12.5px">'+esc(dpVAudit(v.Tipo,dpJ(v.Datos,{})).miss.map(x=>x.f.l+(x.st!=="Ausente"?" (por verificar)":"")).join(", "))+'</span>';}],["",p=>{const v=dpValsOf(p.ID).pop();return v?dpBtn("d8vopen|"+v.ID,"Ver"):"";}]],act,"Sin pacientes activos.")+'</div>';
  h+='<div class="panel"><h3>Por ítem: valoraciones finalizadas de los últimos 3 meses ('+V.length+')</h3>'+dpTbl([["Ítem",a=>esc(a.f.l)],["Aplica",a=>a.n,"num"],["Completo",a=>a.ok,"num"],["Ausente",a=>a.aus,"num"],["Por verificar",a=>a.pv,"num"],["Cumplimiento",a=>'<span class="st '+(a.ok/a.n>=0.9?"ok":a.ok/a.n>=0.7?"warn":"bad")+'">'+Math.round(a.ok/a.n*100)+' %</span>',"num"],["Variable CAC",a=>a.f.cac?'<span class="tag cac">'+esc(a.f.cac)+'</span>':""]],Object.values(agg).sort((a,b)=>a.ok/a.n-b.ok/b.n),"Sin valoraciones finalizadas en el periodo.")+'<p class="note">Los ítems se exigen según el tipo de atención (una valoración de nutrición no se audita por el orificio de salida). «Por verificar» = registrado como no evaluado, sin dato o diuresis referida sin medir. El color (≥ 90 % verde, 70-89 % ámbar) es una referencia de lectura, no una meta adoptada.</p></div>';return h;}


/* ------------------------------ 4. Agenda ------------------------------ */
function dpAgeFilt(){const F=DP.ui.af||{};return dpR("age").filter(a=>{const p=dpPac(a.Paciente);return(!F.p||a.Paciente===F.p)&&(!F.pr||norm(a.Profesional)===norm(F.pr))&&(!F.t||a.Tipo===F.t)&&(!F.e||dpAgeEst(a)===F.e)&&(!F.eps||(p&&p.EPS===F.eps));});}
function dpAgeView(){const t=dpTab("age","mes");const F=DP.ui.af||{};const profs=[...new Set(dpR("age").map(a=>a.Profesional).filter(Boolean))].sort();
  let h='<div class="mhead">'+dpTabs("age",[["mes","Mes"],["sem","Semana"],["dia","Día"],["lst","Lista"],["plan","Plan heredado"]],t)+dpCanBtn("age","d8agenew|","Nueva actividad","sm primary")+'</div>';
  if(t==="plan")return h+dpAgePlan();
  h+='<div class="panel d8filt"><label class="f">Paciente<select id="d8afp">'+dpPacOpts(F.p,"Todos")+'</select></label><label class="f">Profesional<select id="d8afr">'+opt(profs,F.pr||"","Todos")+'</select></label><label class="f">EPS<select id="d8afe">'+opt(EPS_L,F.eps||"","Todas")+'</select></label><label class="f">Tipo<select id="d8aft">'+opt(DP_AGE_TIPOS,F.t||"","Todos")+'</select></label><label class="f">Estado<select id="d8afs">'+opt(DP_AGE_EST.concat(["Vencida"]),F.e||"","Todos")+'</select></label></div>';
  const A=dpAgeFilt();const T=TODAY();const base=pdate(DP.ui.ad||iso(T));
  const chip=a=>{const p=dpPac(a.Paciente);const e=dpAgeEst(a);return'<button type="button" class="d8ev '+DP_AGE_CLS[e]+'" data-p="d8age|'+a.ID+'" title="'+esc(a.Tipo+" · "+(p?dpNombre(p):a.Paciente)+" · "+e)+'">'+esc((a.Hora?a.Hora+" ":"")+a.Tipo)+'<span>'+esc(p?dpNombre(p):a.Paciente)+'</span></button>';};
  const nav=(step,lbl)=>'<div class="copyrow calbar"><button type="button" class="btn sm" data-p="d8anav|-'+step+'" aria-label="Anterior">‹</button><strong class="calmt">'+lbl+'</strong><button type="button" class="btn sm" data-p="d8anav|'+step+'" aria-label="Siguiente">›</button><button type="button" class="btn sm" data-p="d8anav|0">Hoy</button></div>';
  const byDay=d=>A.filter(a=>iso(v6d(a.Fecha))===iso(d)).sort((x,y)=>String(x.Hora||"").localeCompare(String(y.Hora||"")));
  if(t==="mes"){const first=monthStart(base);const off=(first.getDay()+6)%7;const start=addDays(first,-off);const days=[];for(let i=0;i<42;i++){const d=addDays(start,i);if(i>=35&&d.getMonth()!==base.getMonth())break;days.push(d);}
    h+=nav("m",PMESES[base.getMonth()]+" de "+base.getFullYear())+'<div class="panel calm" style="padding:0"><div class="calgrid calhead">'+CAL_DIAS.map(d=>'<div>'+d+'</div>').join("")+'</div><div class="calgrid">'+days.map(d=>{const L=byDay(d);return'<div class="calday'+(d.getMonth()!==base.getMonth()?" out":"")+(iso(d)===iso(T)?" today":"")+'"><button type="button" class="calnum" data-p="d8aday|'+iso(d)+'">'+d.getDate()+'</button>'+L.slice(0,3).map(chip).join("")+(L.length>3?'<button type="button" class="lnk calmore" data-p="d8aday|'+iso(d)+'">+'+(L.length-3)+' más</button>':'')+'</div>';}).join("")+'</div></div>';}
  else if(t==="sem"){const s=addDays(base,-((base.getDay()+6)%7));const D=[0,1,2,3,4,5,6].map(i=>addDays(s,i));
    h+=nav("w","Semana del "+fd(D[0])+" al "+fd(D[6]))+'<div class="d8week">'+D.map(d=>'<div class="panel d8wd'+(iso(d)===iso(T)?" today":"")+'"><h4><button type="button" class="lnk" data-p="d8aday|'+iso(d)+'">'+CAL_DIAS[(d.getDay()+6)%7]+' '+fd(d).slice(0,5)+'</button></h4>'+(byDay(d).map(chip).join("")||'<p class="note">—</p>')+'</div>').join("")+'</div>';}
  else if(t==="dia"){const L=byDay(base);h+=nav("d",CAL_DIAS[(base.getDay()+6)%7]+" "+fd(base))+'<div class="panel">'+dpAgeTable(L)+dpCanBtn("age","d8agenew||"+iso(base),"Agregar en este día")+'</div>';}
  else{const L=A.sort((a,b)=>(v6d(a.Fecha)||0)-(v6d(b.Fecha)||0));const venc=L.filter(a=>dpAgeEst(a)==="Vencida");h+='<div class="panel">'+(venc.length?'<div class="alert bad"><p>'+venc.length+' actividades vencidas: siguen visibles hasta que se registre su resultado, se reprogramen o se cancelen con motivo.</p></div>':'')+dpAgeTable(L)+'</div>';}
  return h+'<div class="calleg">'+["Programada","Confirmada","Realizada","Reprogramada","Cancelada","Inasistencia","Vencida"].map(e=>'<span><i class="d8i '+DP_AGE_CLS[e]+'"></i>'+e+'</span>').join("")+'</div>';}
function dpAgeTable(L){return dpTbl([["Fecha",a=>'<span class="mono">'+fd(v6d(a.Fecha))+' '+esc(a.Hora||"")+'</span>'+(a.DuracionMin?'<span class="sub">'+a.DuracionMin+' min</span>':'')],["Paciente",a=>dpPacLink(dpPac(a.Paciente))],["Actividad",a=>esc(a.Tipo)+'<span class="sub">'+esc([a.Modalidad,a.Lugar].filter(Boolean).join(" · "))+'</span>'],["Profesional",a=>esc(a.Profesional||"")],["Estado",a=>'<span class="st '+DP_AGE_CLS[dpAgeEst(a)]+'">'+dpAgeEst(a)+'</span>'+(a.Resultado?'<span class="sub">'+esc(v6clip(a.Resultado,60))+'</span>':'')],["",a=>dpBtn("d8age|"+a.ID,"Gestionar")]],L,"Sin actividades con estos filtros.");}
function dpAgePlan(){const H=dpR("her").filter(h=>/^Plan de|Cronograma/.test(h.Tipo));const cur=TODAY().getMonth()+1;
  return'<div class="panel"><p class="note">Planes del archivo de control. No se convierten solos en citas: cada mes pendiente se programa con fecha, hora y profesional reales. El cronograma de líquido peritoneal y PET no se programa de forma periódica sin indicación clínica.</p>'+
   dpTbl([["Paciente",x=>x.Paciente?dpPacLink(dpPac(x.Paciente)):'<span class="sd">general</span>'],["Plan",x=>esc(x.Tipo)+'<span class="sub">'+esc(x.Anotacion)+'</span>'],["Estado",x=>dpStChip(x.Estado,x.Estado==="Pendiente de verificación"?"warn":"ok")],["Meses restantes del año",x=>{const m=(/meses marcados: ([^·.]*)/.exec(x.Anotacion)||[])[1]||"";const L=m.split(",").map(s=>s.trim()).filter(Boolean).map(s=>DP_MESES.indexOf(norm(s))+1).filter(n=>n>=cur);
     if(!x.Paciente||/Cronograma/.test(x.Tipo))return'<span class="sd">—</span>';const tipo=/nutrici/i.test(x.Tipo)?"Valoración de nutrición":"Valoración de trabajo social";return L.map(n=>dpCan("age")?'<button type="button" class="btn sm" data-p="d8agenew|'+x.Paciente+'|'+new Date().getFullYear()+"-"+String(n).padStart(2,"0")+'-01|'+tipo+'|'+x.ID+'">'+DP_MESES[n-1].slice(0,3).toLowerCase()+'</button>':DP_MESES[n-1].slice(0,3).toLowerCase()).join(" ")||'<span class="sd">ninguno</span>';}]],H,"Sin planes heredados.")+'</div>';}

/* ------------------------------ 5. Laboratorios ------------------------------ */
function dpLabView(){const t=dpTab("lab","cal");let h='<div class="mhead">'+dpTabs("lab",[["cal","Calendario"],["res","Resultados"],["ten","Tendencias"],["ktv","Kt/V y PET"],["sol","Solicitud del mes"],["plan","Plan de periodicidad"]],t)+dpCanBtn("lab","d8labnew|","Registrar resultado","sm primary")+'</div>';
  return h+({cal:dpLabCal,res:dpLabRes,ten:dpLabTrend,ktv:dpLabKtv,sol:()=>dpSolView("dp"),plan:dpLabPlan}[t]||dpLabCal)();}
function dpLabCal(){const y=+(DP.ui.ly||TODAY().getFullYear());const P=DP.book.pac.filter(lv).filter(p=>dpActivo(p)||dpDias(p,new Date(y,0,1),new Date(y,11,31))).sort((a,b)=>String(a.ID).localeCompare(b.ID));
  const ks=DP_EX.filter(e=>dpR("plab").some(r=>r.Examen===e.k&&(r.Estado==="Validado"||r.Estado==="Propuesta"))||dpR("lab").some(l=>l.Examen===e.k)).map(e=>e.k);const sym={ok:["✓","ok","con resultado"],rev:["?","warn","resultado sin revisión"],sol:["●","info","solicitado"],no:["✕","bad","no tomada"],venc:["!","bad","vencido"],due:["○","warn","corresponde"],prop:["·","base","propuesto (plan sin validar)"],sinbase:["·","base","sin fecha base"]};
  let h='<div class="panel"><div class="mhead"><div class="copyrow"><button type="button" class="btn sm" data-p="d8ly|'+(y-1)+'">‹</button><strong>'+y+'</strong><button type="button" class="btn sm" data-p="d8ly|'+(y+1)+'">›</button></div><span class="note">'+Object.values(sym).filter((v,i,a)=>a.findIndex(z=>z[2]===v[2])===i).map(([s,c,l])=>'<span class="d8c '+c+'">'+s+'</span> '+l).join(" · ")+'</span></div>';
  if(!dpR("plab").some(r=>r.Estado==="Validado"))h+='<div class="alert warn"><p>El plan de periodicidad no está validado: el calendario muestra lo propuesto («·») y los resultados, pero no marca vencidos. Valídelo en «Plan de periodicidad».</p></div>';
  h+='<div class="tablebox"><table class="dense d8lc"><thead><tr><th>Paciente</th><th>Examen</th>'+PMESES.map(m=>'<th class="num">'+m.slice(0,3)+'</th>').join("")+'</tr></thead><tbody>'+P.map(p=>ks.map((k,i)=>'<tr'+(i===0?' class="d8first"':'')+'>'+(i===0?'<td rowspan="'+ks.length+'">'+dpPacLink(p)+'</td>':'')+'<td>'+esc(DPX[k].l)+'</td>'+PMESES.map((m,j)=>{const mes=y+"-"+String(j+1).padStart(2,"0");const d=dpLabDue(p,k,mes);const s=sym[d.st];return'<td class="num">'+(s?'<button type="button" class="d8c '+s[1]+'" data-p="d8lcell|'+p.ID+'|'+k+'|'+mes+'" title="'+esc(DPX[k].l+" · "+dpMesTxt(mes)+" · "+s[2]+(d.L&&d.L.length?" · "+d.L.map(l=>l.Valor).join(", "):""))+'">'+s[0]+'</button>':'')+'</td>';}).join("")+'</tr>').join("")).join("")+'</tbody></table></div><p class="note">Toque una celda para ver o registrar. El cronograma del archivo de control (líquido peritoneal, Kt/V, orina de 24 h, PET) está en Conciliación como información heredada, no como regla.</p></div>';return h;}
function dpLabRes(){const F=DP.ui.lf||{};const L=dpR("lab").filter(l=>(!F.p||l.Paciente===F.p)&&(!F.k||l.Examen===F.k)&&(!F.e||l.Estado===F.e)).sort((a,b)=>(v6d(b.FechaToma)||0)-(v6d(a.FechaToma)||0)||String(b.ID).localeCompare(a.ID));
  return'<div class="panel"><div class="copyrow d8filt"><label class="f">Paciente<select id="d8lfp">'+dpPacOpts(F.p,"Todos")+'</select></label><label class="f">Examen<select id="d8lfk">'+opt(DP_EX.map(e=>[e.k,e.l]),F.k||"","Todos")+'</select></label><label class="f">Estado<select id="d8lfe">'+opt(["Pendiente de validación","Validado","Corregido"],F.e||"","Todos")+'</select></label></div>'+
   dpTbl([["Toma",l=>'<span class="mono">'+fd(v6d(l.FechaToma))+'</span><span class="sub">resultado '+(v6d(l.FechaResultado)?fd(v6d(l.FechaResultado)):"sin fecha")+'</span>'],["Paciente",l=>dpPacLink(dpPac(l.Paciente))],["Examen",l=>esc((DPX[l.Examen]||{l:l.Examen}).l)+'<span class="sub">'+esc(l.ID)+(num(l.Version)>1?" · v"+l.Version:"")+'</span>'],["Valor",l=>'<strong class="mono">'+esc(l.Valor)+'</strong> '+esc(l.Unidad||""),"num"],["Origen",l=>esc(l.LabOrigen||"")+'<span class="sub">'+esc(l.Metodo||"")+'</span>'],["Estado",l=>dpStChip(l.Estado||"",/^Corregido/.test(l.Estado||"")?"base":l.Estado==="Validado"?"ok":"warn")+(l.Reviso?'<span class="sub">'+esc(l.Reviso)+'</span>':'')],["",l=>dpBtn("d8rec|lab|"+l.ID,"Ver")+(l.Estado==="Pendiente de validación"?dpCanBtn("labval","d8labval|"+l.ID,"Validar"):'')+(!/^Corregido/.test(l.Estado||"")?dpCanBtn("lab","d8labcor|"+l.ID,"Corregir"):'')]],L.slice(0,400),"Sin resultados.")+
   '<p class="note">Un resultado nunca se sobrescribe: «Corregir» crea una versión nueva con su motivo y la anterior queda marcada como corregida. Los indicadores usan la versión vigente.</p></div>';}
function dpLabTrend(){const pid=DP.ui.tp||(DP.book.pac.filter(lv)[0]||{}).ID;const p=dpPac(pid);if(!p)return'<div class="panel empty">Sin pacientes.</div>';
  const ks=["Hb","Alb","P","Ca","PTH","K","Ferritina","TSAT","KtV","Diuresis","UF","PET"];
  let h='<div class="panel"><label class="f" style="max-width:420px">Paciente<select id="d8tp">'+dpPacOpts(pid)+'</select></label></div><div class="d8trend">';
  ks.forEach(k=>{const L=dpLabs(pid,k).filter(l=>num(l.Valor)!=null);const e=DPX[k];if(!L.length){h+='<div class="panel d8tc"><h3>'+esc(e.l)+'</h3><p class="note">Sin resultados.</p></div>';return;}const last=L.slice(-3).reverse();
    const ref={Hb:[10,null,"≥ 10 (dia_14)"],Alb:[3.5,null,"≥ 3,5 (dia_16)"],P:[2.5,6,"2,5-6 (dia_18)"],PTH:[130,600,"130-600 (dia_28)"],Ca:[null,10.5,"≤ 10,5 (dia_30)"],KtV:[1.7,null,"≥ 1,7 (dia_12)"]}[k];
    h+='<div class="panel d8tc"><h3>'+esc(e.l)+(e.u?' <span class="sub" style="display:inline">'+esc(e.u)+'</span>':'')+'</h3>'+dpMiniBars(L.slice(-8).map(l=>({l:fd(v6d(l.FechaToma)).slice(0,5)+"/"+String(v6d(l.FechaToma).getFullYear()).slice(2),v:num(l.Valor),warn:l.Estado==="Pendiente de validación"})),ref)+
     '<table class="dense mini"><tbody>'+last.map(l=>'<tr><td class="mono">'+fd(v6d(l.FechaToma))+'</td><td class="num mono"><strong>'+esc(l.Valor)+'</strong></td><td>'+(l.Estado==="Pendiente de validación"?'<span class="st warn">sin validar</span>':'')+'</td></tr>').join("")+'</tbody></table>'+(ref?'<p class="note" style="margin:4px 0 0">Referencia CAC: '+esc(ref[2])+(k==="PET"?'':'')+'</p>':k==="PET"?'<p class="note" style="margin:4px 0 0">Transporte: '+esc(dpPET(num(last[0].Valor)))+' (Twardowski, GAG-GU-002 num. 11)</p>':'')+'</div>';});
  return h+'</div>';}
function dpMiniBars(S,ref){const W=300,H=110,pad=22;const vals=S.map(s=>s.v);const refs=ref?[ref[0],ref[1]].filter(x=>x!=null):[];const mx=Math.max(...vals,...refs)*1.12||1;const bw=(W-pad-6)/S.length;const Y=v=>H-18-(v/mx)*(H-28);
  return'<svg class="d8svg" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Tendencia">'+refs.map(r=>'<line x1="'+pad+'" x2="'+W+'" y1="'+Y(r)+'" y2="'+Y(r)+'" class="d8ref"/><text x="'+(W-2)+'" y="'+(Y(r)-3)+'" text-anchor="end" class="d8tx">'+String(r).replace(".",",")+'</text>').join("")+
   S.map((s,i)=>{const x=pad+i*bw+bw*0.15,w=bw*0.7,y=Y(s.v);return'<rect x="'+x.toFixed(1)+'" y="'+y.toFixed(1)+'" width="'+w.toFixed(1)+'" height="'+(H-18-y).toFixed(1)+'" class="d8bar'+(s.warn?" warn":"")+'" rx="2"><title>'+esc(s.l+": "+s.v)+'</title></rect><text x="'+(x+w/2).toFixed(1)+'" y="'+(H-5)+'" text-anchor="middle" class="d8tx">'+esc(s.l.slice(0,5))+'</text><text x="'+(x+w/2).toFixed(1)+'" y="'+(y-3).toFixed(1)+'" text-anchor="middle" class="d8tx b">'+String(Math.round(s.v*100)/100).replace(".",",")+'</text>';}).join("")+'</svg>';}
function dpLabKtv(){const K=dpR("lab").filter(l=>["KtV","PET"].includes(l.Examen)).sort((a,b)=>(v6d(b.FechaToma)||0)-(v6d(a.FechaToma)||0));
  return'<div class="panel"><div class="mhead"><div><h3 style="margin:0">Adecuación dialítica</h3><p class="note" style="margin:3px 0 0">El cálculo usa solo datos reales de la recolección. Componentes peritoneal y renal por separado. Algoritmo '+esc(DP_KTV_VER)+': V de Watson; debe validarlo Nefrología con el protocolo institucional antes de usarlo en producción (especificación DP-05).</p></div><div class="copyrow">'+dpCanBtn("lab","d8ktv|","Calcular Kt/V","sm primary")+dpCanBtn("lab","d8labnew|||PET","Registrar PET")+'</div></div>'+
   dpTbl([["Fecha",l=>'<span class="mono">'+fd(v6d(l.FechaToma))+'</span>'],["Paciente",l=>dpPacLink(dpPac(l.Paciente))],["Resultado",l=>(l.Examen==="PET"?"PET D/P creat 4 h ":"Kt/V total ")+'<strong class="mono">'+esc(l.Valor)+'</strong>'+(l.Examen==="PET"?' · '+esc(dpPET(num(l.Valor))):'')],["Componentes",l=>{const c=dpJ(l.Componentes,null);return c?'<span style="font-size:12.5px">peritoneal '+f1(c.p,2)+' · renal '+(c.r==null?"no calculado":f1(c.r,2))+' · V '+f1(c.V,1)+' L'+(c.valido?'':' · <strong>no válido</strong>')+'</span>':'<span class="sd">reportado</span>';}],["Estado",l=>dpStChip(l.Estado,l.Estado==="Validado"?"ok":"warn")],["",l=>dpBtn("d8rec|lab|"+l.ID,"Ver")+(l.Estado==="Pendiente de validación"?dpCanBtn("labval","d8labval|"+l.ID,"Validar"):'')]],K,"Sin mediciones de Kt/V ni PET.")+'</div>';}
function dpLabPlan(){const L=dpR("plab").sort((a,b)=>String(a.Paciente).localeCompare(String(b.Paciente))||DP_EX.findIndex(e=>e.k===a.Examen)-DP_EX.findIndex(e=>e.k===b.Examen));
  return'<div class="panel"><div class="mhead"><div><h3 style="margin:0">Plan de periodicidad de laboratorios</h3><p class="note" style="margin:3px 0 0">Configurable por examen (para todos) o por paciente (según su prescripción). Nada se vuelve obligatorio ni genera vencidos mientras esté «Propuesta» o «Sin definir»: lo validan Dirección Médica, Coordinación de la unidad renal o Nefrología.</p></div>'+dpCanBtn("labval","d8plan|","Agregar regla","sm primary")+'</div>'+
   dpTbl([["Alcance",r=>r.Paciente?dpPacLink(dpPac(r.Paciente)):"Todos los pacientes"],["Examen",r=>esc((DPX[r.Examen]||{l:r.Examen}).l)],["Periodicidad",r=>num(r.Periodicidad)?"cada "+r.Periodicidad+" meses":esc(r.Indicacion||"sin definir")],["Fuente",r=>'<span style="font-size:12.5px">'+esc(r.Fuente||"")+'</span>'],["Estado",r=>dpStChip(r.Estado,r.Estado==="Validado"?"ok":r.Estado==="Propuesta"?"warn":"base")+(r.ValidadoPor?'<span class="sub">'+esc(r.ValidadoPor)+' · '+fd(v6d(r.FechaValidacion))+'</span>':'')],["",r=>dpCanBtn("labval","d8plan|"+r.ID,"Editar o validar")]],L)+'</div>';}
/* solicitud del mes de DP: la misma lista la ve Laboratorio (Laboratorio → Solicitud del mes · DP) */
function dpSolProp(mes){const ms=pdate(mes+"-01");return DP.book.pac.filter(lv).filter(p=>dpActivo(p,ms)||dpActivo(p)).map(p=>({p,ex:DP_EX.filter(e=>!["KtV","KtVp","KtVr","UF","PET","LiqPer"].includes(e.k)).filter(e=>{const d=dpLabDue(p,e.k,mes);return["due","venc"].includes(d.st)||!!dpLabOverdue(p,e.k);}).map(e=>e.k)})).filter(x=>x.ex.length);}
function dpSolView(ctx){const mes=DP.ui.smes||ym(TODAY());const R=dpR("sol").filter(r=>r.Mes===mes);const P=dpSolProp(mes);
  let h='<div class="panel" style="display:grid;gap:10px"><div class="mhead"><div><h3 style="margin:0">Solicitud de laboratorio · diálisis peritoneal · '+esc(dpMesTxt(mes))+'</h3><p class="note" style="margin:3px 0 0">'+(ctx==="lab"?"La genera el plan validado de DP; Laboratorio marca las muestras tomadas y carga los resultados en el historial del paciente.":"Es la misma solicitud que ve Laboratorio. Sale del plan de periodicidad validado y de los exámenes vencidos.")+'</p></div><label class="f" style="min-width:160px">Mes<input type="month" id="d8smes" value="'+mes+'"></label></div>';
  if(!R.length){h+=P.length?'<div class="alert warn"><p>Propuesta sin generar: '+P.length+' pacientes, '+P.reduce((a,x)=>a+x.ex.length,0)+' exámenes.</p></div>'+dpTbl([["Paciente",x=>dpPacLink(x.p)],["Exámenes",x=>x.ex.map(k=>'<span class="tag">'+esc(DPX[k].l)+'</span>').join(" ")]],P)+(dpCan("lab")||dpCan("age")?dpBtn("d8solgen|"+mes,"Generar solicitud","primary"):''):'<p class="note">No hay exámenes que correspondan este mes según el plan validado.'+(dpR("plab").some(x=>x.Estado==="Validado")?'':' El plan aún no está validado.')+'</p>';return h+'</div>';}
  const by={};R.forEach(r=>{(by[r.Paciente]=by[r.Paciente]||[]).push(r);});
  h+=dpTbl([["Paciente",([pid])=>dpPacLink(dpPac(pid))],["Exámenes",([pid,L])=>L.map(r=>{const res=dpLabsIn(pid,r.Examen,pdate(mes+"-01"),monthEnd(pdate(mes+"-01"))).length;return'<span class="st '+(res?"ok":r.Estado==="Muestra tomada"?"warn":r.Estado==="No tomada"?"bad":"base")+'">'+esc(DPX[r.Examen].l)+'</span>';}).join(" ")],["",([pid,L])=>(L.some(r=>r.Estado==="Pendiente")&&dpCan("lab")?dpBtn("d8soltom|"+pid+"|"+mes,"Muestra tomada hoy"):'')+(dpCan("lab")?dpBtn("d8labnew|"+pid,"Cargar resultado"):'')]],Object.entries(by));
  return h+'<p class="note">Verde: con resultado del mes. Ámbar: muestra tomada sin resultado. Gris: pendiente. Rojo: no tomada.</p></div>';}

/* ------------------------------ 6. Tratamiento y seguridad ------------------------------ */
function dpTraView(){const t=dpTab("tra","pre");let h=dpTabs("tra",[["pre","Prescripción"],["cat","Catéter"],["inf","Infecciones y antimicrobianos"],["edu","Educación y domicilio"],["ins","Suministros"],["hos","Hospitalizaciones y modalidad"],["trp","Trasplante y calidad de vida"]],t);
  return h+({pre:dpTraPre,cat:dpTraCat,inf:()=>dpEpis()+dpAtbs(),edu:dpTraEdu,ins:dpTraIns,hos:dpTraHos,trp:dpTraTrp}[t]||dpTraPre)();}
function dpTraPre(){const P=DP.book.pac.filter(lv).filter(p=>dpActivo(p)||dpR("pre").some(r=>r.Paciente===p.ID));
  return'<div class="panel"><div class="mhead"><h3 style="margin:0">Prescripción vigente por paciente</h3>'+dpCanBtn("pre","d8pre|","Nueva prescripción","sm primary")+'</div>'+dpTbl([["Paciente",p=>dpPacLink(p)],["Vigente",p=>{const r=dpPreVig(p.ID);return r?esc(dpPreTxt(r))+'<span class="sub">v'+r.Version+' desde '+fd(v6d(r.VigenteDesde))+' · '+esc(r.Prescriptor||"")+'</span>':'<span class="st warn">sin prescripción</span>';}],["Objetivos",p=>{const r=dpPreVig(p.ID);return r?'<span style="font-size:12.5px">'+esc(dpJ(r.Objetivos,[]).join(", "))+'</span>':"";}],["Versiones",p=>dpR("pre").filter(r=>r.Paciente===p.ID).length,"num"],["",p=>dpCanBtn("pre","d8pre|"+p.ID,"Nueva versión")+(dpR("pre").some(r=>r.Paciente===p.ID)?dpBtn("d8prehist|"+p.ID,"Historial"):"")]],P)+'<p class="note">Cada cambio crea una versión nueva con su motivo; la anterior queda con fecha de fin y no se edita. EPO, hierro y demás medicamentos se registran en la valoración (conciliación), no en la prescripción de DP.</p></div>';}
function dpTraCat(){const P=DP.book.pac.filter(lv).filter(p=>dpActivo(p)||dpR("cat").some(c=>c.Paciente===p.ID));const C=dpR("cat").sort((a,b)=>(v6d(b.Fecha)||0)-(v6d(a.Fecha)||0));const iv=dpCfg("lineaMeses",null);
  return'<div class="panel"><div class="mhead"><h3 style="margin:0">Estado del catéter</h3>'+dpCanBtn("seg","d8cat|","Registrar","sm primary")+'</div>'+(iv?'':'<div class="alert warn"><p>El intervalo de cambio de línea (transfer set) no está parametrizado: depende de la ficha técnica del sistema que use la unidad. Defínalo en Reportes → Roles y parámetros; mientras tanto no se calculan vencimientos.</p></div>')+
   dpTbl([["Paciente",p=>dpPacLink(p)],["Catéter",p=>{const s=dpCatState(p.ID);return s.activo?esc(s.tipo||"tipo sin dato")+'<span class="sub">implante '+fd(s.fi)+' · '+s.dias+' días</span>':'<span class="sd">sin implante registrado</span>';}],["Orificio",p=>{const s=dpCatState(p.ID);return s.val?dpStChip(s.val.Clasificacion||"sin clasificar",/Infección/.test(s.val.Clasificacion||"")?"bad":s.val.Clasificacion==="Normal"?"ok":"warn")+'<span class="sub">'+fd(v6d(s.val.Fecha))+'</span>':'<span class="sd">sin valoración</span>';}],["Cambio de línea",p=>{const s=dpCatState(p.ID);return s.lin?fd(v6d(s.lin.Fecha))+(s.prox?'<span class="sub '+(s.prox<TODAY()?"d8bad":"")+'">próximo '+fd(s.prox)+'</span>':''):'<span class="sd">sin registro</span>';}],["Abiertos",p=>dpCatState(p.ID).abiertas.length,"num"]],P)+'</div>'+
   '<div class="panel"><h3>Registros</h3>'+dpTbl([["Fecha",c=>'<span class="mono">'+fd(v6d(c.Fecha))+'</span>'],["Paciente",c=>dpPacLink(dpPac(c.Paciente))],["Registro",c=>esc(c.Tipo)+(c.TipoCateter?'<span class="sub">'+esc(c.TipoCateter)+'</span>':'')],["Clasificación",c=>esc(c.Clasificacion||"")+(c.Episodio?'<span class="sub">episodio '+esc(c.Episodio)+'</span>':'')],["Responsable",c=>esc(c.Responsable||"")],["Estado",c=>c.Estado?dpStChip(c.Estado,c.Estado==="Abierto"?"warn":"ok"):""],["",c=>dpBtn("d8rec|cat|"+c.ID,"Ver")+(c.Estado==="Abierto"?dpCanBtn("seg","d8close|cat|"+c.ID,"Cerrar"):"")]],C)+'</div>';}
function dpTraEdu(){const P=DP.book.pac.filter(lv).filter(p=>dpActivo(p));const E=dpR("edu").sort((a,b)=>(v6d(b.Fecha)||0)-(v6d(a.Fecha)||0));
  return'<div class="panel"><div class="mhead"><h3 style="margin:0">Entrenamiento y competencia</h3>'+dpCanBtn("seg","d8edu|","Registrar","sm primary")+'</div>'+dpTbl([["Paciente",p=>dpPacLink(p)],["Último entrenamiento",p=>{const s=dpEduState(p.ID);return s.ult?fd(v6d(s.ult.Fecha))+'<span class="sub">'+esc(s.ult.Tipo)+' · '+esc(s.ult.Participante||"")+'</span>':'<span class="sd">sin registro</span>';}],["Resultado",p=>{const s=dpEduState(p.ID);return dpStChip(s.res,s.res==="Competente"?"ok":s.res==="Sin entrenamiento documentado"?"bad":"warn");}],["Visita domiciliaria",p=>{const s=dpEduState(p.ID);return s.vis?fd(v6d(s.vis.Fecha))+'<span class="sub">'+esc(s.vis.Resultado||"")+'</span>':'<span class="sd">sin registro</span>';}]],P)+'<p class="note">La competencia se aprueba por demostración, no por asistencia (especificación DP-08). El reentrenamiento se registra ante déficit observado, peritonitis asociada a técnica, contaminación, hospitalización prolongada o cambio de cuidador.</p></div>'+
   '<div class="panel"><h3>Registros</h3>'+dpTbl([["Fecha",e=>'<span class="mono">'+fd(v6d(e.Fecha))+'</span>'],["Paciente",e=>dpPacLink(dpPac(e.Paciente))],["Tipo",e=>esc(e.Tipo)],["Resultado",e=>esc(e.Resultado||"")+(e.Riesgos?'<span class="sub">riesgos: '+esc(v6clip(e.Riesgos,60))+'</span>':'')],["Seguimiento",e=>e.Seguimiento?fd(v6d(e.Seguimiento)||pdate(e.Seguimiento)):""],["Estado",e=>e.Estado?dpStChip(e.Estado,e.Estado==="Abierto"?"warn":"ok"):""],["",e=>dpBtn("d8rec|edu|"+e.ID,"Ver")+(e.Estado==="Abierto"?dpCanBtn("seg","d8close|edu|"+e.ID,"Cerrar"):"")]],E)+'</div>';}
function dpTraIns(){const P=DP.book.pac.filter(lv).filter(p=>dpActivo(p));const I=dpR("ins").filter(i=>i.Paciente&&i.Estado==="Vigente");const E=dpR("ent").sort((a,b)=>(v6d(b.FechaProgramada)||0)-(v6d(a.FechaProgramada)||0));const pend=dpR("ins").filter(i=>/por confirmar|Sin paciente/.test(i.Estado||""));
  return(pend.length?'<div class="alert warn"><p>'+pend.length+' insumos heredados de «Hoja 1» siguen sin paciente confirmado. <button type="button" class="lnk" data-p="d8tab|pac|con">Ir a conciliación</button></p></div>':'')+
   '<div class="panel"><div class="mhead"><h3 style="margin:0">Insumos prescritos vigentes</h3>'+dpCanBtn("ins","d8ins|","Agregar insumo","sm primary")+'</div>'+dpTbl([["Paciente",p=>dpPacLink(p)],["Insumos vigentes",p=>{const L=I.filter(i=>i.Paciente===p.ID);return L.length?L.map(i=>esc(i.Insumo)+' · '+esc(i.Cantidad??"")+' '+esc(i.Periodo==="Mensual"?"/mes":"("+(i.Periodo||"periodo sin dato")+")")+(i.Origen&&/Hoja 1/.test(i.Origen)?' <span class="tag">heredado</span>':'')).join("<br>"):'<span class="sd">sin insumos registrados</span>';}],["",p=>dpCanBtn("ins","d8ins|"+p.ID,"Agregar")+dpCanBtn("ins","d8ent||"+p.ID,"Programar entrega")]],P)+'</div>'+
   '<div class="panel"><div class="mhead"><h3 style="margin:0">Entregas</h3>'+dpCanBtn("ins","d8ent|","Programar entrega","sm primary")+'</div>'+dpTbl([["Periodo",e=>esc(e.Periodo)+'<span class="sub">programada '+fd(v6d(e.FechaProgramada))+'</span>'],["Paciente",e=>dpPacLink(dpPac(e.Paciente))],["Entregado / requerido",e=>{const It=dpJ(e.Items,[]);return'<span style="font-size:12.5px">'+It.map(x=>esc(x.insumo)+": "+(x.ent??"—")+"/"+(x.req??"—")).join("<br>")+'</span>';}],["Entrega",e=>(v6d(e.FechaEntrega)?fd(v6d(e.FechaEntrega)):"—")+'<span class="sub">'+esc(e.Responsable||"")+(e.SoporteRecibido==="Sí"?" · soporte firmado":e.FechaEntrega?" · SIN soporte":"")+'</span>'],["Estado",e=>dpStChip(e.Estado,e.Estado==="Entregada completa"?"ok":e.Estado==="Programada"?(v6d(e.FechaProgramada)<TODAY()?"bad":"base"):"bad")+(e.Incidencia?'<span class="sub">'+esc(e.Incidencia)+'</span>':'')],["",e=>dpBtn("d8rec|ent|"+e.ID,"Ver")+(e.Estado==="Programada"?dpCanBtn("ins","d8ent|"+e.ID,"Registrar entrega"):"")]],E,"Sin entregas registradas.")+'</div>';}
function dpTraHos(){const H=dpR("hos").sort((a,b)=>(v6d(b.FechaIngreso)||0)-(v6d(a.FechaIngreso)||0));const S=dpR("est").sort((a,b)=>(v6d(b.Fecha)||0)-(v6d(a.Fecha)||0));
  return'<div class="panel"><div class="mhead"><h3 style="margin:0">Hospitalizaciones</h3>'+dpCanBtn("seg","d8hos|","Registrar hospitalización","sm primary")+'</div>'+dpTbl([["Ingreso",h=>'<span class="mono">'+fd(v6d(h.FechaIngreso))+'</span><span class="sub">egreso '+(v6d(h.FechaEgreso)?fd(v6d(h.FechaEgreso)):"—")+'</span>'],["Paciente",h=>dpPacLink(dpPac(h.Paciente))],["Causa",h=>esc(h.Causa||"")+'<span class="sub">'+esc(h.RelacionDP||"")+(h.Episodio?' · '+esc(h.Episodio):'')+'</span>'],["Institución",h=>esc(h.Institucion||"")],["> 24 h",h=>esc(h.Mas24h||"sin dato")],["Desenlace",h=>esc(h.Desenlace||"")],["Estado",h=>dpStChip(h.Estado||"Abierta",h.Estado==="Cerrada"?"ok":"warn")],["",h=>dpCanBtn("seg","d8hos|"+h.ID,"Editar o cerrar")]],H,"Sin hospitalizaciones registradas.")+'</div>'+
   '<div class="panel"><div class="mhead"><h3 style="margin:0">Cambios de estado y de modalidad</h3><span class="note">Se registran desde la ficha del paciente → «Cambiar estado o modalidad»</span></div>'+dpTbl([["Fecha",t=>'<span class="mono">'+fd(v6d(t.Fecha))+'</span>'],["Paciente",t=>dpPacLink(dpPac(t.Paciente))],["Estado",t=>esc(t.EstadoAnterior||"—")+" → <strong>"+esc(t.EstadoNuevo)+"</strong>"],["Modalidad",t=>t.ModalidadNueva&&t.ModalidadNueva!==t.ModalidadAnterior?esc(t.ModalidadAnterior||"—")+" → "+esc(t.ModalidadNueva):""],["Motivo y destino",t=>esc(t.Motivo||"")+(t.Destino?'<span class="sub">'+esc(t.Destino)+'</span>':'')],["Soporte",t=>esc(t.Soporte||"")]],S,"Sin transiciones registradas.")+'<p class="note">El paciente conserva su historia al pasar de DPCA a DPA, a hemodiálisis o al egresar: nada se borra y el tiempo en DP se calcula por intervalos.</p></div>';}
function dpTraTrp(){const P=DP.book.pac.filter(lv).filter(p=>dpActivo(p));const C=dpR("cvr").sort((a,b)=>(v6d(b.Fecha)||0)-(v6d(a.Fecha)||0));
  return'<div class="panel"><div class="mhead"><h3 style="margin:0">Trasplante renal</h3>'+dpCanBtn("seg","d8trp|","Registrar estado","sm primary")+'</div>'+dpTbl([["Paciente",p=>dpPacLink(p)],["Estado vigente",p=>{const t=dpTxAt(p.ID);return t?esc(t.Estado)+'<span class="sub">'+fd(v6d(t.Fecha))+(t.Centro?' · '+esc(t.Centro):'')+'</span>':'<span class="st warn">Sin evaluar</span>';}],["Historia",p=>dpR("trp").filter(t=>t.Paciente===p.ID).length,"num"],["",p=>dpCanBtn("seg","d8trp|"+p.ID,"Actualizar")]],P)+'<p class="note">Alimenta dia_22_adul y la variable 62 del reporte CAC. Exclusiones del consenso: disentimiento, cuidados paliativos y contraindicación con soporte.</p></div>'+
   '<div class="panel"><div class="mhead"><h3 style="margin:0">Calidad de vida relacionada con la salud</h3>'+dpCanBtn("seg","d8cvr|","Registrar evaluación","sm primary")+'</div>'+dpTbl([["Fecha",c=>'<span class="mono">'+fd(v6d(c.Fecha))+'</span>'],["Paciente",c=>dpPacLink(dpPac(c.Paciente))],["Escala",c=>esc(c.Escala)],["Momento",c=>esc(c.Momento||"")],["Puntaje",c=>esc(c.Puntaje??""),"num"],["Profesional",c=>esc(c.Profesional||"")],["Soporte",c=>esc(c.Soporte||"")]],C,"Sin evaluaciones.")+'<p class="note">Solo escalas validadas (consenso, dia_35 y dia_36). La escala la aplica un profesional con formación en soporte renal o el paciente si el instrumento es autoaplicado.</p></div>';}


/* ------------------------------ 7. Indicadores ------------------------------ */
function dpBarChart(d,series){const W=340,H=150,pl=34,pb=26,pt=14;const pct=d.t==="pct";const vals=series.map(s=>s.r.val).filter(v=>v!=null);const mx=pct?100:Math.max(0.5,...vals)*1.25;const Y=v=>pt+(H-pt-pb)*(1-v/mx);const bw=(W-pl-8)/Math.max(series.length,1);
  const grid=(pct?[0,50,100]:[0,mx/2,mx]).map(g=>'<line x1="'+pl+'" x2="'+W+'" y1="'+Y(g).toFixed(1)+'" y2="'+Y(g).toFixed(1)+'" class="d8grid"/><text x="'+(pl-4)+'" y="'+(Y(g)+4).toFixed(1)+'" text-anchor="end" class="d8tx">'+(pct?g+"%":f1(g,1))+'</text>').join("");
  const ref=d.cut?'<line x1="'+pl+'" x2="'+W+'" y1="'+Y(d.cut[0]).toFixed(1)+'" y2="'+Y(d.cut[0]).toFixed(1)+'" class="d8ref"/><text x="'+(W-2)+'" y="'+(Y(d.cut[0])-3).toFixed(1)+'" text-anchor="end" class="d8tx">alto &gt; '+d.cut[0]+'%</text>':'';
  const bars=series.map((s,i)=>{const w=Math.min(bw*0.64,58),x=pl+i*bw+(bw-w)/2;if(s.r.val==null)return'<text x="'+(x+w/2).toFixed(1)+'" y="'+(H-pb-6)+'" text-anchor="middle" class="d8tx">s/d</text><text x="'+(x+w/2).toFixed(1)+'" y="'+(H-8)+'" text-anchor="middle" class="d8tx'+(s.sel?" b":"")+'">'+esc(s.l)+'</text>';
    const y=Y(Math.min(s.r.val,mx));return'<rect x="'+x.toFixed(1)+'" y="'+y.toFixed(1)+'" width="'+w.toFixed(1)+'" height="'+(H-pb-y).toFixed(1)+'" rx="2" class="d8bar '+DP_ST_CLS[s.r.status]+(s.sel?" sel":"")+'"><title>'+esc(s.l+": "+(pct?f1(s.r.val,1)+" %":f1(s.r.val,2))+" ("+s.r.num.length+"/"+(pct?s.r.den.length:f1(s.r.meses||0,1)+" meses")+")")+'</title></rect><text x="'+(x+w/2).toFixed(1)+'" y="'+(y-4).toFixed(1)+'" text-anchor="middle" class="d8tx b">'+(pct?Math.round(s.r.val)+"%":f1(s.r.val,2))+'</text><text x="'+(x+w/2).toFixed(1)+'" y="'+(H-8)+'" text-anchor="middle" class="d8tx'+(s.sel?" b":"")+'">'+esc(s.l)+'</text>';}).join("");
  return'<svg class="d8svg" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+esc(d.n)+'">'+grid+ref+bars+'</svg>';}
function dpIndCard(d,sel,F,series){const r=dpEval(d,sel.c,sel.ps,F);const S=series.map(s=>Object.assign({},s,{r:s.sel||(s.c.getTime()===sel.c.getTime())?r:dpEval(d,s.c,s.ps,F)}));
  return'<div class="panel d8ic"><div class="mhead"><div><p class="eyebrow">'+esc(d.c)+(d.shared?' · compartido HD+DP (estrato DP)':'')+'</p><h3 class="d8ict">'+esc(d.n)+'</h3></div><span class="st '+DP_ST_CLS[r.status]+'">'+DP_ST_TXT[r.status]+'</span></div>'+dpBarChart(d,S)+
   '<p class="d8num"><strong class="mono">'+(r.val==null?"sin datos":d.t==="pct"?f1(r.val,1)+" %":f1(r.val,2))+'</strong>'+(d.t==="pct"?' · '+r.num.length+' / '+r.den.length+' pacientes':(r.val!=null?' '+esc(d.unit):'')+'<span class="sub">'+r.num.length+' eventos / '+f1(r.meses||0,1)+' meses en riesgo'+(r.raw!=null?' = '+f1(r.raw,3)+' por mes-paciente (fórmula del consenso)':'')+'</span>')+'</p>'+
   (r.sd.length?'<p class="note d8warn">'+r.sd.length+' paciente(s) sin datos para evaluar'+(d.t==="rate"&&r.block?': la tasa no se calcula hasta completarlos':'')+'.</p>':'')+
   '<p class="note">'+esc(d.win)+(d.cut?' · puntos de corte: alto &gt; '+d.cut[0]+' %, medio '+d.cut[1]+'-'+d.cut[0]+' %, bajo &lt; '+d.cut[1]+' %':' · punto de corte: línea de base')+'</p><div class="copyrow"><button type="button" class="btn sm" data-p="d8nom|'+d.c+'">Ver nominal</button><details class="d8asum"><summary>Cómo se calcula</summary><p class="note">'+esc(d.asum)+'</p></details></div></div>';}
function dpIndView(){const F=DP.ui.if||{};const sel=dpPerSel();const series=dpPerSeries(sel);const muns=[...new Set(DP.book.pac.filter(lv).map(p=>p.Municipio).filter(Boolean))].sort();const t=dpTab("ind","cac");
  let h='<div class="panel d8filt"><label class="f">Tipo de corte<select id="d8ipt">'+opt([["anual","Periodo CAC (1 jul – 30 jun)"],["mes","Corte mensual de gestión"]],DP.ui.ptype||"anual")+'</select></label>'+((DP.ui.ptype||"anual")==="anual"?'<label class="f">Periodo<select id="d8iper">'+opt(dpPeriods().map(p=>[p.k,p.l]),sel.k)+'</select></label>':'<label class="f">Mes<input type="month" id="d8imes" value="'+esc(sel.mes)+'"></label>')+
   '<label class="f">EPS<select id="d8ieps">'+opt(EPS_L,F.eps||"","Todas")+'</select></label><label class="f">Modalidad<select id="d8imod">'+opt(["DPCA","DPA"],F.mod||"","Todas")+'</select></label><label class="f">Municipio<select id="d8imun">'+opt(muns,F.mun||"","Todos")+'</select></label></div>';
  h+=(sel.prov?'<div class="alert warn"><p><strong>Corte provisional de gestión</strong> ('+fd(sel.ps)+' a '+fd(sel.c)+'). El resultado oficial se calcula con el periodo CAC cerrado (1 jul – 30 jun) y sus exclusiones.</p></div>':'<p class="note">Periodo oficial '+fd(sel.ps)+' a '+fd(sel.c)+'. El consenso 2026 inicia la serie con este periodo: no hay tendencia histórica comparable antes de él.</p>');
  h+=dpTabs("ind",[["cac","Consenso CAC 2026 (DP)"],["op","Operativos institucionales"],["ref","Definiciones"]],t);
  if(t==="ref")return h+dpRef()+dpIndRef();
  if(t==="op")return h+'<p class="note"><span class="tag inst">Institucional</span> No son indicadores CAC. Sirven para gestionar la operación del programa.</p><div class="d8grid">'+DP_OP.map(d=>dpIndCard(d,sel,F,series)).join("")+'</div>';
  const prio=DP_IND8.filter(d=>d.prio),rest=DP_IND8.filter(d=>!d.prio);
  h+='<h3 class="d8gh">Prioritarios · porcentajes</h3><div class="d8grid">'+prio.filter(d=>d.t==="pct").map(d=>dpIndCard(d,sel,F,series)).join("")+'</div>';
  h+='<h3 class="d8gh">Prioritarios · tasas (escala propia, no comparable con los porcentajes)</h3><div class="d8grid">'+prio.filter(d=>d.t==="rate").map(d=>dpIndCard(d,sel,F,series)).join("")+'</div>';
  h+='<details class="panel d8more"'+(DP.ui.imore?" open":"")+'><summary data-p="d8imore"><h3 style="display:inline">Los otros '+rest.length+' indicadores CAC aplicables a DP</h3></summary><div class="d8grid">'+(DP.ui.imore?rest.map(d=>dpIndCard(d,sel,F,series)).join(""):'')+'</div></details>';
  return h+'<div class="copyrow">'+dpCanBtn("exp","d8indexp","Descargar indicadores y nominal")+'</div>';}
function dpIndRef(){return'<div class="panel"><h3>Fuente de los indicadores</h3><p class="note">Cuenta de Alto Costo. Actualización del consenso basado en la evidencia: indicadores mínimos para la medición, evaluación y monitoreo de la gestión del riesgo en adultos con ERC tratados con DP o HD en Colombia. Bogotá: CAC; 2026 (abril). Fichas dia_12, 14, 16, 18, 19, 22, 24, 28, 30, 32, 35 y 36 (adultos). Población: mínimo 90 días continuos en diálisis y en la modalidad a la fecha de corte (Res. 2463 de 2014); se eliminó el filtro de vivos activos. Peritonitis: ISPD 2022 (Li PKT et al., Perit Dial Int. 2022;42(2):110-153). Kt/V y PET: ISPD 2020 y guía institucional GAG-GU-002 v02.</p><p class="note">Supuestos institucionales visibles en cada tarjeta («Cómo se calcula»): cuando el consenso no dice qué valor usar si hay varios en la ventana, se toma el último; el calcio usa el promedio, como dice el consenso.</p></div>';}
function dpNominal(code){const d=DP_IND8.concat(DP_OP).find(x=>x.c===code);if(!d)return;const sel=dpPerSel();const r=dpEval(d,sel.c,sel.ps,DP.ui.if||{});
  const sec=(t,L,cls)=>L&&L.length?'<h4>'+t+' ('+L.length+')</h4><ul class="d8nl">'+L.map(x=>'<li><button type="button" class="lnk" data-p="d8ficha|'+esc(x.p?x.p.ID:"")+'">'+esc(x.p?x.p.ID:"")+'</button> '+esc(x.p?dpNombre(x.p):"")+(x.why?' · <span class="'+(cls||"")+'">'+esc(x.why)+'</span>':'')+'</li>').join("")+'</ul>':'';
  const numIds=new Set(r.num.map(x=>x.p&&x.p.ID));
  openDlg(d.c+" · nominal",'<p class="note">'+esc(d.n)+' · '+esc(sel.l)+' · resultado '+(r.val==null?"sin datos":d.t==="pct"?f1(r.val,1)+" %":f1(r.val,2))+'</p>'+sec("Numerador",r.num)+sec(d.t==="pct"?"Denominador sin cumplir":"Denominador (tiempo en riesgo)",d.t==="pct"?r.den.filter(x=>!numIds.has(x.p.ID)):r.den)+sec("Excluidos",r.excl)+sec("Sin datos para evaluar",r.sd,"d8bad")+(r.rel?sec("Recaídas no contadas",r.rel):"")+'<p class="note">'+esc(d.asum)+'</p>',"Cerrar",()=>{});const ok=$("dlgok");if(ok){const x=$("dlgx");if(x)x.hidden=true;}}

/* ------------------------------ 8. Reportes ------------------------------ */
function dpRepView(){const t=dpTab("rep","cac");let h=dpTabs("rep",[["cac","Reporte CAC — DP"],["exp","Exportaciones"],["pm","Planes de mejora"],["log","Bitácora"],["cfg","Roles y parámetros"]],t);
  return h+({cac:dpRepCac,exp:dpRepExp,pm:dpRepPm,log:dpRepLog,cfg:dpRepCfg}[t]||dpRepCac)();}
function dpRepCac(){const y=TODAY().getMonth()>=6?TODAY().getFullYear():TODAY().getFullYear()-1;const c=pdate(DP.ui.cc||(y+"-06-30")),ps=pdate(DP.ui.cps||((y-1)+"-07-01"));const eps=DP.ui.ceps||"";const R=dpCacRun(c,ps,eps);const nb=R.reduce((a,x)=>a+x.v._blk.length,0),na=R.reduce((a,x)=>a+x.v._adv.length,0);
  let h='<div class="panel"><div class="alert warn"><p><strong>Prevalidación institucional.</strong> Estructura: '+esc(DP_CAC_ESTR)+'. Antes de enviar hay que verificar la versión vigente de la estructura de reporte, el instructivo y las reglas de validación de la CAC. El consenso de indicadores y el anexo de reporte nominal son instrumentos distintos.</p></div>'+
   '<div class="form" style="margin-top:10px"><label class="f">Fecha de corte<input type="date" id="d8cc" value="'+iso(c)+'"></label><label class="f">Inicio del periodo<input type="date" id="d8cps" value="'+iso(ps)+'"></label><label class="f">EPS<select id="d8ceps">'+opt(EPS_L,eps,"Todas")+'</select></label></div></div>';
  h+='<div class="tiles"><div class="tile"><span class="tv">'+R.length+'</span><span class="tl">pacientes de DP en el periodo</span></div><div class="tile '+(nb?"bad":"ok")+'"><span class="tv">'+nb+'</span><span class="tl">hallazgos bloqueantes</span></div><div class="tile '+(na?"warn":"ok")+'"><span class="tv">'+na+'</span><span class="tl">advertencias</span></div><div class="tile '+(R.filter(x=>!x.v._blk.length).length===R.length&&R.length?"ok":"warn")+'"><span class="tv">'+R.filter(x=>!x.v._blk.length).length+'/'+R.length+'</span><span class="tl">pacientes listos</span></div></div>';
  h+='<div class="panel"><div class="mhead"><h3 style="margin:0">Matriz de inconsistencias</h3><div class="copyrow">'+dpCanBtn("exp","d8cacgen","Generar archivo de prevalidación","sm primary")+'</div></div>'+dpTbl([["Incluir",x=>'<input type="checkbox" data-cacsel="'+x.p.ID+'"'+((DP.ui.cacx||{})[x.p.ID]?"":" checked")+' aria-label="Incluir '+esc(x.p.ID)+'">'],["Paciente",x=>dpPacLink(x.p)],["Bloqueantes",x=>x.v._blk.length?'<ul class="d8nl">'+x.v._blk.map(b=>'<li><span class="tag">'+esc(b.k)+'</span> '+esc(b.m)+'</li>').join("")+'</ul>':'<span class="st ok">ninguno</span>'],["Advertencias",x=>x.v._adv.length?'<ul class="d8nl">'+x.v._adv.map(b=>'<li><span class="tag">'+esc(b.k)+'</span> '+esc(b.m)+'</li>').join("")+'</ul>':'—']],R,"No hay pacientes de DP en ese periodo.")+'</div>';
  const C=dpR("cac").sort((a,b)=>String(b.Registrado).localeCompare(String(a.Registrado)));
  h+='<div class="panel"><h3>Histórico de cortes</h3>'+dpTbl([["Corte",x=>esc(x.ID)+' · v'+x.Version+'<span class="sub">'+fd(v6d(x.InicioPeriodo))+' – '+fd(v6d(x.FechaCorte))+' · '+esc(x.EPS||"todas")+'</span>'],["Archivo",x=>'<span style="font-size:12.5px">'+esc(x.Archivo)+'</span><span class="sub">'+esc(x.Usuario)+' · '+esc(x.Registrado)+'</span>'],["Pacientes",x=>x.Pacientes,"num"],["Hallazgos",x=>x.Bloqueantes+' bloq. · '+x.Advertencias+' adv.'+(x.Nota?'<span class="sub">'+esc(x.Nota)+'</span>':'')],["Estado",x=>dpStChip(x.Estado,/Enviado/.test(x.Estado)?"ok":/Aprobado/.test(x.Estado)?"info":/bloqueantes/.test(x.Estado)&&!/sin/.test(x.Estado)?"bad":"warn")+(x.AprobadoPor?'<span class="sub">aprobó '+esc(x.AprobadoPor)+'</span>':'')+(x.EnviadoA?'<span class="sub">enviado a '+esc(x.EnviadoA)+' '+fd(v6d(x.FechaEnvio))+'</span>':'')],["",x=>(/sin bloqueantes/.test(x.Estado)?dpCanBtn("apr","d8cacapr|"+x.ID,"Aprobar"):"")+(/Aprobado/.test(x.Estado)?dpCanBtn("apr","d8cacenv|"+x.ID,"Registrar envío"):"")]],C,"Sin cortes generados.")+'<p class="note">Cada generación guarda versión, responsable, número de hallazgos y una copia de los valores por paciente (hoja CortesCACDetalle), para comparar con la versión anterior. Solo se aprueba un corte sin bloqueantes.</p></div>';
  return h;}
function dpRepExp(){const it=(t,d,a)=>'<div class="panel repbox"><h3>'+t+'</h3><p class="note">'+d+'</p><div class="copyrow">'+(dpCan("exp")?dpBtn(a,"Descargar","btn"):'<span class="note">Su rol no exporta.</span>')+'</div></div>';
  return'<div class="repgrid">'+it("Censo nominal","Registro maestro con estado, modalidad, fechas, datos pendientes por verificar e identificador institucional.","d8x|cen")+it("Valoraciones","Todas las versiones con estado, completitud y texto para HC.","d8x|val")+it("Auditoría de completitud","Ítem por ítem de cada valoración finalizada, con la variable CAC relacionada.","d8x|aud")+
   it("Laboratorios","Historial completo (incluidas versiones corregidas) y último valor por paciente.","d8x|lab")+it("Agenda","Actividades con estado, historial de cambios y registro asociado.","d8x|age")+it("Tratamiento y seguridad","Prescripciones, catéter, episodios, antimicrobianos, educación, hospitalizaciones, transiciones, trasplante y calidad de vida.","d8x|seg")+
   it("Suministros","Insumos prescritos, entregas, faltantes y soporte de recibido.","d8x|ins")+it("Alertas y pendientes","Todas las alertas activas con su severidad.","d8x|al")+it("Libro DP completo","Todas las hojas, para respaldo. Es el archivo que se vuelve a cargar.","dpexp")+'</div>';}
function dpRepPm(){const L=dpR("pm").sort((a,b)=>String(b.Registrado).localeCompare(String(a.Registrado)));
  return'<div class="panel"><div class="mhead"><div><h3 style="margin:0">Planes de mejora</h3><p class="note" style="margin:3px 0 0">Ciclo hallazgo → causa → acción → verificación. Se abren desde un indicador o un hallazgo de auditoría.</p></div>'+dpCanBtn("apr","d8pm|","Nuevo plan","sm primary")+'</div>'+dpTbl([["Indicador o hallazgo",x=>esc(x.Indicador||"")+'<span class="sub">'+esc(x.Periodo||"")+'</span>'],["Hallazgo y causa",x=>esc(x.Hallazgo||"")+'<span class="sub">'+esc(x.Causa||"")+'</span>'],["Acción",x=>esc(x.Accion||"")+'<span class="sub">'+esc(x.Responsable||"")+' · '+(v6d(x.FechaLimite)?fd(v6d(x.FechaLimite)):"")+'</span>'],["Estado",x=>dpStChip(x.Estado||"Abierto",x.Estado==="Cerrado"?"ok":v6d(x.FechaLimite)&&v6d(x.FechaLimite)<TODAY()?"bad":"warn")+(x.Evidencia?'<span class="sub">'+esc(x.Evidencia)+'</span>':'')],["",x=>dpCanBtn("apr","d8pm|"+x.ID,"Gestionar")]],L,"Sin planes de mejora.")+'</div>';}
function dpRepLog(){const L=DP.book.log.slice(-300).reverse();const ch=DP.ui.chain;
  return'<div class="panel"><div class="mhead"><div><h3 style="margin:0">Bitácora del libro DP (solo adición)</h3><p class="note" style="margin:3px 0 0">Cada fila queda encadenada con un resumen criptográfico (SHA-256) al descargar el libro. Al cargarlo se verifica la cadena: si alguien edita o borra filas en Excel, el sistema lo detecta y lo avisa. No lo impide: eso lo hace una base de datos con permisos.</p></div><button type="button" class="btn sm" data-p="d8chain">Verificar ahora</button></div>'+
   (ch?'<div class="alert '+(ch.ok?"ok":"bad")+'"><p>'+(ch.ok?"Cadena íntegra ("+ch.n+" filas verificadas).":"Cadena rota en la fila "+ch.fila+" ("+esc(ch.reg.FechaHora)+" · "+esc(ch.reg.Accion)+").")+'</p></div>':'')+
   dpTbl([["Fecha y hora",r=>'<span class="mono">'+esc(r.FechaHora)+'</span>'],["Usuario",r=>esc(r.Usuario)],["Acción",r=>esc(r.Accion)],["Hoja · registro",r=>esc(r.Hoja)+' · '+esc(r.Registro)],["Detalle",r=>'<span style="font-size:12.5px">'+esc(v6clip(r.Detalle,160))+'</span>'],["Sello",r=>r.Hash?'<span class="mono sub">'+esc(String(r.Hash).slice(0,10))+'…</span>':'<span class="sd">al descargar</span>']],L)+'</div>';}
function dpRepCfg(){const R=DP.book.rol;const C=dpCacCfg();const users=PX.book?PX.book.usr.filter(u=>u.Activo!=="NO"):[];
  let h='<div class="panel"><div class="mhead"><div><h3 style="margin:0">Roles del módulo</h3><p class="note" style="margin:3px 0 0">Separan consulta, registro, modificación, aprobación y exportación. Un usuario con acceso al programa pero sin rol aquí queda en «Solo consulta». El administrador del sistema tiene todos los permisos. La clave del portal disuade, pero sin servidor no es un control de acceso real.</p></div>'+dpCanBtn("cfg","d8rol|","Asignar rol","sm primary")+'</div>'+
   dpTbl([["Usuario",r=>{const u=users.find(x=>String(x.Usuario).toLowerCase()===String(r.Usuario).toLowerCase());return'<strong>'+esc(r.Usuario)+'</strong><span class="sub">'+esc(u?u.Nombre+" · "+u.Cargo:"no está en el libro institucional abierto")+'</span>';}],["Rol",r=>esc(DP_ROLES[r.Rol]||r.Rol)],["Estado",r=>r.Activo==="NO"?dpStChip("Inactivo","base"):dpStChip("Activo","ok")],["Concedido",r=>esc(r.ConcedidoPor||"")+'<span class="sub">'+esc(r.Fecha||"")+' · '+esc(r.Motivo||"")+'</span>'],["",r=>dpCanBtn("cfg","d8rol|"+r.Usuario,"Cambiar")]],R,"Sin roles asignados.")+'</div>';
  h+='<div class="panel"><h3>Matriz de permisos</h3><div class="tablebox"><table class="dense"><thead><tr><th>Rol</th>'+Object.keys(DP_ACC).map(a=>'<th title="'+esc(DP_ACC[a])+'">'+a+'</th>').join("")+'</tr></thead><tbody>'+Object.entries(DP_ROLES).map(([k,l])=>'<tr><td>'+esc(l)+'</td>'+Object.keys(DP_ACC).map(a=>{const P=DP_PERM[k];return'<td class="num">'+(P==="*"||P.split(" ").includes(a)?"✓":"")+'</td>';}).join("")+'</tr>').join("")+'</tbody></table></div><p class="note">'+Object.entries(DP_ACC).map(([k,v])=>'<strong>'+k+'</strong>: '+esc(v)).join(" · ")+'. Todos los roles consultan.</p></div>';
  h+='<div class="panel"><div class="mhead"><h3 style="margin:0">Parámetros</h3>'+dpCanBtn("cfg","d8par","Editar parámetros","sm")+'</div><dl class="d8dl"><dt>Intervalo de cambio de línea</dt><dd>'+(dpCfg("lineaMeses",null)?dpCfg("lineaMeses")+" meses":"sin definir (depende del fabricante del sistema)")+'</dd><dt>Tolerancia de entrega de insumos</dt><dd>'+dpCfg("entregaTol",2)+' días (regla de la plantilla Dashboard DP)</dd><dt>Código de habilitación de la IPS</dt><dd class="mono">'+esc(C.ips)+'</dd><dt>Códigos de EPS para la CAC</dt><dd>'+esc(Object.entries(C.epsCod).map(([k,v])=>k+": "+v).join(" · ")||"sin definir")+'</dd></dl></div>';
  return h;}


/* =================== v0.8 · DP · diálogos de registro =================== */
function dpDlg(t,b,ok,fn,wide){openDlg(t,b,ok,fn);if(wide){const d=document.querySelector("#dlg .dlg");if(d)d.style.width="min(920px,100%)";}}
const dv=id=>{const e=$(id);return e?e.value.trim():"";};
const dvd=id=>pdate(dv(id));const dvn=id=>num(dv(id));
const dpDI=v=>v?iso(v6d(v)):"";

/* ---------- paciente: registro maestro ---------- */
function dpDlgPac(id){if(!dpGuard("pac"))return;const p=id?dpPac(id):null;const o=p||{Modalidad:"DPCA",EstadoPrograma:"Activo"};const K=dpJ(o.CAC,{});const cm=new Set(dpJ(o.Comorbilidades,[]));const vf=dpJ(o.Verif,{});
  dpDlg(p?"Datos maestros · "+p.ID:"Nuevo paciente de DP",(p&&Object.keys(vf).length?'<div class="alert warn"><p>'+Object.values(vf).map(esc).join(" · ")+'</p></div>':'')+
   '<h4>Identificación</h4><div class="form"><label class="f">Tipo doc. *<select id="dp_td">'+opt(["CC","TI","CE","PA","PT","RC","AS","MS","CN"],o.TipoDoc||"","Sin verificar")+'</select></label><label class="f">Documento *<input type="text" id="dp_doc" inputmode="numeric" value="'+esc(o.Documento||"")+'"></label><label class="f">Nombres *<input type="text" id="dp_n" value="'+esc(o.Nombres||"")+'"></label><label class="f">Apellidos *<input type="text" id="dp_a" value="'+esc(o.Apellidos||"")+'"></label>'+(o.NombreFuente?'<p class="note wide">Nombre en la fuente: «'+esc(o.NombreFuente)+'»</p>':'')+
   '<label class="f">Fecha de nacimiento<input type="date" id="dp_fn" value="'+dpDI(o.FechaNac)+'"></label><label class="f">Sexo<select id="dp_sx">'+opt(["Femenino","Masculino"],o.Sexo||"","—")+'</select></label><label class="f">EPS<select id="dp_eps">'+opt(EPS_L,o.EPS||"","—")+'</select></label><label class="f">Régimen<select id="dp_rg">'+opt(CAC_REG,o.Regimen||"","—")+'</select></label>'+
   '<label class="f">Municipio<input type="text" id="dp_mu" list="dp_mul" value="'+esc(o.Municipio||"")+'"><datalist id="dp_mul">'+Object.keys(MUN_DANE).map(m=>'<option value="'+esc(dpTitle(m))+'">').join("")+'</datalist></label><label class="f wide">Dirección<input type="text" id="dp_di" value="'+esc(o.Direccion||"")+'"></label><label class="f">Teléfono<input type="text" id="dp_te" value="'+esc(o.Telefono||"")+'"></label><label class="f">Cuidador<input type="text" id="dp_cu" value="'+esc(o.Cuidador||"")+'"></label><label class="f">Teléfono del cuidador<input type="text" id="dp_tc" value="'+esc(o.TelCuidador||"")+'"></label></div>'+
   '<h4>Programa</h4><div class="form"><label class="f">Modalidad<select id="dp_mo">'+opt(["DPCA","DPA"],o.Modalidad||"","Sin dato")+'</select></label>'+(p?'<label class="f">Estado<input type="text" value="'+esc(dpEstado(o))+'" disabled></label>':'<label class="f">Estado inicial<select id="dp_es">'+opt(DP_ESTADOS.slice(0,3),o.EstadoPrograma)+'</select></label>')+
   '<label class="f">Ingreso al programa (unidad)<input type="date" id="dp_fip" value="'+dpDI(o.FechaIngresoPrograma)+'"></label><label class="f">Inicio de diálisis (cualquier modalidad)<input type="date" id="dp_ftrr" value="'+dpDI(o.FechaInicioTRR)+'"></label><label class="f">Inicio de DP<input type="date" id="dp_fi" value="'+dpDI(o.FechaInicioDP)+'"></label><label class="f">Implante del catéter<input type="date" id="dp_fc" value="'+dpDI(o.FechaCateter)+'"></label>'+(p?'<p class="note wide">Los cambios de estado, de modalidad y el egreso se registran como transición desde la ficha, para conservar el historial.</p>':'')+'</div>'+
   '<h4>Clínicos y CAC</h4><div class="form"><label class="f">Etiología de la ERC<select id="dp_et">'+opt(DP_ETIO,o.Etiologia||"","—")+'</select></label><label class="f">HTA<select id="dp_hta">'+opt(["SI","NO"],o.HTA||"","—")+'</select></label><label class="f">Diabetes<select id="dp_dm">'+opt(["SI","NO"],o.DM||"","—")+'</select></label><label class="f">Tipo de DM (var 20)<input type="text" id="k_dmt" value="'+esc(K.dmTipo||"")+'" placeholder="código CAC"></label><label class="f">Talla (cm)<input type="number" id="dp_ta" value="'+esc(o.Talla??"")+'"></label>'+
   '<label class="f">Paratiroidectomía<select id="dp_ptx">'+opt(["No","Sí, realizada","Sí, programada"],o.Paratiroidectomia||"","Sin dato")+'</select></label><label class="f">Tratamiento antineoplásico<select id="dp_ant">'+opt(["No","Sí"],o.Antineoplasicos||"","Sin dato")+'</select></label><label class="f">Vacunación hepatitis B<select id="dp_vhb">'+opt(["Esquema completo","Esquema incompleto","No vacunado","No respondedor"],o.VacunaVHB||"","Sin dato")+'</select></label>'+
   '<fieldset class="f wide d8fs"><legend>Comorbilidades</legend><div class="chkcol">'+DP_COMORB.map(c=>'<label class="chk"><input type="checkbox" data-pcm value="'+esc(c)+'"'+(cm.has(c)?" checked":"")+'> '+esc(c)+'</label>').join("")+'</div></fieldset>'+
   '<label class="f">Pertenencia étnica (var 11)<select id="k_et">'+opt(CAC_ETNIA,K.etnia||"","—")+'</select></label><label class="f">Grupo poblacional (var 12)<select id="k_gp">'+opt(CAC_GRUPO,K.grupo||"","—")+'</select></label><label class="f">Código DANE municipio<input type="text" id="k_mun" value="'+esc(K.munDane||"")+'" placeholder="si no está en la lista"></label><label class="f">Afiliación a la EPS (var 15)<input type="date" id="k_faf" value="'+esc(K.fafil||"")+'"></label>'+
   '<label class="f">Diagnóstico de HTA (var 19)<input type="date" id="k_fhta" value="'+esc(K.fhta||"")+'"></label><label class="f">Diagnóstico de DM (var 21)<input type="date" id="k_fdm" value="'+esc(K.fdm||"")+'"></label><label class="f">Diagnóstico ERC 5 (var 40)<input type="date" id="k_ferc" value="'+esc(K.fdxerc5||"")+'"></label><label class="f">TFG al iniciar TRR (var 42)<input type="number" id="k_tfg" value="'+esc(K.tfgInicio??"")+'"></label>'+
   '<label class="f">Modo de inicio (var 43)<select id="k_mod">'+opt(CAC_MODO,K.modoInicio||"","—")+'</select></label><label class="f">Código BDUA (var 81)<input type="text" id="k_bd" value="'+esc(K.bdua||"")+'"></label><label class="f wide">Observaciones<input type="text" id="dp_ob" value="'+esc(o.Obs||"")+'"></label></div>',"Guardar",()=>{
    const doc=dv("dp_doc").replace(/\D/g,"");const ch={TipoDoc:dv("dp_td"),Documento:doc,Nombres:dv("dp_n"),Apellidos:dv("dp_a"),FechaNac:dvd("dp_fn"),Sexo:dv("dp_sx"),EPS:dv("dp_eps"),Regimen:dv("dp_rg"),Municipio:dv("dp_mu"),Direccion:dv("dp_di"),Telefono:dv("dp_te"),Cuidador:dv("dp_cu"),TelCuidador:dv("dp_tc"),
      Modalidad:dv("dp_mo"),FechaIngresoPrograma:dvd("dp_fip"),FechaInicioTRR:dvd("dp_ftrr"),FechaInicioDP:dvd("dp_fi"),FechaCateter:dvd("dp_fc"),Etiologia:dv("dp_et"),HTA:dv("dp_hta"),DM:dv("dp_dm"),Talla:dvn("dp_ta"),Paratiroidectomia:dv("dp_ptx"),Antineoplasicos:dv("dp_ant"),VacunaVHB:dv("dp_vhb"),
      Comorbilidades:JSON.stringify([...document.querySelectorAll("[data-pcm]:checked")].map(x=>x.value)),Obs:dv("dp_ob")};
    const K2=Object.assign({},K,{dmTipo:dv("k_dmt"),etnia:dv("k_et"),grupo:dv("k_gp"),munDane:dv("k_mun"),fafil:dv("k_faf"),fhta:dv("k_fhta"),fdm:dv("k_fdm"),fdxerc5:dv("k_ferc"),tfgInicio:dv("k_tfg"),modoInicio:dv("k_mod"),bdua:dv("k_bd")});Object.keys(K2).forEach(k=>{if(K2[k]===""||K2[k]==null)delete K2[k];});ch.CAC=JSON.stringify(K2);
    if(!doc||ch.Nombres.length<2||ch.Apellidos.length<2)return"Documento, nombres y apellidos son obligatorios.";
    const T=TODAY();for(const[k,l]of[["FechaNac","nacimiento"],["FechaIngresoPrograma","ingreso"],["FechaInicioTRR","inicio de diálisis"],["FechaInicioDP","inicio de DP"],["FechaCateter","implante"]])if(ch[k]&&ch[k]>T)return"La fecha de "+l+" no puede ser futura.";
    if(ch.FechaNac&&ch.FechaInicioDP&&ch.FechaInicioDP<ch.FechaNac)return"El inicio de DP no puede ser anterior al nacimiento.";if(ch.FechaInicioTRR&&ch.FechaInicioDP&&ch.FechaInicioDP<ch.FechaInicioTRR)return"El inicio de DP no puede ser anterior al inicio de la diálisis.";
    const dup=DP.book.pac.find(x=>lv(x)&&String(x.Documento).replace(/\D/g,"")===doc&&(!p||x.ID!==p.ID));if(dup)return"Ya existe "+dup.ID+" con ese número de documento.";
    ch.IdInst=dpDocKey(ch.TipoDoc,doc);
    const v2=Object.assign({},vf);if(ch.TipoDoc)delete v2.TipoDoc;if(p&&(ch.Nombres!==p.Nombres||ch.Apellidos!==p.Apellidos)||vf.Nombre&&$("dp_n"))delete v2.Nombre;if(ch.Modalidad&&p&&ch.Modalidad!==p.Modalidad)delete v2.Modalidad;if(ch.FechaInicioDP)delete v2.EstadoPrograma;ch.Verif=JSON.stringify(v2);
    if(p){if(p.Modalidad&&ch.Modalidad!==p.Modalidad&&dpIntervals(p)){ch.Modalidad=p.Modalidad;toast("La modalidad de un paciente en curso se cambia con «Cambiar estado o modalidad», para conservar la fecha del cambio.");}dpUpd("pac",p,ch);}
    else{let mx=0;DP.book.pac.forEach(x=>{const m=/(\d+)$/.exec(x.ID||"");if(m)mx=Math.max(mx,+m[1]);});ch.EstadoPrograma=dv("dp_es")||"Activo";dpAdd("pac","DP",Object.assign({ID:"DP"+String(mx+1).padStart(3,"0"),Origen:"Registro manual"},ch));}
    pxRefresh();toast("Datos guardados.");},true);}

/* ---------- transición de estado o modalidad (nunca se borra al paciente) ---------- */
const DP_DEST=["Hemodiálisis en UNO-P","Hemodiálisis en otra unidad","Trasplante","Fallecimiento","Traslado a otra unidad de DP","Recuperación de función renal","Abandono (disentimiento firmado)","Abandono (sin ubicación tras contactos documentados)","Otro"];
function dpDlgTr(pid){if(!dpGuard("pac"))return;const p=dpPac(pid);const st=dpEstado(p);
  dpDlg("Cambio de estado o modalidad · "+pid,'<p class="note">Estado actual: <strong>'+esc(st)+'</strong> · modalidad '+esc(p.Modalidad||"sin dato")+'. La transición queda con fecha, motivo y soporte; el tiempo en DP se recalcula por intervalos.</p><div class="form"><label class="f">Nuevo estado *<select id="tr_e">'+opt(DP_ESTADOS,st)+'</select></label><label class="f">Modalidad<select id="tr_m">'+opt(["DPCA","DPA"],p.Modalidad||"","Sin cambio")+'</select></label><label class="f">Fecha *<input type="date" id="tr_f" value="'+iso(TODAY())+'"></label><label class="f">Destino (salida a HD o egreso)<select id="tr_d">'+opt(DP_DEST,"","—")+'</select></label><label class="f wide">Motivo *<input type="text" id="tr_mo"></label><label class="f wide">Soporte (documento, acta, nota de HC) — obligatorio para egreso y abandono<input type="text" id="tr_s"></label></div>',"Registrar transición",()=>{
    const e=dv("tr_e"),m=dv("tr_m")||p.Modalidad,f=dvd("tr_f"),d=dv("tr_d"),mo=dv("tr_mo"),s=dv("tr_s");if(!f)return"Fecha obligatoria.";if(f>TODAY())return"La fecha no puede ser futura.";if(mo.length<4)return"Escriba el motivo.";
    if(e===st&&m===p.Modalidad)return"No hay cambio de estado ni de modalidad.";if(["Transición a HD","Egreso"].includes(e)&&!d)return"Indique el destino.";if((e==="Egreso"||/^Abandono/.test(d))&&s.length<4)return"El egreso y el abandono requieren soporte.";
    if(/sin ubicación/.test(d)&&!dpR("age").some(a=>a.Paciente===pid&&/contacto/i.test(a.Resultado||"")))toast("Advertencia: no hay intentos de contacto documentados en la agenda; el consenso los exige para clasificar el abandono.");
    if(DP_EN.includes(e)&&!v6d(p.FechaInicioDP)&&!["Candidato","Preparación"].includes(st)){/* se conserva */}
    dpAdd("est","TR-",{Paciente:pid,Fecha:f,EstadoAnterior:st,EstadoNuevo:e,ModalidadAnterior:p.Modalidad||"",ModalidadNueva:m||"",Motivo:mo,Destino:d,Soporte:s});
    const ch={EstadoPrograma:e,Modalidad:m||p.Modalidad};if(["Transición a HD","Egreso"].includes(e)){ch.FechaFinDP=f;ch.MotivoFin=d;}else if(DP_EN.includes(e)&&v6d(p.FechaFinDP)){ch.FechaFinDP=null;ch.MotivoFin="";}
    if(DP_EN.includes(e)&&!v6d(p.FechaInicioDP)&&["Candidato","Preparación"].includes(st))ch.FechaInicioDP=f;dpUpd("pac",p,ch);pxRefresh();toast("Transición registrada.");});}

/* ---------- agenda: crear y gestionar ---------- */
function dpProfs(){const S=new Set(dpR("age").map(a=>a.Profesional).filter(Boolean));try{if(PX.book)PX.book.usr.filter(u=>u.Activo!=="NO"&&(pxAdmin()||String(u.Programas).includes("dp")||u.Rol==="Administrador")).forEach(u=>S.add(u.Nombre));}catch(e){}try{if(typeof CE!=="undefined"&&CE.book)CE.book.pro.filter(x=>x.Activo!=="NO").forEach(x=>S.add(x.Nombre));}catch(e){}return[...S].sort();}
function dpDlgAgeNew(pid,fecha,tipo,herId){if(!dpGuard("age"))return;
  dpDlg("Programar actividad",'<div class="form"><label class="f wide">Paciente *<select id="ag_p">'+dpPacOpts(pid,"Seleccione…")+'</select></label><label class="f wide">Actividad *<select id="ag_t">'+opt(DP_AGE_TIPOS,tipo||"","Seleccione…")+'</select></label><label class="f">Fecha *<input type="date" id="ag_f" value="'+esc(fecha||iso(TODAY()))+'"></label><label class="f">Hora<input type="time" id="ag_h"></label><label class="f">Duración (min)<input type="number" id="ag_d" min="5" max="480" value="30"></label><label class="f">Profesional<input type="text" id="ag_r" list="ag_rl"><datalist id="ag_rl">'+dpProfs().map(x=>'<option value="'+esc(x)+'">').join("")+'</datalist></label><label class="f">Modalidad<select id="ag_m">'+opt(["Presencial","Domiciliaria","Telemedicina"],"Presencial")+'</select></label><label class="f">Lugar<input type="text" id="ag_l"></label><label class="f wide">Nota<input type="text" id="ag_n"></label></div><p class="note" id="ag_x"></p>'+(herId?'<p class="note">Origen: plan heredado '+esc(herId)+' (archivo de control).</p>':''),"Programar",()=>{
    const p=dv("ag_p"),t=dv("ag_t"),f=dvd("ag_f"),h=dv("ag_h"),d=dvn("ag_d"),r=dv("ag_r");if(!p||!t||!f)return"Paciente, actividad y fecha son obligatorios.";if(f<addDays(TODAY(),-60))return"Para registrar algo ya ocurrido use una actividad y márquela realizada con su soporte; no se programa con más de 60 días de atraso.";
    const X=dpCruces(r,f,h,d,null);if(X.length&&!$("ag_x").dataset.ok){$("ag_x").dataset.ok="1";$("ag_x").innerHTML='<strong style="color:var(--warn)">Cruce de agenda:</strong> '+esc(X.join(" · "))+'. Pulse de nuevo «Programar» para confirmar.';return" ";}
    const dupl=dpR("age").find(a=>a.Paciente===p&&a.Tipo===t&&iso(v6d(a.Fecha))===iso(f)&&a.Estado!=="Cancelada");if(dupl&&!$("ag_x").dataset.dup){$("ag_x").dataset.dup="1";$("ag_x").innerHTML+='<br><strong style="color:var(--warn)">El paciente ya tiene esa actividad ese día ('+esc(dupl.ID)+').</strong> Pulse de nuevo para confirmar.';return" ";}
    const a=dpAdd("age","AG-",{Paciente:p,Tipo:t,Fecha:f,Hora:h,DuracionMin:d,Profesional:r,Modalidad:dv("ag_m"),Lugar:dv("ag_l"),Estado:"Programada",Motivo:dv("ag_n"),Origen:herId?"Plan heredado "+herId:"Manual",Historial:"[]"});dpPushHist(a,{de:"",a:"Programada",f:iso(f)+" "+h});pxRefresh();toast("Actividad "+a.ID+" programada.");});}
function dpDlgAge(id){const a=DP.book.age.find(x=>x.ID===id);if(!a)return;const p=dpPac(a.Paciente);const e=dpAgeEst(a);const H=dpHist(a);const can=dpCan("age");const open=DP_AGE_OPEN.includes(a.Estado);const vt=DP_AGE_VAL[a.Tipo];
  const recs=[["",""]].concat(dpR("val").filter(v=>v.Paciente===a.Paciente).map(v=>["val|"+v.ID,v.ID+" · valoración "+v.Tipo+" "+fd(v6d(v.Fecha))]),dpR("lab").filter(l=>l.Paciente===a.Paciente).slice(-15).map(l=>["lab|"+l.ID,l.ID+" · "+(DPX[l.Examen]||{l:l.Examen}).l+" "+fd(v6d(l.FechaToma))]),dpR("edu").filter(x=>x.Paciente===a.Paciente).map(x=>["edu|"+x.ID,x.ID+" · "+x.Tipo+" "+fd(v6d(x.Fecha))]),dpR("cat").filter(x=>x.Paciente===a.Paciente).map(x=>["cat|"+x.ID,x.ID+" · "+x.Tipo+" "+fd(v6d(x.Fecha))]),dpR("ent").filter(x=>x.Paciente===a.Paciente).map(x=>["ent|"+x.ID,x.ID+" · entrega "+x.Periodo]));
  dpDlg(a.ID+" · "+a.Tipo,'<p class="note">'+esc(p?p.ID+" · "+dpNombre(p):a.Paciente)+' · '+fd(v6d(a.Fecha))+' '+esc(a.Hora||"")+' · '+esc(a.Profesional||"sin profesional")+' · <span class="st '+DP_AGE_CLS[e]+'">'+e+'</span>'+(a.Registro?' · registro <button type="button" class="lnk" data-p="d8rec|'+esc(a.Registro)+'">'+esc(a.Registro)+'</button>':'')+'</p>'+
   (can&&open?'<div class="form"><label class="f">Acción<select id="ag_a">'+opt([["Confirmada","Confirmar"],["Realizada","Registrar como realizada"],["Reprogramada","Reprogramar"],["Cancelada","Cancelar"],["Inasistencia","Registrar inasistencia"]],"Realizada")+'</select></label><label class="f">Fecha (realización o nueva fecha)<input type="date" id="ag_f" value="'+iso(TODAY()<v6d(a.Fecha)?v6d(a.Fecha):TODAY())+'"></label><label class="f">Nueva hora<input type="time" id="ag_h" value="'+esc(a.Hora||"")+'"></label><label class="f wide">Registro asociado<select id="ag_rg">'+opt(recs,a.Registro||"")+'</select></label><label class="f wide">Resultado o motivo *<input type="text" id="ag_m"></label></div>'+(vt&&dpCan("val")?'<p class="note">También puede <button type="button" class="lnk" data-p="d8vnew|'+esc(a.Paciente)+'|'+esc(vt)+'|'+a.ID+'">abrir la valoración de esta cita</button>: al finalizarla la actividad queda realizada.</p>':''):'<p class="note">'+(open?"Su rol no gestiona la agenda.":"Actividad cerrada: su historial se conserva.")+'</p>')+
   '<h4>Historial</h4><ul class="d8nl">'+H.map(x=>'<li><span class="mono">'+esc(x.ts)+'</span> · '+esc(x.u)+' · '+esc(x.de||"—")+' → '+esc(x.a)+(x.f?' ('+esc(x.f)+')':'')+(x.m?' · '+esc(x.m):'')+'</li>').join("")+'</ul>',can&&open?"Guardar":"Cerrar",()=>{if(!(can&&open))return;
    const ac=dv("ag_a"),f=dvd("ag_f"),h=dv("ag_h"),m=dv("ag_m"),rg=dv("ag_rg");if(["Reprogramada","Cancelada","Inasistencia"].includes(ac)&&m.length<4)return"Escriba el motivo.";if(ac==="Realizada"){if(!f||f>TODAY())return"La fecha de realización no puede ser futura.";if(!rg&&m.length<4)return"Asocie el registro de la atención o describa el resultado.";}
    if(ac==="Reprogramada"){if(!f||f<TODAY())return"La nueva fecha debe ser hoy o futura.";const X=dpCruces(a.Profesional,f,h,a.DuracionMin,a.ID);if(X.length)toast("Cruce de agenda: "+X.join(" · "));dpPushHist(a,{de:e,a:"Reprogramada",f:iso(v6d(a.Fecha))+" → "+iso(f)+" "+h,m});dpUpd("age",a,{Estado:"Reprogramada",Fecha:f,Hora:h,Motivo:m});}
    else{dpPushHist(a,{de:e,a:ac,f:ac==="Realizada"?iso(f):"",m});const ch={Estado:ac,Motivo:ac==="Confirmada"?a.Motivo:m};if(ac==="Realizada"){ch.FechaRealizacion=f;ch.Resultado=m||"Ver registro asociado";ch.Registro=rg;}if(ac==="Inasistencia"||ac==="Cancelada")ch.Resultado=m;dpUpd("age",a,ch);}
    pxRefresh();toast("Actividad actualizada.");},true);}

/* ---------- laboratorio: registrar, validar, corregir, Kt/V ---------- */
function dpDlgLab(pid,k,mes,corrId){if(!dpGuard("lab"))return;const old=corrId?DP.book.lab.find(x=>x.ID===corrId):null;const ex=old?old.Examen:k||"";const p0=old?old.Paciente:pid||"";
  dpDlg(old?"Corregir resultado "+old.ID:"Registrar resultado de laboratorio",(old?'<p class="note">El resultado '+esc(old.ID)+' ('+esc(old.Valor)+' del '+fd(v6d(old.FechaToma))+') no se borra: queda marcado como corregido y la versión nueva lo reemplaza en tendencias e indicadores.</p>':'')+
   '<div class="form"><label class="f wide">Paciente *<select id="lb_p"'+(old?" disabled":"")+'>'+dpPacOpts(p0,"Seleccione…")+'</select></label><label class="f wide">Examen *<select id="lb_k"'+(old?" disabled":"")+'>'+opt(DP_EX.map(e=>[e.k,e.l+(e.u?" ("+e.u+")":"")]),ex,"Seleccione…")+'</select></label><label class="f">Valor *<input type="text" id="lb_v" value="'+esc(old?old.Valor:"")+'" placeholder="número o resultado cualitativo"></label><label class="f">Fecha de toma *<input type="date" id="lb_ft" value="'+(old?dpDI(old.FechaToma):mes?mes+"-01":"")+'"></label><label class="f">Fecha del resultado<input type="date" id="lb_fr" value="'+(old?dpDI(old.FechaResultado):iso(TODAY()))+'"></label>'+
   '<label class="f">Laboratorio de origen<input type="text" id="lb_o" list="lb_ol" value="'+esc(old?old.LabOrigen:"")+'"><datalist id="lb_ol"><option value="Laboratorio clínico UNO-P"><option value="Laboratorio de apoyo"></datalist></label><label class="f wide">Soporte (n.° de informe, archivo)<input type="text" id="lb_s" value="'+esc(old?old.Soporte:"")+'"></label><label class="f wide">Observaciones<input type="text" id="lb_ob" value="'+esc(old?old.Observacion:"")+'"></label>'+(old?'<label class="f wide">Motivo de la corrección *<input type="text" id="lb_m"></label>':'')+
   (dpCan("labval")?'<label class="chk wide"><input type="checkbox" id="lb_val"> Revisado y validado por mí al registrar</label>':'')+'</div>',"Guardar",()=>{
    const p=old?old.Paciente:dv("lb_p"),k2=old?old.Examen:dv("lb_k"),v=dv("lb_v").replace(",","."),ft=dvd("lb_ft"),fr=dvd("lb_fr");const e=DPX[k2];if(!p||!k2||!v||!ft)return"Paciente, examen, valor y fecha de toma son obligatorios.";
    if(ft>TODAY())return"La toma no puede ser futura.";if(fr&&fr<ft)return"El resultado no puede ser anterior a la toma.";if(e.t==="n"){const n=num(v);if(n==null)return"El valor debe ser numérico para este examen.";if(n<e.min||n>e.max)return"Valor fuera del rango verosímil ("+e.min+"-"+e.max+" "+e.u+"). Revise la unidad.";}
    if(old&&dv("lb_m").length<6)return"Escriba el motivo de la corrección.";
    if(!old&&dpR("lab").some(l=>l.Paciente===p&&l.Examen===k2&&iso(v6d(l.FechaToma))===iso(ft)&&!/^Corregido/.test(l.Estado||"")))return"Ya hay un resultado de ese examen con esa fecha de toma: use «Corregir» sobre el existente.";
    const valid=$("lb_val")&&$("lb_val").checked;const sol=dpR("sol").find(r=>r.Paciente===p&&r.Examen===k2&&r.Mes===ym(ft));
    const r=dpAdd("lab","L-",{Paciente:p,Examen:k2,Valor:e.t==="n"?num(v):v,Unidad:e.u,FechaToma:ft,FechaResultado:fr,LabOrigen:dv("lb_o"),Metodo:"Reportado",Estado:valid?"Validado":"Pendiente de validación",Reviso:valid?dpWho():"",FechaRevision:valid?TODAY():null,Version:old?(num(old.Version)||1)+1:1,VersionDe:old?old.ID:"",Motivo:old?dv("lb_m"):"",Solicitud:sol?sol.ID:"",Soporte:dv("lb_s"),Observacion:dv("lb_ob")});
    if(old)dpUpd("lab",old,{Estado:"Corregido (ver "+r.ID+")"});if(sol&&sol.Estado!=="Muestra tomada")dpUpd("sol",sol,{Estado:"Muestra tomada",FechaToma:ft});pxRefresh();toast("Resultado "+r.ID+" guardado"+(valid?" y validado.":"; queda pendiente de revisión profesional."));});}
function dpLabValidate(id){if(!dpGuard("labval"))return;const l=DP.book.lab.find(x=>x.ID===id);dpDlg("Validar "+id,'<p class="note">'+esc((DPX[l.Examen]||{l:l.Examen}).l)+': <strong>'+esc(l.Valor)+'</strong> '+esc(l.Unidad||"")+' · toma '+fd(v6d(l.FechaToma))+' · '+esc(l.LabOrigen||"")+(l.Componentes?'<br>Componentes del cálculo: '+esc(l.Componentes):'')+'</p><label class="f wide">Observación de la revisión<input type="text" id="lv_o"></label>',"Validar",()=>{dpUpd("lab",l,{Estado:"Validado",Reviso:dpWho(),FechaRevision:TODAY(),Observacion:[l.Observacion,dv("lv_o")].filter(Boolean).join(" · ")});pxRefresh();toast("Resultado validado.");});}
function dpDlgKtv(pid){if(!dpGuard("lab"))return;const p=pid?dpPac(pid):null;
  dpDlg("Kt/V semanal en DP · cálculo",'<p class="note">'+esc(DP_KTV_VER)+'. Use datos de una misma recolección de 24 horas. Si no hay orina medida, el componente renal no se calcula (no se asume cero) salvo anuria documentada.</p><div class="form"><label class="f wide">Paciente *<select id="kt_p">'+dpPacOpts(pid,"Seleccione…")+'</select></label><label class="f">Fecha de la recolección *<input type="date" id="kt_f" value="'+iso(TODAY())+'"></label><label class="f">Recolección completa<select id="kt_c">'+opt(["Sí","No","Incierta"],"")+'</select></label>'+
   '<label class="f">Peso (kg)<input type="number" step="any" id="kt_w"></label><label class="f">Talla (cm)<input type="number" step="any" id="kt_h" value="'+esc(p&&p.Talla||"")+'"></label><label class="f">V manual (L, opcional)<input type="number" step="any" id="kt_V" placeholder="si no, Watson"></label>'+
   '<label class="f">Urea plasmática (mg/dL) *<input type="number" step="any" id="kt_pu"></label><label class="f">Urea del dializado (mg/dL) *<input type="number" step="any" id="kt_du"></label><label class="f">Volumen drenado 24 h (L) *<input type="number" step="any" id="kt_vd"></label>'+
   '<label class="f">Orina 24 h (L)<input type="number" step="any" id="kt_vu"></label><label class="f">Urea urinaria (mg/dL)<input type="number" step="any" id="kt_uu"></label><label class="chk"><input type="checkbox" id="kt_an"> Anuria documentada</label><label class="f wide">Soporte<input type="text" id="kt_s"></label></div><div id="kt_out" class="alert"><p>Complete los datos y pulse «Calcular».</p></div>',"Calcular",()=>{
    const pid2=dv("kt_p");const pp=dpPac(pid2);const f=dvd("kt_f");if(!pp||!f)return"Paciente y fecha son obligatorios.";const x={sexo:pp.Sexo,edad:dpEdad(pp,f),talla:dvn("kt_h"),peso:dvn("kt_w"),V:dvn("kt_V"),Pu:dvn("kt_pu"),Du:dvn("kt_du"),Vd:dvn("kt_vd"),Uu:dvn("kt_uu"),Vu:dvn("kt_vu"),anuria:$("kt_an").checked,completa:dv("kt_c")};
    const r=dpKtvCalc(x);const o=$("kt_out");if(r.err.length){o.className="alert bad";o.innerHTML="<p>"+r.err.map(esc).join("<br>")+"</p>";return" ";}
    if(!o.dataset.done){o.dataset.done="1";o.className="alert "+(r.valido?"ok":"warn");o.innerHTML='<p>V = '+f1(r.V,1)+' L · Kt/V peritoneal '+f1(r.p,2)+' · renal '+(r.r==null?"no calculado":f1(r.r,2))+' · <strong>total '+(r.t==null?"no calculable":f1(r.t,2))+'</strong>'+(r.warn.length?'<br>'+r.warn.map(esc).join("<br>"):'')+'<br>Pulse de nuevo para guardar (queda pendiente de validación por Nefrología).</p>';$("dlgok").textContent="Guardar";return" ";}
    if(r.t==null)return"Sin componente renal válido no se guarda un Kt/V total. Registre la orina o marque anuria documentada.";
    dpAdd("lab","L-",{Paciente:pid2,Examen:"KtV",Valor:Math.round(r.t*100)/100,Unidad:"",FechaToma:f,FechaResultado:TODAY(),LabOrigen:"Calculado en el SIGC",Metodo:"Calculado · "+DP_KTV_VER,Componentes:JSON.stringify({p:Math.round(r.p*1000)/1000,r:r.r==null?null:Math.round(r.r*1000)/1000,V:Math.round(r.V*10)/10,entradas:x,valido:r.valido,avisos:r.warn}),Estado:"Pendiente de validación",Version:1,Soporte:dv("kt_s")});
    dpAdd("lab","L-",{Paciente:pid2,Examen:"KtVp",Valor:Math.round(r.p*100)/100,FechaToma:f,FechaResultado:TODAY(),LabOrigen:"Calculado en el SIGC",Metodo:"Calculado · "+DP_KTV_VER,Estado:"Pendiente de validación",Version:1});if(r.r!=null)dpAdd("lab","L-",{Paciente:pid2,Examen:"KtVr",Valor:Math.round(r.r*100)/100,FechaToma:f,FechaResultado:TODAY(),LabOrigen:"Calculado en el SIGC",Metodo:"Calculado · "+DP_KTV_VER,Estado:"Pendiente de validación",Version:1});
    if(x.Vu!=null&&!x.anuria&&!dpR("lab").some(l=>l.Paciente===pid2&&l.Examen==="Diuresis"&&iso(v6d(l.FechaToma))===iso(f)))dpAdd("lab","L-",{Paciente:pid2,Examen:"Diuresis",Valor:Math.round(x.Vu*1000),Unidad:"mL/24 h",FechaToma:f,LabOrigen:"Recolección de 24 h",Metodo:"Medido",Estado:"Pendiente de validación",Version:1});
    pxRefresh();toast("Kt/V guardado; queda pendiente de validación.");},true);}
function dpDlgPlan(id){if(!dpGuard("labval"))return;const r=id?DP.book.plab.find(x=>x.ID===id):null;const o=r||{Estado:"Propuesta"};
  dpDlg(r?"Regla "+r.ID:"Nueva regla de periodicidad",'<div class="form"><label class="f wide">Alcance<select id="pl_p">'+dpPacOpts(o.Paciente||"","Todos los pacientes")+'</select></label><label class="f">Examen *<select id="pl_k">'+opt(DP_EX.map(e=>[e.k,e.l]),o.Examen||"","Seleccione…")+'</select></label><label class="f">Cada (meses)<input type="number" min="1" max="24" id="pl_n" value="'+esc(o.Periodicidad??"")+'"></label><label class="f">Indicación (si no es periódico)<input type="text" id="pl_i" value="'+esc(o.Indicacion||"")+'"></label><label class="f">Estado<select id="pl_e">'+opt(["Propuesta","Validado","Sin definir"],o.Estado)+'</select></label><label class="f wide">Fuente o justificación *<input type="text" id="pl_f" value="'+esc(o.Fuente||"")+'"></label></div><p class="note">Validar convierte la regla en exigible: genera vencidos y la solicitud del mes. Queda registrado quién y cuándo.</p>',"Guardar",()=>{
    const ch={Paciente:dv("pl_p"),Examen:dv("pl_k"),Periodicidad:dvn("pl_n"),Indicacion:dv("pl_i"),Estado:dv("pl_e"),Fuente:dv("pl_f")};if(!ch.Examen)return"Elija el examen.";if(ch.Fuente.length<6)return"Escriba la fuente o justificación.";if(ch.Estado==="Validado"&&!ch.Periodicidad)return"Una regla validada necesita periodicidad en meses (o déjela «Sin definir» si es por indicación).";
    if(DP.book.plab.some(x=>lv(x)&&x.ID!==(r&&r.ID)&&x.Examen===ch.Examen&&(x.Paciente||"")===ch.Paciente))return"Ya existe una regla para ese examen y alcance: edítela.";
    if(ch.Estado==="Validado"&&(!r||r.Estado!=="Validado")){ch.ValidadoPor=dpWho();ch.FechaValidacion=TODAY();}if(r)dpUpd("plab",r,ch);else dpAdd("plab","PL-",ch);pxRefresh();toast("Regla guardada.");});}
async function dpSolGen(mes){const P=dpSolProp(mes);let n=0;P.forEach(({p,ex})=>ex.forEach(k=>{if(dpR("sol").some(r=>r.Paciente===p.ID&&r.Examen===k&&r.Mes===mes))return;dpAdd("sol","SD-",{Mes:mes,Paciente:p.ID,Examen:k,Origen:dpLabOverdue(p,k)?"Vencido":"Plan validado",Estado:"Pendiente"});n++;}));pxRefresh();toast(n+" exámenes en la solicitud de "+mes+".");}
function dpSolTom(pid,mes){if(!dpGuard("lab"))return;let n=0;dpR("sol").filter(r=>r.Paciente===pid&&r.Mes===mes&&r.Estado==="Pendiente").forEach(r=>{dpUpd("sol",r,{Estado:"Muestra tomada",FechaToma:TODAY()});n++;});pxRefresh();toast(n+" muestras marcadas como tomadas hoy.");}

/* ---------- prescripción versionada ---------- */
const DP_SOLS=["Glucosa 1,5 %","Glucosa 2,5 %","Glucosa 4,25 %","Icodextrina 7,5 %","Otra (especificar en observación)"];
const DP_OBJ=["Control de síntomas","Control de volumen","Control de presión arterial","Estado nutricional","Calidad de vida y participación","Depuración de solutos"];
function dpDlgPre(pid){if(!dpGuard("pre"))return;const prev=pid?dpPreVig(pid):null;const o=prev||{Modalidad:(dpPac(pid)||{}).Modalidad||"DPCA"};const S=dpJ(o.Soluciones,[{},{},{}]);while(S.length<4)S.push({});const OB=new Set(dpJ(o.Objetivos,[]));
  dpDlg("Prescripción de DP · nueva versión",(prev?'<p class="note">Versión vigente: v'+prev.Version+' desde '+fd(v6d(prev.VigenteDesde))+'. Se cerrará el día anterior a la nueva vigencia.</p>':'')+'<div class="form"><label class="f wide">Paciente *<select id="pr_p"'+(pid?" disabled":"")+'>'+dpPacOpts(pid,"Seleccione…")+'</select></label><label class="f">Modalidad *<select id="pr_m">'+opt(["DPCA","DPA"],o.Modalidad)+'</select></label><label class="f">Vigente desde *<input type="date" id="pr_f" value="'+iso(TODAY())+'"></label><label class="f">Motivo *<select id="pr_mo">'+opt(["Inicio","Adecuación","Volumen","Síntomas","Infección","Preferencia del paciente","Otro"],"")+'</select></label><label class="f">Peso de referencia (kg) *<input type="number" step="any" id="pr_w" value="'+esc(o.PesoRef??"")+'"></label><label class="f">Sistema de conexión<input type="text" id="pr_s" value="'+esc(o.Sistema||"")+'"></label></div>'+
   '<h4>Soluciones</h4><div class="tablebox"><table class="dense"><thead><tr><th>Solución</th><th>Volumen por recambio o ciclo (mL)</th><th>N.° por día</th></tr></thead><tbody>'+S.slice(0,4).map((s,i)=>'<tr><td><select id="pr_s'+i+'">'+opt(DP_SOLS,s.sol||"","—")+'</select></td><td><input type="number" id="pr_v'+i+'" value="'+esc(s.vol??"")+'"></td><td><input type="number" id="pr_n'+i+'" value="'+esc(s.n??"")+'"></td></tr>').join("")+'</tbody></table></div>'+
   '<div class="form"><label class="f">Intercambios por día (DPCA)<input type="number" id="pr_ix" value="'+esc(o.Intercambios??"")+'"></label><label class="f">Permanencia nocturna (DPCA)<input type="text" id="pr_pn" value="'+esc(o.PermanenciaNoct||"")+'"></label><label class="f">Tiempo total (h, DPA)<input type="number" step="any" id="pr_tt" value="'+esc(o.TiempoTotalH??"")+'"></label><label class="f">Ciclos (DPA)<input type="number" id="pr_cy" value="'+esc(o.Ciclos??"")+'"></label><label class="f">Volumen por ciclo (mL, DPA)<input type="number" id="pr_vc" value="'+esc(o.VolCiclo??"")+'"></label><label class="f">Tidal (%)<input type="number" id="pr_td" value="'+esc(o.Tidal??"")+'"></label><label class="f">Última infusión (DPA)<input type="text" id="pr_ui" value="'+esc(o.UltimaInfusion||"")+'" placeholder="sí/no, volumen, solución"></label><label class="f">Día seco<select id="pr_ds">'+opt(["No","Sí"],o.DiaSeco||"","—")+'</select></label>'+
   '<fieldset class="f wide d8fs"><legend>Objetivos individualizados *</legend><div class="chkcol">'+DP_OBJ.map(x=>'<label class="chk"><input type="checkbox" data-prob value="'+esc(x)+'"'+(OB.has(x)?" checked":"")+'> '+esc(x)+'</label>').join("")+'</div></fieldset><label class="f wide">Observación clínica<input type="text" id="pr_o" value="'+esc(o.Obs||"")+'"></label></div>',"Guardar versión",()=>{
    const p=pid||dv("pr_p"),f=dvd("pr_f"),mo=dv("pr_mo"),w=dvn("pr_w");if(!p||!f||!mo||w==null)return"Paciente, vigencia, motivo y peso de referencia son obligatorios.";if(w<20||w>250)return"Peso fuera de rango.";
    const sol=[0,1,2,3].map(i=>({sol:dv("pr_s"+i),vol:dvn("pr_v"+i),n:dvn("pr_n"+i)})).filter(s=>s.sol&&s.vol&&s.n);if(!sol.length)return"Registre al menos una solución con volumen y número.";const ob=[...document.querySelectorAll("[data-prob]:checked")].map(x=>x.value);if(!ob.length)return"Marque al menos un objetivo.";
    const vt=sol.reduce((a,s)=>a+s.vol*s.n,0);const cur=dpPreVig(p,f);const last=dpR("pre").filter(r=>r.Paciente===p).sort((a,b)=>num(b.Version)-num(a.Version))[0];if(last&&v6d(last.VigenteDesde)>=f)return"La vigencia debe ser posterior a la de la versión "+last.Version+" ("+fd(v6d(last.VigenteDesde))+").";
    if(cur)dpUpd("pre",cur,{VigenteHasta:addDays(f,-1),Estado:"Reemplazada"});
    dpAdd("pre","PR-",{Paciente:p,Version:last?(num(last.Version)||0)+1:1,Modalidad:dv("pr_m"),VigenteDesde:f,Prescriptor:dpWho(),Motivo:mo,PesoRef:w,Sistema:dv("pr_s"),Soluciones:JSON.stringify(sol),VolumenTotal:vt,Intercambios:dvn("pr_ix"),PermanenciaNoct:dv("pr_pn"),TiempoTotalH:dvn("pr_tt"),Ciclos:dvn("pr_cy"),VolCiclo:dvn("pr_vc"),Tidal:dvn("pr_td"),UltimaInfusion:dv("pr_ui"),DiaSeco:dv("pr_ds"),Objetivos:JSON.stringify(ob),Obs:dv("pr_o"),Estado:"Vigente"});
    const pp=dpPac(p);if(pp&&pp.Modalidad!==dv("pr_m"))toast("La prescripción es "+dv("pr_m")+" y el paciente figura en "+(pp.Modalidad||"sin modalidad")+": registre la transición de modalidad desde la ficha.");else toast("Prescripción guardada.");pxRefresh();},true);}

/* ---------- catéter ---------- */
const DP_CAT_T=["Implante","Valoración del orificio","Cambio de línea (transfer set)","Disfunción o complicación mecánica","Intervención","Recambio","Retiro"];
const DP_CAT_MEC=["Drenaje deficiente u obstrucción","Migración o malposición","Fuga","Hernia","Dolor de infusión o drenaje","Hemoperitoneo","Efluente anormal (quiloperitoneo u otro)","Pérdida de ultrafiltración","Otra"];
function dpDlgCat(pid){if(!dpGuard("seg"))return;const S=["No","Sí"];
  dpDlg("Catéter y orificio de salida",'<div class="form"><label class="f wide">Paciente *<select id="ct_p">'+dpPacOpts(pid,"Seleccione…")+'</select></label><label class="f">Registro *<select id="ct_t">'+opt(DP_CAT_T,"Valoración del orificio")+'</select></label><label class="f">Fecha *<input type="date" id="ct_f" value="'+iso(TODAY())+'"></label><label class="f">Responsable<input type="text" id="ct_r" value="'+esc(PX.user?PX.user.Nombre:"")+'"></label><label class="f">Tipo de catéter (implante/recambio)<input type="text" id="ct_tc" list="ct_tcl"><datalist id="ct_tcl"><option value="Tenckhoff recto, 2 cuffs"><option value="Tenckhoff curvo, 2 cuffs"><option value="Tenckhoff cuello de cisne"></datalist></label></div>'+
   '<h4>Valoración del orificio y del túnel</h4><div class="form">'+[["Eritema","ct_er"],["Dolor","ct_do"],["Edema o induración","ct_ed"],["Costra","ct_co"],["Tejido de granulación","ct_gr"],["Dolor o colección en el túnel","ct_tu"]].map(([l,i])=>'<label class="f">'+l+'<select id="'+i+'">'+opt(S,"","—")+'</select></label>').join("")+'<label class="f">Exudado<select id="ct_ex">'+opt(["Ninguno","Seroso","Hemático","Purulento"],"","—")+'</select></label><label class="f">Clasificación final<select id="ct_cl">'+opt(["Normal","Inflamación sin infección","Infección del orificio","Infección del túnel","Incierta"],"","—")+'</select></label></div>'+
   '<h4>Cambio de línea, complicación o intervención</h4><div class="form"><label class="f">Motivo del cambio de línea<select id="ct_ml">'+opt(["Rutina","Contaminación","Fuga","Otro"],"","—")+'</select></label><label class="f">Complicación mecánica<select id="ct_mc">'+opt(DP_CAT_MEC,"","—")+'</select></label><label class="f wide">Descripción, conducta y desenlace<input type="text" id="ct_o"></label><label class="chk wide"><input type="checkbox" id="ct_ab"> Queda abierto (requiere seguimiento y cierre)</label></div><p class="note">Si clasifica infección del orificio o del túnel, el sistema abre el episodio infeccioso para IAAS y PROA (un solo registro del evento).</p>',"Guardar",()=>{
    const p=dv("ct_p"),t=dv("ct_t"),f=dvd("ct_f");if(!p||!t||!f)return"Paciente, registro y fecha son obligatorios.";if(f>TODAY())return"La fecha no puede ser futura.";const cl=dv("ct_cl");if(t==="Valoración del orificio"&&!cl)return"Clasifique el orificio.";if(t==="Cambio de línea (transfer set)"&&!dv("ct_ml"))return"Indique el motivo del cambio de línea.";if(t==="Disfunción o complicación mecánica"&&!dv("ct_mc"))return"Indique la complicación.";
    const D={eritema:dv("ct_er"),dolor:dv("ct_do"),edema:dv("ct_ed"),costra:dv("ct_co"),granulacion:dv("ct_gr"),tunel:dv("ct_tu"),exudado:dv("ct_ex"),motivoLinea:dv("ct_ml"),complicacion:dv("ct_mc")};
    const inf=/^Infección/.test(cl);const abierto=$("ct_ab").checked||t==="Disfunción o complicación mecánica"||inf;let ep="";
    if(inf){const tipo=cl==="Infección del túnel"?"Infección del túnel":"Infección del orificio de salida";const dup=dpR("epi").find(e=>e.Paciente===p&&e.Tipo===tipo&&Math.abs(dayDiff(v6d(e.Fecha),f))<=7);
      if(dup)ep=dup.ID;else{const e=dpAdd("epi","EP-",{Paciente:p,Tipo:tipo,Fecha:f,Sintomas:JSON.stringify(D.exudado==="Purulento"?["Secreción purulenta del orificio de salida"]:D.eritema==="Sí"?["Eritema del orificio de salida"]:[]),DxClinico:"En estudio",Clasificacion:"Sin clasificar",Desenlace:"En tratamiento",Seguimiento:"Abierto desde Catéter"});ep=e.ID;}}
    const r=dpAdd("cat","CT-",{Paciente:p,Tipo:t,Fecha:f,TipoCateter:dv("ct_tc"),Datos:JSON.stringify(D),Clasificacion:t==="Valoración del orificio"?cl:t==="Disfunción o complicación mecánica"?dv("ct_mc"):t==="Cambio de línea (transfer set)"?"Motivo: "+dv("ct_ml"):"",Responsable:dv("ct_r"),Episodio:ep,Estado:abierto?"Abierto":"",Obs:dv("ct_o")});
    if(["Implante","Recambio"].includes(t)){const pp=dpPac(p);if(pp&&(!v6d(pp.FechaCateter)||v6d(pp.FechaCateter)<f))dpUpd("pac",pp,{FechaCateter:f});}
    pxRefresh();toast("Registro "+r.ID+" guardado"+(ep?" · episodio "+ep+" para IAAS/PROA":"")+".");},true);}
function dpDlgClose(k,id){if(!dpGuard("seg"))return;const r=DP.book[k].find(x=>x.ID===id);dpDlg("Cerrar "+id,'<label class="f wide">Cierre: resultado y evidencia *<input type="text" id="cl_t"></label><label class="f">Fecha<input type="date" id="cl_f" value="'+iso(TODAY())+'"></label>',"Cerrar",()=>{const t=dv("cl_t"),f=dvd("cl_f");if(t.length<6)return"Describa el cierre y su evidencia.";dpUpd(k,r,{Estado:"Cerrado",FechaCierre:f,Cierre:t+" · "+dpWho()});pxRefresh();toast("Cerrado; el registro se conserva.");});}

/* ---------- educación, entrenamiento y visita domiciliaria ---------- */
function dpDlgEdu(pid){if(!dpGuard("seg"))return;
  dpDlg("Educación y domicilio",'<div class="form"><label class="f wide">Paciente *<select id="ed_p">'+dpPacOpts(pid,"Seleccione…")+'</select></label><label class="f">Tipo *<select id="ed_t">'+opt(["Entrenamiento inicial","Reentrenamiento","Visita domiciliaria","Sesión educativa"],"Entrenamiento inicial")+'</select></label><label class="f">Fecha *<input type="date" id="ed_f" value="'+iso(TODAY())+'"></label><label class="f">Responsable<input type="text" id="ed_r" value="'+esc(PX.user?PX.user.Nombre:"")+'"></label><label class="f">Participante<select id="ed_pa">'+opt(["Paciente","Cuidador","Paciente y cuidador"],"Paciente")+'</select></label></div>'+
   '<h4>Competencias (entrenamiento o reentrenamiento)</h4><div class="tablebox"><table class="dense"><tbody>'+DP_COMP.map((c,i)=>'<tr><td>'+esc(c)+'</td><td><select id="ed_c'+i+'">'+opt(DP_COMP_RES,"No evaluada")+'</select></td></tr>').join("")+'</tbody></table></div>'+
   '<h4>Entorno (visita domiciliaria)</h4><div class="form">'+DP_ENTORNO.map((c,i)=>'<label class="f">'+esc(c)+'<select id="ed_e'+i+'">'+opt(["Adecuado","Inadecuado","No evaluado"],"No evaluado")+'</select></label>').join("")+'</div>'+
   '<div class="form"><label class="f wide">Riesgos identificados<input type="text" id="ed_ri"></label><label class="f wide">Plan e intervenciones<input type="text" id="ed_pl"></label><label class="f">Seguimiento<input type="date" id="ed_sg"></label><label class="chk"><input type="checkbox" id="ed_ab"> Queda abierto hasta verificar el seguimiento</label></div>',"Guardar",()=>{
    const p=dv("ed_p"),t=dv("ed_t"),f=dvd("ed_f");if(!p||!f)return"Paciente y fecha son obligatorios.";if(f>TODAY())return"La fecha no puede ser futura.";
    const C=Object.fromEntries(DP_COMP.map((c,i)=>[c,dv("ed_c"+i)]));const En=Object.fromEntries(DP_ENTORNO.map((c,i)=>[c,dv("ed_e"+i)]));const ev=Object.values(C).filter(x=>x!=="No evaluada");
    let res="";if(["Entrenamiento inicial","Reentrenamiento"].includes(t)){if(!ev.length)return"Evalúe al menos una competencia: la competencia se aprueba por demostración.";res=ev.includes("No competente")?"No competente":ev.includes("Requiere refuerzo")?"Requiere refuerzo":ev.length===DP_COMP.length?"Competente":"Evaluación parcial";}
    else if(t==="Visita domiciliaria"){const inad=Object.entries(En).filter(([k,v])=>v==="Inadecuado").map(([k])=>k);res=inad.length?"Hallazgos: "+inad.join(", "):Object.values(En).every(v=>v==="No evaluado")?"Sin evaluación del entorno":"Entorno adecuado";}else res="Realizada";
    const ab=$("ed_ab").checked||res==="No competente"||/Hallazgos/.test(res);if(ab&&!dv("ed_pl"))return"Con hallazgos o competencia no lograda, registre el plan.";
    const r=dpAdd("edu","ED-",{Paciente:p,Tipo:t,Fecha:f,Responsable:dv("ed_r"),Participante:dv("ed_pa"),Datos:JSON.stringify({competencias:C,entorno:En}),Resultado:res,Riesgos:dv("ed_ri"),Plan:dv("ed_pl"),Seguimiento:dvd("ed_sg"),Estado:ab?"Abierto":""});pxRefresh();toast(r.ID+": "+res+".");},true);}

/* ---------- suministros ---------- */
function dpDlgIns(pid){if(!dpGuard("ins"))return;dpDlg("Insumo prescrito",'<div class="form"><label class="f wide">Paciente *<select id="in_p">'+dpPacOpts(pid,"Seleccione…")+'</select></label><label class="f wide">Insumo *<input type="text" id="in_i" list="in_il"><datalist id="in_il">'+[...new Set(dpR("ins").map(i=>i.Insumo))].map(x=>'<option value="'+esc(x)+'">').join("")+'</datalist></label><label class="f">Cantidad *<input type="number" id="in_q"></label><label class="f">Periodo<select id="in_pe">'+opt(["Mensual","Semanal","Por entrega"],"Mensual")+'</select></label><label class="f">Vigente desde<input type="date" id="in_f" value="'+iso(TODAY())+'"></label></div>',"Guardar",()=>{
  const p=dv("in_p"),i=dv("in_i"),q=dvn("in_q");if(!p||!i||q==null||q<=0)return"Paciente, insumo y cantidad son obligatorios.";const prev=dpR("ins").find(x=>x.Paciente===p&&norm(x.Insumo)===norm(i)&&x.Estado==="Vigente");if(prev)dpUpd("ins",prev,{Estado:"Reemplazada"});
  dpAdd("ins","IN-",{Paciente:p,Insumo:i,Cantidad:q,Periodo:dv("in_pe"),VigenteDesde:dvd("in_f"),Estado:"Vigente",Origen:"Registro manual"});pxRefresh();toast("Insumo registrado.");});}
function dpDlgInsAs(id){if(!dpGuard("ins"))return;const i=DP.book.ins.find(x=>x.ID===id);const L=dpR("ins").filter(x=>x.NombreFuente===i.NombreFuente&&x.Origen===i.Origen&&(!x.Paciente||/por confirmar|Sin paciente/.test(x.Estado||"")));
  dpDlg("Asociar insumos heredados · «"+i.NombreFuente+"»",'<p class="note">'+esc(i.Origen)+' · '+L.length+' filas. Confianza de la sugerencia: '+esc(i.Confianza||"ninguna")+'.</p><div class="tablebox"><table class="dense"><thead><tr><th>Insumo en la fuente</th><th>Cantidad</th><th>Nota</th></tr></thead><tbody>'+L.map((x,k)=>'<tr><td>'+esc(x.Insumo)+'</td><td><input type="number" id="ia_q'+k+'" value="'+esc(x.Cantidad??"")+'"></td><td style="font-size:12px">'+esc(x.Nota||"")+'</td></tr>').join("")+'</tbody></table></div>'+
   '<div class="form"><label class="f wide">Paciente<select id="ia_p">'+dpPacOpts(i.Sugerido||"","Seleccione…")+'</select></label><label class="f">Periodo de las cantidades *<select id="ia_pe">'+opt(["Mensual","Semanal","Por entrega"],"","Sin confirmar")+'</select></label><label class="f">Acción<select id="ia_a">'+opt([["as","Confirmar asociación"],["de","Descartar (no corresponde)"]],"as")+'</select></label><label class="f wide">Cómo se verificó *<input type="text" id="ia_v" placeholder="p. ej. confirmado con la enfermera de DP y la formulación vigente"></label></div>',"Guardar",()=>{
   const a=dv("ia_a"),v=dv("ia_v");if(v.length<6)return"Describa cómo se verificó.";if(a==="de"){L.forEach(x=>dpUpd("ins",x,{Estado:"Descartado",Nota:(x.Nota||"")+" · descartado: "+v}));pxRefresh();toast(L.length+" filas descartadas; quedan en el libro.");return;}
   const p=dv("ia_p"),pe=dv("ia_pe");if(!p)return"Elija el paciente.";if(!pe)return"Confirme el periodo de las cantidades.";
   L.forEach((x,k)=>dpUpd("ins",x,{Paciente:p,Cantidad:dvn("ia_q"+k),Periodo:pe,Estado:"Vigente",VigenteDesde:TODAY(),Nota:(x.Nota||"")+" · asociado: "+v}));pxRefresh();toast(L.length+" insumos asociados a "+p+".");},true);}
function dpDlgEnt(id,pid){if(!dpGuard("ins"))return;const e=id?DP.book.ent.find(x=>x.ID===id):null;
  if(!e){dpDlg("Programar entrega de insumos",'<div class="form"><label class="f wide">Paciente *<select id="en_p">'+dpPacOpts(pid,"Seleccione…")+'</select></label><label class="f">Periodo *<input type="month" id="en_m" value="'+ym(TODAY())+'"></label><label class="f">Fecha programada *<input type="date" id="en_f" value="'+iso(TODAY())+'"></label><label class="f">Responsable<input type="text" id="en_r"></label></div><p class="note">Los requeridos salen de los insumos vigentes del paciente.</p>',"Programar",()=>{
    const p=dv("en_p"),m=dv("en_m"),f=dvd("en_f");if(!p||!m||!f)return"Paciente, periodo y fecha son obligatorios.";const I=dpR("ins").filter(i=>i.Paciente===p&&i.Estado==="Vigente");if(!I.length)return"El paciente no tiene insumos vigentes registrados.";
    if(dpR("ent").some(x=>x.Paciente===p&&x.Periodo===m&&x.Estado!=="No entregada"))return"Ya hay una entrega de ese periodo para el paciente.";
    dpAdd("ent","EN-",{Paciente:p,Periodo:m,FechaProgramada:f,Items:JSON.stringify(I.map(i=>({insumo:i.Insumo,req:i.Periodo==="Mensual"?i.Cantidad:i.Periodo==="Semanal"?Math.round(i.Cantidad*4.345):i.Cantidad,ent:null}))),Estado:"Programada",Responsable:dv("en_r")});pxRefresh();toast("Entrega programada.");});return;}
  const It=dpJ(e.Items,[]);dpDlg("Registrar entrega "+e.ID,'<p class="note">'+esc(e.Paciente)+' · periodo '+esc(e.Periodo)+' · programada '+fd(v6d(e.FechaProgramada))+'</p><div class="tablebox"><table class="dense"><thead><tr><th>Insumo</th><th class="num">Requerido</th><th>Entregado</th></tr></thead><tbody>'+It.map((x,i)=>'<tr><td>'+esc(x.insumo)+'</td><td class="num">'+esc(x.req??"")+'</td><td><input type="number" id="en_q'+i+'" value="'+esc(x.ent??x.req??"")+'"></td></tr>').join("")+'</tbody></table></div>'+
   '<div class="form"><label class="f">Fecha de entrega<input type="date" id="en_f" value="'+iso(TODAY())+'"></label><label class="f">Responsable *<input type="text" id="en_r" value="'+esc(e.Responsable||"")+'"></label><label class="f">Soporte de recibido firmado *<select id="en_s">'+opt(["Sí","No"],"")+'</select></label><label class="f">Referencia del soporte<input type="text" id="en_sr"></label><label class="f">Incidencia<select id="en_i">'+opt(["Faltante","Daño","Error","Retraso","Rechazo","No entregada","Otra"],"","Ninguna")+'</select></label><label class="f wide">Contingencia (obligatoria si hay faltante)<input type="text" id="en_c"></label></div>',"Guardar",()=>{
    const f=dvd("en_f"),r=dv("en_r"),s=dv("en_s");const I2=It.map((x,i)=>Object.assign({},x,{ent:dvn("en_q"+i)}));const noEnt=dv("en_i")==="No entregada";if(!noEnt&&!f)return"Fecha de entrega obligatoria.";if(f&&f>TODAY())return"La entrega no puede ser futura.";if(!r)return"Responsable obligatorio.";if(!noEnt&&!s)return"Indique si hay soporte de recibido firmado.";
    const falt=I2.filter(x=>(x.ent||0)<(x.req||0));const est=noEnt?"No entregada":falt.length?"Parcial":"Entregada completa";if(est!=="Entregada completa"&&dv("en_c").length<4)return"Registre la contingencia: hay riesgo de interrumpir la terapia.";
    dpUpd("ent",e,{Items:JSON.stringify(I2),FechaEntrega:noEnt?null:f,Responsable:r,SoporteRecibido:s,Soporte:dv("en_sr"),Incidencia:dv("en_i")||(falt.length?"Faltante":""),Contingencia:dv("en_c"),Estado:est});pxRefresh();toast("Entrega: "+est.toLowerCase()+".");});}

/* ---------- hospitalización, trasplante, calidad de vida ---------- */
function dpDlgHos(id){if(!dpGuard("seg"))return;const h=id?DP.book.hos.find(x=>x.ID===id):null;const o=h||{};const ep=dpR("epi").filter(e=>!o.Paciente||e.Paciente===o.Paciente);
  dpDlg(h?"Hospitalización "+h.ID:"Registrar hospitalización",'<div class="form"><label class="f wide">Paciente *<select id="ho_p"'+(h?" disabled":"")+'>'+dpPacOpts(o.Paciente,"Seleccione…")+'</select></label><label class="f">Ingreso *<input type="date" id="ho_i" value="'+dpDI(o.FechaIngreso)+'"></label><label class="f">Egreso<input type="date" id="ho_e" value="'+dpDI(o.FechaEgreso)+'"></label><label class="f">¿Más de 24 horas? *<select id="ho_24">'+opt(["Sí","No"],o.Mas24h||"","Sin dato")+'</select></label><label class="f">Institución<input type="text" id="ho_in" value="'+esc(o.Institucion||"")+'"></label><label class="f wide">Causa principal *<input type="text" id="ho_c" value="'+esc(o.Causa||"")+'"></label><label class="f">Relación con DP<select id="ho_r">'+opt(["Peritonitis","Infección del orificio o túnel","Mecánica del catéter","Volumen o metabólica","No relacionada","Por definir"],o.RelacionDP||"Por definir")+'</select></label><label class="f">Episodio infeccioso<select id="ho_ep">'+opt(ep.map(e=>[e.ID,e.ID+" · "+e.Paciente+" · "+e.Tipo+" "+fd(v6d(e.Fecha))]),o.Episodio||"","Ninguno")+'</select></label><label class="f">Desenlace<select id="ho_d">'+opt(["Egreso a DP","Transferencia temporal a HD","Transferencia definitiva a HD","Fallecimiento","Remisión a otra institución","En curso"],o.Desenlace||"En curso")+'</select></label></div><p class="note">Si el desenlace cambia la modalidad, registre además la transición desde la ficha.</p>',"Guardar",()=>{
    const p=h?h.Paciente:dv("ho_p"),i=dvd("ho_i"),e=dvd("ho_e");if(!p||!i)return"Paciente e ingreso son obligatorios.";if(i>TODAY())return"El ingreso no puede ser futuro.";if(e&&e<i)return"El egreso no puede ser anterior al ingreso.";if(dv("ho_c").length<3)return"Escriba la causa.";
    let m24=dv("ho_24");if(!m24&&e&&dayDiff(i,e)>=2)m24="Sí";if(!m24&&e&&dayDiff(i,e)===0)m24="No";
    const ch={FechaIngreso:i,FechaEgreso:e,Mas24h:m24,Institucion:dv("ho_in"),Causa:dv("ho_c"),RelacionDP:dv("ho_r"),Episodio:dv("ho_ep"),Desenlace:dv("ho_d"),Estado:e?"Cerrada":"Abierta"};if(h)dpUpd("hos",h,ch);else dpAdd("hos","HO-",Object.assign({Paciente:p},ch));pxRefresh();toast("Hospitalización guardada.");});}
function dpDlgTrp(pid){if(!dpGuard("seg"))return;const cur=pid?dpTxAt(pid):null;
  dpDlg("Trasplante renal · estado",'<p class="note">Estado vigente: '+esc(cur?cur.Estado+" desde "+fd(v6d(cur.Fecha)):"Sin evaluar")+'. Cada cambio queda como un registro nuevo.</p><div class="form"><label class="f wide">Paciente *<select id="tp_p">'+dpPacOpts(pid,"Seleccione…")+'</select></label><label class="f">Estado *<select id="tp_e">'+opt(DP_TX_EST,"")+'</select></label><label class="f">Fecha *<input type="date" id="tp_f" value="'+iso(TODAY())+'"></label><label class="f">IPS trasplantadora<input type="text" id="tp_c" value="'+esc(cur&&cur.Centro||"")+'"></label>'+
   '<fieldset class="f wide d8fs"><legend>Contraindicaciones (si no es idóneo)</legend><div class="chkcol">'+CAC_CONTRA.map(([k,l])=>'<label class="chk"><input type="checkbox" data-tpc value="'+k+'"> '+esc(l)+'</label>').join("")+'</div></fieldset><label class="f wide">Soporte *<input type="text" id="tp_s" placeholder="concepto, disentimiento firmado, remisión…"></label><label class="f wide">Nota<input type="text" id="tp_n"></label></div>',"Guardar",()=>{
    const p=dv("tp_p"),e=dv("tp_e"),f=dvd("tp_f");if(!p||!e||!f)return"Paciente, estado y fecha son obligatorios.";if(f>TODAY())return"La fecha no puede ser futura.";if(dv("tp_s").length<4)return"Registre el soporte.";const c=[...document.querySelectorAll("[data-tpc]:checked")].map(x=>x.value);
    if(e==="No idóneo (contraindicación con soporte)"&&!c.length)return"Marque la contraindicación.";dpAdd("trp","TX-",{Paciente:p,Fecha:f,Estado:e,Contraindicaciones:c.join(","),Centro:dv("tp_c"),Soporte:dv("tp_s"),Nota:dv("tp_n")});pxRefresh();toast("Estado de trasplante registrado.");});}
function dpDlgCvr(pid){if(!dpGuard("seg"))return;dpDlg("Calidad de vida · evaluación",'<div class="form"><label class="f wide">Paciente *<select id="cv_p">'+dpPacOpts(pid,"Seleccione…")+'</select></label><label class="f">Escala validada *<select id="cv_e">'+opt(["KDQOL-36","KDQOL-SF 1.3","EQ-5D-5L","SF-36","Otra validada (especificar en soporte)"],"","Seleccione…")+'</select></label><label class="f">Momento *<select id="cv_m">'+opt(["Inicio de la terapia","Seguimiento"],"")+'</select></label><label class="f">Fecha *<input type="date" id="cv_f" value="'+iso(TODAY())+'"></label><label class="f">Puntaje<input type="text" id="cv_s"></label><label class="f">Profesional<input type="text" id="cv_pr" value="'+esc(PX.user?PX.user.Nombre:"")+'"></label><label class="f wide">Soporte *<input type="text" id="cv_so"></label></div>',"Guardar",()=>{
  const p=dv("cv_p"),e=dv("cv_e"),m=dv("cv_m"),f=dvd("cv_f");if(!p||!e||!m||!f)return"Paciente, escala, momento y fecha son obligatorios.";if(dv("cv_so").length<4)return"Registre el soporte (formato aplicado).";dpAdd("cvr","CV-",{Paciente:p,Fecha:f,Escala:e,Momento:m,Puntaje:dv("cv_s"),Profesional:dv("cv_pr"),Soporte:dv("cv_so")});pxRefresh();toast("Evaluación registrada.");});}

/* ---------- heredados, roles, parámetros, planes de mejora, CAC ---------- */
function dpDlgHerV(id){if(!dpGuard("apr"))return;const x=DP.book.her.find(h=>h.ID===id);const disc={"Trabajo social":"Valoración de trabajo social","Nutrición":"Valoración de nutrición","Psicología":"Valoración de psicología"}[x.Tipo];
  dpDlg("Verificar registro heredado "+id,'<p class="note">'+esc(x.Tipo)+' · '+esc(x.Anotacion)+'<br>'+esc(x.Fuente)+'</p><div class="form"><label class="f">Resultado<select id="hv_a">'+opt([["ver","Verificado con soporte"],["des","Descartado (no hay soporte o no corresponde)"]],"ver")+'</select></label>'+(disc&&x.Paciente?'<label class="f">Fecha real de la atención<input type="date" id="hv_f" value="'+dpDI(x.FechaFuente)+'"></label><label class="chk wide"><input type="checkbox" id="hv_c" checked> Crear la actividad realizada en la agenda con este soporte</label>':'')+'<label class="f wide">Soporte o motivo *<input type="text" id="hv_s" placeholder="p. ej. nota de nutrición en SIIS del 30/05/2026"></label></div>',"Guardar",()=>{
    const a=dv("hv_a"),s=dv("hv_s");if(s.length<6)return"Describa el soporte o el motivo.";if(a==="des"){dpUpd("her",x,{Estado:"Descartado",Verificacion:s,VerificadoPor:dpWho(),FechaVerificacion:TODAY()});pxRefresh();return;}
    let extra="";if(disc&&x.Paciente&&$("hv_c")&&$("hv_c").checked){const f=dvd("hv_f");if(!f||f>TODAY())return"Indique la fecha real (no futura) de la atención.";const ag=dpAdd("age","AG-",{Paciente:x.Paciente,Tipo:disc,Fecha:f,Estado:"Realizada",FechaRealizacion:f,Resultado:"Verificado desde registro heredado: "+s,Registro:"her|"+x.ID,Origen:"Heredado "+x.ID,Historial:"[]"});dpPushHist(ag,{de:"",a:"Realizada",m:"Verificación de "+x.ID});extra=" · actividad "+ag.ID;}
    dpUpd("her",x,{Estado:"Verificado con soporte",Verificacion:s+extra,VerificadoPor:dpWho(),FechaVerificacion:TODAY()});pxRefresh();toast("Registro verificado"+extra+".");});}
function dpDlgRol(u){if(!dpGuard("cfg"))return;const r=u?DP.book.rol.find(x=>x.Usuario===u):null;const users=PX.book?PX.book.usr.filter(x=>x.Activo!=="NO"):[];
  dpDlg(r?"Rol de "+u:"Asignar rol en DP",'<div class="form"><label class="f wide">Usuario *<select id="ro_u"'+(r?" disabled":"")+'>'+opt(users.map(x=>[x.Usuario,x.Usuario+" · "+x.Nombre+" · "+x.Cargo]),u||"","Seleccione…")+'</select></label><label class="f">Rol *<select id="ro_r">'+opt(Object.entries(DP_ROLES),r?r.Rol:"")+'</select></label><label class="f">Estado<select id="ro_a">'+opt([["SI","Activo"],["NO","Inactivo"]],r?r.Activo||"SI":"SI")+'</select></label><label class="f wide">Motivo *<input type="text" id="ro_m"></label></div>',"Guardar",()=>{
    const us=r?u:dv("ro_u"),ro=dv("ro_r"),m=dv("ro_m");if(!us||!ro)return"Usuario y rol son obligatorios.";if(m.length<4)return"Escriba el motivo.";if(PX.user&&us===PX.user.Usuario&&!pxAdmin())return"No puede cambiar su propio rol.";
    const ch={Rol:ro,Activo:dv("ro_a"),ConcedidoPor:dpWho(),Fecha:nowTs(),Motivo:m};if(r){Object.assign(r,ch);dpLog("MODIFICA","rol",us,ro+" · "+m);}else{DP.book.rol.push(Object.assign({Usuario:us},ch));dpLog("CREA","rol",us,ro+" · "+m);}DP.dirty=true;pxRefresh();toast("Rol guardado.");});}
function dpDlgPar(){if(!dpGuard("cfg"))return;const C=dpCacCfg();dpDlg("Parámetros del módulo",'<div class="form"><label class="f">Intervalo de cambio de línea (meses)<input type="number" min="1" max="24" id="pa_l" value="'+esc(dpCfg("lineaMeses",""))+'" placeholder="según ficha técnica"></label><label class="f">Tolerancia de entrega (días)<input type="number" min="0" max="10" id="pa_t" value="'+esc(dpCfg("entregaTol",2))+'"></label><label class="f">Código de habilitación de la IPS<input type="text" id="pa_ips" value="'+esc(C.ips)+'"></label>'+EPS_L.map((e,i)=>'<label class="f">Código CAC de '+esc(e)+'<input type="text" id="pa_e'+i+'" value="'+esc(C.epsCod[e]||"")+'"></label>').join("")+'<label class="f wide">Fuente del intervalo de cambio de línea *<input type="text" id="pa_f" value="'+esc(dpCfg("lineaFuente",""))+'"></label></div>',"Guardar",()=>{
  const l=dvn("pa_l");if(l!=null&&dv("pa_f").length<4)return"Indique la fuente del intervalo (ficha técnica del fabricante).";dpCfgSet("lineaMeses",l);dpCfgSet("lineaFuente",dv("pa_f"));dpCfgSet("entregaTol",dvn("pa_t")??2);const ec={};EPS_L.forEach((e,i)=>{const v=dv("pa_e"+i);if(v)ec[e]=v;});dpCfgSet("cac",{ips:dv("pa_ips")||C.ips,epsCod:ec});pxRefresh();toast("Parámetros guardados.");});}
function dpDlgPm(id){if(!dpGuard("apr"))return;const r=id?DP.book.pm.find(x=>x.ID===id):null;const o=r||{Estado:"Abierto"};
  dpDlg(r?"Plan de mejora "+r.ID:"Nuevo plan de mejora",'<div class="form"><label class="f">Indicador o hallazgo *<input type="text" id="pm_i" list="pm_il" value="'+esc(o.Indicador||"")+'"><datalist id="pm_il">'+DP_IND8.concat(DP_OP).map(d=>'<option value="'+esc(d.c+" · "+d.n)+'">').join("")+'</datalist></label><label class="f">Periodo<input type="text" id="pm_pe" value="'+esc(o.Periodo||dpPerSel().l)+'"></label><label class="f wide">Hallazgo *<input type="text" id="pm_h" value="'+esc(o.Hallazgo||"")+'"></label><label class="f wide">Causa<input type="text" id="pm_c" value="'+esc(o.Causa||"")+'"></label><label class="f wide">Acción *<input type="text" id="pm_a" value="'+esc(o.Accion||"")+'"></label><label class="f">Responsable *<input type="text" id="pm_r" value="'+esc(o.Responsable||"")+'"></label><label class="f">Fecha límite *<input type="date" id="pm_f" value="'+dpDI(o.FechaLimite)+'"></label><label class="f">Estado<select id="pm_e">'+opt(["Abierto","En ejecución","Ejecutado","Cerrado"],o.Estado)+'</select></label><label class="f wide">Evidencia<input type="text" id="pm_ev" value="'+esc(o.Evidencia||"")+'"></label><label class="f wide">Verificación de eficacia<input type="text" id="pm_v" value="'+esc(o.Verificacion||"")+'"></label></div>',"Guardar",()=>{
    const ch={Indicador:dv("pm_i"),Periodo:dv("pm_pe"),Hallazgo:dv("pm_h"),Causa:dv("pm_c"),Accion:dv("pm_a"),Responsable:dv("pm_r"),FechaLimite:dvd("pm_f"),Estado:dv("pm_e"),Evidencia:dv("pm_ev"),Verificacion:dv("pm_v")};if(!ch.Indicador||!ch.Hallazgo||!ch.Accion||!ch.Responsable||!ch.FechaLimite)return"Complete indicador, hallazgo, acción, responsable y fecha.";
    if(["Ejecutado","Cerrado"].includes(ch.Estado)&&ch.Evidencia.length<4)return"Ejecutar o cerrar exige evidencia.";if(ch.Estado==="Cerrado"&&ch.Verificacion.length<4)return"Cerrar exige la verificación de eficacia.";if(r)dpUpd("pm",r,ch);else dpAdd("pm","PM-",ch);pxRefresh();toast("Plan guardado.");},true);}
function dpCacApprove(id){if(!dpGuard("apr"))return;const x=DP.book.cac.find(c=>c.ID===id);dpDlg("Aprobar corte "+id,'<p class="note">'+esc(x.Archivo)+' · '+x.Pacientes+' pacientes · '+x.Advertencias+' advertencias. La aprobación certifica la revisión institucional; no la compatibilidad con la CAC.</p><label class="f wide">Observación<input type="text" id="ca_o"></label>',"Aprobar",()=>{dpUpd("cac",x,{Estado:"Aprobado para envío",AprobadoPor:dpWho(),FechaAprobacion:TODAY(),Nota:[x.Nota,dv("ca_o")].filter(Boolean).join(" · ")});pxRefresh();});}
function dpCacSend(id){if(!dpGuard("apr"))return;const x=DP.book.cac.find(c=>c.ID===id);dpDlg("Registrar envío "+id,'<div class="form"><label class="f">Enviado a *<input type="text" id="cs_a" value="'+esc(x.EPS||"")+'"></label><label class="f">Fecha *<input type="date" id="cs_f" value="'+iso(TODAY())+'"></label><label class="f wide">Medio y evidencia (radicado, correo) *<input type="text" id="cs_e"></label></div>',"Registrar",()=>{if(!dv("cs_a")||!dvd("cs_f")||dv("cs_e").length<4)return"Complete destino, fecha y evidencia.";dpUpd("cac",x,{Estado:"Enviado",EnviadoA:dv("cs_a"),FechaEnvio:dvd("cs_f"),Nota:[x.Nota,"Envío: "+dv("cs_e")].filter(Boolean).join(" · ")});pxRefresh();});}

/* ---------- visor genérico de un registro original ---------- */
function dpRec(ref){const[k,id]=String(ref).split("|");if(k==="val"){dpValOpen(id);return;}if(k==="age"){dpDlgAge(id);return;}if(k==="epi"&&dpCan("seg")){dpDlgEpi(id);return;}if(k==="atb"&&dpCan("seg")){dpDlgAtb(id);return;}
  let r=null,t="";if(k==="mic"){r=(PX.book&&PX.book.mic||[]).find(x=>x.ID===id);t="Microbiología";}else if(k==="ce"){try{r=CE.book.cit.find(x=>x.ID===id);}catch(e){}t="Consulta externa";}else if(DP.book[k]){r=DP.book[k].find(x=>x.ID===id);t=DPS[k][0];}
  if(!r){toast("Registro no encontrado.");return;}const cols=(DPS[k]?DPS[k][1]:Object.keys(r));
  const fmt=(c,v)=>{if(v instanceof Date)return fd(v);if(typeof v==="string"&&/^[\[{]/.test(v)){const j=dpJ(v,null);if(j)return'<pre class="d8pre">'+esc(JSON.stringify(j,null,1))+'</pre>';}return esc(v);};
  const log=DP.book.log.filter(l=>l.Registro===id);
  dpDlg(t+" · "+id,'<dl class="d8dl">'+cols.filter(c=>r[c]!=null&&r[c]!=="").map(c=>'<dt>'+esc(c)+'</dt><dd>'+fmt(c,r[c])+'</dd>').join("")+'</dl>'+(log.length?'<h4>Trazabilidad</h4><ul class="d8nl">'+log.map(l=>'<li><span class="mono">'+esc(l.FechaHora)+'</span> · '+esc(l.Usuario)+' · '+esc(l.Accion)+(l.Detalle?' · '+esc(v6clip(l.Detalle,200)):'')+'</li>').join("")+'</ul>':''),"Cerrar",()=>{},true);const x=$("dlgx");if(x)x.hidden=true;}


/* =================== v0.8 · DP · libro: carga, exportación encadenada, demostración =================== */
function dpOnFile(f){if(!f)return;const rd=new FileReader();rd.onload=async ev=>{try{const wb=XLSX.read(new Uint8Array(ev.target.result),{type:"array"});if(!dpIsBook(wb)){toast("Ese archivo no es un libro de DP (faltan las hojas Pacientes y Episodios). Para el archivo de control use «Importar archivos».");return;}
  const b=dpParse(wb);const demoFile=b.pac.some(p=>/ficticio/i.test(String(p.Usuario||"")+String(p.Obs||"")))||(b.cfg.find(x=>x.Clave==="demo")||{}).Valor==="true";
  if(PX.demo&&!demoFile){toast("Está en la demostración: no se cargan libros con datos reales. Entre con el libro institucional real.");return;}
  DP.book=b;dpEnsure();DP.demo=demoFile;DP.dirty=false;DP.src=f.name;DP.ui={};dpPlanSeed();if(DP.dirty)DP.dirty=true;
  DP.ui.chain=await dpVerifyChain();dpLog("CARGA","log",f.name,DP.book.pac.length+" pacientes"+(DP.ui.chain&&!DP.ui.chain.ok?" · CADENA DE BITÁCORA ROTA en fila "+DP.ui.chain.fila:""));DP.dirty=false;
  pxRefresh();toast("Libro DP cargado: "+DP.book.pac.length+" pacientes."+(DP.ui.chain&&!DP.ui.chain.ok?" ATENCIÓN: la bitácora fue alterada por fuera del sistema.":""));}catch(e){console.error(e);toast("No se pudo leer el archivo: "+e.message);}};rd.readAsArrayBuffer(f);}
async function dpExportBook(){if(!DP.book)return;if(!DP.demo&&!dpCan("exp")&&!dpCan("pac")&&!dpCan("val")&&!dpCan("lab")&&!dpCan("age")&&!dpCan("ins")){toast("Su rol no descarga el libro.");return;}
  dpLog("EXPORTA","log","libro DP","Descarga del libro completo");await dpChain();const ok=await saveWb(dpBuildWb(),(DP.demo?"DP_libro_DEMO_":"DP_libro_")+iso(TODAY())+".xlsx");if(ok){DP.dirty=false;DP.ui.chain={ok:true,n:DP.book.log.length};pxRefresh();}}
/* demostración: amplía la cohorte ficticia de la v0.6 con datos de las hojas nuevas (semilla fija; nunca se mezcla con un libro real) */
const dpDemo06=dpDemo;
dpDemo=function(){dpDemo06();dpEnsure();const b=DP.book;let seed=81013;const R=()=>{seed=(seed*1103515245+12345)%2147483648;return seed/2147483648;};const ri=(a,c)=>a+Math.floor(R()*(c-a+1)),pick=a=>a[Math.floor(R()*a.length)];const T=TODAY(),ts=nowTs(),U="Demo (ficticio)";
  b.cfg.push({Clave:"demo",Valor:"true"});dpPlanSeed();b.plab.forEach(r=>{if(r.Estado==="Propuesta"){r.Estado="Validado";r.ValidadoPor="Demo (ficticio)";r.FechaValidacion=addDays(T,-60);}});
  const muns=["Mocoa","Villagarzón","Puerto Asís","Sibundoy","Orito"];
  b.pac.forEach((p,i)=>{p.IdInst=dpDocKey(p.TipoDoc||"CC",p.Documento);p.FechaInicioTRR=p.FechaInicioDP?addDays(v6d(p.FechaInicioDP),-ri(0,120)):null;p.FechaIngresoPrograma=p.FechaInicioDP;p.EstadoPrograma=v6d(p.FechaFinDP)?(/hemodi/i.test(p.MotivoFin||"")?"Transición a HD":"Egreso"):"Activo";p.Regimen=pick(["C","S"]);p.Municipio=p.Municipio||pick(muns);p.Etiologia=pick(["1","1","5","2"]);p.HTA=pick(["SI","SI","NO"]);p.DM=pick(["SI","NO","NO"]);p.Talla=ri(150,178);p.VacunaVHB=pick(["Esquema completo","Esquema incompleto","No vacunado"]);if(!p.FechaNac)p.FechaNac=new Date(1950+ri(0,45),ri(0,11),ri(1,28));p.Sexo=p.Sexo||pick(["Femenino","Masculino"]);p.Usuario=U;
    if(p.FechaFinDP)b.est.push({ID:dpNext("est","TR-"),Paciente:p.ID,Fecha:p.FechaFinDP,EstadoAnterior:"Activo",EstadoNuevo:p.EstadoPrograma,ModalidadAnterior:p.Modalidad,ModalidadNueva:p.Modalidad,Motivo:p.MotivoFin,Destino:/hemodi/i.test(p.MotivoFin||"")?"Hemodiálisis en UNO-P":"Trasplante",Soporte:"Nota de HC (ficticia)",Usuario:U,Registrado:ts});
    const st=v6d(p.FechaInicioDP);if(!st)return;const end=v6d(p.FechaFinDP)||T;
    b.pre.push({ID:dpNext("pre","PR-"),Paciente:p.ID,Version:1,Modalidad:p.Modalidad,VigenteDesde:st,Prescriptor:"Nefrología (ficticio)",Motivo:"Inicio",PesoRef:ri(50,82),Soluciones:JSON.stringify(p.Modalidad==="DPA"?[{sol:"Glucosa 1,5 %",vol:2000,n:4},{sol:"Glucosa 2,5 %",vol:2000,n:1}]:[{sol:"Glucosa 1,5 %",vol:2000,n:3},{sol:"Glucosa 2,5 %",vol:2000,n:1}]),VolumenTotal:p.Modalidad==="DPA"?10000:8000,Intercambios:p.Modalidad==="DPA"?null:4,TiempoTotalH:p.Modalidad==="DPA"?9:null,Ciclos:p.Modalidad==="DPA"?5:null,Objetivos:JSON.stringify(["Control de volumen","Control de síntomas"]),Estado:"Vigente",Usuario:U,Registrado:ts});
    b.cat.push({ID:dpNext("cat","CT-"),Paciente:p.ID,Tipo:"Implante",Fecha:p.FechaCateter||addDays(st,-14),TipoCateter:"Tenckhoff recto, 2 cuffs",Responsable:"Cirugía (ficticio)",Usuario:U,Registrado:ts});
    b.edu.push({ID:dpNext("edu","ED-"),Paciente:p.ID,Tipo:"Entrenamiento inicial",Fecha:addDays(st,-7),Responsable:"Enf. DP (ficticio)",Participante:"Paciente y cuidador",Datos:JSON.stringify({competencias:Object.fromEntries(DP_COMP.map(c=>[c,R()<0.9?"Competente":"Requiere refuerzo"]))}),Resultado:R()<0.75?"Competente":"Requiere refuerzo",Usuario:U,Registrado:ts});
    for(let m=0;m<6;m++){const ms=monthStart(addMonths(T,-m));if(ms<monthStart(st)||ms>end)continue;const d=addDays(ms,ri(3,20));if(d>T||d>end)continue;
      ["Hb","Alb","P","Ca"].forEach(k=>{if(m%3!==0&&k!=="Hb")return;const v=k==="Hb"?9+R()*3.5:k==="Alb"?3+R()*1.1:k==="P"?3+R()*4:8.5+R()*2.3;b.lab.push({ID:dpNext("lab","L-"),Paciente:p.ID,Examen:k,Valor:Math.round(v*10)/10,Unidad:DPX[k].u,FechaToma:d,FechaResultado:addDays(d,1),LabOrigen:"Laboratorio clínico UNO-P",Metodo:"Reportado",Estado:R()<0.85?"Validado":"Pendiente de validación",Reviso:"Nefrología (ficticio)",Version:1,Usuario:U,Registrado:ts});});
      if(m===1||m===4){b.lab.push({ID:dpNext("lab","L-"),Paciente:p.ID,Examen:"PTH",Valor:ri(90,820),Unidad:"pg/mL",FechaToma:d,LabOrigen:"Laboratorio de apoyo",Metodo:"Reportado",Estado:"Validado",Version:1,Usuario:U,Registrado:ts});b.lab.push({ID:dpNext("lab","L-"),Paciente:p.ID,Examen:"KtV",Valor:Math.round((1.4+R()*0.9)*100)/100,FechaToma:d,LabOrigen:"Calculado en el SIGC",Metodo:"Calculado · "+DP_KTV_VER,Estado:"Validado",Version:1,Usuario:U,Registrado:ts});}
      b.val.push({ID:dpNext("val","V-"),Paciente:p.ID,Fecha:d,Tipo:"Control de nefrología",Profesional:"Laura Benavides (ficticio)",Estado:"Finalizada",Version:1,Datos:JSON.stringify({hora:"08:30",modo:"Presencial",motivo:"Control mensual",ta_s:ri(110,160),ta_d:ri(60,95),peso:ri(50,82),edema:pick(["Ausente","+"]),volumen:pick(["Euvolémico","Sobrecarga"]),orificio:pick(["Normal","Normal","Inflamación sin infección"]),cat_func:"Adecuado",modalidad:p.Modalidad,presc_conc:"Concordante",diuresis:ri(0,900),diuresis_f:pick(["Medida (recolección de 24 h)","Referida por el paciente"]),analisis:"Paciente estable (ficticio).",plan:"Continuar prescripción.",alarma:"Sí, explicados y comprendidos",firma:"Laura Benavides",registro:"RM 000 (ficticio)"}),Completitud:ri(62,100),FinalizadaPor:"Laura Benavides (ficticio)",FinalizadaEn:ts,Usuario:U,Registrado:ts});}
    if(dpActivo(p,T)){const tipos=["Consulta de nefrología","Valoración de nutrición","Visita domiciliaria","Toma de laboratorios","Valoración de enfermería"];for(let j=0;j<3;j++){const d=addDays(T,ri(-12,20));const est=d<T?pick(["Realizada","Realizada","Programada","Inasistencia"]):pick(["Programada","Confirmada"]);
      b.age.push({ID:dpNext("age","AG-"),Paciente:p.ID,Tipo:pick(tipos),Fecha:d,Hora:pick(["08:00","09:00","10:30","14:00"]),DuracionMin:30,Profesional:pick(["Laura Benavides","Yuli Narváez","Diana Muñoz"]),Modalidad:"Presencial",Estado:est,FechaRealizacion:est==="Realizada"?d:null,Resultado:est==="Realizada"?"Atención realizada (ficticio)":est==="Inasistencia"?"No asistió (ficticio)":"",Historial:JSON.stringify([{ts,u:U,de:"",a:"Programada"}]),Origen:"Demostración",Usuario:U,Registrado:ts});}
      b.ins.push({ID:dpNext("ins","IN-"),Paciente:p.ID,Insumo:p.Modalidad==="DPA"?"Bolsa 6000 mL glucosa 1,5 %":"Bolsa 2000 mL glucosa 1,5 %",Cantidad:p.Modalidad==="DPA"?30:90,Periodo:"Mensual",Estado:"Vigente",Origen:"Demostración",Usuario:U,Registrado:ts});
      const pe=ym(addMonths(T,-1));const ok=R()<0.8;b.ent.push({ID:dpNext("ent","EN-"),Paciente:p.ID,Periodo:pe,FechaProgramada:addDays(monthStart(addMonths(T,-1)),2),FechaEntrega:addDays(monthStart(addMonths(T,-1)),ok?2:5),Items:JSON.stringify([{insumo:"Bolsas",req:90,ent:ok?90:80}]),Estado:ok?"Entregada completa":"Parcial",Responsable:"Logística (ficticio)",SoporteRecibido:"Sí",Incidencia:ok?"":"Faltante",Contingencia:ok?"":"Entrega complementaria (ficticio)",Usuario:U,Registrado:ts});
      if(R()<0.35)b.trp.push({ID:dpNext("trp","TX-"),Paciente:p.ID,Fecha:addDays(T,-ri(30,200)),Estado:pick(["Idóneo, en estudio","En lista de espera","No idóneo (contraindicación con soporte)"]),Contraindicaciones:"1",Centro:"IPS trasplantadora (ficticia)",Soporte:"Concepto (ficticio)",Usuario:U,Registrado:ts});
      if(R()<0.4)b.cvr.push({ID:dpNext("cvr","CV-"),Paciente:p.ID,Fecha:addDays(T,-ri(10,200)),Escala:"KDQOL-36",Momento:"Seguimiento",Puntaje:String(ri(40,85)),Profesional:"Psicología (ficticio)",Soporte:"Formato (ficticio)",Usuario:U,Registrado:ts});}});
  b.hos.push({ID:dpNext("hos","HO-"),Paciente:b.pac[1].ID,FechaIngreso:addDays(T,-40),FechaEgreso:addDays(T,-35),Mas24h:"Sí",Institucion:"Hospital José María Hernández (ficticio)",Causa:"Peritonitis",RelacionDP:"Peritonitis",Desenlace:"Egreso a DP",Estado:"Cerrada",Usuario:U,Registrado:ts});
  [["coordinacion","dir"],["nefrologia","nefro"],["enfdp","enf"],["tsocial","multi"],["laboratorio","lab"],["calidad","cons"]].forEach(([u,r])=>b.rol.push({Usuario:u,Rol:r,Activo:"SI",ConcedidoPor:"Demostración",Fecha:ts,Motivo:"Rol de demostración"}));
  DP.demo=true;DP.dirty=false;DP.ui={};};

/* =================== v0.8 · DP · Laboratorio clínico ve la solicitud de DP =================== */
const pxLab07=pxLab;
pxLab=function(){const sub=PX.ui.sub||"sol";if(sub==="dp"){return pxLabDpHead()+(DP.book?dpSolView("lab"):'<div class="panel empty">Abra el libro de Diálisis peritoneal (o la demostración) para ver su solicitud.</div>');}
  return pxLab07().replace('<button type="button" data-p="go|lab|res"','<button type="button" data-p="go|lab|dp" aria-pressed="false">Solicitud del mes · DP</button><button type="button" data-p="go|lab|res"');};
function pxLabDpHead(){return'<div class="mhead"><div><p class="eyebrow">Servicio de apoyo</p><h2 class="mt">Laboratorio clínico</h2><p class="note" style="margin:3px 0 0">Solicitud mensual de diálisis peritoneal: sale del plan validado del programa. Laboratorio marca las muestras y carga los resultados, que quedan en el historial del paciente en DP (una sola fuente).</p></div></div><div class="seg" role="group">'+[["sol","Solicitud del mes · HD"],["vih","Solicitud del mes · VIH"],["dp","Solicitud del mes · DP"],["res","Carga de resultados"],["mic","Microbiología"],["pend","Pendientes y oportunidad"]].map(([k,l])=>'<button type="button" data-p="go|lab|'+k+'" aria-pressed="'+(k==="dp")+'">'+l+'</button>').join("")+'</div>';}
