  if(k==="age")return pxExport("DP_agenda_"+tag+".xlsx",[["Agenda",DP.book.age,[["ID",a=>a.ID],["Paciente",a=>a.Paciente],["Nombre",a=>pn(a.Paciente)],["Actividad",a=>a.Tipo],["Fecha",a=>v6d(a.Fecha)],["Hora",a=>a.Hora],["Profesional",a=>a.Profesional],["Estado",a=>dpAgeEst(a)],["Realizada",a=>v6d(a.FechaRealizacion)],["Resultado",a=>a.Resultado],["Registro",a=>a.Registro],["Motivo",a=>a.Motivo],["Historial",a=>dpHist(a).map(h=>h.ts+" "+h.u+": "+(h.de||"—")+"→"+h.a+(h.m?" ("+h.m+")":"")).join(" | ")]]]]);
