  /* IAAS-07 y IAAS-08: captura excepcional */
  [["IAAS-07","noint","Vigilancia en Salud Pública / Calidad","No hay registro estructurado de notificaciones IAAS en el SIGC"],["IAAS-08","noex","Seguridad y Salud en el Trabajo","No existe registro estructurado de accidentes biológicos en el SIGC"]].forEach(([id,dsp,own,why])=>{const d=D[id];const M=manEval(per,"IAAS",id);const n=M.used.reduce((a,x)=>a+x.num,0),dn=M.used.reduce((a,x)=>a+x.den,0);
   out.push(trR(d,M.used.length?{num:n,den:dn,parts:M.used,srcN:M.used.map(manSrc),disp:dn?"calc":"na",exc:true,why:"Captura excepcional con procedencia ("+own+")."}:{disp:dsp,why,falt:[{que:"Numerador y denominador del mes",donde:own,dispone:dsp==="noint"?"El dato existe fuera del SIGC":"No",impide:why,mod:"Registro estructurado en el proceso propietario; mientras tanto, captura excepcional con responsable y motivo"}]}));});
