function trTrz(mat){const D=mat==="IAAS"?IAAS_DEF:PROA_DEF;const per=pxMes();const R=trGet(mat,per);
  let h='<div class="panel"><div class="mhead"><h3 style="margin:0">Fichas técnicas · '+esc(mat)+'</h3><button type="button" class="btn sm" data-p="trzexp">Exportar matriz y fichas</button></div><div class="tablebox"><table class="dense"><thead><tr><th>Código</th><th>Indicador</th><th>Numerador</th><th>Denominador</th><th>Propietarios</th><th>Disponibilidad en '+esc(pxMesTxt(per))+'</th><th>Versión</th><th></th></tr></thead><tbody>'+
   D.map(d=>{const F=FICHAS[d.id]||{};const r=R.find(x=>x.id===d.id)||{};return'<tr><td class="mono">'+d.id+'</td><td>'+esc(d.n)+'</td><td style="font-size:12.5px">'+esc(F.num||"")+'</td><td style="font-size:12.5px">'+esc(F.den||"")+'</td><td style="font-size:12.5px">'+esc([...new Set((F.own||[]).map(o=>o[1]))].join(" · "))+'</td><td>'+(r.disp?dispB(r):"")+'</td><td class="mono" style="font-size:12px">'+esc(fichaVer(d.id))+'</td><td><button type="button" class="lnk" data-p="trficha|'+d.id+'">ficha</button></td></tr>';}).join("")+'</tbody></table></div></div>';
  h+='<div class="panel"><h3>Matriz de trazabilidad de datos fuente</h3><p class="note">Clasificación: disponible · requiere adaptación · requiere nueva captura en el proceso fuente · no disponible. La última columna se verifica con los libros abiertos en esta sesión.</p><div class="tablebox"><table class="trz dense"><thead><tr><th>Indicador o variable</th><th>Proceso propietario</th><th>Módulo fuente</th><th>Campo disponible</th><th>Dato faltante</th><th>Regla de cálculo</th><th>Validación</th><th>Modificación</th><th>Clasificación</th><th>En esta sesión</th></tr></thead><tbody>'+
   TRZ.map(r=>{let ok=false;try{ok=r[9]();}catch(e){}return'<tr>'+r.slice(0,8).map(c=>'<td>'+esc(c)+'</td>').join("")+'<td><span class="tag '+(r[8]==="Disponible"?"cac":r[8]==="No disponible"?"bad":"inst")+'">'+esc(r[8])+'</span></td><td>'+(ok?'<span class="st ok">con datos</span>':'<span class="st base">sin datos</span>')+'</td></tr>';}).join("")+'</tbody></table></div></div>';
  const C=PX.book.cie.filter(c=>c.Matriz===mat);const per_=[...new Set(C.map(c=>c.Periodo+"|"+c.Vigente+"|"+c.Fecha+"|"+c.CerradoPor))];
  h+='<div class="panel"><h3>Cierres de mes ('+per_.length+')</h3>'+(per_.length?'<ul class="v6list">'+per_.map(x=>{const[p,v,f,u]=x.split("|");return'<li>'+esc(pxMesTxt(p))+' · cerrado '+esc(f)+' por '+esc(u)+(v==="SI"?' · <span class="st ok">vigente</span>':' · <span class="st base">reabierto</span>')+'</li>';}).join("")+'</ul>':'<p class="note">Sin meses cerrados.</p>')+'</div>';
  return h;}
function trzExport(){pxExport("Matriz_trazabilidad_IAAS_PROA_"+pxToday()+".xlsx",[["Matriz",TRZ,[["Indicador o variable",r=>r[0]],["Proceso propietario",r=>r[1]],["Módulo fuente existente",r=>r[2]],["Campo disponible",r=>r[3]],["Dato faltante",r=>r[4]],["Regla de cálculo",r=>r[5]],["Validación requerida",r=>r[6]],["Modificación propuesta",r=>r[7]],["Clasificación",r=>r[8]]]],
  ["Fichas",IAAS_DEF.concat(PROA_DEF),[["Código",d=>d.id],["Nombre",d=>d.n],["Objetivo",d=>(FICHAS[d.id]||{}).obj],["Numerador",d=>(FICHAS[d.id]||{}).num],["Denominador",d=>(FICHAS[d.id]||{}).den],["Factor",d=>d.f],["Unidad",d=>d.u],["Periodicidad",d=>(FICHAS[d.id]||{}).per],["Meta",d=>fichaMeta(d.id)==null?"":fichaMeta(d.id)],["Propietarios",d=>((FICHAS[d.id]||{}).own||[]).map(o=>o[0]+" → "+o[1]+" ("+o[2]+")").join("; ")],["Registro fuente",d=>(FICHAS[d.id]||{}).fue],["Campos",d=>(FICHAS[d.id]||{}).campos],["Inclusión",d=>(FICHAS[d.id]||{}).incl],["Exclusión",d=>(FICHAS[d.id]||{}).excl],["Doble conteo",d=>(FICHAS[d.id]||{}).dup],["Validación",d=>(FICHAS[d.id]||{}).valida],["Versión",d=>fichaVer(d.id)],["Limitaciones",d=>(FICHAS[d.id]||{}).nota]]]]);}

/* =================== v0.6 · Seguridad del paciente con pestaña de higiene de manos =================== */
function pxSP(){const sub=PX.ui.sub||"tab";const per=pxMes();let h=pxTraHead("sp",sub,[["tab","Tablero"],["rep","Reportes"],["hm","Higiene de manos"],["lst","Rondas de seguridad"]],'<button type="button" class="btn primary" data-p="spnew|">Reportar evento</button>');
  if(sub==="tab")h+=pxTab(pxSPCalc(per),per,pxSPCalc,'<p class="note">No se recibió una matriz institucional de seguridad del paciente; estos cinco indicadores son una propuesta y las metas quedan por definir en el Comité de Seguridad del Paciente. La adherencia a higiene de manos (IAAS-04) se mide en la pestaña «Higiene de manos» y la lee IAAS.</p>');
  else if(sub==="rep")h+=pxSPRep();else if(sub==="hm")h+=spHHView(per);else h+=pxLstView(["ron","med"],per);return h;}
function catDays(p,a,b){const C=cdCalc(a,b,"",p.ID);if(C.block.some(x=>x.p.ID===p.ID))return null;const r=C.per.find(x=>x.p.ID===p.ID);return r?r.days:0;}
function v6Pendientes(L){const T=TODAY();const b=(p,l)=>' · <button type="button" class="lnk" data-p="'+p+'">'+l+'</button>';
  if(hdOn()&&(pxCan("hd")||pxCan("iaas"))){const v=terSlots(addMonths(T,-2),T).filter(s=>s.es==="Vencida");if(v.length)L.push({l:"bad",t:"Limpieza terminal",h:v.length+(v.length===1?" limpieza terminal vencida":" limpiezas terminales vencidas")+" en la sala de hemodiálisis"+b("trgo|hd|lim","ver cronograma")});
    const R=limRutina(addDays(T,-1),addDays(T,-1));if(R.sin.length)L.push({l:"warn",t:"Desinfección",h:R.sin.length+" sesiones de ayer sin registro de desinfección del puesto"+b("trgo|hd|lim","ver")});}
  if(pxCan("sp")&&PX.book){[hhPeriod(ym(T)),hhPeriod(ym(addMonths(T,-3)))].forEach(x=>{if(x.st==="vencida")L.push({l:"bad",t:"Higiene de manos",h:"Auditoría del trimestre "+(x.q+1)+" de "+x.y+" vencida"+b("go|sp|hm","registrar")});else if(x.st==="plazo")L.push({l:"info",t:"Higiene de manos",h:"Este mes toca la auditoría trimestral"+b("go|sp|hm","registrar")});});}
  if(pxCan("iaas")){const n=epAll(addMonths(T,-6)).filter(e=>!e.cls||e.cls.Estado==="Pendiente").length;if(n)L.push({l:"warn",t:"IAAS",h:n+" episodios infecciosos por clasificar"+b("go|iaas|epi","ver")});}
  if(pxCan("proa")){const n=trtAll().filter(t=>t.ini&&!trtAudit(t)&&dayDiff(t.ini,T)<=60).length;if(n)L.push({l:"warn",t:"PROA",h:n+" tratamientos antimicrobianos sin auditar"+b("go|proa|trt","ver")});}}

