const v7histHtml=r=>{const h=v7hist(r);return h.length?'<details class="hist"><summary>Historial ('+h.length+')</summary><ul class="v6list">'+h.map(x=>'<li><span class="mono">'+esc(x.f)+'</span> · '+esc(x.u)+' · '+esc((x.de?x.de+" → ":"")+x.a)+(x.n?' · <em>'+esc(x.n)+'</em>':'')+'</li>').join("")+'</ul></details>':'';};
const v7d=s=>s?pdate(String(s).slice(0,10)):null;
const v7late=(s,ref)=>{const d=v7d(s);return d&&d<(ref||TODAY());};
const v7in=(s,days)=>{const d=v7d(s);return d&&d>=TODAY()&&dayDiff(TODAY(),d)<=days;};
