function v7DlgBatDec(k){const B=v7bat();openDlg("Decisión del comité sobre la batería depurada",'<p class="note">Estado actual: '+esc(B.estado)+'. Aprobar exige el número del acta donde consta la decisión. La matriz vigente se sigue calculando aunque la batería se apruebe.</p><div class="form"><label class="f">Decisión<select id="bd_e">'+opt(["Propuesta","Aprobada","Aprobada con ajustes","Rechazada"],B.estado)+'</select></label><label class="f">Acta<input type="text" id="bd_a" value="'+esc(B.acta)+'"></label><label class="f">Fecha<input type="date" id="bd_f" value="'+esc(B.fecha||pxToday())+'"></label><label class="f wide">Ajustes o nota<textarea id="bd_n" rows="2">'+esc(B.nota||"")+'</textarea></label></div>',"Guardar",()=>{const e=$("bd_e").value,a=$("bd_a").value.trim();if(e!=="Propuesta"&&a.length<2)return"Indique el acta donde consta la decisión.";const o={estado:e==="Aprobada con ajustes"?"Aprobada":e,acta:a,fecha:$("bd_f").value,nota:$("bd_n").value.trim(),por:PX.user?PX.user.Nombre:""};pxSetCfg("v7_bat",o);pxLog("MODIFICA","cfg","v7_bat",e+" · acta "+a);TRM.c={};pxRender();toast("Decisión registrada.");});}
