function v7DlgValList(k){const p=v7prog(k);const ok=v7valOk();openDlg("Validaciones del entregable previo · "+PROG[p].n,'<p class="note">Salen de la revisión documental del 12-oct-2026. Cada una se marca resuelta con la evidencia (acta, documento).</p><table class="dense"><tbody>'+V7VAL.map((x,i)=>[x,i]).filter(([x])=>x[0].split(",").includes(p)).map(([x,i])=>'<tr><td>'+esc(x[1])+'<span class="sub">'+esc(x[2])+'</span></td><td>'+(ok[i]?'<span class="st ok">Resuelta '+esc(ok[i].fecha)+'</span>':'<button type="button" class="btn sm" data-p="v7val|'+i+'">Resolver</button>')+'</td></tr>').join("")+'</tbody></table>',"Cerrar",()=>{});}
function v7DlgVal(i){const x=V7VAL[i];const ok=v7valOk();const r=ok[i];openDlg("Validación pendiente",'<p><strong>'+esc(x[1])+'</strong></p><p class="note">Responsable: '+esc(x[2])+(r?'<br>Resuelta el '+esc(r.fecha)+' por '+esc(r.por)+': '+esc(r.nota):'')+'</p>'+(pxCan(x[0].split(",")[0])?'<label class="f wide">Cómo se resolvió (acta, documento, decisión)<textarea id="vl_n" rows="2"></textarea></label>':''),r?"Cerrar":"Marcar resuelta",()=>{if(r||!$("vl_n"))return;const n=$("vl_n").value.trim();if(n.length<6)return"Indique cómo se resolvió (acta, documento).";const o=Object.assign({},ok);o[i]={fecha:pxToday(),por:PX.user?PX.user.Nombre:"",nota:n};pxSetCfg("v7_val_ok",o);pxLog("MODIFICA","cfg","v7_val_ok","#"+i+" "+n);pxRender();toast("Validación registrada.");});}

